@app.route('/api/chat/notifications', methods=['GET'])
@login_required
def get_chat_notifications():
    """Get new chat messages for notifications across all accessible projects"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    try:
        user_id = session['user_id']
        username = session['username']
        
        # Get user role
        cursor.execute("SELECT role FROM users WHERE id = ?", (user_id,))
        user_role_result = cursor.fetchone()
        user_role = user_role_result[0] if user_role_result else None
        
        # Get last seen message ID for this user (from session or query param)
        last_seen_id = request.args.get('last_seen_id', 0, type=int)
        
        # Build query based on user role
        if user_role == 'Sales Engineer':
            # Sales Engineer - only their projects
            cursor.execute("SELECT id FROM engineers WHERE username = ?", (username,))
            engineer_result = cursor.fetchone()
            if not engineer_result:
                return jsonify({'success': True, 'messages': [], 'count': 0})
            
            engineer_id = engineer_result[0]
            cursor.execute("""
                SELECT 
                    pcm.id, pcm.project_id, pcm.username, pcm.message_text,
                    pcm.attachment_filename, pcm.created_at,
                    rp.project_name
                FROM project_chat_messages pcm
                JOIN register_project rp ON pcm.project_id = rp.id
                WHERE pcm.id > ? 
                    AND pcm.user_id != ?
                    AND rp.sales_engineer_id = ?
                ORDER BY pcm.created_at DESC
                LIMIT 10
            """, (last_seen_id, user_id, engineer_id))
        else:
            # Other roles - all approved projects
            cursor.execute("""
                SELECT 
                    pcm.id, pcm.project_id, pcm.username, pcm.message_text,
                    pcm.attachment_filename, pcm.created_at,
                    rp.project_name
                FROM project_chat_messages pcm
                JOIN register_project rp ON pcm.project_id = rp.id
                WHERE pcm.id > ? 
                    AND pcm.user_id != ?
                ORDER BY pcm.created_at DESC
                LIMIT 10
            """, (last_seen_id, user_id))
        
        messages = []
        max_id = last_seen_id
        for row in cursor.fetchall():
            messages.append({
                'id': row['id'],
                'project_id': row['project_id'],
                'project_name': row['project_name'],
                'username': row['username'],
                'message_text': row['message_text'][:100] if row['message_text'] else '',
                'has_attachment': bool(row['attachment_filename']),
                'attachment_filename': row['attachment_filename'],
                'created_at': row['created_at']
            })
            if row['id'] > max_id:
                max_id = row['id']
        
        conn.close()
        return jsonify({
            'success': True,
            'messages': messages,
            'count': len(messages),
            'max_id': max_id
        })
        
    except Exception as e:
        conn.close()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/chat/latest_id', methods=['GET'])
@login_required
def get_latest_chat_id():
    """Get the latest chat message ID to initialize the notification system"""
    conn = sqlite3.connect('ProjectStatus.db')
    cursor = conn.cursor()
    
    try:
        cursor.execute("SELECT MAX(id) FROM project_chat_messages")
        result = cursor.fetchone()
        max_id = result[0] if result and result[0] else 0
        conn.close()
        return jsonify({'success': True, 'latest_id': max_id})
    except Exception as e:
        conn.close()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/toggle_quote_for_deal_value/<int:project_id>/<quote_ref>', methods=['POST'])
@login_required
def toggle_quote_for_deal_value(project_id, quote_ref):
    """Toggle a quotation's inclusion in the deal value calculation"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    try:
        # Get the project name for this project_id
        c.execute("SELECT project_name FROM register_project WHERE id = ?", (project_id,))
        project = c.fetchone()
        if not project:
            flash('Project not found!', 'danger')
            conn.close()
            return redirect(url_for('view_projects'))
        
        project_name = project['project_name']
        
        # Toggle the selected_for_deal_value flag
        c.execute("SELECT selected_for_deal_value FROM projects WHERE quote_ref = ?", (quote_ref,))
        quote = c.fetchone()
        
        if not quote:
            flash('Quotation not found!', 'danger')
            conn.close()
            return redirect(url_for('project_detail', project_id=project_id))
        
        new_status = 0 if quote['selected_for_deal_value'] else 1
        c.execute("UPDATE projects SET selected_for_deal_value = ? WHERE quote_ref = ?", (new_status, quote_ref))
        
        # Recalculate total deal value from all selected quotations for this project
        c.execute("""
            SELECT SUM(quotation_selling_price) as total,
                   GROUP_CONCAT(quote_ref || ' (SAR ' || printf('%,.2f', quotation_selling_price) || ')', ', ') as quotes_list
            FROM projects 
            WHERE project_name = ? AND selected_for_deal_value = 1
        """, (project_name,))
        
        result = c.fetchone()
        total_value = result['total'] or 0
        quotes_list = result['quotes_list'] or ''
        
        # Update the register_project with new deal value
        if total_value > 0:
            deal_value_note = f"Deal Value from {quotes_list}"
        else:
            deal_value_note = None
        
        c.execute("""
            UPDATE register_project 
            SET deal_value = ?, 
                deal_value_note = ?,
                updated_time = datetime('now'),
                updated_by = ?
            WHERE id = ?
        """, (total_value, deal_value_note, session.get('username', 'Unknown'), project_id))
        
        conn.commit()
        
        if new_status == 1:
            flash(f'Added {quote_ref} to deal value. Total: SAR {total_value:,.2f}', 'success')
        else:
            flash(f'Removed {quote_ref} from deal value. Total: SAR {total_value:,.2f}', 'info')
        
    except Exception as e:
        flash(f'Error updating deal value: {e}', 'danger')
    finally:
        conn.close()
    
    return redirect(url_for('project_detail', project_id=project_id))

@app.route('/download_project_data_excel/<int:project_id>')
@login_required
def download_project_data_excel(project_id):
    """Export all project data (quotations, RFQs, POs) to Excel with enhanced formatting"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    FONT_NAME = 'Calibri'
    
    cursor.execute("""
        SELECT 
            rp.*,
            eu.name as end_user_name,
            c.name as contractor_name,
            cons.name as consultant_name,
            e.name as sales_engineer_name
        FROM register_project rp
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors c ON rp.contractor_id = c.id
        LEFT JOIN consultants cons ON rp.consultant_id = cons.id
        LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
        WHERE rp.id = ?
    """, (project_id,))
    project = cursor.fetchone()
    
    if not project:
        flash('Project not found!', 'danger')
        conn.close()
        return redirect(url_for('view_projects'))
    
    project_name = project['project_name']
    
    quotations_query = """
        SELECT 
            quote_ref AS "Quote Reference",
            system AS "System",
            presale_eng AS "Presale Engineer",
            sales_eng AS "Sales Engineer",
            quotation_cost AS "Cost (SAR)",
            quotation_selling_price AS "Selling Price (SAR)",
            margin AS "Margin %",
            status AS "Status",
            registered_date AS "Registered Date",
            updated_time AS "Updated Date",
            sow AS "Scope of Work",
            quotation_note AS "Notes",
            feedback AS "Feedback"
        FROM projects
        WHERE project_name = ?
        ORDER BY registered_date DESC
    """
    df_quotations = pd.read_sql_query(quotations_query, conn, params=(project_name,))
    
    rfqs_query = """
        SELECT 
            rfq_reference AS "RFQ Reference",
            project_status AS "Project Status",
            priority AS "Priority",
            sales_engineer_presale AS "Presale Engineer",
            sales_engineer_sales AS "Sales Engineer",
            rfq_status AS "RFQ Status",
            quotation_status AS "Quotation Status",
            deadline AS "Deadline",
            requested_time AS "Requested Date",
            note AS "Notes"
        FROM rfq_requests
        WHERE project_name = ?
        ORDER BY requested_time DESC
    """
    df_rfqs = pd.read_sql_query(rfqs_query, conn, params=(project_name,))
    
    pos_query = """
        SELECT 
            po.po_request_number AS "PO Request Number",
            po.po_number AS "PO Number",
            d.name AS "Distributor",
            v.name AS "Vendor",
            po.system AS "System/Scope",
            po.total_amount AS "Total Amount (SAR)",
            po.po_approval_status AS "Approval Status",
            po.po_delivery_status AS "Delivery Status",
            eng.username AS "Presale Engineer",
            pmeng.username AS "Project Manager",
            po.created_at AS "Created Date",
            po.po_notes_vendor AS "Vendor Notes",
            po.po_notes_client AS "Client Notes"
        FROM purchase_orders po
        LEFT JOIN distributors d ON CAST(po.distributor AS TEXT) = CAST(d.id AS TEXT)
        LEFT JOIN vendors v ON CAST(po.vendor AS TEXT) = CAST(v.id AS TEXT)
        LEFT JOIN engineers eng ON po.presale_engineer = eng.id
        LEFT JOIN engineers pmeng ON po.project_manager = pmeng.id
        WHERE CAST(po.project_name AS TEXT) = CAST(? AS TEXT)
        ORDER BY po.created_at DESC
    """
    df_pos = pd.read_sql_query(pos_query, conn, params=(project_name,))
    
    # Query to fetch RFTS (Request for Technical Support)
    rfts_query = """
        SELECT 
            rfts_reference AS "RFTS Reference",
            system AS "System",
            request_type AS "Request Type",
            presale_engineer AS "Presale Engineer",
            priority AS "Priority",
            request_status AS "Status",
            deadline AS "Deadline",
            requested_time AS "Requested Date",
            note AS "Notes"
        FROM technical_support_requests
        WHERE project_name = ?
        ORDER BY requested_time DESC
    """
    df_rfts = pd.read_sql_query(rfts_query, conn, params=(project_name,))
    
    
    # Query to fetch PO Items for all POs in this project
    po_items_query = """
        SELECT 
            poi.po_number AS "PO Number",
            poi.item_number AS "Item #",
            poi.part_number AS "Part Number",
            poi.description AS "Description",
            poi.quantity AS "Quantity",
            poi.unit_price AS "Unit Price (SAR)",
            poi.total_price AS "Total Price (SAR)",
            poi.quantity_delivered AS "Qty Delivered",
            poi.delivery_status AS "Delivery Status",
            poi.delivery_date AS "Delivery Date",
            poi.notes AS "Notes"
        FROM po_items poi
        WHERE poi.po_number IN (
            SELECT po_number FROM purchase_orders WHERE project_name = ?
        )
        ORDER BY poi.po_number, poi.item_number
    """
    df_po_items = pd.read_sql_query(po_items_query, conn, params=(project_name,))
    conn.close()
    
    total_quotation_value = df_quotations['Selling Price (SAR)'].sum() if not df_quotations.empty else 0
    total_po_value = df_pos['Total Amount (SAR)'].sum() if not df_pos.empty else 0
    
    output = BytesIO()
    with pd.ExcelWriter(output, engine='xlsxwriter') as writer:
        workbook = writer.book
        
        title_format = workbook.add_format({
            'bold': True, 'font_name': FONT_NAME, 'font_size': 16, 'font_color': '#667eea'
        })
        subtitle_format = workbook.add_format({
            'font_name': FONT_NAME, 'font_size': 11, 'font_color': '#666666'
        })
        label_format = workbook.add_format({
            'bold': True, 'font_name': FONT_NAME, 'font_size': 10, 'bg_color': '#f0f0f0', 'border': 1
        })
        value_format = workbook.add_format({
            'font_name': FONT_NAME, 'font_size': 10, 'border': 1
        })
        
        summary_sheet = workbook.add_worksheet('Project Summary')
        summary_sheet.set_column('A:A', 25)
        summary_sheet.set_column('B:B', 45)
        
        summary_sheet.write('A1', f'Project Profile: {project_name}', title_format)
        summary_sheet.write('A2', f'Stage: {project["stage"] or "N/A"} | Probability: {project["probability"] or 0}%', subtitle_format)
        
        summary_data = [
            ('Sales Engineer', project['sales_engineer_name'] or 'N/A'),
            ('End User', project['end_user_name'] or 'N/A'),
            ('Contractor', project['contractor_name'] or 'No Contractor'),
            ('Consultant', project['consultant_name'] or 'No Consultant'),
            ('Expected Close Date', project['expected_close_date'] or 'N/A'),
            ('Deal Value', f"SAR {project['deal_value'] or 0:,.2f}"),
            ('Scope of Work', project['scope_of_work'] or 'N/A'),
        ]
        
        row = 4
        for label, value in summary_data:
            summary_sheet.write(row, 0, label, label_format)
            summary_sheet.write(row, 1, str(value) if value else '', value_format)
            row += 1
        
        row += 2
        summary_sheet.write(row, 0, 'Statistics', title_format)
        row += 1
        stats = [
            ('Total Quotations', len(df_quotations)),
            ('Total Quotation Value', f"SAR {total_quotation_value:,.2f}"),
            ('Total RFQs', len(df_rfqs)),
            ('Total Purchase Orders', len(df_pos)),
            ('Total PO Value', f"SAR {total_po_value:,.2f}"),
        ]
        for label, value in stats:
            summary_sheet.write(row, 0, label, label_format)
            summary_sheet.write(row, 1, str(value), value_format)
            row += 1
        
        green_header = workbook.add_format({
            'bold': True, 'font_name': FONT_NAME, 'font_size': 11,
            'bg_color': '#28a745', 'font_color': 'white', 'border': 1, 'align': 'center', 'valign': 'vcenter'
        })
        df_quotations.to_excel(writer, sheet_name='Quotations', index=False, startrow=1)
        ws_quot = writer.sheets['Quotations']
        ws_quot.write('A1', f'Quotations for {project_name}', title_format)
        for col_num, col_name in enumerate(df_quotations.columns):
            ws_quot.write(1, col_num, col_name, green_header)
        for idx, col in enumerate(df_quotations.columns):
            max_len = max(df_quotations[col].astype(str).map(len).max() if len(df_quotations) > 0 else 10, len(str(col)))
            ws_quot.set_column(idx, idx, min(max_len + 2, 40))
        
        yellow_header = workbook.add_format({
            'bold': True, 'font_name': FONT_NAME, 'font_size': 11,
            'bg_color': '#ffc107', 'font_color': '#333333', 'border': 1, 'align': 'center', 'valign': 'vcenter'
        })
        df_rfqs.to_excel(writer, sheet_name='RFQs', index=False, startrow=1)
        ws_rfq = writer.sheets['RFQs']
        ws_rfq.write('A1', f'RFQs for {project_name}', title_format)
        for col_num, col_name in enumerate(df_rfqs.columns):
            ws_rfq.write(1, col_num, col_name, yellow_header)
        for idx, col in enumerate(df_rfqs.columns):
            max_len = max(df_rfqs[col].astype(str).map(len).max() if len(df_rfqs) > 0 else 10, len(str(col)))
            ws_rfq.set_column(idx, idx, min(max_len + 2, 40))
        
        red_header = workbook.add_format({
            'bold': True, 'font_name': FONT_NAME, 'font_size': 11,
            'bg_color': '#dc3545', 'font_color': 'white', 'border': 1, 'align': 'center', 'valign': 'vcenter'
        })
        df_pos.to_excel(writer, sheet_name='Purchase Orders', index=False, startrow=1)
        ws_po = writer.sheets['Purchase Orders']
        ws_po.write('A1', f'Purchase Orders for {project_name}', title_format)
        for col_num, col_name in enumerate(df_pos.columns):
            ws_po.write(1, col_num, col_name, red_header)
        for idx, col in enumerate(df_pos.columns):
            max_len = max(df_pos[col].astype(str).map(len).max() if len(df_pos) > 0 else 10, len(str(col)))
            ws_po.set_column(idx, idx, min(max_len + 2, 40))
        
        
        # PO Items Sheet (detailed line items for each PO)
        if not df_po_items.empty:
            orange_header = workbook.add_format({
                'bold': True, 'font_name': FONT_NAME, 'font_size': 11,
                'bg_color': '#fd7e14', 'font_color': 'white', 'border': 1, 'align': 'center', 'valign': 'vcenter'
            })
            df_po_items.to_excel(writer, sheet_name='PO Items', index=False, startrow=1)
            ws_po_items = writer.sheets['PO Items']
            ws_po_items.write('A1', f'PO Line Items for {project_name}', title_format)
            for col_num, col_name in enumerate(df_po_items.columns):
                ws_po_items.write(1, col_num, col_name, orange_header)
            for idx, col in enumerate(df_po_items.columns):
                max_len = max(df_po_items[col].astype(str).map(len).max() if len(df_po_items) > 0 else 10, len(str(col)))
                ws_po_items.set_column(idx, idx, min(max_len + 2, 45))
        # RFTS Sheet
        purple_header = workbook.add_format({
            'bold': True, 'font_name': FONT_NAME, 'font_size': 11,
            'bg_color': '#6f42c1', 'font_color': 'white', 'border': 1, 'align': 'center', 'valign': 'vcenter'
        })
        df_rfts.to_excel(writer, sheet_name='RFTS', index=False, startrow=1)
        ws_rfts = writer.sheets['RFTS']
        ws_rfts.write('A1', f'Request For Technical Support - {project_name}', title_format)
        for col_num, col_name in enumerate(df_rfts.columns):
            ws_rfts.write(1, col_num, col_name, purple_header)
        for idx, col in enumerate(df_rfts.columns):
            max_len = max(df_rfts[col].astype(str).map(len).max() if len(df_rfts) > 0 else 10, len(str(col)))
            ws_rfts.set_column(idx, idx, min(max_len + 2, 40))
    
    output.seek(0)
    safe_name = "".join(c for c in project_name if c.isalnum() or c in (' ', '-', '_')).strip()
    filename = f'{safe_name}_Project_Data.xlsx'
    
    return send_file(output, 
                     download_name=filename, 
                     as_attachment=True,
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
@app.route('/project/<int:project_id>/export/pptx')
@login_required
def download_project_data_pptx(project_id):
    """Export project profile data to PowerPoint presentation"""
    from pptx import Presentation
    from pptx.util import Inches, Pt
    from pptx.dml.color import RGBColor
    from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
    from pptx.oxml.ns import nsdecls
    from pptx.oxml import parse_xml
    
    FONT_NAME = 'Calibri'
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    cursor.execute("""
        SELECT 
            rp.*,
            eu.name as end_user_name,
            c.name as contractor_name,
            cons.name as consultant_name,
            e.name as sales_engineer_name
        FROM register_project rp
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors c ON rp.contractor_id = c.id
        LEFT JOIN consultants cons ON rp.consultant_id = cons.id
        LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
        WHERE rp.id = ?
    """, (project_id,))
    project = cursor.fetchone()
    
    if not project:
        flash('Project not found!', 'danger')
        conn.close()
        return redirect(url_for('view_projects'))
    
    project_name = project['project_name']
    
    cursor.execute("""
        SELECT * FROM projects WHERE project_name = ? ORDER BY registered_date DESC
    """, (project_name,))
    quotations = cursor.fetchall()
    
    cursor.execute("""
        SELECT * FROM rfq_requests WHERE project_name = ? ORDER BY requested_time DESC
    """, (project_name,))
    rfqs = cursor.fetchall()
    
    cursor.execute("""
        SELECT po.*, d.name as distributor_name, v.name as vendor_name
        FROM purchase_orders po
        LEFT JOIN distributors d ON CAST(po.distributor AS TEXT) = CAST(d.id AS TEXT)
        LEFT JOIN vendors v ON CAST(po.vendor AS TEXT) = CAST(v.id AS TEXT)
        WHERE CAST(po.project_name AS TEXT) = CAST(? AS TEXT)
        ORDER BY po.created_at DESC
    """, (project_name,))
    purchase_orders = cursor.fetchall()
    
    cursor.execute("""
        SELECT rfpo.*, d.name as distributor_name, v.name as vendor_name
        FROM po_requests rfpo
        LEFT JOIN distributors d ON CAST(rfpo.distributor_id AS TEXT) = CAST(d.id AS TEXT)
        LEFT JOIN vendors v ON rfpo.vendor_id = v.id
        WHERE rfpo.project_name = ?
        ORDER BY rfpo.requested_time DESC
    """, (project_name,))
    po_requests = cursor.fetchall()
    
    # Get RFTS (Request for Technical Support)
    cursor.execute("""
        SELECT * FROM technical_support_requests
        WHERE project_name = ?
        ORDER BY requested_time DESC
    """, (project_name,))
    rfts_requests = cursor.fetchall()
    
    conn.close()
    
    total_quotation_value = sum(float(q['quotation_selling_price'] or 0) or 0 for q in quotations)
    total_po_value = sum(po['total_amount'] or 0 for po in purchase_orders)
    
    prs = Presentation()
    prs.slide_width = Inches(13.333)
    prs.slide_height = Inches(7.5)
    
    def add_styled_text(cell, text, bold=False, size=10):
        cell.text = str(text) if text else ''
        for paragraph in cell.text_frame.paragraphs:
            paragraph.font.name = FONT_NAME
            paragraph.font.size = Pt(size)
            paragraph.font.bold = bold
            paragraph.alignment = PP_ALIGN.LEFT
        cell.vertical_anchor = MSO_ANCHOR.MIDDLE
    
    def set_cell_bg(cell, color_hex):
        cell_xml = cell._tc
        cell_xml.get_or_add_tcPr()
        cell_xml.tcPr.append(parse_xml(
            f'<a:solidFill {nsdecls("a")}><a:srgbClr val="{color_hex}"/></a:solidFill>'
        ))
    
    slide_layout = prs.slide_layouts[6]
    
    FONT_NAME = "Calibri"
    slide = prs.slides.add_slide(slide_layout)
    
    title_box = slide.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(12), Inches(0.8))
    title_frame = title_box.text_frame
    title_para = title_frame.paragraphs[0]
    title_para.text = f"Project Profile: {project_name}"
    title_para.font.name = FONT_NAME
    title_para.font.size = Pt(28)
    title_para.font.bold = True
    title_para.font.color.rgb = RGBColor(0x66, 0x7E, 0xEA)
    
    subtitle_box = slide.shapes.add_textbox(Inches(0.5), Inches(1.1), Inches(12), Inches(0.4))
    subtitle_frame = subtitle_box.text_frame
    subtitle_para = subtitle_frame.paragraphs[0]
    subtitle_para.text = f"Stage: {project['stage'] or 'N/A'} | Probability: {project['probability'] or 0}%"
    subtitle_para.font.name = FONT_NAME
    subtitle_para.font.size = Pt(14)
    subtitle_para.font.color.rgb = RGBColor(0x64, 0x64, 0x64)
    
    info_table = slide.shapes.add_table(6, 2, Inches(0.5), Inches(1.8), Inches(5.5), Inches(2.5)).table
    info_data = [
        ('Sales Engineer', project['sales_engineer_name'] or 'N/A'),
        ('End User', project['end_user_name'] or 'N/A'),
        ('Contractor', project['contractor_name'] or 'No Contractor'),
        ('Consultant', project['consultant_name'] or 'No Consultant'),
        ('Expected Close', project['expected_close_date'] or 'N/A'),
        ('Deal Value', f"SAR {project['deal_value'] or 0:,.2f}"),
    ]
    for i, (label, value) in enumerate(info_data):
        set_cell_bg(info_table.cell(i, 0), "667eea")
        add_styled_text(info_table.cell(i, 0), label, bold=True, size=11)
        info_table.cell(i, 0).text_frame.paragraphs[0].font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
        add_styled_text(info_table.cell(i, 1), value, size=11)
    
    stats_table = slide.shapes.add_table(5, 2, Inches(6.5), Inches(1.8), Inches(4.5), Inches(2.1)).table
    stats_data = [
        ('Quotations', len(quotations)),
        ('Total Quotation Value', f"SAR {total_quotation_value:,.2f}"),
        ('RFQs', len(rfqs)),
        ('PO Requests', len(po_requests)),
        ('Purchase Orders', f"{len(purchase_orders)} (SAR {total_po_value:,.2f})"),
    ]
    for i, (label, value) in enumerate(stats_data):
        set_cell_bg(stats_table.cell(i, 0), "28a745")
        add_styled_text(stats_table.cell(i, 0), label, bold=True, size=11)
        stats_table.cell(i, 0).text_frame.paragraphs[0].font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
        add_styled_text(stats_table.cell(i, 1), str(value), size=11)
    
    scope_box = slide.shapes.add_textbox(Inches(0.5), Inches(4.5), Inches(10), Inches(0.8))
    scope_frame = scope_box.text_frame
    scope_para = scope_frame.paragraphs[0]
    scope_para.text = f"Scope of Work: {project['scope_of_work'] or 'N/A'}"
    scope_para.font.name = FONT_NAME
    scope_para.font.size = Pt(12)
    
    if quotations:
        slide2 = prs.slides.add_slide(slide_layout)
        q_title = slide2.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(12), Inches(0.6))
        q_title_frame = q_title.text_frame
        q_title_para = q_title_frame.paragraphs[0]
        q_title_para.text = f"Quotations ({len(quotations)})"
        q_title_para.font.name = FONT_NAME
        q_title_para.font.size = Pt(24)
        q_title_para.font.bold = True
        q_title_para.font.color.rgb = RGBColor(0x28, 0xA7, 0x45)
        
        headers = ['Quote Ref', 'System', 'Presale Eng', 'Sales Eng', 'Cost', 'Selling Price', 'Margin', 'Status']
        rows_to_show = min(len(quotations), 12)
        q_table = slide2.shapes.add_table(rows_to_show + 1, len(headers), Inches(0.3), Inches(1), Inches(12.5), Inches(5.5)).table
        
        for j, header in enumerate(headers):
            set_cell_bg(q_table.cell(0, j), "28a745")
            add_styled_text(q_table.cell(0, j), header, bold=True, size=10)
            q_table.cell(0, j).text_frame.paragraphs[0].font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
        
        for i, q in enumerate(quotations[:rows_to_show]):
            row_data = [
                q['quote_ref'] or '',
                q['system'] or '',
                q['presale_eng'] or '',
                q['sales_eng'] or '',
                f"SAR {q['quotation_cost'] or 0:,.2f}",
                f"SAR {q['quotation_selling_price'] or 0:,.2f}",
                f"{q['margin'] or 0}%",
                q['status'] or ''
            ]
            for j, val in enumerate(row_data):
                add_styled_text(q_table.cell(i + 1, j), val, size=9)
    
    if rfqs:
        slide3 = prs.slides.add_slide(slide_layout)
        r_title = slide3.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(12), Inches(0.6))
        r_title_frame = r_title.text_frame
        r_title_para = r_title_frame.paragraphs[0]
        r_title_para.text = f"RFQs ({len(rfqs)})"
        r_title_para.font.name = FONT_NAME
        r_title_para.font.size = Pt(24)
        r_title_para.font.bold = True
        r_title_para.font.color.rgb = RGBColor(0xFF, 0xC1, 0x07)
        
        headers = ['RFQ Reference', 'Status', 'Priority', 'Presale Eng', 'Sales Eng', 'Deadline', 'Age', 'RFQ Status']
        rows_to_show = min(len(rfqs), 12)
        r_table = slide3.shapes.add_table(rows_to_show + 1, len(headers), Inches(0.3), Inches(1), Inches(12.5), Inches(5.5)).table
        
        for j, header in enumerate(headers):
            set_cell_bg(r_table.cell(0, j), "ffc107")
            add_styled_text(r_table.cell(0, j), header, bold=True, size=10)
        
        for i, r in enumerate(rfqs[:rows_to_show]):
            age_days = ''
            if r['requested_time']:
                try:
                    from datetime import datetime
                    req_date = datetime.strptime(str(r['requested_time'])[:10], '%Y-%m-%d')
                    age_days = f"{(datetime.now() - req_date).days} days"
                except:
                    age_days = ''
            row_data = [
                r['rfq_reference'] or '',
                r['project_status'] or '',
                r['priority'] or '',
                r['sales_engineer_presale'] or '',
                r['sales_engineer_sales'] or '',
                r['deadline'] or '',
                age_days,
                r['rfq_status'] or ''
            ]
            for j, val in enumerate(row_data):
                add_styled_text(r_table.cell(i + 1, j), val, size=9)
    
    if purchase_orders:
        slide4 = prs.slides.add_slide(slide_layout)
        po_title = slide4.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(12), Inches(0.6))
        po_title_frame = po_title.text_frame
        po_title_para = po_title_frame.paragraphs[0]
        po_title_para.text = f"Purchase Orders ({len(purchase_orders)})"
        po_title_para.font.name = FONT_NAME
        po_title_para.font.size = Pt(24)
        po_title_para.font.bold = True
        po_title_para.font.color.rgb = RGBColor(0xDC, 0x35, 0x45)
        
        headers = ['PO Reference', 'Distributor', 'Vendor', 'System', 'Amount', 'Approval', 'Delivery']
        rows_to_show = min(len(purchase_orders), 12)
        po_table = slide4.shapes.add_table(rows_to_show + 1, len(headers), Inches(0.3), Inches(1), Inches(12.5), Inches(5.5)).table
        
        for j, header in enumerate(headers):
            set_cell_bg(po_table.cell(0, j), "dc3545")
            add_styled_text(po_table.cell(0, j), header, bold=True, size=10)
            po_table.cell(0, j).text_frame.paragraphs[0].font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
        
        for i, po in enumerate(purchase_orders[:rows_to_show]):
            row_data = [
                po['po_number'] or '',
                po['distributor_name'] or '',
                po['vendor_name'] or '',
                po['system'] or '',
                f"SAR {po['total_amount'] or 0:,.2f}",
                po['po_approval_status'] or '',
                po['po_delivery_status'] or ''
            ]
            for j, val in enumerate(row_data):
                add_styled_text(po_table.cell(i + 1, j), val, size=9)
    
    # RFTS Slide
    if rfts_requests:
        slide5 = prs.slides.add_slide(slide_layout)
        rfts_title = slide5.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(12), Inches(0.6))
        rfts_title_frame = rfts_title.text_frame
        rfts_title_para = rfts_title_frame.paragraphs[0]
        rfts_title_para.text = f"Request For Technical Support ({len(rfts_requests)})"
        rfts_title_para.font.name = FONT_NAME
        rfts_title_para.font.size = Pt(24)
        rfts_title_para.font.bold = True
        rfts_title_para.font.color.rgb = RGBColor(0x6F, 0x42, 0xC1)
        
        headers = ['RFTS Ref', 'System', 'Request Type', 'Presale Eng', 'Priority', 'Status', 'Deadline']
        rows_to_show = min(len(rfts_requests), 12)
        rfts_table = slide5.shapes.add_table(rows_to_show + 1, len(headers), Inches(0.3), Inches(1), Inches(12.5), Inches(5.5)).table
        
        for j, header in enumerate(headers):
            set_cell_bg(rfts_table.cell(0, j), "6f42c1")
            add_styled_text(rfts_table.cell(0, j), header, bold=True, size=10)
            rfts_table.cell(0, j).text_frame.paragraphs[0].font.color.rgb = RGBColor(0xFF, 0xFF, 0xFF)
        
        for i, rfts in enumerate(rfts_requests[:rows_to_show]):
            row_data = [
                rfts['rfts_reference'] or '',
                rfts['system'] or '',
                rfts['request_type'] or '',
                rfts['presale_engineer'] or '',
                rfts['priority'] or '',
                rfts['request_status'] or '',
                rfts['deadline'] or ''
            ]
            for j, val in enumerate(row_data):
                add_styled_text(rfts_table.cell(i + 1, j), val, size=9)
    
    output = BytesIO()
    prs.save(output)
    output.seek(0)
    
    safe_name = "".join(c for c in project_name if c.isalnum() or c in (' ', '-', '_')).strip()
    filename = f'{safe_name}_Project_Profile.pptx'
    
    return send_file(output, 
                     download_name=filename, 
                     as_attachment=True,
                     mimetype='application/vnd.openxmlformats-officedocument.presentationml.presentation')

@app.route('/charts')
def charts():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Fetch total won cost by summing all quotation costs
    c.execute("""
        SELECT SUM(quotation_cost) FROM projects WHERE status='WON'
    """)
    total_won_cost = c.fetchone()[0] or 0  # Default to 0 if None

    # Fetch all projects with their quote references, costs, and engineers
    c.execute("""
        SELECT quote_ref, quotation_cost, sales_eng, presale_eng
        FROM projects
        WHERE status='WON'
    """)
    won_projects = c.fetchall()
    conn.close()

    # Prepare data for the chart
    labels = [row[0] for row in won_projects]
    data = [row[1] for row in won_projects]
    sales_eng = [row[2] for row in won_projects]
    presale_eng = [row[3] for row in won_projects]

    return render_template('charts.html', labels=labels, data=data,
                           sales_eng=sales_eng, presale_eng=presale_eng,
                           total_won_cost=total_won_cost)
