def _merge_preqal_pdf(main_buf, sections):
    """Merge the Pre-Qualification PDF (local upload) into the main PDF after the
    Company Profile section separator (page index 2 = cover + index + first separator)."""
    import io as _mio, os as _os
    try:
        # 1. Check for locally uploaded pre-qual PDF first (most reliable)
        local_path = _os.path.join('static', 'company_docs', 'prequalification.pdf')
        if _os.path.exists(local_path):
            with open(local_path, 'rb') as _lf:
                preq_bytes = _lf.read()
        else:
            # 2. Fallback: try to fetch from DB URL
            import sqlite3 as _msql, requests as _mreq, re as _re
            _conn = _msql.connect('ProjectStatus.db')
            _cur  = _conn.cursor()
            _cur.execute("SELECT content FROM company_profile_content WHERE section_key='doc_prequalification_url'")
            _row  = _cur.fetchone()
            _conn.close()
            if not _row or not _row[0]:
                return main_buf
            url = _row[0].strip()
            gd_match = _re.search(r'/file/d/([A-Za-z0-9_\-]+)', url)
            if gd_match:
                file_id = gd_match.group(1)
                url = f'https://drive.google.com/uc?export=download&id={file_id}'
            try:
                _sess = _mreq.Session()
                _resp = _sess.get(url, stream=True, timeout=15)
                if 'text/html' in _resp.headers.get('Content-Type', ''):
                    _token = None
                    for key, val in _resp.cookies.items():
                        if key.startswith('download_warning'):
                            _token = val
                            break
                    if _token:
                        _resp = _sess.get(url + f'&confirm={_token}', stream=True, timeout=30)
                if _resp.status_code != 200:
                    return main_buf
                preq_bytes = _resp.content
            except Exception:
                return main_buf

        if not preq_bytes or not preq_bytes.startswith(b'%PDF'):
            return main_buf

        # 4. Find the Company Profile section index (0-based in sections list)
        # Page layout: cover(1) + index(1) + section_separators(1 each)
        # The first non-closing section → cover + index + 1 page = insert after page index 2
        cp_section_idx = 0   # Company Profile is always the first section
        insert_after_page = 1 + 1 + cp_section_idx   # 0-indexed: page 2

        # 5. Merge using pypdf
        from pypdf import PdfReader, PdfWriter
        reader_main = PdfReader(_mio.BytesIO(main_buf.read() if hasattr(main_buf, 'read') else main_buf))
        reader_preq = PdfReader(_mio.BytesIO(preq_bytes))

        writer = PdfWriter()
        n_main = len(reader_main.pages)

        # Pages 0 .. insert_after_page (inclusive)
        for i in range(min(insert_after_page + 1, n_main)):
            writer.add_page(reader_main.pages[i])

        # All pre-qualification pages
        for pg in reader_preq.pages:
            writer.add_page(pg)

        # Remaining main pages
        for i in range(insert_after_page + 1, n_main):
            writer.add_page(reader_main.pages[i])

        out = _mio.BytesIO()
        writer.write(out)
        out.seek(0)
        return out

    except Exception as _me:
        import traceback as _tb
        print("[merge_preqal] WARNING: " + str(_me) + "\n" + _tb.format_exc())
        # Non-fatal — return original PDF on any error
        if hasattr(main_buf, 'seek'):
            main_buf.seek(0)
        return main_buf


@app.route('/proposal_generator/upload_stamp', methods=['POST'])
@login_required
def upload_stamp():
    """Upload a custom stamp image to overlay on Technical Submittal PDFs."""
    f = request.files.get('stamp_file')
    if not f or not f.filename:
        return jsonify({'success': False, 'error': 'No file provided'}), 400
    import os
    allowed = {'.png', '.jpg', '.jpeg', '.gif', '.webp'}
    ext = os.path.splitext(f.filename)[1].lower()
    if ext not in allowed:
        return jsonify({'success': False, 'error': 'Image files only'}), 400
    save_dir = os.path.join('static', 'company_docs')
    os.makedirs(save_dir, exist_ok=True)
    save_path = os.path.join(save_dir, 'stamp.png')
    # Convert to PNG with transparent background using Pillow
    try:
        from PIL import Image as _PIL
        img = _PIL.open(f)
        img = img.convert('RGBA')
        datas = img.getdata()
        new_data = []
        for item in datas:
            r, g, b, a = item
            # Make near-white pixels transparent
            if r > 220 and g > 220 and b > 220:
                new_data.append((255, 255, 255, 0))
            else:
                new_data.append(item)
        img.putdata(new_data)
        img.save(save_path, 'PNG')
    except Exception:
        f.seek(0)
        f.save(save_path)
    return jsonify({'success': True, 'message': 'Stamp uploaded successfully'})


def _apply_stamp_and_page_numbers(pdf_buf, rfq_ref, add_stamp=True, add_page_num=True):
    """Overlay transparent company stamp and page numbers (Page X of Y) on ALL pages."""
    import io as _sio, os as _sos
    try:
        from pypdf import PdfReader, PdfWriter
        from reportlab.pdfgen import canvas as _rl_canvas
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.units import cm

        raw    = pdf_buf.read() if hasattr(pdf_buf, 'read') else pdf_buf
        reader = PdfReader(_sio.BytesIO(raw))
        total  = len(reader.pages)

        if total == 0:
            return _sio.BytesIO(raw)

        W, H = A4   # 595.28 x 841.89 pts

        # Load and preprocess stamp image (remove white bg if not already done)
        stamp_path  = _sos.path.join('static', 'company_docs', 'stamp.png')
        stamp_bytes = None
        if add_stamp and _sos.path.exists(stamp_path):
            try:
                from PIL import Image as _PILI
                _simg = _PILI.open(stamp_path).convert('RGBA')
                _sdata = _simg.getdata()
                _new   = []
                for r, g, b, a in _sdata:
                    _new.append((r, g, b, 0) if (r > 220 and g > 220 and b > 220) else (r, g, b, a))
                _simg.putdata(_new)
                _sbuf = _sio.BytesIO()
                _simg.save(_sbuf, 'PNG')
                _sbuf.seek(0)
                stamp_bytes = _sbuf.read()
            except Exception:
                with open(stamp_path, 'rb') as _sf:
                    stamp_bytes = _sf.read()

        writer = PdfWriter()

        for page_num, page in enumerate(reader.pages, start=1):
            # Detect actual page size from PDF
            try:
                pw = float(page.mediabox.width)
                ph = float(page.mediabox.height)
            except Exception:
                pw, ph = W, H

            # Build overlay PDF for this page
            overlay_buf = _sio.BytesIO()
            c = _rl_canvas.Canvas(overlay_buf, pagesize=(pw, ph))

            # ── Transparent stamp (bottom-right corner) ──────────────────────
            if add_stamp and stamp_bytes:
                stamp_size = min(pw * 0.18, 4.5 * cm)
                sx = pw - stamp_size - 1.2 * cm
                sy = 0.8 * cm
                try:
                    from reportlab.lib.utils import ImageReader
                    _stamp_io = _sio.BytesIO(stamp_bytes)
                    _stamp_reader = ImageReader(_stamp_io)
                    c.saveState()
                    c.setFillAlpha(0.35)
                    c.drawImage(_stamp_reader, sx, sy, width=stamp_size, height=stamp_size,
                                mask='auto', preserveAspectRatio=True)
                    c.restoreState()
                except Exception:
                    pass

            # ── Page number (bottom center) ──────────────────────────────────
            if add_page_num:
                c.saveState()
                c.setFont('Helvetica', 8)
                c.setFillColorRGB(0.45, 0.45, 0.45)
                c.drawCentredString(pw / 2, 0.55 * cm, f'Page {page_num} of {total}')
                c.restoreState()

            c.save()
            overlay_buf.seek(0)

            overlay_reader = PdfReader(overlay_buf)
            page.merge_page(overlay_reader.pages[0])
            writer.add_page(page)

        out = _sio.BytesIO()
        writer.write(out)
        out.seek(0)
        return out

    except Exception as _e:
        import traceback as _tb
        print(f"[stamp] WARNING: {_e}\n{_tb.format_exc()}")
        if hasattr(pdf_buf, 'seek'):
            pdf_buf.seek(0)
        return pdf_buf


def _merge_all_section_pdfs(main_buf, sections, rfq_ref, vendor):
    """Merge pre-qualification PDF (after section 1 separator) and any uploaded
    section PDFs (after each vendor section separator) into the main PDF.

    Page layout of main_buf BEFORE merging:
      [0] Cover
      [1] Index
      [2] Separator for sections_with_sep[0]  (= Company Profile)
      [3] Separator for sections_with_sep[1]  (= first vendor section)
      ...
    """
    import io as _io, os as _os, re as _re
    try:
        from pypdf import PdfReader, PdfWriter

        # Identify sections that have separator pages (not no_separator, not closing)
        main_secs       = [s for s in sections if not s.get('closing')]
        secs_with_sep   = [s for s in main_secs if not s.get('no_separator')]

        if not secs_with_sep:
            return main_buf

        # --- Load main PDF ---
        raw = main_buf.read() if hasattr(main_buf, 'read') else main_buf
        reader_main = PdfReader(_io.BytesIO(raw))
        n_main      = len(reader_main.pages)

        # --- Load pre-qual PDF (if available) ---
        local_preqal = _os.path.join('static', 'company_docs', 'prequalification.pdf')
        preqal_pages = []
        if _os.path.exists(local_preqal):
            with open(local_preqal, 'rb') as _f:
                pb = _f.read()
            if pb.startswith(b'%PDF'):
                preqal_pages = list(PdfReader(_io.BytesIO(pb)).pages)
        else:
            # Fallback: try URL from DB (short timeout)
            try:
                import sqlite3 as _sql, requests as _mreq
                _conn = _sql.connect('ProjectStatus.db')
                _cur  = _conn.cursor()
                _cur.execute("SELECT content FROM company_profile_content WHERE section_key='doc_prequalification_url'")
                _row  = _cur.fetchone()
                _conn.close()
                if _row and _row[0]:
                    url = _row[0].strip()
                    gd  = _re.search(r'/file/d/([A-Za-z0-9_\-]+)', url)
                    if gd:
                        url = f'https://drive.google.com/uc?export=download&id={gd.group(1)}'
                    _resp = _mreq.Session().get(url, timeout=8)
                    if _resp.status_code == 200 and _resp.content.startswith(b'%PDF'):
                        preqal_pages = list(PdfReader(_io.BytesIO(_resp.content)).pages)
            except Exception:
                pass

        # --- Load uploaded section PDFs (vendor sections) ---
        safe_ref = _re.sub(r'[^A-Za-z0-9_\-]', '_', rfq_ref or '')
        sec_dir  = _os.path.join('static', 'company_docs', 'sections', safe_ref)

        def _slug(title):
            resolved = title.replace('{vendor}', vendor or '')
            return _re.sub(r'[^a-z0-9]+', '_', resolved.lower()).strip('_')

        # Build mapping: section index in secs_with_sep → uploaded pages
        sec_uploaded = {}
        # Load Company Profile PDF for section idx=0
        company_profile_pdf_path = _os.path.join('static', 'company_docs', 'company_profile.pdf')
        if _os.path.exists(company_profile_pdf_path):
            with open(company_profile_pdf_path, 'rb') as _cf:
                cpb = _cf.read()
            if cpb.startswith(b'%PDF'):
                sec_uploaded[0] = list(PdfReader(_io.BytesIO(cpb)).pages)

        for idx, sec in enumerate(secs_with_sep[1:], start=1):   # skip Company Profile (idx 0)
            sl    = _slug(sec.get('title', ''))
            fpath = _os.path.join(sec_dir, sl + '.pdf')
            if _os.path.exists(fpath):
                with open(fpath, 'rb') as _sf:
                    sb = _sf.read()
                if sb.startswith(b'%PDF'):
                    sec_uploaded[idx] = list(PdfReader(_io.BytesIO(sb)).pages)

        # --- Build merged output ---
        writer = PdfWriter()

        # Cover + Index (pages 0,1)
        for p in range(min(2, n_main)):
            writer.add_page(reader_main.pages[p])

        # For each section with separator, add its separator + injected content
        for sep_idx, sec in enumerate(secs_with_sep):
            main_page_idx = 2 + sep_idx   # separator is at this page in main PDF
            if main_page_idx >= n_main:
                break
            writer.add_page(reader_main.pages[main_page_idx])

            if sep_idx == 0:
                # Company Profile → prefer company_profile.pdf, else fall back to preqal PDF
                cp_pages = sec_uploaded.get(0, preqal_pages)
                for pg in cp_pages:
                    writer.add_page(pg)
            elif sep_idx in sec_uploaded:
                # Vendor section → insert uploaded PDF pages
                for pg in sec_uploaded[sep_idx]:
                    writer.add_page(pg)

        out = _io.BytesIO()
        writer.write(out)
        out.seek(0)
        return out

    except Exception as _e:
        import traceback as _tb
        print(f"[merge_all] WARNING: {_e}\n{_tb.format_exc()}")
        if hasattr(main_buf, 'seek'):
            main_buf.seek(0)
        return main_buf


def _build_technical_submittal_pdf(tech_title, project_name, location, contractor,
                                    consultant, vendor, date_str, quote_ref, rfq_ref, sections,
                                    end_user='', submittal_ref='',
                                    logo_end_user=None, logo_contractor=None, logo_consultant=None,
                                    vendors=None, prep_name='', prep_title='', appr_name='', appr_title=''):
    """Build a Technical Submittal PDF: Cover + Index + Separator per section."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.enums import TA_LEFT, TA_CENTER, TA_RIGHT, TA_JUSTIFY
    from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table,
                                    TableStyle, PageBreak, KeepTogether, HRFlowable)
    from reportlab.platypus import Image as RLImage
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    from io import BytesIO

    W, H = A4
    C_PURPLE  = colors.HexColor('#CC0000')   # EJTech brand red
    C_PURPLE2 = colors.HexColor('#A00000')   # darker red
    C_GOLD    = colors.HexColor('#888888')   # medium gray accent
    C_WHITE   = colors.white
    C_DARK    = colors.HexColor('#333333')   # dark gray text
    C_GREY    = colors.HexColor('#F5F5F5')   # light gray bg
    C_LGREY   = colors.HexColor('#EEEEEE')   # light gray
    C_MGREY   = colors.HexColor('#777777')   # medium gray

    buf = BytesIO()
    LMARGIN = 1.8*cm
    RMARGIN = 1.8*cm
    TMARGIN = 1.5*cm
    BMARGIN = 1.9*cm
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=LMARGIN, rightMargin=RMARGIN,
                            topMargin=TMARGIN, bottomMargin=BMARGIN,
                            title=f"Technical Submittal - {project_name}")
    BW = W - LMARGIN - RMARGIN
    story = []

    def _ps(name, **kw):
        base = ParagraphStyle(name, fontName='Helvetica', fontSize=10, textColor=C_DARK, leading=14)
        for k, v in kw.items(): setattr(base, k, v)
        return base

    def _p(text, style=None):
        return Paragraph(str(text) if text else '', style or _ps('body'))

    # Try to load logo
    try:
        LOGO_PATH = os.path.join(os.path.dirname(__file__), 'static', 'ejt.png')
        logo_img = RLImage(LOGO_PATH, width=3.8*cm, height=1.28*cm)
        logo_img_sm = RLImage(LOGO_PATH, width=2.5*cm, height=0.84*cm)
    except Exception:
        logo_img = _p('<b>EJTech</b>', _ps('lg', fontName='Helvetica-Bold', fontSize=16, textColor=C_PURPLE))
        logo_img_sm = _p('<b>EJTech</b>', _ps('lgsm', fontName='Helvetica-Bold', fontSize=12, textColor=C_PURPLE))

    # ═══════════════════════════ 1. COVER PAGE ════════════════════════════
    # -- Header band: logo left, title right
    hdr_title = Table([
        [_p('TECHNICAL SUBMITTAL', _ps('ht', fontName='Helvetica-Bold', fontSize=14, textColor=C_PURPLE, alignment=TA_RIGHT))],
        [_p('Document Submission Package', _ps('hs', fontSize=8, textColor=C_MGREY, alignment=TA_RIGHT))],
    ], colWidths=[BW - 5.0*cm])
    hdr_title.setStyle(TableStyle([('TOPPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),2)]))

    banner = Table([[logo_img, hdr_title]], colWidths=[4.5*cm, BW - 4.5*cm])
    banner.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),C_WHITE),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('LEFTPADDING',(0,0),(0,-1),8),
        ('RIGHTPADDING',(0,0),(-1,-1),8),
        ('TOPPADDING',(0,0),(-1,-1),14),
        ('BOTTOMPADDING',(0,0),(-1,-1),14),
        ('BOX',(0,0),(-1,-1),0.5,colors.HexColor('#E0E0E0')),
        ('LINEBELOW',(0,0),(-1,-1),3,C_PURPLE),
    ]))
    story.append(banner)

    # Accent line below header
    acc = Table([['','']], colWidths=[BW*0.7, BW*0.3])
    acc.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(0,0),C_GOLD),
        ('BACKGROUND',(1,0),(1,0),C_PURPLE),
        ('TOPPADDING',(0,0),(-1,-1),0),('BOTTOMPADDING',(0,0),(-1,-1),0),
        ('LINEBELOW',(0,0),(-1,-1),3,C_GOLD),
    ]))
    story.append(Table([[acc]], colWidths=[BW],
        style=TableStyle([('TOPPADDING',(0,0),(-1,-1),0),('BOTTOMPADDING',(0,0),(-1,-1),0),
                          ('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),0)])))
    story.append(Spacer(1, 1.2*cm))

    # -- System Type Title box
    sys_title = Table([[
        _p(f'TECHNICAL SUBMITTAL: {tech_title}',
           _ps('syst', fontName='Helvetica-Bold', fontSize=18, textColor=C_WHITE, alignment=TA_CENTER, leading=22))
    ]], colWidths=[BW])
    sys_title.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),C_PURPLE),
        ('PADDING',(0,0),(-1,-1),18),
        ('ALIGN',(0,0),(-1,-1),'CENTER'),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('ROUNDEDCORNERS',[4]),
    ]))
    story.append(sys_title)
    story.append(Spacer(1, 0.8*cm))

    # -- Project Name
    if project_name:
        proj_tbl = Table([[
            _p(project_name, _ps('pname', fontName='Helvetica-Bold', fontSize=22, textColor=C_DARK, alignment=TA_CENTER, leading=26))
        ]], colWidths=[BW])
        proj_tbl.setStyle(TableStyle([
            ('BOTTOMPADDING',(0,0),(-1,-1),4),
            ('LINEBELOW',(0,0),(-1,-1),1.5,C_GOLD),
        ]))
        story.append(proj_tbl)
        story.append(Spacer(1, 0.3*cm))

    # -- Location
    if location:
        story.append(_p(location, _ps('loc', fontSize=11, textColor=C_MGREY, alignment=TA_CENTER, leading=14)))
        story.append(Spacer(1, 1.0*cm))

    # ── Vendor Panel (shown only when vendors supplied) ──────────────────
    if vendors:
        # Helper: make transparent logo (reuse same logic)
        def _v_transparent(logo_buf):
            if not logo_buf:
                return None
            try:
                import io as _io4
                from PIL import Image as PILImage
                logo_buf.seek(0)
                pil = PILImage.open(logo_buf).convert('RGBA')
                data = pil.getdata()
                new_data = []
                for r, g, b, a in data:
                    dist = ((r-255)**2 + (g-255)**2 + (b-255)**2) ** 0.5
                    new_data.append((r, g, b, 0 if dist < 35 else a))
                pil.putdata(new_data)
                out = _io4.BytesIO()
                pil.save(out, format='PNG')
                out.seek(0)
                return out
            except Exception:
                logo_buf.seek(0)
                return logo_buf

        # "VENDORS / MANUFACTURERS" header strip
        v_hdr = Table([[_p('VENDORS  /  MANUFACTURERS',
                            _ps('vh', fontName='Helvetica-Bold', fontSize=9,
                                textColor=C_WHITE, alignment=TA_CENTER, letterSpacing=2))]],
                      colWidths=[BW],
                      style=TableStyle([
                          ('BACKGROUND',    (0,0), (-1,-1), C_PURPLE),
                          ('TOPPADDING',    (0,0), (-1,-1), 6),
                          ('BOTTOMPADDING', (0,0), (-1,-1), 6),
                          ('LEFTPADDING',   (0,0), (-1,-1), 0),
                          ('RIGHTPADDING',  (0,0), (-1,-1), 0),
                      ]))
        story.append(v_hdr)

        # Vendor cards grid — up to 4 per row
        MAX_PER_ROW = min(4, len(vendors))
        VCARD_W     = BW / MAX_PER_ROW
        VCARD_H     = 2.0 * cm
        C_VBG       = colors.HexColor('#FFF5F5')

        def _vendor_card(v):
            vname = v.get('name', '') or ''
            vbuf  = v.get('logo')
            processed = _v_transparent(vbuf) if vbuf else None
            card_rows = []
            if processed:
                try:
                    img = RLImage(processed)
                    iw, ih = img.imageWidth, img.imageHeight
                    mw = VCARD_W - 16
                    mh = VCARD_H * 0.55
                    ratio = min(mw/iw, mh/ih)
                    img.drawWidth  = round(iw*ratio, 2)
                    img.drawHeight = round(ih*ratio, 2)
                    card_rows.append([img])
                except Exception:
                    pass
            if vname:
                card_rows.append([_p(vname, _ps(f'vn_{vname}', fontName='Helvetica-Bold',
                                                  fontSize=8.5, textColor=C_DARK,
                                                  alignment=TA_CENTER, leading=11))])
            if not card_rows:
                return ''
            inner = Table(card_rows, colWidths=[VCARD_W - 8])
            inner.setStyle(TableStyle([
                ('ALIGN',         (0,0), (-1,-1), 'CENTER'),
                ('VALIGN',        (0,0), (-1,-1), 'MIDDLE'),
                ('TOPPADDING',    (0,0), (-1,-1), 4),
                ('BOTTOMPADDING', (0,0), (-1,-1), 4),
                ('LEFTPADDING',   (0,0), (-1,-1), 4),
                ('RIGHTPADDING',  (0,0), (-1,-1), 4),
            ]))
            wrap = Table([[inner]], colWidths=[VCARD_W])
            wrap.setStyle(TableStyle([
                ('BOX',          (0,0), (-1,-1), 0.5, colors.HexColor('#DDDDDD')),
                ('BACKGROUND',   (0,0), (-1,-1), C_VBG),
                ('TOPPADDING',   (0,0), (-1,-1), 4),
                ('BOTTOMPADDING',(0,0), (-1,-1), 4),
                ('LEFTPADDING',  (0,0), (-1,-1), 0),
                ('RIGHTPADDING', (0,0), (-1,-1), 0),
            ]))
            return wrap

        # Chunk vendors into rows of MAX_PER_ROW
        for chunk_start in range(0, len(vendors), MAX_PER_ROW):
            chunk = vendors[chunk_start:chunk_start+MAX_PER_ROW]
            # Pad to fill row
            while len(chunk) < MAX_PER_ROW:
                chunk.append({'name': '', 'logo': None})
            row_cells  = [_vendor_card(v) for v in chunk]
            vendor_row = Table([row_cells], colWidths=[VCARD_W] * MAX_PER_ROW)
            vendor_row.setStyle(TableStyle([
                ('TOPPADDING',    (0,0), (-1,-1), 0),
                ('BOTTOMPADDING', (0,0), (-1,-1), 0),
                ('LEFTPADDING',   (0,0), (-1,-1), 0),
                ('RIGHTPADDING',  (0,0), (-1,-1), 0),
                ('BOX',           (0,0), (-1,-1), 0.5, colors.HexColor('#E0E0E0')),
            ]))
            story.append(vendor_row)

        story.append(Spacer(1, 0.5*cm))

    # ── Info block: professional card with transparent logos ─────────────
    C_RED_LIGHT = colors.HexColor('#FFF5F5')
    C_BORDER    = colors.HexColor('#E8E8E8')
    LBL_W = BW * 0.26
    VAL_W = BW * 0.44
    LOG_W = BW * 0.30

    def _make_transparent_logo(logo_buf, bg_rgb=(255, 255, 255), threshold=30):
        """Use Pillow to remove near-white background and return a PNG BytesIO."""
        try:
            import io as _io3
            from PIL import Image as PILImage
            logo_buf.seek(0)
            pil = PILImage.open(logo_buf).convert('RGBA')
            data = pil.getdata()
            new_data = []
            br, bg, bb = bg_rgb
            for r, g, b, a in data:
                dist = ((r-br)**2 + (g-bg)**2 + (b-bb)**2) ** 0.5
                if dist < threshold:
                    new_data.append((r, g, b, 0))
                else:
                    new_data.append((r, g, b, a))
            pil.putdata(new_data)
            out = _io3.BytesIO()
            pil.save(out, format='PNG')
            out.seek(0)
            return out
        except Exception:
            logo_buf.seek(0)
            return logo_buf

    def _logo_cell(logo_buf):
        """Return an RLImage scaled to fit neatly, transparent background."""
        if not logo_buf:
            return ''
        try:
            processed = _make_transparent_logo(logo_buf)
            img = RLImage(processed)
            iw, ih = img.imageWidth, img.imageHeight
            max_w = LOG_W - 16
            max_h = 1.3 * cm
            ratio = min(max_w / iw, max_h / ih)
            img.drawWidth  = round(iw * ratio, 2)
            img.drawHeight = round(ih * ratio, 2)
            return img
        except Exception:
            return ''

    # Build company rows (with logo) and meta rows (ref/date)
    company_rows = []   # (label, text, logo_buf)
    if end_user:
        company_rows.append(('End User:',    end_user,    logo_end_user))
    if contractor:
        company_rows.append(('Contractor:',  contractor,  logo_contractor))
    if consultant:
        company_rows.append(('Consultant:',  consultant,  logo_consultant))

    meta_rows = []
    if submittal_ref:
        meta_rows.append(('Submittal Ref.:', submittal_ref))
    if date_str:
        meta_rows.append(('Date:',           date_str))

    all_rows  = []
    hi_rows   = []

    for lbl, val, lbuf in company_rows:
        all_rows.append([
            _p(lbl, _ps(f'lbl_{lbl}', fontName='Helvetica-Bold', fontSize=9.5,
                        textColor=C_PURPLE, alignment=TA_RIGHT)),
            _p(val, _ps(f'val_{lbl}', fontName='Helvetica-Bold', fontSize=10.5,
                        textColor=C_DARK)),
            _logo_cell(lbuf),
        ])
        hi_rows.append(len(all_rows) - 1)

    if company_rows and meta_rows:
        # Thin divider row between company info and meta info
        all_rows.append(['', '', ''])

    for lbl, val in meta_rows:
        all_rows.append([
            _p(lbl, _ps(f'lbl_{lbl}', fontName='Helvetica-Bold', fontSize=8.5,
                        textColor=C_MGREY, alignment=TA_RIGHT)),
            _p(val, _ps(f'val_{lbl}', fontSize=8.5, textColor=colors.HexColor('#555555'))),
            '',
        ])

    if all_rows:
        info_tbl = Table(all_rows, colWidths=[LBL_W, VAL_W, LOG_W])
        style_cmds = [
            ('BACKGROUND',    (0, 0), (-1, -1), colors.white),
            ('LEFTPADDING',   (0, 0), (0, -1),  12),
            ('RIGHTPADDING',  (0, 0), (0, -1),  10),
            ('LEFTPADDING',   (1, 0), (1, -1),  10),
            ('LEFTPADDING',   (2, 0), (2, -1),  8),
            ('RIGHTPADDING',  (2, 0), (2, -1),  10),
            ('TOPPADDING',    (0, 0), (-1, -1), 9),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 9),
            ('VALIGN',        (0, 0), (-1, -1), 'MIDDLE'),
            ('ALIGN',         (2, 0), (2, -1),  'RIGHT'),
            ('BOX',           (0, 0), (-1, -1), 0.6, C_BORDER),
            ('LINEBEFORE',    (0, 0), (0, -1),  4,   C_PURPLE),
        ]
        # Faint red highlight on company rows
        for i in hi_rows:
            style_cmds.append(('BACKGROUND', (0, i), (-1, i), C_RED_LIGHT))
        # Row separators
        for i in range(len(all_rows) - 1):
            style_cmds.append(('LINEBELOW', (0, i), (-1, i), 0.4, C_BORDER))
        # Divider row (between company & meta) gets special treatment
        if company_rows and meta_rows:
            div_i = len(company_rows)
            style_cmds += [
                ('TOPPADDING',    (0, div_i), (-1, div_i), 0),
                ('BOTTOMPADDING', (0, div_i), (-1, div_i), 0),
                ('LINEABOVE',     (0, div_i), (-1, div_i), 0.8, colors.HexColor('#DDDDDD')),
            ]
        info_tbl.setStyle(TableStyle(style_cmds))
        story.append(info_tbl)

    # ── Prepared By / Approved By — professional signature cards ─────────
    story.append(Spacer(1, 0.7*cm))

    GAP   = 0.35*cm
    CW    = (BW - GAP) / 2

    def _sig_card(label, name, title):
        # Red header band (row 0)
        hdr = Table([[_p(label.upper(),
                         _ps(f'sh_{label}', fontName='Helvetica-Bold', fontSize=9,
                             textColor=C_WHITE, alignment=TA_CENTER, letterSpacing=1.5))]],
                    colWidths=[CW],
                    style=TableStyle([
                        ('BACKGROUND',    (0,0), (-1,-1), C_PURPLE),
                        ('TOPPADDING',    (0,0), (-1,-1), 8),
                        ('BOTTOMPADDING', (0,0), (-1,-1), 8),
                        ('LEFTPADDING',   (0,0), (-1,-1), 0),
                        ('RIGHTPADDING',  (0,0), (-1,-1), 0),
                    ]))

        # Body: name + title centered on white
        body_rows = [
            [_p(name or '—', _ps(f'nm_{label}', fontName='Helvetica-Bold', fontSize=13,
                                  textColor=C_DARK, alignment=TA_CENTER, leading=17,
                                  spaceBefore=12))],
        ]
        if title:
            body_rows.append(
                [_p(title, _ps(f'ti_{label}', fontSize=9, textColor=C_MGREY,
                                alignment=TA_CENTER, spaceAfter=12))]
            )
        else:
            body_rows.append([Spacer(1, 0.35*cm)])

        body = Table(body_rows, colWidths=[CW])
        body.setStyle(TableStyle([
            ('BACKGROUND',    (0,0), (-1,-1), colors.white),
            ('TOPPADDING',    (0,0), (-1,-1), 0),
            ('BOTTOMPADDING', (0,0), (-1,-1), 0),
            ('LEFTPADDING',   (0,0), (-1,-1), 10),
            ('RIGHTPADDING',  (0,0), (-1,-1), 10),
            ('ALIGN',         (0,0), (-1,-1), 'CENTER'),
            ('VALIGN',        (0,0), (-1,-1), 'MIDDLE'),
        ]))

        # Wrap in outer card with border
        card = Table([[hdr], [body]], colWidths=[CW])
        card.setStyle(TableStyle([
            ('BOX',          (0,0), (-1,-1), 0.8, colors.HexColor('#CCCCCC')),
            ('TOPPADDING',   (0,0), (-1,-1), 0),
            ('BOTTOMPADDING',(0,0), (-1,-1), 0),
            ('LEFTPADDING',  (0,0), (-1,-1), 0),
            ('RIGHTPADDING', (0,0), (-1,-1), 0),
        ]))
        return card

    prep_card = _sig_card('Prepared By', prep_name or 'EJTech', prep_title)
    appr_card = _sig_card('Approved By', appr_name, appr_title)

    sig_row = Table([[prep_card, Spacer(GAP, 1), appr_card]],
                    colWidths=[CW, GAP, CW])
    sig_row.setStyle(TableStyle([
        ('VALIGN',       (0,0), (-1,-1), 'TOP'),
        ('TOPPADDING',   (0,0), (-1,-1), 0),
        ('BOTTOMPADDING',(0,0), (-1,-1), 0),
        ('LEFTPADDING',  (0,0), (-1,-1), 0),
        ('RIGHTPADDING', (0,0), (-1,-1), 0),
    ]))
    story.append(sig_row)
    story.append(PageBreak())

    # ═══════════════════════════ 2. INDEX PAGE ════════════════════════════
    # Header
    idx_hdr = Table([[
        _p('INDEX', _ps('idxh', fontName='Helvetica-Bold', fontSize=16, textColor=C_WHITE, alignment=TA_CENTER))
    ]], colWidths=[BW])
    idx_hdr.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),C_PURPLE),
        ('PADDING',(0,0),(-1,-1),14),
    ]))
    story.append(idx_hdr)
    story.append(Spacer(1, 0.4*cm))

    # Two-column index layout
    # We'll split sections into two halves
    main_sections = [s for s in sections if not s.get('closing')]
    closing_secs  = [s for s in sections if s.get('closing')]

    # Build left and right column items
    half = max(1, (len(main_sections) + 1) // 2)
    left_secs  = main_sections[:half]
    right_secs = main_sections[half:]

    def _render_section_col(secs, start_num):
        items = []
        for i, sec in enumerate(secs):
            num     = start_num + i
            title   = sec.get('title', '')
            sub_items = sec.get('subs', [])
            # Replace {vendor} placeholder
            if vendor:
                title = title.replace('{vendor}', vendor)
            # Section header row — clickable link if this section has a separator page
            if not sec.get('no_separator'):
                hdr_markup = f'<b><link href="#sep_{num}" color="#CC0000">{num}-  {title}</link></b>'
            else:
                hdr_markup = f'<b>{num}-  {title}</b>'
            items.append(_p(hdr_markup,
                            _ps(f's{num}', fontName='Helvetica-Bold', fontSize=9,
                                textColor=C_PURPLE, leading=13, spaceAfter=1)))
            # Sub-items
            for sub in sub_items:
                if vendor:
                    sub = sub.replace('{vendor}', vendor)
                items.append(_p(f'    • {sub}',
                                _ps(f'sub{num}', fontSize=8, textColor=C_DARK, leading=11,
                                    leftIndent=8, spaceAfter=0)))
            items.append(Spacer(1, 0.25*cm))
        return items

    left_items  = _render_section_col(left_secs, 1)
    right_items = _render_section_col(right_secs, len(left_secs) + 1)

    # Pad so both columns have same number of flowables
    while len(left_items) < len(right_items):
        left_items.append(Spacer(1, 0.1*cm))
    while len(right_items) < len(left_items):
        right_items.append(Spacer(1, 0.1*cm))

    col_w = (BW - 0.4*cm) / 2
    for l_item, r_item in zip(left_items, right_items):
        row_tbl = Table([[l_item, r_item]], colWidths=[col_w, col_w])
        row_tbl.setStyle(TableStyle([
            ('VALIGN',(0,0),(-1,-1),'TOP'),
            ('LEFTPADDING',(0,0),(-1,-1),4),
            ('RIGHTPADDING',(0,0),(-1,-1),4),
            ('TOPPADDING',(0,0),(-1,-1),0),
            ('BOTTOMPADDING',(0,0),(-1,-1),0),
        ]))
        story.append(row_tbl)

    # Closing section (Get in Touch)
    if closing_secs:
        story.append(Spacer(1, 0.3*cm))
        for sec in closing_secs:
            title = sec.get('title', '')
            if vendor:
                title = title.replace('{vendor}', vendor)
            story.append(_p(f'<b>....... {title}</b>',
                            _ps('closing', fontName='Helvetica-Bold', fontSize=9,
                                textColor=C_PURPLE, alignment=TA_CENTER)))
    story.append(PageBreak())

    # ═══════════════════════ 3. SEPARATOR PAGES ═══════════════════════════
    # One separator per main section (not the closing one)
    # Sections with no_separator=True are part of the pre-qualification merge — skip their separator page
    for i, sec in enumerate(main_sections):
        sec_num   = i + 1
        sec_title = sec.get('title', '')
        if vendor:
            sec_title = sec_title.replace('{vendor}', vendor)

        if sec.get('no_separator'):
            continue  # This section's content is inside the pre-qual PDF — no separator page needed

        # Named anchor for internal PDF links from the index
        from reportlab.platypus.flowables import AnchorFlowable
        story.append(AnchorFlowable(f'sep_{sec_num}'))

        # Full-page separator: purple left strip + white right
        # We simulate a full-page look using a two-column table

        # Left purple strip: section number
        num_cell = Table([[
            _p(str(sec_num),
               _ps(f'sn{sec_num}', fontName='Helvetica-Bold', fontSize=72,
                   textColor=colors.HexColor('#FF8888'), alignment=TA_CENTER, leading=80))
        ]], colWidths=[BW*0.28])
        num_cell.setStyle(TableStyle([
            ('BACKGROUND',(0,0),(-1,-1),C_PURPLE2),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('TOPPADDING',(0,0),(-1,-1),60),
            ('BOTTOMPADDING',(0,0),(-1,-1),60),
            ('LEFTPADDING',(0,0),(-1,-1),4),
            ('RIGHTPADDING',(0,0),(-1,-1),4),
        ]))

        # Right white area: logo + title
        right_inner = []
        right_inner.append(logo_img_sm)
        right_inner.append(Spacer(1, 0.6*cm))
        right_inner.append(HRFlowable(width=BW*0.55, thickness=2, color=C_GOLD, spaceAfter=10))
        right_inner.append(_p(sec_title,
                              _ps(f'st{sec_num}', fontName='Helvetica-Bold', fontSize=22,
                                  textColor=C_PURPLE, leading=28, alignment=TA_LEFT)))
        right_inner.append(Spacer(1, 0.3*cm))
        right_inner.append(HRFlowable(width=BW*0.55, thickness=1, color=C_LGREY, spaceAfter=6))
        right_inner.append(_p('TECHNICAL SUBMITTAL',
                              _ps(f'sub_ts{sec_num}', fontSize=8, textColor=C_MGREY, letterSpacing=1.5)))
        if project_name:
            right_inner.append(_p(project_name,
                                  _ps(f'pn{sec_num}', fontSize=8, textColor=C_MGREY)))

        right_cell = Table([[item] for item in right_inner], colWidths=[BW*0.66])
        right_cell.setStyle(TableStyle([
            ('BACKGROUND',(0,0),(-1,-1),C_WHITE),
            ('VALIGN',(0,0),(-1,-1),'TOP'),
            ('TOPPADDING',(0,0),(0,0),40),
            ('BOTTOMPADDING',(0,0),(-1,-1),6),
            ('LEFTPADDING',(0,0),(-1,-1),20),
            ('RIGHTPADDING',(0,0),(-1,-1),10),
        ]))

        # Combine side-by-side in a page-height table (simulated)
        sep_tbl = Table([[num_cell, right_cell]], colWidths=[BW*0.28, BW*0.72])
        sep_tbl.setStyle(TableStyle([
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('TOPPADDING',(0,0),(-1,-1),0),
            ('BOTTOMPADDING',(0,0),(-1,-1),0),
            ('LEFTPADDING',(0,0),(-1,-1),0),
            ('RIGHTPADDING',(0,0),(-1,-1),0),
            ('BOX',(0,0),(-1,-1),0.5,colors.HexColor('#DDDDDD')),
        ]))
        story.append(sep_tbl)
        story.append(PageBreak())

    doc.build(story)
    buf.seek(0)
    return buf


@app.route('/proposal_generator/generate_excel', methods=['POST'])
@login_required
def proposal_generate_excel():
    """Generate an Excel quotation from the Proposal Generator form data."""
    from flask import request as _req
    try:
        cover = {
            'date':          _req.form.get('date', ''),
            'quoteref':      _req.form.get('quoteref', ''),
            'engref':        _req.form.get('engref', ''),
            'to':            _req.form.get('to', ''),
            'attn':          _req.form.get('attn', ''),
            'frm':           _req.form.get('frm', ''),
            'cont':          _req.form.get('cont', ''),
            'sub':           _req.form.get('sub', ''),
            'scope':         _req.form.get('scope', ''),
            'exec_summary':  _req.form.get('exec_summary', ''),
            'cta_email':     _req.form.get('cta_email', ''),
            'cta_phone':     _req.form.get('cta_phone', ''),
            'cta_body':      _req.form.get('cta_body', ''),
            'prep_by_name':  _req.form.get('prep_by_name', ''),
            'prep_by_title': _req.form.get('prep_by_title', ''),
            'mgr_name':      _req.form.get('mgr_name', ''),
            'mgr_title':     _req.form.get('mgr_title', ''),
            'systems': [], 'terms': {},
        }
        for i, name in enumerate(_req.form.getlist('sys_name[]')):
            if name.strip():
                sys_tot = _req.form.getlist('sys_total[]')
                sys_sum = _req.form.getlist('sys_is_summary[]')
                sys_idx = _req.form.getlist('sys_idx[]')
                try: tot = float(str(sys_tot[i]).replace(',', '')) if i < len(sys_tot) else 0
                except: tot = 0
                cover['systems'].append({'idx': sys_idx[i] if i < len(sys_idx) else '',
                                         'name': name, 'total': tot,
                                         'is_summary': (i < len(sys_sum) and sys_sum[i] == '1')})
        for k, v in zip(_req.form.getlist('term_key[]'), _req.form.getlist('term_value[]')):
            if k.strip(): cover['terms'][k.strip()] = v.strip()
        cover['notes']      = [n.strip() for n in _req.form.getlist('note_item[]')      if n.strip()]
        cover['exclusions'] = [e.strip() for e in _req.form.getlist('exclusion_item[]') if e.strip()]

        boq_sheets = []
        rfq_ref   = _req.form.get('rfq_ref', '').strip()
        quote_ref = cover.get('quoteref', '').strip() or 'Proposal'
        if rfq_ref and quote_ref and quote_ref != 'Proposal':
            try:
                conn = sqlite3.connect('ProjectStatus.db')
                row = conn.execute(
                    "SELECT sheets_json FROM cost_sheets WHERE rfq_ref=? AND quote_ref=?",
                    (rfq_ref, quote_ref)
                ).fetchone()
                conn.close()
                if row and row[0]:
                    sheets = json.loads(row[0])
                    boq_sheets = _cost_sheet_json_to_boq(sheets)
            except Exception as db_err:
                app.logger.warning(f"Excel: cost sheet load error: {db_err}")

        boq_opts = {
            'show_item_code': 'boq_show_item_code' in _req.form,
            'show_vendor':    'boq_show_vendor'    in _req.form,
            'show_stock':     'boq_show_stock'     in _req.form,
        }
        buf = _build_quotation_excel(cover, boq_sheets, quote_ref, boq_opts=boq_opts)
        safe = quote_ref.replace('/', '-').replace('\\', '-').replace(' ', '_')
        return send_file(buf, as_attachment=True,
                         download_name=f'{safe}_Commercial_Proposal.xlsx',
                         mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    except Exception as e:
        import traceback
        app.logger.error(f"proposal_generate_excel error: {e}\n{traceback.format_exc()}")
        flash(f'Excel generation failed: {str(e)}', 'danger')
        return redirect(url_for('proposal_generator'))


def _cost_sheet_json_to_boq(sheets):
    """Convert cost sheet builder JSON (from DB) to boq_sheets list for _build_quotation_pdf."""
    boq_sheets = []
    for sheet in sheets:
        sname = sheet.get('name', 'System')
        rows  = sheet.get('rows', [])
        items = []
        sn_ctr = 0
        for row in rows:
            rtype = row.get('type', 'item')
            if rtype == 'header':
                desc = str(row.get('desc', '')).strip()
                if desc:
                    items.append({'sn': '', 'code': '', 'desc': desc, 'uom': '',
                                  'qty': None, 'unit_price': None, 'total': None,
                                  'is_section': True})
            else:
                try: qty = float(row.get('qty') or 0)
                except: qty = 0.0
                try: up = float(row.get('unit_price') or 0)
                except: up = 0.0
                if qty <= 0 and up <= 0:
                    continue
                tot = round(qty * up, 2)
                sn_ctr += 1
                items.append({
                    'sn':         str(sn_ctr),
                    'code':       str(row.get('item_code', '') or '').strip(),
                    'desc':       str(row.get('desc', '') or '').strip(),
                    'vendor':     str(row.get('vendor', '') or '').strip(),
                    'stock':      str(row.get('stock',  '') or '').strip(),
                    'uom':        str(row.get('uom', '') or '').strip(),
                    'qty':        qty,
                    'unit_price': up,
                    'total':      tot,
                    'is_section': False,
                })
        priced = [it for it in items if not it.get('is_section') and it.get('total')]
        if priced:
            boq_sheets.append({
                'name':        sname,
                'scope':       str(sheet.get('scope', '') or '').strip(),
                'items':       items,
                'grand_total': sum(it['total'] for it in priced),
            })
    return boq_sheets


def _build_quotation_excel(cover, boq_sheets, quote_ref, boq_opts=None):
    """Build a BytesIO Excel workbook matching the PDF quotation layout."""
    import openpyxl
    from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
    from io import BytesIO

    boq_opts    = boq_opts or {}
    show_code   = boq_opts.get('show_item_code', True)
    show_vendor = boq_opts.get('show_vendor',    False)
    show_stock  = boq_opts.get('show_stock',     False)

    # ── Colour constants ────────────────────────────────────────────────
    def _f(hex_): return PatternFill("solid", fgColor=hex_)
    NAVY_F  = _f("1A0000"); RED_F   = _f("C30010"); GOLD_F  = _f("F59E0B")
    TEAL_F  = _f("9B0012"); GREEN_F = _f("065F46"); LGREY_F = _f("FFF8F8")
    LPINK_F = _f("FFE4E6"); WHITE_F = _f("FFFFFF"); LBLUE_F = _f("EEF2FF")
    LRED_F  = _f("FFF0F0"); AMBE_F  = _f("FFF7ED"); PURP_F  = _f("4B2D8F")
    REDTL_F = _f("FFCDD2")

    def _font(name="Calibri", sz=10, bold=False, color="000000", italic=False):
        return Font(name=name, size=sz, bold=bold, color=color, italic=italic)
    def _al(h="left", v="center", wrap=False):
        return Alignment(horizontal=h, vertical=v, wrap_text=wrap)
    def _bd(clr="CCCCCC", style="thin"):
        s = Side(border_style=style, color=clr)
        return Border(left=s, right=s, top=s, bottom=s)
    def _fmt(v):
        try: return f"{float(v):,.2f}"
        except: return str(v) if v else ""

    RED_BD  = _bd("C30010"); NAVY_BD = _bd("1A0000"); THIN_BD = _bd("DDDDDD")
    PURP_BD = _bd("4B2D8F")

    def _c(ws, r, col, val="", fill=None, font=None, align=None, border=None, nf=None):
        cell = ws.cell(row=r, column=col, value=val)
        if fill:   cell.fill   = fill
        if font:   cell.font   = font
        if align:  cell.alignment = align
        if border: cell.border = border
        if nf:     cell.number_format = nf
        return cell

    def _merge(ws, r, c1, c2, val="", fill=None, font=None, align=None, border=None, h=None):
        ws.merge_cells(start_row=r, start_column=c1, end_row=r, end_column=c2)
        cell = _c(ws, r, c1, val, fill, font, align, border)
        if h: ws.row_dimensions[r].height = h
        return cell

    def _row_h(ws, r, h): ws.row_dimensions[r].height = h

    wb = openpyxl.Workbook()

    # ═══════════════════════════════════════════════════════════════════
    # COVER SHEET
    # Layout: 6 columns
    #   A(20) = left label   B(40) = left value
    #   C(2)  = divider      D(18) = right label   E(30) = right value
    #   F(3)  = right margin
    # ═══════════════════════════════════════════════════════════════════
    ws = wb.active
    ws.title = "Commercial Quotation"
    ws.sheet_view.showGridLines = False
    ws.page_setup.orientation = "portrait"
    ws.page_setup.paperSize   = 9   # A4
    ws.page_margins.left  = ws.page_margins.right  = 0.5
    ws.page_margins.top   = ws.page_margins.bottom = 0.6
    ws.print_area = "A1:F200"

    # Column widths: A=20, B=40, C=2, D=18, E=30, F=3
    for col, w in zip("ABCDEF", [20, 40, 2, 18, 30, 3]):
        ws.column_dimensions[col].width = w

    NC = 6   # total columns on cover sheet
    ri = 1

    # ── Gold top stripe ───────────────────────────────────────────────
    _row_h(ws, ri, 5)
    for ci in range(1, NC+1): ws.cell(ri, ci).fill = GOLD_F
    ri += 1

    # ── Main header ───────────────────────────────────────────────────
    _row_h(ws, ri, 38)
    _merge(ws, ri, 1, NC, "COMMERCIAL QUOTATION", NAVY_F,
           _font("Calibri", 22, True, "FFFFFF"), _al("center","center"))
    ri += 1
    _row_h(ws, ri, 18)
    _merge(ws, ri, 1, NC, "Proposal & Pricing Submission", NAVY_F,
           _font("Calibri", 10, False, "F59E0B"), _al("center","center"))
    ri += 1

    # ── Gold bottom stripe ────────────────────────────────────────────
    _row_h(ws, ri, 5)
    for ci in range(1, NC+1): ws.cell(ri, ci).fill = GOLD_F
    ri += 1
    _row_h(ws, ri, 6); ri += 1   # spacer

    # ── Document info (label row + value row) ─────────────────────────
    for val, c1, c2 in [("DATE",1,1),("QUOTE REFERENCE",2,3),("ENG. REFERENCE",4,5)]:
        ws.merge_cells(start_row=ri, start_column=c1, end_row=ri, end_column=c2)
        _c(ws, ri, c1, val, _f("F0F0F0"),
           _font("Calibri",7,True,"888888"), _al("left","center"), _bd("DDDDDD"))
    _row_h(ws, ri, 13); ri += 1

    for val, c1, c2 in [(cover.get("date",""),1,1),
                        (cover.get("quoteref",""),2,3),
                        (cover.get("engref",""),4,5)]:
        ws.merge_cells(start_row=ri, start_column=c1, end_row=ri, end_column=c2)
        _c(ws, ri, c1, val, WHITE_F,
           _font("Calibri",11,True,"1A0000"), _al("left","center"), _bd())
    _row_h(ws, ri, 20); ri += 1
    _row_h(ws, ri, 8); ri += 1   # spacer

    # ── SUBMITTED TO ──────────────────────────────────────────────────
    _row_h(ws, ri, 18)
    _merge(ws, ri, 1, NC, "SUBMITTED TO", RED_F,
           _font("Calibri",10,True,"FFFFFF"), _al("left","center"))
    ri += 1

    # Two-column rows: left label(A) + left value(B), right label(D) + right value(E:F)
    pair_rows = [
        ("COMPANY",   cover.get("to",  ""), "ATTENTION", cover.get("attn","")),
        ("FROM",      cover.get("frm", ""), "MOBILE",    cover.get("cont","")),
    ]
    for lbl1, val1, lbl2, val2 in pair_rows:
        _row_h(ws, ri, 18)
        _c(ws, ri, 1, lbl1, RED_F,  _font("Calibri",9,True,"FFFFFF"),  _al("left","center"), RED_BD)
        _merge(ws, ri, 2, 3, val1, WHITE_F, _font("Calibri",9,False,"1A0000"), _al("left","center",True), _bd())
        _c(ws, ri, 4, lbl2, RED_F,  _font("Calibri",9,True,"FFFFFF"),  _al("left","center"), RED_BD)
        _merge(ws, ri, 5, 6, val2, WHITE_F, _font("Calibri",9,False,"1A0000"), _al("left","center",True), _bd())
        ri += 1

    # Full-width rows: label(A) + value(B:F)
    for lbl, val, rh in [("SUBJECT", cover.get("sub",""), 20),
                         ("SCOPE",   cover.get("scope",""), 28)]:
        _row_h(ws, ri, rh)
        _c(ws, ri, 1, lbl, RED_F, _font("Calibri",9,True,"FFFFFF"), _al("left","center"), RED_BD)
        _merge(ws, ri, 2, NC, val, WHITE_F, _font("Calibri",9,False,"1A0000"), _al("left","center",True), _bd())
        ri += 1

    # ── Opening paragraph ─────────────────────────────────────────────
    _row_h(ws, ri, 8); ri += 1
    _row_h(ws, ri, 13)
    _merge(ws, ri, 1, NC, "Dear Sir,", None,
           _font("Calibri",9,True,"1A0000"), _al("left","center"))
    ri += 1
    _row_h(ws, ri, 36)
    _merge(ws, ri, 1, NC,
           "We thank you for your subject enquiry and have pleasure in putting together a "
           "comprehensive proposal for the same. We hope this is in line with your requirements "
           "and that you will favour us with your order.",
           None, _font("Calibri",9,False,"1A0000"), _al("left","center",True))
    ri += 1

    # ── Executive Summary ─────────────────────────────────────────────
    exec_sum = cover.get("exec_summary","").strip()
    if exec_sum:
        _row_h(ws, ri, 8); ri += 1
        _row_h(ws, ri, 18)
        _merge(ws, ri, 1, NC, "EXECUTIVE SUMMARY", NAVY_F,
               _font("Calibri",10,True,"F59E0B"), _al("left","center"))
        ri += 1
        est_h = max(60, min(150, len(exec_sum)//3))
        _row_h(ws, ri, est_h)
        _merge(ws, ri, 1, NC, exec_sum, LBLUE_F,
               _font("Calibri",9,False,"1A0000"), _al("left","top",True), _bd("B0C4DE"))
        ri += 1

    # ── Commercial Summary ────────────────────────────────────────────
    _row_h(ws, ri, 8); ri += 1
    _row_h(ws, ri, 18)
    _merge(ws, ri, 1, NC, "COMMERCIAL SUMMARY", NAVY_F,
           _font("Calibri",10,True,"FFFFFF"), _al("left","center"))
    ri += 1

    # Table header: No.(A) | System/Line Item(B:D) | Total Price SAR (E:F)
    _row_h(ws, ri, 16)
    _c(ws, ri, 1, "No.", RED_F, _font("Calibri",9,True,"FFFFFF"), _al("center","center"), RED_BD)
    _merge(ws, ri, 2, 4, "System / Line Item", RED_F,
           _font("Calibri",9,True,"FFFFFF"), _al("left","center"), RED_BD)
    _merge(ws, ri, 5, NC, "Total Price (SAR)", RED_F,
           _font("Calibri",9,True,"FFFFFF"), _al("right","center"), RED_BD)
    ri += 1

    grand_total = 0.0
    row_num = 0
    for sys in cover.get("systems",[]):
        if sys.get("is_summary"): continue   # skip Total/VAT/Grand Total summary rows
        tot = float(sys.get("total",0) or 0)
        grand_total += tot
        row_num += 1
        rf = WHITE_F if row_num % 2 else LGREY_F
        _row_h(ws, ri, 16)
        _c(ws, ri, 1, row_num, rf, _font("Calibri",9,True,"C30010"), _al("center","center"), _bd())
        _merge(ws, ri, 2, 4, sys.get("name",""), rf,
               _font("Calibri",9,False,"1A0000"), _al("left","center"), _bd())
        tc = _merge(ws, ri, 5, NC, tot, rf,
               _font("Calibri",9,False,"1A0000"), _al("right","center"), _bd())
        tc.number_format = "#,##0.00"; ri += 1

    vat_pct  = 0.15
    vat_amt  = grand_total * vat_pct
    g_total  = grand_total + vat_amt

    for lbl_s, val_s, bg, fg, bold in [
        ("Total (SAR)",               grand_total, "C30010", "FFFFFF", True),
        (f"VAT ({int(vat_pct*100)}%)", vat_amt,   "E53935", "FFFFFF", True),
        ("Grand Total",               g_total,     "065F46", "FFFFFF", True),
    ]:
        _row_h(ws, ri, 18)
        f_ = _f(bg)
        _merge(ws, ri, 1, 4, lbl_s, f_, _font("Calibri",10,bold,fg), _al("right","center"), _bd(bg))
        tc = _merge(ws, ri, 5, NC, val_s, f_, _font("Calibri",10,bold,fg), _al("right","center"), _bd(bg))
        tc.number_format = "#,##0.00"; ri += 1

    # ── Terms & Conditions ────────────────────────────────────────────
    terms = cover.get("terms",{})
    if terms:
        _row_h(ws, ri, 8); ri += 1
        _row_h(ws, ri, 18)
        _merge(ws, ri, 1, NC, "TERMS & CONDITIONS", NAVY_F,
               _font("Calibri",10,True,"FFFFFF"), _al("left","center"))
        ri += 1
        for tk, tv in terms.items():
            _row_h(ws, ri, 16)
            _c(ws, ri, 1, tk, RED_F,
               _font("Calibri",9,True,"FFFFFF"), _al("left","center"), RED_BD)
            _merge(ws, ri, 2, NC, tv, WHITE_F,
                   _font("Calibri",9,False,"1A0000"), _al("left","center",True), _bd())
            ri += 1

    # ── Call to Action ────────────────────────────────────────────────
    cta_email = cover.get("cta_email","").strip()
    cta_phone = cover.get("cta_phone","").strip()
    cta_body  = cover.get("cta_body","").strip()
    if cta_email or cta_body:
        _row_h(ws, ri, 8); ri += 1
        _row_h(ws, ri, 18)
        _merge(ws, ri, 1, NC, "CALL TO ACTION", NAVY_F,
               _font("Calibri",10,True,"F59E0B"), _al("left","center"))
        ri += 1
        if cta_email or cta_phone:
            contact = f"For inquiries, please contact us at: {cta_email}"
            if cta_phone: contact += f"   |   Tel: {cta_phone}"
            _row_h(ws, ri, 16)
            _merge(ws, ri, 1, NC, contact, AMBE_F,
                   _font("Calibri",9,False,"1A0000"), _al("left","center",True), _bd("F59E0B"))
            ri += 1
        if cta_body:
            est_h = max(40, min(100, len(cta_body)//4))
            _row_h(ws, ri, est_h)
            _merge(ws, ri, 1, NC, cta_body, AMBE_F,
                   _font("Calibri",9,False,"1A0000"), _al("left","top",True), _bd("F59E0B"))
            ri += 1

    # ── "With best regards" ───────────────────────────────────────────
    _row_h(ws, ri, 8); ri += 1
    _row_h(ws, ri, 16)
    _merge(ws, ri, 1, NC, "With best regards,", None,
           _font("Calibri",10,True,"1A0000"), _al("left","center"))
    ri += 1
    _row_h(ws, ri, 28); ri += 1   # sig space

    # Signatures side by side
    sig_pairs = [
        (cover.get("prep_by_name",""),  cover.get("prep_by_title",""),  "Prepared By",  1, 3),
        (cover.get("mgr_name",""),      cover.get("mgr_title",""),      "Approved By",  4, 6),
    ]
    max_sig_rows = 0
    sig_start = ri
    for sname, stitle, srole, c1, c2 in sig_pairs:
        if not sname: continue
        r2 = sig_start
        _row_h(ws, r2, 13)
        _merge(ws, r2, c1, c2, srole, _f("E8EAF6"),
               _font("Calibri",8,True,"4B2D8F"), _al("left","center"), PURP_BD)
        r2 += 1
        _row_h(ws, r2, 14)
        _merge(ws, r2, c1, c2, sname, WHITE_F,
               _font("Calibri",10,True,"1A0000"), _al("left","center"), _bd())
        r2 += 1
        if stitle:
            _row_h(ws, r2, 13)
            _merge(ws, r2, c1, c2, stitle, WHITE_F,
                   _font("Calibri",9,False,"666666"), _al("left","center"), _bd())
            r2 += 1
        max_sig_rows = max(max_sig_rows, r2 - sig_start)
    ri += max_sig_rows

    # ── Footer stripes ────────────────────────────────────────────────
    _row_h(ws, ri, 6); [ws.cell(ri, ci).__setattr__("fill", NAVY_F) for ci in range(1,NC+1)]; ri += 1
    _row_h(ws, ri, 4); [ws.cell(ri, ci).__setattr__("fill", GOLD_F) for ci in range(1,NC+1)]; ri += 1

    ws.freeze_panes = "A6"

    # ═══════════════════════════════════════════════════════════════════
    # BOQ SHEETS — one per system
    # ═══════════════════════════════════════════════════════════════════
    def _boq_cols():
        cols = [("sn",   "S.#",              5,  "center")]
        if show_code:   cols.append(("code",   "ITEM CODE",       16, "center"))
        cols.append(    ("desc",  "ITEM DESCRIPTION", 46, "left"))
        if show_vendor: cols.append(("vendor", "VENDOR",          14, "center"))
        cols.append(    ("uom",   "UOM",                7, "center"))
        cols.append(    ("qty",   "QTY",                8, "right"))
        cols.append(    ("up",    "UNIT PRICE",         15, "right"))
        cols.append(    ("total", "TOTAL",              15, "right"))
        if show_stock:  cols.append(("stock",  "STOCK",           13, "center"))
        return cols

    COL_DEFS  = _boq_cols()
    NCOLS_BOQ = len(COL_DEFS)

    def _ci_boq(key):
        for i, c in enumerate(COL_DEFS):
            if c[0] == key: return i + 1
        return -1

    for bs in boq_sheets:
        sname = bs.get("name","System")
        scope = bs.get("scope","")
        items = bs.get("items",[])

        bad = str.maketrans({"/":"_", "\\":"_", "*":"", "?":"", "[":"", "]":"", ":":""})
        safe_sh = sname[:29].translate(bad).strip() or "Sheet"
        # Ensure unique sheet name
        existing = [s.title for s in wb.worksheets]
        base = safe_sh; cnt = 2
        while safe_sh in existing: safe_sh = f"{base[:26]}_{cnt}"; cnt += 1

        bws = wb.create_sheet(title=safe_sh)
        bws.sheet_view.showGridLines = False
        bws.page_setup.orientation = "landscape"
        bws.page_setup.paperSize   = 9
        bws.page_margins.left  = bws.page_margins.right  = 0.4
        bws.page_margins.top   = bws.page_margins.bottom = 0.5

        for ci, (_, _, cw, _) in enumerate(COL_DEFS, start=1):
            bws.column_dimensions[get_column_letter(ci)].width = cw

        bri = 1

        # System name banner
        _row_h(bws, bri, 24)
        bws.merge_cells(start_row=bri, start_column=1, end_row=bri, end_column=NCOLS_BOQ)
        _c(bws, bri, 1, sname, NAVY_F, _font("Calibri",12,True,"FFFFFF"), _al("left","center"))
        bri += 1

        # Scope row
        if scope:
            h_scope = max(16, min(50, len(scope)//6))
            _row_h(bws, bri, h_scope)
            bws.merge_cells(start_row=bri, start_column=1, end_row=bri, end_column=NCOLS_BOQ)
            _c(bws, bri, 1, f"SCOPE:  {scope}", LRED_F,
               _font("Calibri",9,False,"1A0000"), _al("left","center",True), _bd("C30010"))
            bri += 1

        # Column headers
        _row_h(bws, bri, 20)
        for ci, (key, hdr, cw, algn) in enumerate(COL_DEFS, start=1):
            hf = _al("right","center") if key in ("qty","up","total") else _al("center","center") if key != "desc" else _al("left","center")
            _c(bws, bri, ci, hdr, RED_F, _font("Calibri",9,True,"FFFFFF"), hf, RED_BD)
        bws.freeze_panes = f"A{bri+1}"
        hdr_ri = bri; bri += 1

        # Data rows
        item_ctr = 0; grand_boq = 0.0
        for it in items:
            is_sec = it.get("is_section", False)
            if is_sec:
                _row_h(bws, bri, 16)
                bws.merge_cells(start_row=bri, start_column=1, end_row=bri, end_column=NCOLS_BOQ)
                _c(bws, bri, 1, it.get("desc",""), LPINK_F,
                   _font("Calibri",9,True,"C30010"), _al("center","center"), RED_BD)
            else:
                item_ctr += 1
                tot = float(it.get("total") or 0)
                if tot: grand_boq += tot
                try: qty_v = int(float(it.get("qty",0)))
                except: qty_v = it.get("qty","")
                rf = WHITE_F if item_ctr % 2 else LGREY_F
                desc_len = len(str(it.get("desc","")))
                rh = 28 if desc_len > 60 else 20 if desc_len > 30 else 16
                _row_h(bws, bri, rh)
                rd = {"sn": item_ctr, "code": it.get("code",""),
                      "desc": it.get("desc",""), "vendor": it.get("vendor",""),
                      "uom": it.get("uom",""), "qty": qty_v,
                      "up": it.get("unit_price") or "", "total": tot or "",
                      "stock": it.get("stock","")}
                for ci, (key, _, _, algn) in enumerate(COL_DEFS, start=1):
                    val = rd.get(key,"")
                    af  = _al(algn,"center", wrap=True if key=="desc" else False)
                    cell = _c(bws, bri, ci, val, rf,
                              _font("Calibri",9,False,"1A0000"), af, THIN_BD)
                    if key in ("up","total") and val != "":
                        cell.number_format = "#,##0.00"
            bri += 1

        # Total row
        _row_h(bws, bri, 20)
        i_up  = _ci_boq("up"); i_tot = _ci_boq("total")
        for ci in range(1, NCOLS_BOQ+1): bws.cell(bri, ci).fill = TEAL_F
        if i_up > 1:
            bws.merge_cells(start_row=bri, start_column=1, end_row=bri, end_column=i_up-1)
        _c(bws, bri, 1, "", TEAL_F)
        _c(bws, bri, i_up, "Total Excluding VAT", TEAL_F,
           _font("Calibri",10,True,"FFFFFF"), _al("right","center"), _bd("9B0012"))
        tc = _c(bws, bri, i_tot, grand_boq, TEAL_F,
                _font("Calibri",10,True,"FFFFFF"), _al("right","center"), _bd("9B0012"))
        tc.number_format = "#,##0.00"
        if show_stock:
            _c(bws, bri, NCOLS_BOQ, "", TEAL_F, None, None, _bd("9B0012"))
        bri += 1

        bws.print_title_rows = f"1:{hdr_ri}"

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    return buf


def _build_quotation_pdf(cover, boq_sheets, quote_ref, boq_opts=None):
    """Build a BytesIO PDF from parsed cover dict and boq_sheets list."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm
    from reportlab.lib import colors
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.enums import TA_LEFT, TA_CENTER, TA_RIGHT
    from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table,
                                    TableStyle, PageBreak, KeepTogether)
    from reportlab.platypus import Image as RLImage
    from io import BytesIO
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont

    # ── Arabic font registration ──────────────────────────────────────────
    _AMIRI_FONT = 'Amiri'
    try:
        _amiri_path = os.path.join(os.path.dirname(__file__), 'static', 'Amiri-Regular.ttf')
        pdfmetrics.registerFont(TTFont(_AMIRI_FONT, _amiri_path))
        _arabic_ok = True
    except Exception:
        _arabic_ok = False

    def _has_arabic(text):
        if not text: return False
        return any('؀' <= ch <= 'ۿ' or 'ݐ' <= ch <= 'ݿ' or
                   'ﭐ' <= ch <= '﷿' or 'ﹰ' <= ch <= '﻿' for ch in str(text))

    def _fix_arabic(text):
        """Reshape + bidi-reorder Arabic text for ReportLab."""
        if not text or not _arabic_ok: return str(text) if text else ''
        try:
            import arabic_reshaper
            from bidi.algorithm import get_display
            if _has_arabic(str(text)):
                reshaped = arabic_reshaper.reshape(str(text))
                return get_display(reshaped)
        except Exception:
            pass
        return str(text) if text else ''

    def _p_ar(text, style=None):
        """Return Paragraph with Arabic-safe rendering (auto-detects Arabic)."""
        t = str(text) if text else ''
        if _has_arabic(t) and _arabic_ok:
            ar_style = ParagraphStyle(
                'ar_auto', fontName=_AMIRI_FONT, fontSize=10,
                textColor=(style.textColor if style else colors.HexColor('#0F172A')),
                alignment=TA_RIGHT, leading=14,
            )
            return Paragraph(_fix_arabic(t), ar_style)
        return Paragraph(t, style or S_BODY)

    W, H = A4
    C_NAVY     = colors.HexColor('#555555')   # dark gray
    C_PURPLE   = colors.HexColor('#CC0000')   # brand red
    C_PURPLE2  = colors.HexColor('#D94040')   # medium red
    C_PURPLE3  = colors.HexColor('#E5E5E5')   # light gray
    C_GOLD     = colors.HexColor('#8B8B8B')   # medium gray
    C_GOLD_DK  = colors.HexColor('#666666')   # dark gray
    C_TEAL     = colors.HexColor('#9B0012')   # dark red totals
    C_GREEN_DK = colors.HexColor('#7B0000')  # grand total dark red
    C_DARK     = colors.HexColor('#333333')   # dark text
    C_GREY_HDR = colors.HexColor('#F5F5F5')   # light gray header
    C_GREY_ROW = colors.HexColor('#FAFAFA')   # near-white row
    C_SEC_BG   = colors.HexColor('#EEEEEE')   # section bg gray
    C_WHITE    = colors.white

    def _ps(name, **kw):
        base = ParagraphStyle(name, fontName='Helvetica', fontSize=9, textColor=C_DARK, leading=12)
        for k, v in kw.items(): setattr(base, k, v)
        return base

    S_BODY  = _ps('body')
    S_BOLD  = _ps('bold', fontName='Helvetica-Bold')
    S_SUBHD = _ps('subhd', fontName='Helvetica-Bold', fontSize=9, textColor=C_PURPLE2)
    S_WHITE = _ps('wht', fontName='Helvetica-Bold', fontSize=9, textColor=C_WHITE, alignment=TA_CENTER)
    S_ITEM  = _ps('item', fontSize=8.5, leading=11)
    S_SEC   = _ps('sec', fontName='Helvetica-Bold', fontSize=8.5, textColor=C_PURPLE, alignment=TA_CENTER)
    S_CODHD = _ps('codhd', fontName='Helvetica-Bold', fontSize=8, textColor=C_WHITE, alignment=TA_CENTER)

    def _p(text, style=None):
        return Paragraph(str(text) if text else '', style or S_BODY)

    def _fmt(v):
        try: return f'{float(v):,.2f}'
        except: return str(v) if v else ''

    buf = BytesIO()
    MARGINS = 1.8*cm
    doc = SimpleDocTemplate(buf, pagesize=A4,
                            leftMargin=MARGINS, rightMargin=MARGINS,
                            topMargin=1.5*cm, bottomMargin=1.9*cm,
                            title=f"Quotation {quote_ref}")
    BW = W - 2*MARGINS
    story = []

    def _header_band(text, color=None):
        color = color or C_PURPLE
        return Table([[_p(text, _ps('hb', fontName='Helvetica-Bold', fontSize=9.5, textColor=C_WHITE, alignment=TA_CENTER))]],
                     colWidths=[BW],
                     style=TableStyle([('BACKGROUND',(0,0),(-1,-1),color),
                                       ('PADDING',(0,0),(-1,-1),6),
                                       ('ALIGN',(0,0),(-1,-1),'CENTER')]))

    def _sub_scope_block():
        sub  = cover.get('sub','')
        scop = cover.get('scope','')
        rows = []
        if sub:
            rows.append(Table([[_p(f'<b>SUB.:</b> {sub}', S_SUBHD)]],colWidths=[BW],
                style=TableStyle([('BACKGROUND',(0,0),(-1,-1),C_GREY_HDR),
                                  ('BOX',(0,0),(-1,-1),0.5,C_PURPLE),('PADDING',(0,0),(-1,-1),5)])))
            rows.append(Spacer(1, 0.15*cm))
        if scop:
            rows.append(Table([[_p(f'<b>SCOPE:</b> {scop}', S_BODY)]],colWidths=[BW],
                style=TableStyle([('BACKGROUND',(0,0),(-1,-1),C_GREY_HDR),
                                  ('BOX',(0,0),(-1,-1),0.5,C_PURPLE),('PADDING',(0,0),(-1,-1),5)])))
        return rows

    # ══════════════════════════ COVER PAGE ══════════════════════════════
    BW_eff = BW - 0.28*cm   # effective width (left accent bar eats 2.8mm)

    # Paragraph styles
    def _pw(name, **kw):
        base = ParagraphStyle(name, fontName='Helvetica', fontSize=9, textColor=C_WHITE, leading=12)
        for k,v in kw.items(): setattr(base, k, v)
        return base

    # ── 1. HEADER BANNER ──────────────────────────────────────────────────
    try:
        logo_img = RLImage(os.path.join(os.path.dirname(__file__), 'static', 'ejt.png'),
                           width=4.0*cm, height=1.35*cm)
    except Exception:
        logo_img = _p('<b>EJTech</b>', _ps('lg', fontName='Helvetica-Bold', fontSize=18, textColor=C_WHITE))

    # Diagonal gold stripe decorative element (simulated via nested table)
    deco = Table([['', '']], colWidths=[0.5*cm, 0.15*cm])
    deco.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(0,0),C_PURPLE),
        ('BACKGROUND',(1,0),(1,0),colors.HexColor('#E0E0E0')),
        ('TOPPADDING',(0,0),(-1,-1),0),('BOTTOMPADDING',(0,0),(-1,-1),0),
    ]))

    title_inner = Table([
        [_p('COMMERCIAL QUOTATION', _pw('bt', fontName='Helvetica-Bold', fontSize=15, textColor=C_PURPLE, alignment=TA_RIGHT))],
        [_p('Proposal &amp; Pricing Submission', _pw('bs', fontSize=8.5, textColor=colors.HexColor('#888888'), alignment=TA_RIGHT))],
    ], colWidths=[BW_eff - 5.5*cm])
    title_inner.setStyle(TableStyle([('TOPPADDING',(0,0),(-1,-1),2)]))

    banner = Table([[logo_img, deco, title_inner]],
                   colWidths=[4.2*cm, 0.7*cm, BW_eff - 4.9*cm])
    banner.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),C_WHITE),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('LEFTPADDING',(0,0),(0,-1),10),('RIGHTPADDING',(0,0),(-1,-1),12),
        ('TOPPADDING',(0,0),(-1,-1),14),('BOTTOMPADDING',(0,0),(-1,-1),14),
        ('BOX',(0,0),(-1,-1),0.5,colors.HexColor('#E0E0E0')),
        ('LINEBELOW',(0,0),(-1,-1),3,C_PURPLE),
    ]))
    story.append(banner)

    # Gold + purple dual accent line
    accent = Table([['', '']], colWidths=[BW_eff*0.72, BW_eff*0.28])
    accent.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(0,0),colors.HexColor('#888888')),
        ('BACKGROUND',(1,0),(1,0),C_PURPLE),
        ('TOPPADDING',(0,0),(-1,-1),0),('BOTTOMPADDING',(0,0),(-1,-1),0),
        ('LINEBELOW',(0,0),(-1,-1),3.5,colors.HexColor('#888888')),
    ]))
    story.append(Table([[accent]], colWidths=[BW_eff],
        style=TableStyle([('TOPPADDING',(0,0),(-1,-1),0),('BOTTOMPADDING',(0,0),(-1,-1),0),
                           ('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),0),
                           ('LINEBELOW',(0,0),(-1,-1),4,colors.HexColor('#888888'))])))
    story.append(Spacer(1, 0.4*cm))

    # ── 2. DOCUMENT REFERENCE CARDS ──────────────────────────────────────
    # Reference card column widths: DATE 20%, QUOTE REFERENCE 50%, ENG. REFERENCE 30%
    _REF_TOTAL = BW_eff - 0.4*cm
    _REF_COLS  = [_REF_TOTAL * 0.20, _REF_TOTAL * 0.50, _REF_TOTAL * 0.30]

    def _ref_card(label, value, col_w, highlight=False):
        val_col  = C_NAVY if highlight else C_DARK
        val_font = 'Helvetica-Bold' if highlight else 'Helvetica'
        val_text = value or '—'
        # Shrink font slightly for long values so they don't wrap awkwardly
        val_fs   = 8.5 if len(val_text) > 20 else 9.5
        if _has_arabic(val_text) and _arabic_ok:
            val_cell = _p_ar(val_text)
        else:
            val_cell = _p(val_text, _ps(f'rv{label}', fontName=val_font, fontSize=val_fs,
                                        textColor=val_col, leading=11))
        return Table([
            [_p(label, _ps(f'rl{label}', fontName='Helvetica-Bold', fontSize=6.5,
                           textColor=C_PURPLE, leading=8, spaceAfter=1))],
            [val_cell],
        ], colWidths=[col_w])

    ref_row = [
        _ref_card('DATE',            cover.get('date', ''),    _REF_COLS[0]),
        _ref_card('QUOTE REFERENCE', cover.get('quoteref', ''), _REF_COLS[1], highlight=True),
        _ref_card('ENG. REFERENCE',  cover.get('engref', ''),   _REF_COLS[2]),
    ]
    ref_tbl = Table([ref_row], colWidths=_REF_COLS)
    ref_tbl.setStyle(TableStyle([
        ('BOX',(0,0),(-1,-1),0.5,C_PURPLE3),
        ('LINEAFTER',(0,0),(1,-1),0.5,C_PURPLE3),
        ('BACKGROUND',(0,0),(-1,-1),C_WHITE),
        ('LINEBELOW',(0,0),(-1,-1),2,C_PURPLE),
        ('LINETOP',(0,0),(-1,-1),0.3,C_PURPLE3),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),
        ('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),
    ]))
    story.append(ref_tbl)
    story.append(Spacer(1, 0.28*cm))

    # ── 3. SUBMITTED TO SECTION ───────────────────────────────────────────
    # Sub-header bar
    story.append(Table([[
        _p('SUBMITTED TO', _pw('sth', fontName='Helvetica-Bold', fontSize=8.5, textColor=C_WHITE)),
    ]], colWidths=[BW_eff], style=TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),C_NAVY),
        ('LEFTPADDING',(0,0),(-1,-1),10),
        ('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),
    ])))

    # Client info grid
    LW_A = BW_eff * 0.155   # label col width
    VW_A = BW_eff * 0.345   # value col width

    def _lbl_p(t, c): return _p(t, _ps(f'lbl{t}', fontName='Helvetica-Bold', fontSize=8, textColor=c))
    def _val_p(t):    return _p_ar(t or '—', _ps(f'val{t[:8]}', fontSize=9, textColor=C_DARK, leading=12))

    ci = Table([
        [_lbl_p('COMPANY',  C_WHITE), _val_p(cover.get('to','')),
         _lbl_p('ATTENTION', C_PURPLE), _val_p(cover.get('attn',''))],
        [_lbl_p('FROM',     C_WHITE), _val_p(cover.get('frm','')),
         _lbl_p('MOBILE',   C_PURPLE),  _val_p(cover.get('cont',''))],
    ], colWidths=[LW_A, VW_A, LW_A, BW_eff - LW_A*2 - VW_A])
    ci.setStyle(TableStyle([
        ('BOX',(0,0),(-1,-1),0.5,C_PURPLE3),
        ('INNERGRID',(0,0),(-1,-1),0.3,colors.HexColor('#E5E5E5')),
        ('BACKGROUND',(0,0),(0,-1),C_PURPLE),    # left label col
        ('BACKGROUND',(2,0),(2,-1),colors.HexColor('#555555')),  # right label col gray
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),
        ('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),
        ('ROWBACKGROUNDS',(1,0),(-1,-1),[C_WHITE, C_GREY_ROW]),
        ('FONTSIZE',(0,0),(-1,-1),9),
    ]))
    story.append(ci)
    story.append(Spacer(1, 0.18*cm))

    # Subject / Scope
    sub  = cover.get('sub', '')
    scop = cover.get('scope', '')
    sc_rows = []
    if sub:
        sc_rows.append([_lbl_p('SUBJECT', C_WHITE),
                        _p(sub, _ps('subv', fontName='Helvetica-Bold', fontSize=9, textColor=C_PURPLE))])
    if scop:
        sc_rows.append([_lbl_p('SCOPE', C_WHITE),
                        _p(scop, _ps('scpv', fontSize=9, textColor=C_DARK))])
    if sc_rows:
        sc_tbl = Table(sc_rows, colWidths=[LW_A, BW_eff - LW_A])
        sc_tbl.setStyle(TableStyle([
            ('BOX',(0,0),(-1,-1),0.5,C_PURPLE3),
            ('INNERGRID',(0,0),(-1,-1),0.3,colors.HexColor('#E5E5E5')),
            ('BACKGROUND',(0,0),(0,-1),C_PURPLE),
            ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
            ('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),
            ('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),
        ]))
        story.append(sc_tbl)
        story.append(Spacer(1, 0.18*cm))

    # ── 4. OPENING TEXT ───────────────────────────────────────────────────
    story.append(_p('Dear Sir,',
                    _ps('dear', fontName='Helvetica-Bold', fontSize=9, textColor=C_NAVY)))
    story.append(Spacer(1, 0.1*cm))
    story.append(_p(
        'We thank you for your subject enquiry and have pleasure in putting together a comprehensive '
        'proposal for the same. We hope this is in line with your requirements and that you will '
        'favour us with your order.',
        _ps('body3', fontSize=9, textColor=C_DARK, leading=13)))
    story.append(Spacer(1, 0.28*cm))

    # ── 4b. EXECUTIVE SUMMARY (AI) ───────────────────────────────────────
    _exec_sum = (cover.get('exec_summary') or '').strip()
    if _exec_sum:
        from reportlab.platypus import HRFlowable
        # Section header bar
        _es_hdr = Table([[
            _p('EXECUTIVE SUMMARY', _pw('esh', fontName='Helvetica-Bold', fontSize=9, textColor=colors.white)),
        ]], colWidths=[BW_eff])
        _es_hdr.setStyle(TableStyle([
            ('BACKGROUND', (0,0),(-1,-1), colors.HexColor('#CC0000')),
            ('LINEBELOW',  (0,0),(-1,-1), 2, colors.HexColor('#888888')),
            ('TOPPADDING', (0,0),(-1,-1), 5),
            ('BOTTOMPADDING',(0,0),(-1,-1), 5),
            ('LEFTPADDING', (0,0),(-1,-1), 10),
        ]))
        story.append(_es_hdr)
        story.append(Spacer(1, 0.12*cm))
        # Split by newlines — each non-empty paragraph on its own
        _es_paras = [ln.strip() for ln in _exec_sum.split('\n') if ln.strip()]
        _es_body_style = _ps('esb', fontName='Helvetica', fontSize=8.8, textColor=C_DARK, leading=13.5,
                              leftIndent=4, rightIndent=4)
        for _ep in _es_paras:
            story.append(_p(_ep, _es_body_style))
        story.append(Spacer(1, 0.25*cm))

    # ── 5. COMMERCIAL SUMMARY ─────────────────────────────────────────────
    # Header
    sum_hdr_tbl = Table([[
        _p('COMMERCIAL SUMMARY', _pw('csh', fontName='Helvetica-Bold', fontSize=10, textColor=C_WHITE)),
    ]], colWidths=[BW_eff])
    sum_hdr_tbl.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),C_NAVY),
        ('LINEBELOW',(0,0),(-1,-1),3,C_PURPLE),
        ('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),
        ('LEFTPADDING',(0,0),(-1,-1),12),
    ]))
    story.append(sum_hdr_tbl)

    SN_W  = 1.2*cm
    SYS_W = BW_eff - 7.2*cm
    TOT_W = 6.0*cm

    col_hdr = [
        _p('No.', _ps('snh', fontName='Helvetica-Bold', fontSize=8, textColor=C_PURPLE, alignment=TA_CENTER)),
        _p('System / Line Item', _ps('ssh', fontName='Helvetica-Bold', fontSize=8.5, textColor=C_PURPLE)),
        _p('Total Price (SAR)', _ps('sth2', fontName='Helvetica-Bold', fontSize=8.5, textColor=C_PURPLE, alignment=TA_RIGHT)),
    ]
    sum_data = [col_hdr]
    systems  = cover.get('systems', [])
    for sys in systems:
        if sys.get('is_summary'):
            nm = sys['name']
            is_grand = (nm == 'Grand Total')
            bg  = C_GREEN_DK if is_grand else C_PURPLE2
            fst = _ps(f'sf{nm}', fontName='Helvetica-Bold',
                      fontSize=10.5 if is_grand else 9, textColor=C_WHITE, alignment=TA_RIGHT)
            nst = _ps(f'sn{nm}', fontName='Helvetica-Bold',
                      fontSize=10.5 if is_grand else 9, textColor=C_WHITE)
            sum_data.append([_p('', S_BODY), _p(nm, nst), _p(_fmt(sys['total']), fst)])
        else:
            sum_data.append([
                _p(str(sys.get('idx', '')),
                   _ps('si2', fontSize=8.5, alignment=TA_CENTER, textColor=C_WHITE)),
                _p(str(sys.get('name', '')), _ps('snm2', fontSize=9, textColor=C_DARK)),
                _p(_fmt(sys.get('total', 0)), _ps('sv2', fontSize=9, alignment=TA_RIGHT, textColor=C_DARK)),
            ])

    sum_ts = TableStyle([
        ('BACKGROUND',(0,0),(-1,0),C_GREY_ROW),
        ('LINEBELOW',(0,0),(-1,0),1,C_PURPLE),
        ('BOX',(0,0),(-1,-1),0.5,C_PURPLE3),
        ('INNERGRID',(0,0),(-1,-1),0.25,colors.HexColor('#FFE4E6')),
        ('ALIGN',(0,0),(0,-1),'CENTER'),('ALIGN',(2,0),(2,-1),'RIGHT'),
        ('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),
        ('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),
        ('FONTSIZE',(0,1),(-1,-1),9),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        # No. column — navy background for item rows
        ('BACKGROUND',(0,1),(0,-1),C_PURPLE),
    ])
    # Alternating rows + summary row styles
    item_rows = [i for i, s in enumerate(systems, start=1) if not s.get('is_summary')]
    for pos, orig_i in enumerate(item_rows):
        bg = C_WHITE if pos % 2 == 0 else C_GREY_ROW
        sum_ts.add('BACKGROUND',(1,orig_i),(2,orig_i),bg)
    for i, sys in enumerate(systems, start=1):
        if sys.get('is_summary'):
            nm = sys['name']
            bg = C_GREEN_DK if nm == 'Grand Total' else C_PURPLE2
            sum_ts.add('BACKGROUND',(0,i),(-1,i),bg)
            sum_ts.add('TEXTCOLOR',(0,i),(-1,i),C_WHITE)
            sum_ts.add('FONTNAME',(0,i),(-1,i),'Helvetica-Bold')
            if nm == 'Grand Total':
                sum_ts.add('LINEABOVE',(0,i),(-1,i),1.5,C_WHITE)
                sum_ts.add('FONTSIZE',(0,i),(-1,i),10.5)

    sum_tbl = Table(sum_data, colWidths=[SN_W, SYS_W, TOT_W])
    sum_tbl.setStyle(sum_ts)
    story.append(sum_tbl)
    story.append(Spacer(1, 0.28*cm))

    _fin = []  # collect all final-page elements
    # ── 6. TERMS & CONDITIONS ─────────────────────────────────────────────
    terms = cover.get('terms', {})
    if not terms:
        terms = {
            'Price':           'SAR, Excluding VAT',
            'Payment Terms':   '30 days from invoice date',
            'Offer Validity':  '30 days',
            'Warranty':        '1 Year',
            'Delivery Terms':  '4-6 Weeks ARO',
        }
    tc_hdr = Table([[
        _p('TERMS &amp; CONDITIONS', _pw('tch', fontName='Helvetica-Bold', fontSize=10, textColor=C_WHITE)),
    ]], colWidths=[BW_eff])
    tc_hdr.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,-1),C_NAVY),
        ('LINEBELOW',(0,0),(-1,-1),3,C_PURPLE),
        ('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),
        ('LEFTPADDING',(0,0),(-1,-1),12),
    ]))
    _fin.append(tc_hdr)

    TK_W = 3.8*cm
    t_rows = []
    for i, (k, v) in enumerate(terms.items()):
        t_rows.append([
            _p(k, _ps(f'tk{i}', fontName='Helvetica-Bold', fontSize=8.5, textColor=C_WHITE)),
            _p(v, _ps(f'tv{i}', fontSize=8.5, textColor=C_DARK, leading=12)),
        ])
    terms_tbl = Table(t_rows, colWidths=[TK_W, BW_eff - TK_W])
    terms_tbl.setStyle(TableStyle([
        ('BOX',(0,0),(-1,-1),0.5,C_PURPLE3),
        ('INNERGRID',(0,0),(-1,-1),0.3,colors.HexColor('#E5E5E5')),
        ('BACKGROUND',(0,0),(0,-1),C_PURPLE),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
        ('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),
        ('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),
        ('ROWBACKGROUNDS',(1,0),(-1,-1),[C_WHITE, C_GREY_ROW]),
    ]))
    _fin.append(terms_tbl)
    _fin.append(Spacer(1, 0.25*cm))

    # ── 6b. CALL TO ACTION (unified professional closing) ────────────────
    _cta_email = (cover.get('cta_email') or '').strip()
    _cta_phone = (cover.get('cta_phone') or '').strip()

    _cta_ps = _ps('ctab', fontName='Helvetica', fontSize=9, textColor=C_DARK, leading=13.5,
                  leftIndent=4, rightIndent=4)

    _cta_hdr = Table([[
        _p('CALL TO ACTION', _pw('ctah', fontName='Helvetica-Bold', fontSize=9, textColor=colors.white)),
    ]], colWidths=[BW_eff])
    _cta_hdr.setStyle(TableStyle([
        ('BACKGROUND',    (0,0),(-1,-1), colors.HexColor('#555555')),
        ('LINEBELOW',     (0,0),(-1,-1), 2, colors.HexColor('#888888')),
        ('TOPPADDING',    (0,0),(-1,-1), 5),
        ('BOTTOMPADDING', (0,0),(-1,-1), 5),
        ('LEFTPADDING',   (0,0),(-1,-1), 10),
    ]))
    _fin.append(_cta_hdr)
    _fin.append(Spacer(1, 0.12*cm))

    # Paragraph 1 — contact details (only if email/phone exist)
    if _cta_email or _cta_phone:
        if _cta_email and _cta_phone:
            _cta_contact_part = (
                f'<font color="#CC0000"><u>{_cta_email}</u></font> or call us at '
                f'<b>{_cta_phone}</b>'
            )
        elif _cta_email:
            _cta_contact_part = f'<font color="#CC0000"><u>{_cta_email}</u></font>'
        else:
            _cta_contact_part = f'<b>{_cta_phone}</b>'
        _fin.append(_p(
            f'To proceed with this proposal or for any further discussion, please contact our '
            f'sales team at {_cta_contact_part}. We look forward to partnering with you.',
            _cta_ps))
        _fin.append(Spacer(1, 0.10*cm))

    # Paragraphs 2-3 — use AI/custom body if provided, else defaults
    _cta_body = (cover.get('cta_body') or '').strip()
    def _cta_par(text):
        """Render CTA paragraph — Arabic-safe."""
        if _has_arabic(str(text)) and _arabic_ok:
            _ar_st = ParagraphStyle(
                'cta_ar', fontName=_AMIRI_FONT, fontSize=10,
                textColor=C_DARK, alignment=TA_RIGHT, leading=15, rightIndent=4,
            )
            return Paragraph(_fix_arabic(str(text)), _ar_st)
        return _p(str(text), _cta_ps)

    if _cta_body:
        for _cb_line in [ln.strip() for ln in _cta_body.split('\n') if ln.strip()]:
            _fin.append(_cta_par(_cb_line))
            _fin.append(Spacer(1, 0.08*cm))
    else:
        _fin.append(_cta_par(
            'In the meantime, should you have any questions or need to discuss the commercials in '
            'greater detail, please do not hesitate to contact the undersigned.'))
        _fin.append(Spacer(1, 0.10*cm))
        _fin.append(_cta_par(
            'We thank you for your support to EJ TECH and look forward to the pleasure of doing business.'))
        _fin.append(Spacer(1, 0.10*cm))

    # Sign-off
    _fin.append(_p('With best regards,',
        _ps('ctabr', fontName='Helvetica-Oblique', fontSize=9, textColor=C_DARK, leading=13,
            leftIndent=4)))
    _fin.append(Spacer(1, 0.22*cm))

    # ── 7. CLOSING & SIGNATURES ───────────────────────────────────────────
    prep_name  = cover.get('prep_by_name', '')
    prep_title = cover.get('prep_by_title', '') or 'Pre-Sales Engineer'
    mgr_name   = cover.get('mgr_name', '')
    mgr_title  = cover.get('mgr_title', '') or 'Sales Engineer'

    SIG_COL = (BW_eff - 0.8*cm) / 2   # each signature column width

    C_SIG_BG   = colors.HexColor('#FAFAFA')
    C_LINE     = colors.HexColor('#AAAAAA')

    def _sig_block(role, name, title, accent):
        """Build one signature column."""
        line_w = SIG_COL - 1.0*cm
        return Table([
            # Role label with coloured left micro-bar
            [Table([[_p(role, _ps(f'sr{role}', fontName='Helvetica-Bold',
                                  fontSize=7.5, textColor=accent))]],
                   colWidths=[SIG_COL - 0.4*cm],
                   style=TableStyle([
                       ('LINEBEFORE',(0,0),(-1,-1),3,accent),
                       ('LEFTPADDING',(0,0),(-1,-1),6),
                       ('TOPPADDING',(0,0),(-1,-1),2),
                       ('BOTTOMPADDING',(0,0),(-1,-1),2),
                   ]))],
            [Spacer(1, 0.25*cm)],
            # Dotted signature line
            [Table([['']], colWidths=[line_w],
                   style=TableStyle([
                       ('LINEABOVE',(0,0),(-1,-1),0.75,C_LINE),
                       ('TOPPADDING',(0,0),(-1,-1),0),
                       ('BOTTOMPADDING',(0,0),(-1,-1),0),
                   ]))],
            [Spacer(1, 0.1*cm)],
            # Name
            [_p(name or '', _ps(f'sn6{role}', fontName='Helvetica-Bold',
                                fontSize=10, textColor=C_NAVY, leading=13))],
            # Title
            [_p(title or '', _ps(f'st4{role}', fontSize=8.5,
                                 textColor=C_PURPLE2, leading=12))],
        ], colWidths=[SIG_COL - 0.4*cm])

    sig_outer = Table(
        [[_sig_block('Prepared By', prep_name, prep_title, C_PURPLE),
          _sig_block('Approved By', mgr_name, mgr_title, C_NAVY)]],
        colWidths=[SIG_COL + 0.4*cm, SIG_COL + 0.4*cm]
    )
    sig_outer.setStyle(TableStyle([
        ('VALIGN',(0,0),(-1,-1),'TOP'),
        ('BACKGROUND',(0,0),(-1,-1),C_SIG_BG),
        ('BOX',(0,0),(-1,-1),0.5,colors.HexColor('#E0E0E0')),
        ('LINEBEFORE',(1,0),(1,-1),0.5,colors.HexColor('#E0E0E0')),
        ('LINEABOVE',(0,0),(-1,-1),0,C_WHITE),
        ('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),
        ('TOPPADDING',(0,0),(-1,-1),12),('BOTTOMPADDING',(0,0),(-1,-1),12),
    ]))

    _fin.append(sig_outer)

    # ── Notes & Exclusions page (before final Terms/CTA/Sig page) ────────
    _notes_list      = [str(n) for n in (cover.get('notes')      or []) if str(n).strip()]
    _excl_list       = [str(e) for e in (cover.get('exclusions') or []) if str(e).strip()]
    if _notes_list or _excl_list:
        _ne_elements = [PageBreak()]

        def _ne_section_hdr(title, icon_char=''):
            t = Table([[_p(title, _pw('neh', fontName='Helvetica-Bold', fontSize=10, textColor=C_WHITE))]],
                      colWidths=[BW_eff])
            t.setStyle(TableStyle([
                ('BACKGROUND',(0,0),(-1,-1), C_NAVY),
                ('LINEBELOW', (0,0),(-1,-1), 3, C_PURPLE),
                ('TOPPADDING',(0,0),(-1,-1), 7),
                ('BOTTOMPADDING',(0,0),(-1,-1), 7),
                ('LEFTPADDING',(0,0),(-1,-1), 12),
            ]))
            return t

        def _ne_numbered_table(items):
            if not items:
                return None
            rows = []
            for idx, txt in enumerate(items, 1):
                num_cell = _p(str(idx), _ps(f'ni{idx}', fontName='Helvetica-Bold',
                               fontSize=9, textColor=C_WHITE, alignment=TA_CENTER))
                num_bg = Table([[num_cell]], colWidths=[0.75*cm])
                num_bg.setStyle(TableStyle([
                    ('BACKGROUND',(0,0),(-1,-1), C_PURPLE),
                    ('TOPPADDING',(0,0),(-1,-1), 4),
                    ('BOTTOMPADDING',(0,0),(-1,-1), 4),
                    ('LEFTPADDING',(0,0),(-1,-1), 2),
                    ('RIGHTPADDING',(0,0),(-1,-1), 2),
                    ('ROUNDEDCORNERS',[3]),
                ]))
                txt_cell = _p_ar(txt, _ps(f'nt{idx}', fontSize=9, textColor=C_DARK, leading=13))
                row_bg = C_WHITE if idx % 2 == 1 else C_GREY_ROW
                rows.append([num_bg, txt_cell])

            tbl = Table(rows, colWidths=[0.9*cm, BW_eff - 0.9*cm])
            cmds = [
                ('BOX',  (0,0),(-1,-1), 0.5, C_PURPLE3),
                ('INNERGRID',(0,0),(-1,-1), 0.25, colors.HexColor('#E5E5E5')),
                ('VALIGN',(0,0),(-1,-1), 'TOP'),
                ('TOPPADDING',(0,0),(-1,-1), 5),
                ('BOTTOMPADDING',(0,0),(-1,-1), 5),
                ('LEFTPADDING',(0,0),(-1,-1), 4),
                ('RIGHTPADDING',(0,0),(-1,-1), 8),
            ]
            for idx in range(len(rows)):
                bg = C_WHITE if idx % 2 == 0 else C_GREY_ROW
                cmds.append(('BACKGROUND',(1,idx),(1,idx), bg))
                cmds.append(('BACKGROUND',(0,idx),(0,idx), C_PURPLE))
            tbl.setStyle(TableStyle(cmds))
            return tbl

        if _notes_list:
            _ne_elements.append(_ne_section_hdr('NOTES'))
            _notes_tbl = _ne_numbered_table(_notes_list)
            if _notes_tbl:
                _ne_elements.append(_notes_tbl)
            _ne_elements.append(Spacer(1, 0.3*cm))

        if _excl_list:
            _ne_elements.append(_ne_section_hdr('EXCLUSIONS'))
            _excl_tbl = _ne_numbered_table(_excl_list)
            if _excl_tbl:
                _ne_elements.append(_excl_tbl)

        _post_boq = list(_ne_elements)
    else:
        _post_boq = []

    # Final pages (Notes+Exclusions then Terms/CTA/Sig) added AFTER BOQ loop
    _post_boq.extend([PageBreak(), KeepTogether(_fin)])

    # ── BOQ pages ────────────────────────────────────────────────────────
    # ── BOQ column visibility (from boq_opts) ─────────────────────────────
    _boq_opts      = boq_opts or {}
    _show_code     = _boq_opts.get('show_item_code', True)
    _show_vendor   = _boq_opts.get('show_vendor',    False)
    _show_stock    = _boq_opts.get('show_stock',     False)

    # Column order: S.# | [ITEM CODE] | ITEM DESCRIPTION | [VENDOR] | UOM | QTY | UNIT PRICE | TOTAL | [STOCK]
    # Fixed always-present overhead: sn(0.6)+uom(1.1)+qty(1.1)+up(2.0)+tot(2.5)+gutter(1.0) = 8.3
    _FIXED_OH = 8.7
    _code_w   = 2.0 if _show_code   else 0
    _vend_w   = 1.7 if _show_vendor else 0
    _stck_w   = 1.4 if _show_stock  else 0
    _desc_w   = BW - (_FIXED_OH + _code_w + _vend_w + _stck_w) * cm

    # Dynamic column spec: (key, header_label, width_cm, align)
    _COLDEFS = [('sn',   'S.#',            1.0,  'CENTER')]
    if _show_code:   _COLDEFS.append(('code',   'ITEM CODE', _code_w, 'CENTER'))
    _COLDEFS.append(('desc',  'ITEM DESCRIPTION', _desc_w/cm, 'LEFT'))
    if _show_vendor: _COLDEFS.append(('vendor', 'VENDOR',     _vend_w, 'CENTER'))
    _COLDEFS.append(('uom',   'UOM',              1.1,  'CENTER'))
    _COLDEFS.append(('qty',   'QTY',              1.1,  'RIGHT'))
    _COLDEFS.append(('up',    'UNIT PRICE',        2.0,  'RIGHT'))
    _COLDEFS.append(('total', 'TOTAL',             2.5,  'RIGHT'))
    if _show_stock:  _COLDEFS.append(('stock',  'STOCK',      _stck_w, 'CENTER'))

    _NCOLS_G = len(_COLDEFS)
    COL_W    = [c[2]*cm for c in _COLDEFS]

    def _ci(key):
        for i, c in enumerate(_COLDEFS): 
            if c[0] == key: return i
        return -1

    for bs in boq_sheets:
        story.append(PageBreak())
        ph = Table([[
            _p(f"<b>Date:</b> {cover.get('date','')}", S_BODY),
            _p(f"<b>Quote Ref.:</b> {cover.get('quoteref','')}", _ps('qrp', fontName='Helvetica-Bold', fontSize=9, textColor=C_PURPLE, alignment=TA_RIGHT)),
        ]], colWidths=[BW/2, BW/2])
        ph.setStyle(TableStyle([('LINEBELOW',(0,0),(-1,-1),1,C_PURPLE),
                                 ('PADDING',(0,0),(-1,-1),4),('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
        story.append(ph)
        story.append(Spacer(1, 0.3*cm))

        # ── System name + scope embedded in table (repeats on every page) ─
        sys_name  = bs.get('name', '')
        sys_scope = bs.get('scope', '')
        _NCOLS = _NCOLS_G  # number of columns in BOQ table (dynamic)

        S_SYSHD  = _ps('syshd',  fontName='Helvetica-Bold', fontSize=10,
                       textColor=C_WHITE, leading=14, alignment=TA_LEFT)
        S_SCOPTXT = _ps('scoptxt', fontName='Helvetica', fontSize=8.5,
                        textColor=colors.HexColor('#1A0000'), leading=12, alignment=TA_LEFT)

        tbl_data   = []
        style_cmds = []

        # Row 0 — System name banner (navy, full-width)
        _empty = [_p('') for _ in range(_NCOLS - 1)]
        tbl_data.append([_p(sys_name, S_SYSHD)] + _empty)
        style_cmds += [
            ('SPAN',          (0, 0), (-1, 0)),
            ('BACKGROUND',    (0, 0), (-1, 0), C_NAVY),
            ('TOPPADDING',    (0, 0), (-1, 0), 6),
            ('BOTTOMPADDING', (0, 0), (-1, 0), 6),
            ('LEFTPADDING',   (0, 0), (-1, 0), 8),
            ('RIGHTPADDING',  (0, 0), (-1, 0), 8),
        ]

        # Row 1 (optional) — Scope of work (light red, full-width)
        ri_offset = 1
        if sys_scope:
            tbl_data.append([_p(f'<b>SCOPE:</b> {sys_scope}', S_SCOPTXT)] + _empty)
            style_cmds += [
                ('SPAN',          (0, 1), (-1, 1)),
                ('BACKGROUND',    (0, 1), (-1, 1), colors.HexColor('#F5F5F5')),
                ('BOX',           (0, 1), (-1, 1), 0.6, C_PURPLE),
                ('TOPPADDING',    (0, 1), (-1, 1), 5),
                ('BOTTOMPADDING', (0, 1), (-1, 1), 5),
                ('LEFTPADDING',   (0, 1), (-1, 1), 8),
                ('RIGHTPADDING',  (0, 1), (-1, 1), 8),
            ]
            ri_offset = 2

        # Column header row (at ri_offset) — dynamic columns
        _hri = ri_offset
        _i_uom   = _ci('uom'); _i_qty = _ci('qty')
        _i_up    = _ci('up');  _i_tot = _ci('total')
        boq_hdr = []
        for _ckey, _clabel, _cw, _calign in _COLDEFS:
            if _calign == 'RIGHT':
                _hs = _ps(f'h_{_ckey}', fontName='Helvetica-Bold', fontSize=8, textColor=C_WHITE, alignment=TA_RIGHT)
            else:
                _hs = S_CODHD
            boq_hdr.append(_p(_clabel, _hs))
        tbl_data.append(boq_hdr)
        style_cmds += [
            ('BACKGROUND', (0, _hri), (-1, _hri), C_PURPLE),
            ('FONTNAME',   (0, _hri), (-1, _hri), 'Helvetica-Bold'),
            ('FONTSIZE',   (0, _hri), (-1, _hri), 8),
            ('TEXTCOLOR',  (0, _hri), (-1, _hri), C_WHITE),
            ('TOPPADDING',    (0, _hri), (-1, _hri), 5),
            ('BOTTOMPADDING', (0, _hri), (-1, _hri), 5),
            ('LEFTPADDING',   (0, 0),    (-1, -1),   4),
            ('RIGHTPADDING',  (0, 0),    (-1, -1),   4),
            ('TOPPADDING',    (0, 0),    (-1, -1),   4),
            ('BOTTOMPADDING', (0, 0),    (-1, -1),   4),
            ('ALIGN',  (0, 0),       (0, -1),       'CENTER'),
            ('ALIGN',  (_i_uom, 0),  (_i_uom, -1),  'CENTER'),
            ('ALIGN',  (_i_qty, 0),  (_i_qty, -1),  'RIGHT'),
            ('ALIGN',  (_i_up,  0),  (_i_up,  -1),  'RIGHT'),
            ('ALIGN',  (_i_tot, 0),  (_i_tot, -1),  'RIGHT'),
            ('BOX',       (0, 0), (-1, -1), 0.5, C_PURPLE),
            ('INNERGRID', (0, 0), (-1, -1), 0.25, colors.HexColor('#E5E5E5')),
            ('FONTSIZE',  (0, _hri+1), (-1, -1), 8.5),
            ('VALIGN',    (0, 0), (-1, -1), 'MIDDLE'),
        ]

        repeat_rows = _hri + 1   # sys name [+ scope] + col headers repeat on every page
        item_ctr = 0; grand_tot = 0.0; ri = _hri + 1

        for it in bs['items']:
            is_sec = it.get('is_section', False)
            desc = it.get('desc',''); code = it.get('code','')
            uom = it.get('uom',''); qty = it.get('qty')
            up = it.get('unit_price'); tot = it.get('total'); sn = it.get('sn','')

            if is_sec:
                _i_desc = _ci('desc')
                _sec_cells = [_p('') for _ in range(_NCOLS_G)]
                _sec_cells[_i_desc] = _p(f'<b>{desc}</b>', S_SEC)
                tbl_data.append(_sec_cells)
                style_cmds += [
                    ('SPAN',(0,ri),(-1,ri)),('BACKGROUND',(0,ri),(-1,ri),C_SEC_BG),
                    ('ALIGN',(0,ri),(-1,ri),'CENTER'),('FONTNAME',(0,ri),(-1,ri),'Helvetica-Bold'),
                    ('FONTSIZE',(0,ri),(-1,ri),8.5),('LINEABOVE',(0,ri),(-1,ri),0.5,C_PURPLE2),
                ]
            else:
                item_ctr += 1
                if tot: grand_tot += float(tot)
                try: qs = str(int(float(qty))) if qty is not None else ''
                except: qs = str(qty) if qty else ''
                tot_str = _fmt(tot) if tot else ('Option' if up else '')
                up_str  = _fmt(up)  if up  else ''
                _row_cells = {}
                _row_cells['sn']     = _p(sn or str(item_ctr), _ps(f'sn{ri}', fontSize=8.5, alignment=TA_CENTER))
                _row_cells['code']   = _p(code,    _ps(f'cd{ri}', fontSize=7.5))
                _row_cells['vendor'] = _p(it.get('vendor',''), _ps(f'vd{ri}', fontSize=7.5, alignment=TA_CENTER))
                _row_cells['stock']  = _p(it.get('stock',''),  _ps(f'st{ri}', fontSize=7.5, alignment=TA_CENTER))
                _row_cells['desc']   = _p(desc,    _ps(f'ds{ri}', fontSize=8.5, leading=11))
                _row_cells['uom']    = _p(uom,     _ps(f'um{ri}', fontSize=8.5, alignment=TA_CENTER))
                _row_cells['qty']    = _p(qs,      _ps(f'qt{ri}', fontSize=8.5, alignment=TA_RIGHT))
                _row_cells['up']     = _p(up_str,  _ps(f'up{ri}', fontSize=8.5, alignment=TA_RIGHT))
                _row_cells['total']  = _p(tot_str, _ps(f'tt{ri}', fontSize=8.5, alignment=TA_RIGHT))
                tbl_data.append([_row_cells[c[0]] for c in _COLDEFS])
                bg = C_GREY_ROW if item_ctr % 2 == 0 else C_WHITE
                style_cmds.append(('BACKGROUND',(0,ri),(-1,ri),bg))
            ri += 1

        _i_up_tot = _ci('up'); _i_tot_tot = _ci('total')
        _span_end  = _i_up_tot - 1  # merge everything before UNIT PRICE into label
        _tot_cells = [_p('') for _ in range(_NCOLS_G)]
        _tot_cells[0]          = _p('')
        _tot_cells[_i_up_tot]  = _p('Total Excluding VAT', _ps('gtt', fontName='Helvetica-Bold', fontSize=9, textColor=C_WHITE, alignment=TA_RIGHT))
        _tot_cells[_i_tot_tot] = _p(_fmt(grand_tot), _ps('gtv', fontName='Helvetica-Bold', fontSize=9, textColor=C_WHITE, alignment=TA_RIGHT))
        tbl_data.append(_tot_cells)
        style_cmds += [
            ('BACKGROUND',(0,ri),(-1,ri),C_TEAL),('TEXTCOLOR',(0,ri),(-1,ri),C_WHITE),
            ('FONTNAME',(0,ri),(-1,ri),'Helvetica-Bold'),('SPAN',(0,ri),(_span_end,ri)),
            ('LINEABOVE',(0,ri),(-1,ri),1,C_TEAL),('PADDING',(0,ri),(-1,ri),5),
        ]
        boq_tbl = Table(tbl_data, colWidths=COL_W, repeatRows=repeat_rows)
        boq_tbl.setStyle(TableStyle(style_cmds))
        story.append(boq_tbl)

        # ── Per-system notes (below BOQ table) ───────────────────────
        _sys_notes = [str(n).strip() for n in (bs.get('notes') or []) if str(n).strip()]
        if _sys_notes:
            story.append(Spacer(1, 0.2*cm))
            _sn_hdr = Table([[_p('NOTES', _pw('snh2', fontName='Helvetica-Bold', fontSize=8.5, textColor=C_WHITE))]],
                            colWidths=[BW_eff])
            _sn_hdr.setStyle(TableStyle([
                ('BACKGROUND', (0,0),(-1,-1), colors.HexColor('#555555')),
                ('LINEBELOW',  (0,0),(-1,-1), 2, C_PURPLE),
                ('TOPPADDING', (0,0),(-1,-1), 4),('BOTTOMPADDING',(0,0),(-1,-1), 4),
                ('LEFTPADDING',(0,0),(-1,-1), 10),
            ]))
            story.append(_sn_hdr)
            _sn_rows = []
            for _ni, _ntxt in enumerate(_sys_notes, 1):
                _nbadge = Table([[_p(str(_ni), _ps(f'snb{_ni}', fontName='Helvetica-Bold',
                    fontSize=8, textColor=C_WHITE, alignment=TA_CENTER))]],
                    colWidths=[0.75*cm])
                _nbadge.setStyle(TableStyle([
                    ('BACKGROUND',(0,0),(-1,-1), C_PURPLE),
                    ('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3),
                    ('LEFTPADDING',(0,0),(-1,-1),2),('RIGHTPADDING',(0,0),(-1,-1),2),
                ]))
                _sn_rows.append([_nbadge,
                    _p_ar(_ntxt, _ps(f'snt{_ni}', fontSize=8.5, textColor=C_DARK, leading=12))])
            _sn_tbl = Table(_sn_rows, colWidths=[0.9*cm, BW_eff - 0.9*cm])
            _sn_cmds = [
                ('BOX',(0,0),(-1,-1),0.5, C_PURPLE3),
                ('INNERGRID',(0,0),(-1,-1),0.25, colors.HexColor('#E5E5E5')),
                ('VALIGN',(0,0),(-1,-1),'MIDDLE'),
                ('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),
                ('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),8),
            ]
            for _ni in range(len(_sn_rows)):
                _sn_cmds.append(('BACKGROUND',(0,_ni),(0,_ni), C_PURPLE))
                _sn_cmds.append(('BACKGROUND',(1,_ni),(1,_ni),
                    C_WHITE if _ni % 2 == 0 else C_GREY_ROW))
            _sn_tbl.setStyle(TableStyle(_sn_cmds))
            story.append(_sn_tbl)

    # Append Notes/Exclusions + Terms/CTA/Sig after all BOQ pages
    story.extend(_post_boq)

    # ── NumberedCanvas: adds "Page X / Y" after all pages are known ────────
    from reportlab.pdfgen import canvas as _rl_canvas

    class _NumberedCanvas(_rl_canvas.Canvas):
        """Defers page number drawing so total page count is available."""
        def __init__(self, *args, **kwargs):
            _rl_canvas.Canvas.__init__(self, *args, **kwargs)
            self._saved_page_states = []

        def showPage(self):
            # Snapshot current canvas state (includes drawn content) then start fresh
            self._saved_page_states.append(dict(self.__dict__))
            self._startPage()

        def save(self):
            total = len(self._saved_page_states)
            for i, state in enumerate(self._saved_page_states, 1):
                self.__dict__.update(state)          # restore page content
                # Add ONLY the page number — decorations drawn by on_page already
                self.setFont('Helvetica-Bold', 8)
                self.setFillColor(C_PURPLE)
                self.drawRightString(W - MARGINS, 0.55*cm, f"Page {i} / {total}")
                _rl_canvas.Canvas.showPage(self)     # finalise this page
            _rl_canvas.Canvas.save(self)             # write PDF to buffer

    def on_page(canv, doc):
        canv.saveState()
        # Page background
        canv.setFillColor(colors.HexColor('#FAFAFA'))
        canv.rect(0, 0, W, H, fill=1, stroke=0)
        # Left accent stripe (3 mm)
        canv.setFillColor(C_NAVY)
        canv.rect(0, 0, 0.28*cm, H, fill=1, stroke=0)
        # Top border
        canv.setFillColor(colors.HexColor('#888888'))
        canv.rect(0, H - 0.22*cm, W, 0.22*cm, fill=1, stroke=0)
        # Footer bar
        canv.setFillColor(C_NAVY)
        canv.rect(0, 0, W, 1.4*cm, fill=1, stroke=0)
        # Footer left — company / ref info
        canv.setFont('Helvetica', 7.5)
        canv.setFillColor(colors.HexColor('#CCCCCC'))
        canv.drawString(MARGINS, 0.55*cm, f"EJ TECH  |  {quote_ref}  |  Confidential")
        # (page number drawn by _NumberedCanvas.save — not here)
        canv.restoreState()

    doc.build(story, onFirstPage=on_page, onLaterPages=on_page,
              canvasmaker=_NumberedCanvas)
    buf.seek(0)
    return buf



