@app.route('/cost_sheet_builder', methods=['GET'])
@login_required
def cost_sheet_builder():
    """Standalone Cost Sheet Builder page - loads previously saved sheet if any."""
    from flask import request as _req
    import sqlite3
    project_name = _req.args.get('project', '')
    rfq_ref      = _req.args.get('rfq', '')
    quoteref     = _req.args.get('quoteref', '')
    saved_sheets_json = None
    saved_at = None
    saved_by = None
    if rfq_ref:
        try:
            conn = sqlite3.connect('ProjectStatus.db')
            row = conn.execute(
                "SELECT sheets_json, updated_at, saved_by FROM cost_sheets WHERE rfq_ref=? AND quote_ref=?",
                (rfq_ref, quoteref or '')
            ).fetchone()
            conn.close()
            if row:
                saved_sheets_json = row[0]
                saved_at = row[1]
                saved_by = row[2]
        except Exception as e:
            app.logger.warning(f"cost_sheet load error: {e}")
    return render_template('cost_sheet_builder.html',
                           project_name=project_name,
                           rfq_ref=rfq_ref,
                           quoteref=quoteref,
                           saved_sheets_json=saved_sheets_json,
                           saved_at=saved_at,
                           saved_by=saved_by)




@app.route('/cost_sheet_builder/save', methods=['POST'])
@login_required
def cost_sheet_save():
    """AJAX: Upsert cost sheet data keyed by rfq_ref+quote_ref."""
    import sqlite3, json
    from flask import request as _req, jsonify, session
    data = _req.get_json(force=True) or {}
    rfq_ref      = data.get('rfq_ref', '').strip()
    quote_ref    = data.get('quote_ref', '').strip()
    project_name = data.get('project_name', '').strip()
    sheets       = data.get('sheets')
    if not rfq_ref:
        return jsonify({'error': 'RFQ reference is required to save.'}), 400
    if not sheets:
        return jsonify({'error': 'No sheet data to save.'}), 400
    sheets_json = json.dumps(sheets, ensure_ascii=False)
    saved_by = session.get('username', 'unknown')
    try:
        conn = sqlite3.connect('ProjectStatus.db')
        sql = ('INSERT INTO cost_sheets (rfq_ref, quote_ref, project_name, sheets_json, saved_by, updated_at) '
               'VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP) '
               'ON CONFLICT(rfq_ref, quote_ref) DO UPDATE SET '
               'sheets_json=excluded.sheets_json, project_name=excluded.project_name, '
               'saved_by=excluded.saved_by, updated_at=CURRENT_TIMESTAMP')
        conn.execute(sql, (rfq_ref, quote_ref, project_name, sheets_json, saved_by))
        conn.commit()
        row = conn.execute(
            'SELECT updated_at FROM cost_sheets WHERE rfq_ref=? AND quote_ref=?',
            (rfq_ref, quote_ref)
        ).fetchone()
        conn.close()
        return jsonify({'ok': True, 'updated_at': row[0] if row else '', 'saved_by': saved_by})
    except Exception as e:
        import traceback
        app.logger.error(f'cost_sheet_save error: {e}')
        return jsonify({'error': str(e)}), 500

@app.route('/cost_sheet_builder/import', methods=['POST'])
@login_required
def cost_sheet_import():
    """AJAX: Parse an uploaded cost-sheet Excel and return builder-compatible JSON."""
    import openpyxl
    from flask import request as _req, jsonify
    f = _req.files.get('excel_file')
    if not f:
        return jsonify({'error': 'No file uploaded'}), 400
    try:
        wb = openpyxl.load_workbook(BytesIO(f.read()), data_only=True)
        SKIP_NAMES = {'SUMMARY'}
        result_sheets = []

        for sname in wb.sheetnames:
            if sname.upper().strip() in SKIP_NAMES:
                continue
            ws = wb[sname]

            # Detect header row (rows 1-6, look for QTY/QUANTITY column)
            hdr_row_idx = None
            col_map = {}
            for row in ws.iter_rows(min_row=1, max_row=6):
                row_vals = {}
                for cell in row:
                    v = str(cell.value).strip() if cell.value is not None else ''
                    row_vals[cell.column] = v
                flat = ' '.join(row_vals.values()).upper()
                if 'QTY' not in flat and 'QUANTITY' not in flat:
                    continue
                for ci, hv in row_vals.items():
                    hu = hv.upper().strip()
                    if hu in ('S.#','S/#','S.NO','S/N','NO','#','NO.') and 'sn' not in col_map:
                        col_map['sn'] = ci
                    elif ('CODE' in hu or 'PART' in hu) and 'code' not in col_map:
                        col_map['code'] = ci
                    elif 'DESC' in hu and 'desc' not in col_map:
                        col_map['desc'] = ci
                    elif hu in ('UOM','UNIT','U/M','U.O.M') and 'uom' not in col_map:
                        col_map['uom'] = ci
                    elif hu in ('QTY','QUANTITY') and 'qty' not in col_map:
                        col_map['qty'] = ci
                    elif 'UNIT COST' in hu and 'unit_cost' not in col_map:
                        col_map['unit_cost'] = ci
                    elif 'UNIT PRICE' in hu and 'unit_price' not in col_map:
                        col_map['unit_price'] = ci
                    elif 'ROUND' in hu and 'round' not in col_map:
                        col_map['round'] = ci
                    elif hu in ('%','MARGIN') and 'pct' not in col_map:
                        col_map['pct'] = ci
                if col_map.get('desc') or col_map.get('qty'):
                    hdr_row_idx = row[0].row
                    break

            if hdr_row_idx is None:
                continue

            def _cv(row_cells, ci):
                cell = next((c for c in row_cells if c.column == ci), None)
                return cell.value if cell else None

            def _fv(v):
                if v is None: return ''
                try: f = float(v); return f if f != int(f) else int(f)
                except: return str(v).strip() if str(v).strip() not in ('None','') else ''

            rows_out = []
            for row in ws.iter_rows(min_row=hdr_row_idx + 1):
                sn_val   = _cv(row, col_map.get('sn',   0))
                code_val = _cv(row, col_map.get('code',  0))
                desc_val = _cv(row, col_map.get('desc',  0))
                qty_val  = _cv(row, col_map.get('qty',   0))

                sn_str   = str(sn_val).strip()   if sn_val   is not None else ''
                code_str = str(code_val).strip()  if code_val is not None else ''
                desc_str = str(desc_val).strip()  if desc_val is not None else ''

                # Skip totally empty rows
                if not sn_str and not desc_str and not code_str:
                    continue

                # Skip the grand total row
                desc_up = desc_str.upper()
                sn_up   = sn_str.upper()
                if any(k in desc_up for k in ('GRAND TOTAL','TOTAL EXCL','EXCLUDING VAT',
                                               'VALUE ADDED','TOTAL INCL')):
                    continue
                if 'TOTAL' in sn_up:
                    continue
                # Detect sheet-level total row (red footer) — stop here
                if (not sn_str or sn_str in ('', '-')) and code_str.upper() in ('', 'TOTAL EXCLUDING VAT')                         and 'TOTAL EXCLUDING VAT' in desc_up:
                    continue
                if code_str.upper() == 'TOTAL EXCLUDING VAT':
                    continue

                # `*` in S.# or empty S.# with no qty = section header
                if sn_str == '*':
                    sec_label = code_str or desc_str
                    if sec_label:
                        rows_out.append({'type': 'section', 'desc': sec_label})
                    continue

                # Empty S.# with a description but no numeric qty = subsection header
                if not sn_str:
                    if desc_str and not qty_val:
                        rows_out.append({'type': 'section', 'desc': desc_str or code_str})
                    continue

                # Item row
                uc_val  = _fv(_cv(row, col_map.get('unit_cost',  0)))
                up_val  = _fv(_cv(row, col_map.get('unit_price', 0)))
                ru_val  = _fv(_cv(row, col_map.get('round',      0)))

                # If old sheet has Round up but no Unit Price, treat Round up as Unit Price
                effective_up = up_val if up_val else ru_val
                uc_f = float(uc_val) if uc_val else 0
                up_f = float(effective_up) if effective_up else 0
                margin_val = round((1 - uc_f / up_f) * 100, 2) if uc_f and up_f else ''
                rows_out.append({
                    'type':       'item',
                    'item_code':  code_str,
                    'desc':       desc_str,
                    'uom':        str(_cv(row, col_map.get('uom', 0)) or '').strip(),
                    'qty':        _fv(qty_val),
                    'unit_cost':  uc_val,
                    'unit_price': effective_up,
                    'margin':     margin_val,
                })

            if rows_out:
                result_sheets.append({'name': sname, 'rows': rows_out})

        if not result_sheets:
            return jsonify({'error': 'No recognisable cost-sheet data found in this file. '
                                     'Make sure the file has Qty/UOM column headers.'}), 400

        return jsonify({'sheets': result_sheets})

    except Exception as e:
        import traceback
        app.logger.error(f"cost_sheet_import error: {e}\n{traceback.format_exc()}")
        return jsonify({'error': str(e)}), 500


@app.route('/cost_sheet_builder/export', methods=['POST'])
@login_required
def cost_sheet_export():
    """Generate and download the cost sheet as Excel (compatible with _parse_cost_sheet_boq)."""
    import openpyxl
    from openpyxl.styles import (Font, PatternFill, Alignment, Border, Side,
                                 numbers as xl_numbers)
    from openpyxl.utils import get_column_letter
    import json
    from flask import request as _req

    try:
        sheets_json = _req.form.get('sheets_data', '[]')
        sheets = json.loads(sheets_json)
        project_name = _req.form.get('project_name', '')
        quoteref     = _req.form.get('quoteref', '')

        wb = openpyxl.Workbook()
        wb.remove(wb.active)  # remove default sheet

        # ── Style helpers ──────────────────────────────────────────────
        HEADER_FILL   = PatternFill("solid", fgColor="1F3864")   # dark blue
        SECTION_FILL  = PatternFill("solid", fgColor="D6E4F7")   # light blue
        TOTAL_FILL    = PatternFill("solid", fgColor="C0504D")   # red
        TOTAL_FILL_W  = PatternFill("solid", fgColor="FFFFFF")
        hdr_font      = Font(bold=True, color="FFFFFF", name="Calibri", size=10)
        sec_font      = Font(bold=True, name="Calibri", size=10)
        item_font     = Font(name="Calibri", size=10)
        total_font    = Font(bold=True, color="FFFFFF", name="Calibri", size=10)
        center        = Alignment(horizontal="center", vertical="center", wrap_text=True)
        left          = Alignment(horizontal="left",   vertical="center", wrap_text=True)
        right         = Alignment(horizontal="right",  vertical="center")
        thin_side     = Side(style="thin", color="BBBBBB")
        thin_border   = Border(left=thin_side, right=thin_side,
                               top=thin_side, bottom=thin_side)

        COLS = ["S.#", "Item Code", "Item Description", "Vendor", "Stock", "UOM", "Qty",
                "Unit Cost", "Total Cost", "Unit Price", "Total Sell", "Margin %"]
        COL_WIDTHS = [5, 12, 45, 14, 11, 7, 7, 11, 12, 11, 12, 8]

        for sh_data in sheets:
            ws = wb.create_sheet(title=sh_data.get('name', 'Sheet')[:31])

            # ── Header row (row 1) ─────────────────────────────────────
            for ci, (col, w) in enumerate(zip(COLS, COL_WIDTHS), start=1):
                cell = ws.cell(row=1, column=ci, value=col)
                cell.fill = HEADER_FILL; cell.font = hdr_font
                cell.alignment = center; cell.border = thin_border
                ws.column_dimensions[get_column_letter(ci)].width = w
            ws.row_dimensions[1].height = 28

            row_idx = 2
            section_total_cost = 0.0
            section_total_sell = 0.0
            item_counter = 0

            for row in sh_data.get('rows', []):
                rtype = row.get('type', 'item')
                if rtype == 'section':
                    ws.cell(row=row_idx, column=1, value='*').font = sec_font
                    ws.cell(row=row_idx, column=1).alignment = center
                    sec_cell = ws.cell(row=row_idx, column=2,
                                       value=row.get('desc', ''))
                    sec_cell.font = Font(bold=True, name="Calibri", size=10)
                    sec_cell.fill = SECTION_FILL
                    for ci in range(1, 13):
                        ws.cell(row=row_idx, column=ci).fill = SECTION_FILL
                        ws.cell(row=row_idx, column=ci).border = thin_border
                    ws.row_dimensions[row_idx].height = 18
                else:
                    # Item row
                    item_counter += 1
                    try: qty = float(row.get('qty')       or 0)
                    except: qty = 0
                    try: uc  = float(row.get('unit_cost')  or 0)
                    except: uc = 0
                    try: up  = float(row.get('unit_price') or 0)
                    except: up = 0
                    # Margin: use stored value or derive from uc/up
                    try: stored_margin = float(row.get('margin') or 0)
                    except: stored_margin = 0
                    if not stored_margin and uc and up:
                        stored_margin = round((1 - uc / up) * 100, 2)

                    tot_cost = round(qty * uc, 2) if qty and uc else 0
                    tot_sell = round(qty * up, 2) if qty and up else 0
                    section_total_cost += tot_cost
                    section_total_sell += tot_sell

                    vals = [item_counter,
                            row.get('item_code', ''),
                            row.get('desc', ''),
                            row.get('vendor', ''),
                            row.get('stock', ''),
                            row.get('uom', ''),
                            qty, uc, tot_cost, up, tot_sell,
                            f"{stored_margin:.2f}%"]
                    for ci, v in enumerate(vals, start=1):
                        cell = ws.cell(row=row_idx, column=ci, value=v)
                        cell.font = item_font
                        cell.border = thin_border
                        if ci in (7, 8, 9, 10, 11):   # Qty, UC, TC, UP, TS
                            cell.alignment = right
                            if isinstance(v, (int, float)):
                                cell.number_format = '#,##0.00'
                        elif ci == 12:   # Margin %
                            cell.alignment = center
                        elif ci in (3, 4):   # Desc, Vendor
                            cell.alignment = left
                        else:
                            cell.alignment = center
                    ws.row_dimensions[row_idx].height = 32

                row_idx += 1

            # ── Total row (10 cols: no Round up) ───────────────────────
            margin_total = round((1 - section_total_cost / section_total_sell) * 100, 3) \
                           if section_total_sell else 0
            sh_name = sh_data.get('name', 'System')

            # Col 1-5: merged label (S.#, Code, Desc, Vendor, Stock)
            ws.merge_cells(start_row=row_idx, start_column=1,
                           end_row=row_idx, end_column=5)
            ws.cell(row=row_idx, column=1,
                    value=f"Total {sh_name} System").font = total_font
            ws.cell(row=row_idx, column=1).fill = TOTAL_FILL
            ws.cell(row=row_idx, column=1).alignment = center

            # Col 6-7: merged "TOTAL EXCLUDING VAT" (UOM, Qty)
            ws.merge_cells(start_row=row_idx, start_column=6,
                           end_row=row_idx, end_column=7)
            ws.cell(row=row_idx, column=6,
                    value="TOTAL EXCLUDING VAT").font = total_font
            ws.cell(row=row_idx, column=6).fill = TOTAL_FILL
            ws.cell(row=row_idx, column=6).alignment = center

            # Col 8: blank (Unit Cost column)
            ws.cell(row=row_idx, column=8, value='').fill = TOTAL_FILL

            # Col 9: Total Cost
            ws.cell(row=row_idx, column=9, value=section_total_cost)
            ws.cell(row=row_idx, column=9).font = total_font
            ws.cell(row=row_idx, column=9).fill = TOTAL_FILL
            ws.cell(row=row_idx, column=9).number_format = '#,##0.00'
            ws.cell(row=row_idx, column=9).alignment = right

            # Col 10: blank (Unit Price column)
            ws.cell(row=row_idx, column=10, value='').fill = TOTAL_FILL

            # Col 11: Total Sell
            ws.cell(row=row_idx, column=11, value=section_total_sell)
            ws.cell(row=row_idx, column=11).font = total_font
            ws.cell(row=row_idx, column=11).fill = TOTAL_FILL
            ws.cell(row=row_idx, column=11).number_format = '#,##0.00'
            ws.cell(row=row_idx, column=11).alignment = right

            # Col 12: Overall Margin %
            ws.cell(row=row_idx, column=12, value=f"{margin_total:.3f}%")
            ws.cell(row=row_idx, column=12).font = total_font
            ws.cell(row=row_idx, column=12).fill = TOTAL_FILL
            ws.cell(row=row_idx, column=12).alignment = center

            ws.row_dimensions[row_idx].height = 22
            ws.freeze_panes = "A2"

        buf = BytesIO()
        wb.save(buf)
        buf.seek(0)
        safe = (quoteref or project_name or 'CostSheet').replace('/', '-').replace(' ', '_')
        return send_file(buf, as_attachment=True,
                         download_name=f'{safe}_Cost_Sheet.xlsx',
                         mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')

    except Exception as e:
        import traceback
        app.logger.error(f"cost_sheet_export error: {e}\n{traceback.format_exc()}")
        flash(f'Export failed: {str(e)}', 'danger')
        return redirect(url_for('cost_sheet_builder'))


def _parse_cost_sheet_boq(wb):
    """Parse EJTech cost-sheet workbook → boq_sheets list.
    Uses 'Round up' column as unit price; Total = Round_up * Qty.
    Rows with '*' in S.# are section headers. Skips Summary & BOQ sheets."""
    SKIP = {'SUMMARY'}
    boq_sheets = []
    for sname in wb.sheetnames:
        if sname.upper().strip() in SKIP: continue
        if 'BOQ' in sname.upper(): continue
        ws = wb[sname]
        hdr_row_idx = None
        col_map = {}
        for row in ws.iter_rows(min_row=1, max_row=5):
            row_vals = {cell.column: str(cell.value).strip() if cell.value is not None else '' for cell in row}
            flat = ' '.join(row_vals.values()).upper()
            if 'QTY' not in flat and 'QUANTITY' not in flat: continue
            for ci, hv in row_vals.items():
                hu = hv.upper().strip()
                if hu in ('S.#','S/#','S.NO','S/N','NO','#','NO.') and 'sn' not in col_map: col_map['sn'] = ci
                elif ('CODE' in hu or 'PART' in hu) and 'code' not in col_map: col_map['code'] = ci
                elif 'DESC' in hu and 'desc' not in col_map: col_map['desc'] = ci
                elif hu in ('UOM','UNIT','U/M','U.O.M') and 'uom' not in col_map: col_map['uom'] = ci
                elif hu in ('QTY','QUANTITY') and 'qty' not in col_map: col_map['qty'] = ci
                elif 'ROUND' in hu and 'round' not in col_map: col_map['round'] = ci
                elif 'UNIT PRICE' in hu and 'unit_price' not in col_map: col_map['unit_price'] = ci
                elif hu in ('%','MARGIN','MARGIN%') and 'pct' not in col_map: col_map['pct'] = ci
                elif hu == 'TOTAL' and ci > col_map.get('qty', 0):
                    if 'round' in col_map and ci > col_map['round']: col_map['total_sell'] = ci
                    elif 'total_cost' not in col_map: col_map['total_cost'] = ci
            if col_map.get('desc'):
                hdr_row_idx = row[0].row
                # Detect unlabeled round-up col after % column
                if 'round' not in col_map and 'pct' in col_map:
                    pct_ci = col_map['pct']
                    for chk_row in ws.iter_rows(min_row=hdr_row_idx+1, max_row=hdr_row_idx+3):
                        for cell in chk_row:
                            if cell.column > pct_ci:
                                try: float(cell.value); col_map['round'] = cell.column; break
                                except (TypeError, ValueError): pass
                        if 'round' in col_map: break
                break
        if hdr_row_idx is None or 'desc' not in col_map: continue
        price_col = col_map.get('round') or col_map.get('unit_price')
        total_col = col_map.get('total_sell')
        items = []
        for row in ws.iter_rows(min_row=hdr_row_idx + 1):
            def _v(ci, _row=row):
                if ci is None: return None
                cell = next((c for c in _row if c.column == ci), None)
                return cell.value if cell else None
            sn_val = _v(col_map.get('sn')); desc_val = _v(col_map.get('desc'))
            code_val = _v(col_map.get('code'))
            if desc_val is None and sn_val is None: continue
            sn_str = str(sn_val).strip() if sn_val is not None else ''
            desc_str = str(desc_val).strip() if desc_val is not None else ''
            code_str = str(code_val).strip() if code_val is not None else ''
            if not desc_str and not sn_str: continue
            if any(kw in desc_str.upper() for kw in ('GRAND TOTAL','TOTAL EXCL','TOTAL INCL','EXCLUDING VAT','VALUE ADDED')): continue
            if any(kw in sn_str.upper() for kw in ('TOTAL','VAT')): continue
            if sn_str == '*':
                sec_desc = code_str or desc_str
                if sec_desc: items.append({'sn':'','code':'','desc':sec_desc,'uom':'','qty':None,'unit_price':None,'total':None,'is_section':True})
                continue
            def _f(val):
                if val is None: return None
                try: return float(val)
                except: return None
            qty_val = _f(_v(col_map.get('qty'))); up_val = _f(_v(price_col)); tot_val = _f(_v(total_col))
            if up_val is None and tot_val is None: continue
            if tot_val is None and up_val is not None and qty_val: tot_val = round(up_val * qty_val, 2)
            uom_val = str(_v(col_map.get('uom')) or '').strip()
            items.append({'sn':sn_str,'code':code_str,'desc':desc_str,'uom':uom_val,'qty':qty_val,
                          'unit_price':up_val,'total':tot_val,'is_section':False})
        priced = [it for it in items if it.get('total') and not it.get('is_section')]
        if priced:
            boq_sheets.append({'name':sname,'items':items,'grand_total':sum(it['total'] for it in priced)})
    return boq_sheets


@app.route('/quotation_pdf_professional/<path:quote_ref>', methods=['GET'])
@login_required
def quotation_pdf_professional(quote_ref):
    """Generate a professional formatted PDF quotation from the Excel BOQ data."""
    if not user_has_permission('download_quotation'):
        flash('You do not have permission to download quotations.', 'danger')
        return redirect(url_for('quotation_profile', quote_ref=quote_ref))

    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM projects WHERE quote_ref=?", (quote_ref,))
    proj = c.fetchone()
    conn.close()

    if not proj or not proj['quotation']:
        flash('Quotation file not found.', 'danger')
        return redirect(url_for('quotation_profile', quote_ref=quote_ref))

    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.units import cm
        from reportlab.lib import colors
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.enums import TA_LEFT, TA_CENTER, TA_RIGHT
        from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table,
                                        TableStyle, PageBreak, KeepTogether)
        from reportlab.platypus import Image as RLImage
        import openpyxl

        W, H = A4

        # ── Brand colours ──────────────────────────────────────────────────
        C_PURPLE   = colors.HexColor('#4B2D8F')
        C_PURPLE2  = colors.HexColor('#7B5EA7')
        C_GOLD     = colors.HexColor('#F9A825')
        C_TEAL     = colors.HexColor('#00897B')
        C_DARK     = colors.HexColor('#212121')
        C_GREY_HDR = colors.HexColor('#F3F0FA')
        C_GREY_ROW = colors.HexColor('#F8F8F8')
        C_SEC_BG   = colors.HexColor('#EDE7F6')
        C_WHITE    = colors.white

        def _ps(name, **kw):
            base = ParagraphStyle(name, fontName='Helvetica', fontSize=9, textColor=C_DARK, leading=12)
            for k, v in kw.items():
                setattr(base, k, v)
            return base

        S_BODY  = _ps('body')
        S_BOLD  = _ps('bold', fontName='Helvetica-Bold')
        S_SUBHD = _ps('subhd', fontName='Helvetica-Bold', fontSize=9, textColor=C_PURPLE2)
        S_WHITE = _ps('wht', fontName='Helvetica-Bold', fontSize=9, textColor=C_WHITE, alignment=TA_CENTER)
        S_ITEM  = _ps('item', fontSize=8.5, leading=11)
        S_CODE  = _ps('code', fontSize=8, fontName='Helvetica')
        S_RIGHT = _ps('right', alignment=TA_RIGHT)
        S_CENT  = _ps('cent', alignment=TA_CENTER)
        S_NUM   = _ps('num', fontSize=8.5, alignment=TA_RIGHT)
        S_SEC   = _ps('sec', fontName='Helvetica-Bold', fontSize=8.5, textColor=C_PURPLE, alignment=TA_CENTER)
        S_CODHD = _ps('codhd', fontName='Helvetica-Bold', fontSize=8, textColor=C_WHITE, alignment=TA_CENTER)
        S_GREY  = _ps('grey', fontSize=8, textColor=colors.HexColor('#666666'))

        def _p(text, style=None):
            return Paragraph(str(text) if text else '', style or S_BODY)

        def _fmt(v):
            try: return f'{float(v):,.2f}'
            except: return str(v) if v else ''

        def _logo():
            lp = os.path.join(os.path.dirname(__file__), 'static', 'ejt.png')
            try: return RLImage(lp, width=3.2*cm, height=1.1*cm)
            except: return _p('<b>EJ TECH</b>', _ps('lg', fontName='Helvetica-Bold', fontSize=13, textColor=C_PURPLE))

        # ── Parse COVER PAGE ──────────────────────────────────────────────
        wb = openpyxl.load_workbook(BytesIO(proj['quotation']), data_only=True)
        cov_ws = next((wb[s] for s in wb.sheetnames if 'COVER' in s.upper()), None)

        def _parse_cover(ws):
            cells = {}
            if ws is None: return {}
            for row in ws.iter_rows():
                for cell in row:
                    if cell.value is not None:
                        cells[(cell.row, cell.column)] = str(cell.value).strip()
            def g(r, c): return cells.get((r, c), '')
            data = {
                'date':    g(1,1).replace('Date:','').strip(),
                'quoteref': g(1,3).replace('Quote Ref.:','').strip() or quote_ref,
                'engref':  g(1,4).replace('Eng. Ref:','').replace('Eng. Ref. :','').strip(),
                'to':      g(2,1).replace('To:','').strip(),
                'attn':    g(2,3).replace('Attn.:','').strip(),
                'frm':     g(2,4).replace('From:','').strip(),
                'cont':    g(3,4).replace('Cont.:','').strip(),
                'sub': '', 'scope': '', 'systems': [], 'terms': {},
                'prep_by_label':'Prepared By:', 'mgr_label':'Managed by:',
                'prep_by_name':'','mgr_name':'','prep_by_title':'','mgr_title':'',
            }
            for (r, c), v in sorted(cells.items()):
                if v.startswith('SUB.:'):   data['sub']   = v[5:].strip()
                elif v.startswith('SCOPE:'): data['scope'] = v[6:].strip()
            in_sum = False
            for r in range(1, 70):
                c1 = cells.get((r,1),''); c2 = cells.get((r,2),''); c4 = cells.get((r,4),'')
                if c1 == 'SUMMARY': in_sum = True; continue
                if in_sum and c1 not in ('No.','') and not c1.startswith('Supply') and not c1.startswith('\xa0'):
                    if c1.strip().lstrip('0123456789') == '' and c4:
                        data['systems'].append({'idx':c1,'name':c2,'total':c4})
                    elif c1 in ('Total (SAR)','VAT (15%)','Grand Total') and c4:
                        data['systems'].append({'idx':'','name':c1,'total':c4,'is_summary':True})
                # Terms
                if c1 in ('Price','Payment Terms','Offer Validity','Delivery Terms','Scope of Work','Warranty','Notes:','Exclusions'):
                    c2v = cells.get((r,2),'')
                    if c2v: data['terms'][c1] = c2v
                # Signatures
                if 'Prepared By' in c2:
                    data['prep_by_label'] = c2; data['mgr_label'] = cells.get((r,3),'Managed by:')
                    data['prep_by_name']  = cells.get((r+1,2),''); data['mgr_name'] = cells.get((r+1,3),'')
                    data['prep_by_title'] = cells.get((r+2,2),''); data['mgr_title'] = cells.get((r+2,3),'')
            return data

        cover = _parse_cover(cov_ws)
        if not cover.get('sub'):
            cover['sub'] = f"PROPOSAL OF {proj.get('system','')} SYSTEM For {proj.get('project_name','')}"
        if not cover.get('scope'):
            cover['scope'] = proj.get('sow','Supply, Installation, Testing and Commissioning')
        if not cover.get('quoteref'):
            cover['quoteref'] = quote_ref
        if not cover.get('prep_by_name'):
            cover['prep_by_name'] = proj.get('presale_eng','')
        if not cover.get('mgr_name'):
            cover['mgr_name'] = proj.get('sales_eng','')

        # ── Parse BOQ sheets ──────────────────────────────────────────────
        SKIP_SHEETS = {'COVER PAGE','COVER PAGE ','COVER PAGE  ','COVER','SUMMARY','INDEX','TOC'}

        def _parse_boq_sheet(ws):
            for rr in ws.iter_rows(min_row=1, max_row=20):
                vals = [str(c.value).upper().strip() if c.value else '' for c in rr]
                row_text = ' '.join(vals)
                has_desc = 'DESCRIPTION' in row_text or 'ITEM DESC' in row_text
                has_qty  = 'QTY' in row_text or 'QUANTITY' in row_text
                has_sn   = any(v in ('S.#','S.NO','NO','S/N','#','NO.') for v in vals)
                if not (has_desc and (has_qty or has_sn)): continue
                col_map = dict(sn=None,code=None,desc=None,uom=None,qty=None,uprice=None,total=None)
                for cell in rr:
                    hv = str(cell.value).upper().strip() if cell.value else ''
                    ci = cell.column
                    if hv in ('S.#','S.NO','NO','S/N','#','NO.'): col_map['sn'] = ci
                    elif ('CODE' in hv or 'PART' in hv or 'P/N' in hv or hv=='PN') and col_map['code'] is None: col_map['code'] = ci
                    elif 'DESC' in hv and col_map['desc'] is None: col_map['desc'] = ci
                    elif hv in ('UOM','UNIT','U/M','U.O.M') and col_map['uom'] is None: col_map['uom'] = ci
                    elif hv in ('QTY',"QUANTITY","Q\'TY") and col_map['qty'] is None: col_map['qty'] = ci
                    elif ('UNIT PRICE' in hv or 'UNIT COST' in hv or hv in ('U.P','U/P')) and col_map['uprice'] is None: col_map['uprice'] = ci
                    elif 'TOTAL' in hv and col_map['total'] is None: col_map['total'] = ci
                if col_map['desc']:
                    return rr[0].row, col_map
            return None

        def _read_boq_items(ws, hdr_idx, col_map):
            items = []
            for row2 in ws.iter_rows(min_row=hdr_idx + 1):
                dv = row2[col_map['desc']-1].value if col_map.get('desc') else None
                if dv is None or str(dv).strip() == '': continue
                ds = str(dv).strip()
                if any(kw in ds.upper() for kw in ('GRAND TOTAL','VAT AMOUNT','TOTAL EXCL','TOTAL INCL','VALUE ADDED')): continue
                def _n(col):
                    if not col: return None
                    raw = row2[col-1].value
                    try: return float(raw) if raw is not None else None
                    except: return None
                def _s(col):
                    if not col: return ''
                    v = row2[col-1].value
                    s = str(v).strip() if v is not None else ''
                    return '' if s == 'None' else s
                qv = _n(col_map.get('qty')); upv = _n(col_map.get('uprice'))
                tv = _n(col_map.get('total'))
                if tv is None and qv and upv: tv = qv * upv
                is_sec = (qv is None and upv is None)
                items.append({'sn':_s(col_map.get('sn')),'code':_s(col_map.get('code')),'desc':ds,
                              'uom':_s(col_map.get('uom')),'qty':qv,'unit_price':upv,'total':tv,'is_section':is_sec})
            return items

        boq_sheets = []
        for sname in wb.sheetnames:
            if sname.upper().strip() in SKIP_SHEETS: continue
            ws2 = wb[sname]
            res = _parse_boq_sheet(ws2)
            if res is None: continue
            hdr_idx, col_map = res
            items = _read_boq_items(ws2, hdr_idx, col_map)
            priced = [it for it in items if it.get('total') and not it.get('is_section')]
            if priced:
                boq_sheets.append({'name': sname, 'items': items,
                                   'grand_total': sum(it['total'] for it in priced)})

        # ── Build PDF ────────────────────────────────────────────────────
        buf = _build_quotation_pdf(cover, boq_sheets, quote_ref)

        buf.seek(0)
        safe_name = quote_ref.replace('/', '-').replace('\\', '-').replace(' ', '_')
        return send_file(buf, as_attachment=True,
                         download_name=f'{safe_name}_Quotation.pdf',
                         mimetype='application/pdf')

    except Exception as _pdf_err:
        import traceback
        app.logger.error(f"PDF generation failed: {_pdf_err}\n{traceback.format_exc()}")
        flash(f'PDF generation failed: {str(_pdf_err)}', 'danger')
        return redirect(url_for('quotation_profile', quote_ref=quote_ref))


