@app.route('/registered_quotations')
@permission_required('view_reports')
def registered_quotations():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Get filter values from URL
    filters = {
        'start_registered': request.args.get('start_registered_date'),
        'end_registered': request.args.get('end_registered_date'),
        'start_updated': request.args.get('start_updated_date'),
        'end_updated': request.args.get('end_updated_date'),
        'sales_eng': request.args.get('sales_eng'),
        'presale_eng': request.args.get('presale_eng')
    }

    # Base query updated to select quotation_cost, rfq_reference and rfq_id
    query = """
        SELECT p.id, p.project_name, p.quote_ref, p.presale_eng, p.sales_eng, p.status, 
               p.quotation_selling_price, p.margin, p.registered_date, p.updated_time,
               p.quotation_cost, p.rfq_reference,
               (SELECT rp.id FROM register_project rp WHERE rp.project_name = p.project_name LIMIT 1) as project_id,
               (SELECT r.id FROM rfq_requests r WHERE r.rfq_reference = p.rfq_reference LIMIT 1) as rfq_id
        FROM projects p
        WHERE 1=1
    """
    params = []

    # Apply filters to the query
    if filters['start_registered']: query += " AND date(registered_date) >= ?"; params.append(
        filters['start_registered'])
    if filters['end_registered']: query += " AND date(registered_date) <= ?"; params.append(filters['end_registered'])
    if filters['start_updated']: query += " AND date(updated_time) >= ?"; params.append(filters['start_updated'])
    if filters['end_updated']: query += " AND date(updated_time) <= ?"; params.append(filters['end_updated'])
    if filters['sales_eng']: query += " AND sales_eng = ?"; params.append(filters['sales_eng'])
    if filters['presale_eng']: query += " AND presale_eng = ?"; params.append(filters['presale_eng'])

    query += " ORDER BY registered_date DESC"
    c.execute(query, params)
    quotations = c.fetchall()

    # Fetch engineers for filter dropdowns based on registered quotation data
    c.execute("SELECT DISTINCT sales_eng FROM projects WHERE sales_eng IS NOT NULL AND sales_eng != '' ORDER BY sales_eng")
    sales_engineers = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT presale_eng FROM projects WHERE presale_eng IS NOT NULL AND presale_eng != '' ORDER BY presale_eng")
    presale_engineers = [row[0] for row in c.fetchall()]
    conn.close()

    is_admin = session.get('username', '').lower() == 'm.saleh'
    
    return render_template('registered_quotations.html',
                           quotations=quotations,
                           presale_engineers=presale_engineers,
                           sales_engineers=sales_engineers,
                           current_filters=filters,
                           is_admin=is_admin)


@app.route('/api/quotation/<int:quotation_id>', methods=['DELETE'])
@login_required
def delete_quotation(quotation_id):
    """Delete a quotation by ID - Admin only (M.Saleh)"""
    if session.get('username', '').lower() != 'm.saleh':
        return jsonify({'success': False, 'error': 'Unauthorized. Admin access required.'}), 403
    
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    # Check if quotation exists and get quote_ref
    c.execute("SELECT id, quote_ref FROM projects WHERE id = ?", (quotation_id,))
    quotation = c.fetchone()
    
    if not quotation:
        conn.close()
        return jsonify({'success': False, 'error': 'Quotation not found'}), 404
    
    quote_ref = quotation[1]
    
    # Delete quotation products for this specific quotation
    c.execute("DELETE FROM quotation_products WHERE quote_ref = ? AND id IN (SELECT qp.id FROM quotation_products qp WHERE qp.quote_ref = ? LIMIT 1)", (quote_ref, quote_ref))
    
    # Delete only this specific quotation by ID
    c.execute("DELETE FROM projects WHERE id = ?", (quotation_id,))
    
    conn.commit()
    conn.close()
    
    return jsonify({'success': True, 'message': 'Quotation deleted successfully'})


@app.route('/engineer_reports')
@login_required
def engineer_reports():
    """Engineer Reports - View projects and quotations by Sales or Presale Engineer"""
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    report_type = request.args.get('type', 'sales')
    selected_engineer = request.args.get('engineer', '')
    selected_year = request.args.get('year', '')
    selected_quarter = request.args.get('quarter', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    
    # Get available years from projects
    c.execute("SELECT DISTINCT strftime('%Y', registered_date) as year FROM projects WHERE registered_date IS NOT NULL ORDER BY year DESC")
    years = [row[0] for row in c.fetchall() if row[0]]
    
    # Get list of engineers based on report type
    if report_type == 'sales':
        c.execute("SELECT DISTINCT sales_eng FROM projects WHERE sales_eng IS NOT NULL AND sales_eng != '' ORDER BY sales_eng")
    else:
        c.execute("SELECT DISTINCT presale_eng FROM projects WHERE presale_eng IS NOT NULL AND presale_eng != '' ORDER BY presale_eng")
    
    engineers = [row[0] for row in c.fetchall()]
    
    projects = []
    total_quotations = 0
    
    if selected_engineer:
        # Build date filter conditions
        date_conditions = ""
        params_base = [selected_engineer]
        
        if selected_year:
            date_conditions += " AND strftime('%Y', registered_date) = ?"
            params_base.append(selected_year)
        
        # Month filter takes priority over quarter if both are set
        if selected_month:
            date_conditions += " AND strftime('%m', registered_date) = ?"
            params_base.append(selected_month)
            
            # Week filter only applies when month is selected
            if selected_week:
                # Calculate week of month based on day: Week 1 = days 1-7, Week 2 = days 8-14, etc.
                week_num = int(selected_week)
                start_day = (week_num - 1) * 7 + 1
                end_day = week_num * 7
                date_conditions += " AND CAST(strftime('%d', registered_date) AS INTEGER) BETWEEN ? AND ?"
                params_base.extend([start_day, end_day])
        elif selected_quarter:
            quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
            if selected_quarter in quarter_map:
                start_month, end_month = quarter_map[selected_quarter]
                date_conditions += " AND strftime('%m', registered_date) BETWEEN ? AND ?"
                params_base.extend([start_month, end_month])
        
        # Get projects for this engineer with date filters
        if report_type == 'sales':
            query = f"""
                SELECT project_name, MAX(registered_date) as latest_date
                FROM projects 
                WHERE sales_eng = ? AND project_name IS NOT NULL AND project_name != ''
                {date_conditions}
                GROUP BY project_name
                ORDER BY latest_date DESC
            """
        else:
            query = f"""
                SELECT project_name, MAX(registered_date) as latest_date
                FROM projects 
                WHERE presale_eng = ? AND project_name IS NOT NULL AND project_name != ''
                {date_conditions}
                GROUP BY project_name
                ORDER BY latest_date DESC
            """
        c.execute(query, params_base)
        project_names = [row[0] for row in c.fetchall()]
        
        for project_name in project_names:
            # Get quotations for this project by this engineer with date filters
            if report_type == 'sales':
                query = f"""
                    SELECT p.id, p.quote_ref, p.presale_eng, p.status, p.quotation_selling_price, p.registered_date, p.project_name,
                           COALESCE(eu.name, co.name, cn.name, 'N/A') as client_name, rp.client_type, rp.id as register_project_id,
                           rp.end_user_id, rp.contractor_id, rp.consultant_id
                    FROM projects p
                    LEFT JOIN register_project rp ON p.project_name = rp.project_name
                    LEFT JOIN end_users eu ON rp.end_user_id = eu.id
                    LEFT JOIN contractors co ON rp.contractor_id = co.id
                    LEFT JOIN consultants cn ON rp.consultant_id = cn.id
                    WHERE p.project_name = ? AND p.sales_eng = ?
                    {date_conditions.replace('registered_date', 'p.registered_date') if date_conditions else ''}
                    ORDER BY p.registered_date DESC
                """
                params = [project_name, selected_engineer] + params_base[1:]
            else:
                query = f"""
                    SELECT p.id, p.quote_ref, p.sales_eng, p.status, p.quotation_selling_price, p.registered_date, p.project_name,
                           COALESCE(eu.name, co.name, cn.name, 'N/A') as client_name, rp.client_type, rp.id as register_project_id,
                           rp.end_user_id, rp.contractor_id, rp.consultant_id
                    FROM projects p
                    LEFT JOIN register_project rp ON p.project_name = rp.project_name
                    LEFT JOIN end_users eu ON rp.end_user_id = eu.id
                    LEFT JOIN contractors co ON rp.contractor_id = co.id
                    LEFT JOIN consultants cn ON rp.consultant_id = cn.id
                    WHERE p.project_name = ? AND p.presale_eng = ?
                    {date_conditions.replace('registered_date', 'p.registered_date') if date_conditions else ''}
                    ORDER BY p.registered_date DESC
                """
                params = [project_name, selected_engineer] + params_base[1:]
            c.execute(query, params)
            
            quotations = []
            for row in c.fetchall():
                # Determine client_id based on client_type
                client_type = row[8]
                client_id = None
                if client_type == 'End User' and row[10]:
                    client_id = row[10]
                elif client_type == 'Contractor' and row[11]:
                    client_id = row[11]
                elif client_type == 'Consultant' and row[12]:
                    client_id = row[12]
                
                quotations.append({
                    'id': row[0],
                    'quote_ref': row[1],
                    'associated_engineer': row[2],
                    'status': row[3],
                    'selling_price': row[4],
                    'registered_date': row[5],
                    'project_name': row[6],
                    'client_name': row[7],
                    'client_type': client_type,
                    'register_project_id': row[9],
                    'client_id': client_id
                })
            
            if quotations:
                projects.append({
                    'name': project_name,
                    'quotations': quotations
                })
                total_quotations += len(quotations)
    
    # Calculate summary statistics and add status flags to each project
    won_count = 0
    lost_count = 0
    ongoing_count = 0
    total_won_value = 0
    total_lost_value = 0
    total_ongoing_value = 0
    
    for project in projects:
        project_has_won = False
        project_has_lost = False
        project_has_ongoing = False
        
        for q in project['quotations']:
            status = (q['status'] or '').lower()
            selling_price = float(q['selling_price'] or 0)
            # Check for won status variations (Won, Closed Won, etc.)
            if 'won' in status:
                won_count += 1
                total_won_value += selling_price
                project_has_won = True
                q['status_category'] = 'won'
            # Check for lost status variations (Lost, Closed Lost, etc.)
            elif 'lost' in status:
                lost_count += 1
                total_lost_value += selling_price
                project_has_lost = True
                q['status_category'] = 'lost'
            else:
                ongoing_count += 1
                total_ongoing_value += selling_price
                project_has_ongoing = True
                q['status_category'] = 'ongoing'
        
        project['has_won'] = project_has_won
        project['has_lost'] = project_has_lost
        project['has_ongoing'] = project_has_ongoing
    
    summary = {
        'won_count': won_count,
        'lost_count': lost_count,
        'ongoing_count': ongoing_count,
        'total_won_value': total_won_value,
        'total_lost_value': total_lost_value,
        'total_ongoing_value': total_ongoing_value
    }
    
    # Calculate presale/sales engineer statistics (associated engineers)
    associated_stats = []
    if selected_engineer and projects:
        # Collect all associated engineers and their stats
        engineer_data = {}
        for project in projects:
            for q in project['quotations']:
                assoc_eng = q.get('associated_engineer', '') or 'Unassigned'
                if assoc_eng not in engineer_data:
                    engineer_data[assoc_eng] = {'total': 0, 'won': 0, 'lost': 0, 'ongoing': 0, 'won_value': 0, 'lost_value': 0, 'ongoing_value': 0}
                
                engineer_data[assoc_eng]['total'] += 1
                selling_price = float(q.get('selling_price') or 0)
                status_cat = q.get('status_category', 'ongoing')
                
                if status_cat == 'won':
                    engineer_data[assoc_eng]['won'] += 1
                    engineer_data[assoc_eng]['won_value'] += selling_price
                elif status_cat == 'lost':
                    engineer_data[assoc_eng]['lost'] += 1
                    engineer_data[assoc_eng]['lost_value'] += selling_price
                else:
                    engineer_data[assoc_eng]['ongoing'] += 1
                    engineer_data[assoc_eng]['ongoing_value'] += selling_price
        
        # Convert to list and sort by total quotations descending
        for eng_name, stats in engineer_data.items():
            associated_stats.append({
                'name': eng_name,
                'total': stats['total'],
                'won': stats['won'],
                'lost': stats['lost'],
                'ongoing': stats['ongoing'],
                'won_value': stats['won_value'],
                'lost_value': stats['lost_value'],
                'ongoing_value': stats['ongoing_value']
            })
        associated_stats.sort(key=lambda x: x['total'], reverse=True)
    
    conn.close()
    
    return render_template('engineer_reports.html',
                           report_type=report_type,
                           engineers=engineers,
                           selected_engineer=selected_engineer,
                           years=years,
                           selected_year=selected_year,
                           selected_quarter=selected_quarter,
                           selected_month=selected_month,
                           selected_week=selected_week,
                           projects=projects,
                           total_quotations=total_quotations,
                           summary=summary,
                           associated_stats=associated_stats)


@app.route('/export_engineer_report_excel')
@login_required
def export_engineer_report_excel():
    """Export Engineer Report to Excel with professional formatting"""
    from openpyxl import Workbook
    from openpyxl.styles import Font, Fill, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
    from io import BytesIO
    
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    report_type = request.args.get('type', 'sales')
    selected_engineer = request.args.get('engineer', '')
    selected_year = request.args.get('year', '')
    selected_quarter = request.args.get('quarter', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    
    if not selected_engineer:
        flash('Please select an engineer first', 'warning')
        return redirect(url_for('engineer_reports', type=report_type))
    
    # Build date filter conditions (same logic as engineer_reports)
    date_conditions = ""
    params_base = [selected_engineer]
    
    if selected_year:
        date_conditions += " AND strftime('%Y', registered_date) = ?"
        params_base.append(selected_year)
    
    if selected_month:
        date_conditions += " AND strftime('%m', registered_date) = ?"
        params_base.append(selected_month)
        if selected_week:
            week_num = int(selected_week)
            start_day = (week_num - 1) * 7 + 1
            end_day = week_num * 7
            date_conditions += " AND CAST(strftime('%d', registered_date) AS INTEGER) BETWEEN ? AND ?"
            params_base.extend([start_day, end_day])
    elif selected_quarter:
        quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
        if selected_quarter in quarter_map:
            start_month, end_month = quarter_map[selected_quarter]
            date_conditions += " AND strftime('%m', registered_date) BETWEEN ? AND ?"
            params_base.extend([start_month, end_month])
    
    # Get projects and quotations
    if report_type == 'sales':
        query = f"""
            SELECT project_name, MAX(registered_date) as latest_date
            FROM projects 
            WHERE sales_eng = ? AND project_name IS NOT NULL AND project_name != ''
            {date_conditions}
            GROUP BY project_name
            ORDER BY latest_date DESC
        """
    else:
        query = f"""
            SELECT project_name, MAX(registered_date) as latest_date
            FROM projects 
            WHERE presale_eng = ? AND project_name IS NOT NULL AND project_name != ''
            {date_conditions}
            GROUP BY project_name
            ORDER BY latest_date DESC
        """
    c.execute(query, params_base)
    project_names = [row[0] for row in c.fetchall()]
    
    projects = []
    won_count = lost_count = ongoing_count = 0
    total_won = total_lost = total_ongoing = 0
    
    for project_name in project_names:
        if report_type == 'sales':
            query = f"""
                SELECT id, quote_ref, presale_eng, status, quotation_selling_price, registered_date, quotation_note, feedback
                FROM projects 
                WHERE project_name = ? AND sales_eng = ?
                {date_conditions.replace('?', '?', 1) if date_conditions else ''}
                ORDER BY registered_date DESC
            """
        else:
            query = f"""
                SELECT id, quote_ref, sales_eng, status, quotation_selling_price, registered_date, quotation_note, feedback
                FROM projects 
                WHERE project_name = ? AND presale_eng = ?
                {date_conditions.replace('?', '?', 1) if date_conditions else ''}
                ORDER BY registered_date DESC
            """
        params = [project_name, selected_engineer] + params_base[1:]
        c.execute(query, params)
        
        quotations = []
        for row in c.fetchall():
            status = (row[3] or '').lower()
            selling_price = float(row[4] or 0)
            note = row[6] or ''
            feedback = row[7] or ''
            if 'won' in status:
                won_count += 1
                total_won += selling_price
                category = 'Won'
            elif 'lost' in status:
                lost_count += 1
                total_lost += selling_price
                category = 'Lost'
            else:
                ongoing_count += 1
                total_ongoing += selling_price
                category = 'Ongoing'
            quotations.append({
                'quote_ref': row[1],
                'associated_engineer': row[2],
                'status': row[3],
                'category': category,
                'selling_price': selling_price,
                'registered_date': row[5],
                'note': note,
                'feedback': feedback
            })
        
        if quotations:
            projects.append({'name': project_name, 'quotations': quotations})
    
    conn.close()
    
    # Create Excel workbook
    wb = Workbook()
    ws = wb.active
    ws.title = "Engineer Report"
    
    # Styles
    header_fill = PatternFill(start_color="667eea", end_color="667eea", fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF", size=12)
    title_font = Font(bold=True, size=16, color="667eea")
    subtitle_font = Font(bold=True, size=12)
    won_fill = PatternFill(start_color="28a745", end_color="28a745", fill_type="solid")
    lost_fill = PatternFill(start_color="dc3545", end_color="dc3545", fill_type="solid")
    ongoing_fill = PatternFill(start_color="ffc107", end_color="ffc107", fill_type="solid")
    border = Border(
        left=Side(style='thin'),
        right=Side(style='thin'),
        top=Side(style='thin'),
        bottom=Side(style='thin')
    )
    
    # Title
    ws.merge_cells('A1:H1')
    ws['A1'] = f"{selected_engineer}'s {'Sales' if report_type == 'sales' else 'Presale'} Report"
    ws['A1'].font = title_font
    ws['A1'].alignment = Alignment(horizontal='center')
    
    # Filter info
    filter_text = []
    if selected_year:
        filter_text.append(f"Year: {selected_year}")
    if selected_month:
        months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
        filter_text.append(f"Month: {months[int(selected_month)-1]}")
    if selected_week:
        filter_text.append(f"Week: {selected_week}")
    if selected_quarter and not selected_month:
        filter_text.append(f"Quarter: {selected_quarter}")
    
    ws.merge_cells('A2:H2')
    ws['A2'] = ' | '.join(filter_text) if filter_text else 'All Time'
    ws['A2'].alignment = Alignment(horizontal='center')
    
    # Summary section
    row = 4
    ws.merge_cells(f'A{row}:H{row}')
    ws[f'A{row}'] = 'SUMMARY'
    ws[f'A{row}'].font = subtitle_font
    ws[f'A{row}'].fill = PatternFill(start_color="e9ecef", end_color="e9ecef", fill_type="solid")
    
    row = 5
    summary_headers = ['Total Quotations', 'Won', 'Won Value (SAR)', 'Lost', 'Lost Value (SAR)', 'Ongoing', 'Ongoing Value (SAR)']
    for col, header in enumerate(summary_headers, 1):
        cell = ws.cell(row=row, column=col, value=header)
        cell.font = Font(bold=True)
        cell.border = border
    
    row = 6
    total_quotations = won_count + lost_count + ongoing_count
    summary_data = [total_quotations, won_count, total_won, lost_count, total_lost, ongoing_count, total_ongoing]
    for col, value in enumerate(summary_data, 1):
        cell = ws.cell(row=row, column=col, value=value)
        cell.border = border
        if col in [3, 5, 7]:
            cell.number_format = '#,##0.00'
    
    # Projects and Quotations
    row = 8
    ws.merge_cells(f'A{row}:H{row}')
    ws[f'A{row}'] = 'PROJECTS & QUOTATIONS'
    ws[f'A{row}'].font = subtitle_font
    ws[f'A{row}'].fill = PatternFill(start_color="e9ecef", end_color="e9ecef", fill_type="solid")
    
    row = 9
    headers = ['Project Name', 'Quote Reference', 'Associated Engineer', 'Status', 'Selling Price (SAR)', 'Registered Date', 'Note', 'Client Feedback']
    for col, header in enumerate(headers, 1):
        cell = ws.cell(row=row, column=col, value=header)
        cell.font = header_font
        cell.fill = header_fill
        cell.border = border
        cell.alignment = Alignment(horizontal='center')
    
    row = 10
    for project in projects:
        for q in project['quotations']:
            ws.cell(row=row, column=1, value=project['name']).border = border
            ws.cell(row=row, column=2, value=q['quote_ref']).border = border
            ws.cell(row=row, column=3, value=q['associated_engineer']).border = border
            status_cell = ws.cell(row=row, column=4, value=q['status'] or 'Ongoing')
            status_cell.border = border
            if q['category'] == 'Won':
                status_cell.fill = won_fill
                status_cell.font = Font(color="FFFFFF", bold=True)
            elif q['category'] == 'Lost':
                status_cell.fill = lost_fill
                status_cell.font = Font(color="FFFFFF", bold=True)
            else:
                status_cell.fill = ongoing_fill
            price_cell = ws.cell(row=row, column=5, value=q['selling_price'])
            price_cell.border = border
            price_cell.number_format = '#,##0.00'
            date_cell = ws.cell(row=row, column=6, value=q['registered_date'].split(' ')[0] if q['registered_date'] else '')
            date_cell.border = border
            note_cell = ws.cell(row=row, column=7, value=q.get('note', '') or '-')
            note_cell.border = border
            feedback_cell = ws.cell(row=row, column=8, value=q.get('feedback', '') or '-')
            feedback_cell.border = border
            row += 1
    
    # Adjust column widths - updated for 8 columns
    column_widths = [40, 25, 25, 15, 20, 15, 30, 30]
    for i, width in enumerate(column_widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = width
    
    # Calculate associated engineer stats (Presale/Sales Engineers Performance)
    engineer_stats = {}
    for project in projects:
        for q in project['quotations']:
            eng_name = q['associated_engineer'] or 'Unassigned'
            if eng_name not in engineer_stats:
                engineer_stats[eng_name] = {'total': 0, 'won': 0, 'lost': 0, 'ongoing': 0, 'won_value': 0, 'lost_value': 0, 'ongoing_value': 0}
            engineer_stats[eng_name]['total'] += 1
            if q['category'] == 'Won':
                engineer_stats[eng_name]['won'] += 1
                engineer_stats[eng_name]['won_value'] += q['selling_price']
            elif q['category'] == 'Lost':
                engineer_stats[eng_name]['lost'] += 1
                engineer_stats[eng_name]['lost_value'] += q['selling_price']
            else:
                engineer_stats[eng_name]['ongoing'] += 1
                engineer_stats[eng_name]['ongoing_value'] += q['selling_price']
    
    # Add Presale/Sales Engineers Performance sheet
    if engineer_stats:
        ws2 = wb.create_sheet(title="Engineer Performance")
        
        # Header styling
        presale_header_fill = PatternFill(start_color="1e3c72", end_color="1e3c72", fill_type="solid")
        green_fill = PatternFill(start_color="28a745", end_color="28a745", fill_type="solid")
        red_fill = PatternFill(start_color="dc3545", end_color="dc3545", fill_type="solid")
        orange_fill = PatternFill(start_color="fd7e14", end_color="fd7e14", fill_type="solid")
        
        # Title
        ws2.merge_cells('A1:G1')
        ws2['A1'] = f"{'Presale' if report_type == 'sales' else 'Sales'} Engineers Performance"
        ws2['A1'].font = Font(bold=True, size=16, color="1e3c72")
        ws2['A1'].alignment = Alignment(horizontal='center')
        
        # Headers
        perf_headers = ['Engineer Name', 'Total Quotes', 'Won', 'Won Value (SAR)', 'Lost', 'Lost Value (SAR)', 'Ongoing', 'Ongoing Value (SAR)']
        for col, header in enumerate(perf_headers, 1):
            cell = ws2.cell(row=3, column=col, value=header)
            cell.font = Font(bold=True, color="FFFFFF", size=11)
            cell.fill = presale_header_fill
            cell.border = border
            cell.alignment = Alignment(horizontal='center')
        
        # Data rows
        perf_row = 4
        sorted_engineers = sorted(engineer_stats.items(), key=lambda x: x[1]['total'], reverse=True)
        for eng_name, stats in sorted_engineers:
            ws2.cell(row=perf_row, column=1, value=eng_name).border = border
            ws2.cell(row=perf_row, column=2, value=stats['total']).border = border
            
            won_cell = ws2.cell(row=perf_row, column=3, value=stats['won'])
            won_cell.border = border
            won_cell.fill = green_fill
            won_cell.font = Font(color="FFFFFF", bold=True)
            
            won_val_cell = ws2.cell(row=perf_row, column=4, value=stats['won_value'])
            won_val_cell.border = border
            won_val_cell.number_format = '#,##0.00'
            
            lost_cell = ws2.cell(row=perf_row, column=5, value=stats['lost'])
            lost_cell.border = border
            lost_cell.fill = red_fill
            lost_cell.font = Font(color="FFFFFF", bold=True)
            
            lost_val_cell = ws2.cell(row=perf_row, column=6, value=stats['lost_value'])
            lost_val_cell.border = border
            lost_val_cell.number_format = '#,##0.00'
            
            ongoing_cell = ws2.cell(row=perf_row, column=7, value=stats['ongoing'])
            ongoing_cell.border = border
            ongoing_cell.fill = orange_fill
            ongoing_cell.font = Font(bold=True)
            
            ongoing_val_cell = ws2.cell(row=perf_row, column=8, value=stats['ongoing_value'])
            ongoing_val_cell.border = border
            ongoing_val_cell.number_format = '#,##0.00'
            
            perf_row += 1
        
        # Column widths for sheet 2
        ws2.column_dimensions['A'].width = 25
        ws2.column_dimensions['B'].width = 15
        ws2.column_dimensions['C'].width = 12
        ws2.column_dimensions['D'].width = 18
        ws2.column_dimensions['E'].width = 12
        ws2.column_dimensions['F'].width = 18
        ws2.column_dimensions['G'].width = 12
        ws2.column_dimensions['H'].width = 18
    
    # Save to BytesIO
    output = BytesIO()
    wb.save(output)
    output.seek(0)
    
    filename = f"{selected_engineer}_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
    
    return send_file(
        output,
        mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        as_attachment=True,
        download_name=filename
    )


