        y = start_y + row * (card_height + card_spacing_y)
        
        # Card shadow
        shadow = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x + Inches(0.03), y + Inches(0.03), card_width, card_height)
        shadow.fill.solid()
