@app.route('/presales_performance')
@permission_required('view_presales')
def presales_performance():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Get filter values from URL
    current_year = datetime.now().year
    selected_year = request.args.get('year', default=current_year, type=int)
    presale_filter = request.args.get('presale_engineer')
    period_filter = request.args.get('period', default='month')  # 'week' or 'month'

    # Fetch all presales engineers for the filter dropdown
    c.execute("SELECT username FROM engineers WHERE role IN ('Presale Engineer', 'Technical Team Leader')")
    presale_engineers = [row[0] for row in c.fetchall()]
    
    # --- NEW: RFQs and Quotations per Engineer (for the new chart) ---
    # Calculate date range based on period or custom dates
    from datetime import timedelta
    today = datetime.now()
    
    # Get custom date filters if provided
    date_from = request.args.get('date_from')
    date_to = request.args.get('date_to')
    
    if date_from and date_to:
        # Custom date range
        start_date = date_from
        end_date = date_to
        try:
            from_dt = datetime.strptime(date_from, '%Y-%m-%d')
            to_dt = datetime.strptime(date_to, '%Y-%m-%d')
            days_diff = (to_dt - from_dt).days
            period_label = f"{from_dt.strftime('%b %d')} - {to_dt.strftime('%b %d, %Y')} ({days_diff + 1} days)"
        except:
            period_label = f"{date_from} to {date_to}"
    elif period_filter == 'week':
        start_date = (today - timedelta(days=7)).strftime('%Y-%m-%d')
        end_date = today.strftime('%Y-%m-%d')
        period_label = 'Last 7 Days'
        date_from = start_date
        date_to = end_date
    else:  # month (default)
        start_date = (today - timedelta(days=30)).strftime('%Y-%m-%d')
        end_date = today.strftime('%Y-%m-%d')
        period_label = 'Last 30 Days'
        date_from = start_date
        date_to = end_date
    
    # RFQs Received per engineer in period
    rfq_per_eng_query = """
        SELECT sales_engineer_presale, COUNT(*) as count
        FROM rfq_requests
        WHERE date(requested_time) >= ? AND date(requested_time) <= ?
        AND sales_engineer_presale IS NOT NULL AND sales_engineer_presale != ''
    """
    rfq_per_eng_params = [start_date, end_date]
    if presale_filter:
        rfq_per_eng_query += " AND sales_engineer_presale = ?"
        rfq_per_eng_params.append(presale_filter)
    rfq_per_eng_query += " GROUP BY sales_engineer_presale ORDER BY count DESC"
    c.execute(rfq_per_eng_query, rfq_per_eng_params)
    rfq_per_eng_results = c.fetchall()
    
    # Quotations Submitted per engineer in period
    quote_per_eng_query = """
        SELECT presale_eng, COUNT(*) as count
        FROM projects
        WHERE rfq_reference IS NOT NULL
        AND date(registered_date) >= ? AND date(registered_date) <= ?
        AND presale_eng IS NOT NULL AND presale_eng != ''
    """
    quote_per_eng_params = [start_date, end_date]
    if presale_filter:
        quote_per_eng_query += " AND presale_eng = ?"
        quote_per_eng_params.append(presale_filter)
    quote_per_eng_query += " GROUP BY presale_eng ORDER BY count DESC"
    c.execute(quote_per_eng_query, quote_per_eng_params)
    quote_per_eng_results = c.fetchall()
    
    # Quotations Not Submitted per engineer (RFQs without matching quotation, excluding cancelled RFQs)
    not_submitted_query = """
        SELECT r.sales_engineer_presale, COUNT(*) as count
        FROM rfq_requests r
        LEFT JOIN projects p ON r.rfq_reference = p.rfq_reference
        WHERE date(r.requested_time) >= ? AND date(r.requested_time) <= ?
        AND r.sales_engineer_presale IS NOT NULL AND r.sales_engineer_presale != ''
        AND p.id IS NULL
        AND (r.rfq_status IS NULL OR r.rfq_status != 'Cancelled')
    """
    not_submitted_params = [start_date, end_date]
    if presale_filter:
        not_submitted_query += " AND r.sales_engineer_presale = ?"
        not_submitted_params.append(presale_filter)
    not_submitted_query += " GROUP BY r.sales_engineer_presale"
    c.execute(not_submitted_query, not_submitted_params)
    not_submitted_results = c.fetchall()
    
    # Missed Deadline per engineer (RFQs not submitted AND deadline has passed)
    missed_deadline_query = """
        SELECT r.sales_engineer_presale, COUNT(*) as count
        FROM rfq_requests r
        LEFT JOIN projects p ON r.rfq_reference = p.rfq_reference
        WHERE date(r.requested_time) >= ? AND date(r.requested_time) <= ?
        AND r.sales_engineer_presale IS NOT NULL AND r.sales_engineer_presale != ''
        AND p.id IS NULL
        AND (r.rfq_status IS NULL OR r.rfq_status != 'Cancelled')
        AND r.deadline IS NOT NULL AND r.deadline != '' AND date(r.deadline) < date('now')
    """
    missed_deadline_params = [start_date, end_date]
    if presale_filter:
        missed_deadline_query += " AND r.sales_engineer_presale = ?"
        missed_deadline_params.append(presale_filter)
    missed_deadline_query += " GROUP BY r.sales_engineer_presale"
    c.execute(missed_deadline_query, missed_deadline_params)
    missed_deadline_results = c.fetchall()
    
    # Combine into a single dataset
    engineer_performance = {}
    for eng, count in rfq_per_eng_results:
        if eng not in engineer_performance:
            engineer_performance[eng] = {'rfqs': 0, 'quotes': 0, 'not_submitted': 0, 'missed_deadline': 0}
        engineer_performance[eng]['rfqs'] = count
    for eng, count in quote_per_eng_results:
        if eng not in engineer_performance:
            engineer_performance[eng] = {'rfqs': 0, 'quotes': 0, 'not_submitted': 0, 'missed_deadline': 0}
        engineer_performance[eng]['quotes'] = count
    for eng, count in not_submitted_results:
        if eng not in engineer_performance:
            engineer_performance[eng] = {'rfqs': 0, 'quotes': 0, 'not_submitted': 0, 'missed_deadline': 0}
        engineer_performance[eng]['not_submitted'] = count
    for eng, count in missed_deadline_results:
        if eng not in engineer_performance:
            engineer_performance[eng] = {'rfqs': 0, 'quotes': 0, 'not_submitted': 0, 'missed_deadline': 0}
        engineer_performance[eng]['missed_deadline'] = count
    
    # Sort by total activity
    sorted_engineers = sorted(engineer_performance.items(), 
                              key=lambda x: x[1]['rfqs'] + x[1]['quotes'], reverse=True)
    
    engineer_chart_labels = [e[0] for e in sorted_engineers]
    engineer_rfqs_data = [e[1]['rfqs'] for e in sorted_engineers]
    engineer_quotes_data = [e[1]['quotes'] for e in sorted_engineers]
    # For stacked bar: split "not submitted" into missed deadline and still on time
    engineer_missed_deadline_data = [e[1].get('missed_deadline', 0) for e in sorted_engineers]
    # Calculate "not submitted but still on time" = total not_submitted - missed_deadline
    engineer_not_submitted_ontime_data = [max(0, e[1].get('not_submitted', 0) - e[1].get('missed_deadline', 0)) for e in sorted_engineers]

    # --- Calculation 1: RFQs Requested vs. Quoted (for chart) ---
    # ... (This calculation remains the same)
    params_req = [str(selected_year)]
    query_req = "SELECT strftime('%m', requested_time) FROM rfq_requests WHERE strftime('%Y', requested_time) = ?"
    if presale_filter:
        query_req += " AND sales_engineer_presale = ?"
        params_req.append(presale_filter)
    c.execute(query_req, params_req)
    requested_rfqs = c.fetchall()
    quarterly_requests = {'Q1': 0, 'Q2': 0, 'Q3': 0, 'Q4': 0}
    for month in requested_rfqs:
        q = f"Q{(int(month[0]) - 1) // 3 + 1}"
        quarterly_requests[q] += 1

    params_quoted = [str(selected_year)]
    query_quoted = "SELECT strftime('%m', registered_date) FROM projects WHERE rfq_reference IS NOT NULL AND strftime('%Y', registered_date) = ?"
    if presale_filter:
        query_quoted += " AND presale_eng = ?"
        params_quoted.append(presale_filter)
    c.execute(query_quoted, params_quoted)
    quoted_rfqs = c.fetchall()
    quarterly_quoted = {'Q1': 0, 'Q2': 0, 'Q3': 0, 'Q4': 0}
    for month in quoted_rfqs:
        q = f"Q{(int(month[0]) - 1) // 3 + 1}"
        quarterly_quoted[q] += 1

    # --- Calculation 2: Average Turnaround Time (for chart) ---
    # ... (This calculation remains the same)
    turnaround_query = "SELECT r.sales_engineer_presale, julianday(p.registered_date) - julianday(r.requested_time) AS turnaround_days FROM rfq_requests r JOIN projects p ON r.rfq_reference = p.rfq_reference WHERE strftime('%Y', r.requested_time) = ?"
    turnaround_params = [str(selected_year)]
    if presale_filter:
        turnaround_query += " AND r.sales_engineer_presale = ?"
        turnaround_params.append(presale_filter)
    c.execute(turnaround_query, turnaround_params)
    turnaround_results = c.fetchall()
    engineer_times = {}
    for engineer, days in turnaround_results:
        if days is None: continue
        if engineer not in engineer_times: engineer_times[engineer] = []
        engineer_times[engineer].append(days)
    avg_turnaround_data = {engineer: sum(times) / len(times) for engineer, times in engineer_times.items()}
    sorted_turnaround = sorted(avg_turnaround_data.items(), key=lambda item: item[1], reverse=True)
    turnaround_labels = [item[0] for item in sorted_turnaround]
    turnaround_data = [item[1] for item in sorted_turnaround]

    # --- Calculation 3: Win Rate & Value Analysis ---
    value_query = """
        SELECT
            presale_eng,
            SUM(quotation_selling_price) AS total_quoted,
            SUM(CASE WHEN status = 'WON' THEN quotation_selling_price ELSE 0 END) AS total_won
        FROM projects
        WHERE strftime('%Y', registered_date) = ?
    """
    value_params = [str(selected_year)]
    if presale_filter:
        value_query += " AND presale_eng = ?"
        value_params.append(presale_filter)
    value_query += " GROUP BY presale_eng"
    c.execute(value_query, value_params)
    value_results = c.fetchall()

    # --- Calculation 4: Presales Leaderboard ---
    # ... (This calculation remains the same)
    leaderboard_query = "SELECT p.presale_eng, COUNT(p.id), SUM(CASE WHEN p.status = 'Closed Won' THEN 1 ELSE 0 END), SUM(CASE WHEN p.status = 'Closed Won' THEN p.quotation_selling_price ELSE 0 END), AVG(CASE WHEN p.status = 'Closed Won' THEN p.margin ELSE NULL END) FROM projects p WHERE strftime('%Y', p.registered_date) = ?"
    leaderboard_params = [str(selected_year)]
    if presale_filter:
        leaderboard_query += " AND p.presale_eng = ?"
        leaderboard_params.append(presale_filter)
    leaderboard_query += " GROUP BY p.presale_eng ORDER BY SUM(CASE WHEN p.status = 'Closed Won' THEN p.quotation_selling_price ELSE 0 END) DESC"
    c.execute(leaderboard_query, leaderboard_params)
    leaderboard_data = c.fetchall()

    # --- Calculation 5: Deadline Performance (Before vs After Deadline) ---
    deadline_query = """
        SELECT 
            r.sales_engineer_presale,
            SUM(CASE WHEN p.registered_date <= r.deadline THEN 1 ELSE 0 END) AS on_time,
            SUM(CASE WHEN p.registered_date > r.deadline THEN 1 ELSE 0 END) AS late
        FROM rfq_requests r
        JOIN projects p ON r.rfq_reference = p.rfq_reference
        WHERE strftime('%Y', r.requested_time) = ?
        AND r.deadline IS NOT NULL
        AND r.deadline != ''
    """
    deadline_params = [str(selected_year)]
    if presale_filter:
        deadline_query += " AND r.sales_engineer_presale = ?"
        deadline_params.append(presale_filter)
    deadline_query += " GROUP BY r.sales_engineer_presale"
    c.execute(deadline_query, deadline_params)
    deadline_results = c.fetchall()
    
    deadline_labels = [row[0] for row in deadline_results if row[0]]
    deadline_on_time = [row[1] or 0 for row in deadline_results if row[0]]
    deadline_late = [row[2] or 0 for row in deadline_results if row[0]]

    # --- Calculation 6: KPI Statistics ---
    # Total RFQs received
    kpi_query = "SELECT COUNT(*) FROM rfq_requests WHERE strftime('%Y', requested_time) = ?"
    kpi_params = [str(selected_year)]
    if presale_filter:
        kpi_query += " AND sales_engineer_presale = ?"
        kpi_params.append(presale_filter)
    c.execute(kpi_query, kpi_params)
    total_rfqs = c.fetchone()[0] or 0

    # Total Quotations Submitted
    quote_query = "SELECT COUNT(*) FROM projects WHERE rfq_reference IS NOT NULL AND strftime('%Y', registered_date) = ?"
    quote_params = [str(selected_year)]
    if presale_filter:
        quote_query += " AND presale_eng = ?"
        quote_params.append(presale_filter)
    c.execute(quote_query, quote_params)
    total_quotations = c.fetchone()[0] or 0

    # Total Quoted Value
    total_quoted_value_query = "SELECT SUM(quotation_selling_price) FROM projects WHERE strftime('%Y', registered_date) = ?"
    total_quoted_value_params = [str(selected_year)]
    if presale_filter:
        total_quoted_value_query += " AND presale_eng = ?"
        total_quoted_value_params.append(presale_filter)
    c.execute(total_quoted_value_query, total_quoted_value_params)
    total_quoted_value = c.fetchone()[0] or 0

    # Total Won Value
    total_won_value_query = "SELECT SUM(quotation_selling_price) FROM projects WHERE status = 'Closed Won' AND strftime('%Y', registered_date) = ?"
    total_won_value_params = [str(selected_year)]
    if presale_filter:
        total_won_value_query += " AND presale_eng = ?"
        total_won_value_params.append(presale_filter)
    c.execute(total_won_value_query, total_won_value_params)
    total_won_value = c.fetchone()[0] or 0

    # --- NEW: RFTS Requested vs Done per Engineer (for the new RFTS chart) ---
    # RFTS Requested per engineer in the selected date range
    rfts_requested_query = """
        SELECT presale_engineer, COUNT(*) as count
        FROM technical_support_requests
        WHERE date(requested_time) >= ? AND date(requested_time) <= ?
        AND presale_engineer IS NOT NULL AND presale_engineer != ''
    """
    rfts_requested_params = [start_date, end_date]
    if presale_filter:
        rfts_requested_query += " AND presale_engineer = ?"
        rfts_requested_params.append(presale_filter)
    rfts_requested_query += " GROUP BY presale_engineer ORDER BY count DESC"
    c.execute(rfts_requested_query, rfts_requested_params)
    rfts_requested_results = c.fetchall()
    
    # RFTS Done per engineer in the selected date range
    rfts_done_query = """
        SELECT presale_engineer, COUNT(*) as count
        FROM technical_support_requests
        WHERE request_status = 'Done'
        AND date(requested_time) >= ? AND date(requested_time) <= ?
        AND presale_engineer IS NOT NULL AND presale_engineer != ''
    """
    rfts_done_params = [start_date, end_date]
    if presale_filter:
        rfts_done_query += " AND presale_engineer = ?"
        rfts_done_params.append(presale_filter)
    rfts_done_query += " GROUP BY presale_engineer ORDER BY count DESC"
    c.execute(rfts_done_query, rfts_done_params)
    rfts_done_results = c.fetchall()
    
    # RFTS Not Done per engineer in the selected date range (status != 'Done')
    rfts_not_done_query = """
        SELECT presale_engineer, COUNT(*) as count
        FROM technical_support_requests
        WHERE (request_status IS NULL OR request_status != 'Done')
        AND date(requested_time) >= ? AND date(requested_time) <= ?
        AND presale_engineer IS NOT NULL AND presale_engineer != ''
    """
    rfts_not_done_params = [start_date, end_date]
    if presale_filter:
        rfts_not_done_query += " AND presale_engineer = ?"
        rfts_not_done_params.append(presale_filter)
    rfts_not_done_query += " GROUP BY presale_engineer ORDER BY count DESC"
    c.execute(rfts_not_done_query, rfts_not_done_params)
    rfts_not_done_results = c.fetchall()
    
    # Combine RFTS data into a single dataset
    rfts_performance = {}
    for eng, count in rfts_requested_results:
        if eng not in rfts_performance:
            rfts_performance[eng] = {'requested': 0, 'done': 0, 'not_done': 0}
        rfts_performance[eng]['requested'] = count
    for eng, count in rfts_done_results:
        if eng not in rfts_performance:
            rfts_performance[eng] = {'requested': 0, 'done': 0, 'not_done': 0}
        rfts_performance[eng]['done'] = count
    for eng, count in rfts_not_done_results:
        if eng not in rfts_performance:
            rfts_performance[eng] = {'requested': 0, 'done': 0, 'not_done': 0}
        rfts_performance[eng]['not_done'] = count
    
    # Sort by total activity
    sorted_rfts_engineers = sorted(rfts_performance.items(), 
                                   key=lambda x: x[1]['requested'] + x[1]['done'], reverse=True)
    
    rfts_chart_labels = [e[0] for e in sorted_rfts_engineers]
    rfts_requested_data = [e[1]['requested'] for e in sorted_rfts_engineers]
    rfts_done_data = [e[1]['done'] for e in sorted_rfts_engineers]
    rfts_not_done_data = [e[1]['not_done'] for e in sorted_rfts_engineers]

    conn.close()

    # --- Prepare all data for the template ---
    labels = list(quarterly_requests.keys())
    requested_data = list(quarterly_requests.values())
    quoted_data = list(quarterly_quoted.values())
    year_range = range(current_year - 5, current_year + 5)

    # Prepare data for the new value analysis chart
    value_labels = [row[0] for row in value_results]
    total_quoted_data = [row[1] for row in value_results]
    total_won_data = [row[2] for row in value_results]

    return render_template('presales_performance.html',
                           labels=labels, requested_data=requested_data, quoted_data=quoted_data,
                           selected_year=selected_year, year_range=year_range,
                           presale_engineers=presale_engineers, presale_filter=presale_filter,
                           turnaround_labels=turnaround_labels, turnaround_data=turnaround_data,
                           leaderboard_data=leaderboard_data,
                           value_labels=value_labels,
                           total_quoted_data=total_quoted_data,
                           total_won_data=total_won_data,
                           deadline_labels=deadline_labels,
                           deadline_on_time=deadline_on_time,
                           deadline_late=deadline_late,
                           total_rfqs=total_rfqs,
                           total_quotations=total_quotations,
                           total_quoted_value=total_quoted_value,
                           total_won_value=total_won_value,
                           period_filter=period_filter,
                           period_label=period_label,
                           date_from=date_from,
                           date_to=date_to,
                           engineer_chart_labels=engineer_chart_labels,
                           engineer_rfqs_data=engineer_rfqs_data,
                           engineer_quotes_data=engineer_quotes_data,
                           engineer_not_submitted_ontime_data=engineer_not_submitted_ontime_data,
                           engineer_missed_deadline_data=engineer_missed_deadline_data,
                           rfts_chart_labels=rfts_chart_labels,
                           rfts_requested_data=rfts_requested_data,
                           rfts_done_data=rfts_done_data,
                           rfts_not_done_data=rfts_not_done_data)

@app.route('/api/deadline_rfqs')
@login_required
def get_deadline_rfqs():
    """API endpoint to get RFQs for deadline performance chart drill-down"""
    engineer = request.args.get('engineer')
    deadline_type = request.args.get('type')  # 'on_time' or 'late'
    year = request.args.get('year', default=str(datetime.now().year))
    
    if not engineer or not deadline_type:
        return jsonify({'error': 'Missing parameters'}), 400
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    if deadline_type == 'on_time':
        query = """
            SELECT r.id, r.rfq_reference, r.project_name, r.deadline, p.registered_date as quote_date,
                   r.sales_engineer_sales, r.system
            FROM rfq_requests r
            JOIN projects p ON r.rfq_reference = p.rfq_reference
            WHERE r.sales_engineer_presale = ?
            AND strftime('%Y', r.requested_time) = ?
            AND r.deadline IS NOT NULL AND r.deadline != ''
            AND p.registered_date <= r.deadline
            ORDER BY r.deadline DESC
        """
    else:  # late
        query = """
            SELECT r.id, r.rfq_reference, r.project_name, r.deadline, p.registered_date as quote_date,
                   r.sales_engineer_sales, r.system
            FROM rfq_requests r
            JOIN projects p ON r.rfq_reference = p.rfq_reference
            WHERE r.sales_engineer_presale = ?
            AND strftime('%Y', r.requested_time) = ?
            AND r.deadline IS NOT NULL AND r.deadline != ''
            AND p.registered_date > r.deadline
            ORDER BY r.deadline DESC
        """
    
    c.execute(query, (engineer, year))
    rfqs = c.fetchall()
    conn.close()
    
    result = []
    for rfq in rfqs:
        days_diff = 0
        if rfq['deadline'] and rfq['quote_date']:
            try:
                from datetime import datetime as dt
                deadline_date = dt.strptime(rfq['deadline'], '%Y-%m-%d')
                quote_date = dt.strptime(rfq['quote_date'][:10], '%Y-%m-%d')
                days_diff = (quote_date - deadline_date).days
            except:
                pass
        
        result.append({
            'id': rfq['id'],
            'rfq_reference': rfq['rfq_reference'],
            'project_name': rfq['project_name'],
            'deadline': rfq['deadline'],
            'quote_date': rfq['quote_date'][:10] if rfq['quote_date'] else None,
            'sales_engineer': rfq['sales_engineer_sales'],
            'system': rfq['system'],
            'days_diff': days_diff
        })
    
    return jsonify({
        'engineer': engineer,
        'type': deadline_type,
        'count': len(result),
        'rfqs': result
    })

@app.route('/api/engineer_performance_rfqs')
@login_required
def get_engineer_performance_rfqs():
    """API endpoint to get RFQs/Quotations for engineer performance chart drill-down"""
    engineer = request.args.get('engineer')
    data_type = request.args.get('type')  # 'rfqs' or 'quotes'
    date_from = request.args.get('date_from')
    date_to = request.args.get('date_to')
    
    if not engineer or not data_type:
        return jsonify({'error': 'Missing parameters'}), 400
    
    from datetime import timedelta
    today = datetime.now()
    
    # Use custom date range if provided, otherwise default to last 30 days
    if date_from and date_to:
        start_date = date_from
        end_date = date_to
        period_label = f'{date_from} to {date_to}'
    else:
        start_date = (today - timedelta(days=30)).strftime('%Y-%m-%d')
        end_date = today.strftime('%Y-%m-%d')
        period_label = 'Last 30 Days'
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    result = []
    
    if data_type == 'rfqs':
        query = """
            SELECT id, rfq_reference, project_name, requested_time, deadline,
                   sales_engineer_sales, system, priority
            FROM rfq_requests
            WHERE sales_engineer_presale = ?
            AND date(requested_time) >= ? AND date(requested_time) <= ?
            ORDER BY requested_time DESC
        """
        c.execute(query, (engineer, start_date, end_date))
        rfqs = c.fetchall()
        
        for rfq in rfqs:
            result.append({
                'id': rfq['id'],
                'rfq_reference': rfq['rfq_reference'],
                'project_name': rfq['project_name'],
                'date': rfq['requested_time'][:10] if rfq['requested_time'] else None,
                'deadline': rfq['deadline'],
                'sales_engineer': rfq['sales_engineer_sales'],
                'system': rfq['system'],
                'priority': rfq['priority']
            })
    elif data_type == 'not_submitted':
        query = """
            SELECT r.id, r.rfq_reference, r.project_name, r.requested_time, r.deadline,
                   r.sales_engineer_sales, r.system, r.priority, r.quotation_status, r.rfq_status
            FROM rfq_requests r
            LEFT JOIN projects p ON r.rfq_reference = p.rfq_reference
            WHERE r.sales_engineer_presale = ?
            AND date(r.requested_time) >= ? AND date(r.requested_time) <= ?
            AND p.id IS NULL
            AND (r.rfq_status IS NULL OR r.rfq_status != 'Cancelled')
            ORDER BY r.requested_time DESC
        """
        c.execute(query, (engineer, start_date, end_date))
        rfqs = c.fetchall()
        
        for rfq in rfqs:
            result.append({
                'id': rfq['id'],
                'rfq_reference': rfq['rfq_reference'],
                'project_name': rfq['project_name'],
                'date': rfq['requested_time'][:10] if rfq['requested_time'] else None,
                'deadline': rfq['deadline'],
                'sales_engineer': rfq['sales_engineer_sales'],
                'system': rfq['system'],
                'priority': rfq['priority'],
                'quotation_status': rfq['quotation_status']
            })
    elif data_type == 'missed_deadline':
        query = """
            SELECT r.id, r.rfq_reference, r.project_name, r.requested_time, r.deadline,
                   r.sales_engineer_sales, r.system, r.priority, r.quotation_status, r.rfq_status
            FROM rfq_requests r
            LEFT JOIN projects p ON r.rfq_reference = p.rfq_reference
            WHERE r.sales_engineer_presale = ?
            AND date(r.requested_time) >= ? AND date(r.requested_time) <= ?
            AND p.id IS NULL
            AND (r.rfq_status IS NULL OR r.rfq_status != 'Cancelled')
            AND r.deadline IS NOT NULL AND r.deadline != '' AND date(r.deadline) < date('now')
            ORDER BY r.deadline ASC
        """
        c.execute(query, (engineer, start_date, end_date))
        rfqs = c.fetchall()
        
        for rfq in rfqs:
            result.append({
                'id': rfq['id'],
                'rfq_reference': rfq['rfq_reference'],
                'project_name': rfq['project_name'],
                'date': rfq['requested_time'][:10] if rfq['requested_time'] else None,
                'deadline': rfq['deadline'],
                'sales_engineer': rfq['sales_engineer_sales'],
                'system': rfq['system'],
                'priority': rfq['priority'],
                'quotation_status': rfq['quotation_status']
            })
    else:  # quotes
        query = """
            SELECT p.id, p.rfq_reference, p.project_name, p.registered_date,
                   p.quotation_selling_price, r.system, r.sales_engineer_sales
            FROM projects p
            LEFT JOIN rfq_requests r ON p.rfq_reference = r.rfq_reference
            WHERE p.presale_eng = ?
            AND p.rfq_reference IS NOT NULL
            AND date(p.registered_date) >= ? AND date(p.registered_date) <= ?
            ORDER BY p.registered_date DESC
        """
        c.execute(query, (engineer, start_date, end_date))
        quotes = c.fetchall()
        
        for quote in quotes:
            result.append({
                'id': quote['id'],
                'rfq_reference': quote['rfq_reference'],
                'project_name': quote['project_name'],
                'date': quote['registered_date'][:10] if quote['registered_date'] else None,
                'value': quote['quotation_selling_price'],
                'system': quote['system'],
                'sales_engineer': quote['sales_engineer_sales']
            })
    
    conn.close()
    
    return jsonify({
        'engineer': engineer,
        'type': data_type,
        'period': period_label,
        'count': len(result),
        'items': result
    })

@app.route('/api/presales_won_deals')
@login_required
def get_presales_won_deals():
    """API endpoint to get won deals for presales engineer in leaderboard"""
    engineer = request.args.get('engineer')
    year = request.args.get('year', default=str(datetime.now().year))
    
    if not engineer:
        return jsonify({'error': 'Missing engineer parameter'}), 400
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    query = """
        SELECT p.id, p.project_name, p.rfq_reference, p.registered_date,
               p.quotation_selling_price, p.quotation_cost, p.status, p.sales_eng,
               p.quote_ref, r.id as rfq_id, r.system, r.sales_engineer_sales
        FROM projects p
        LEFT JOIN rfq_requests r ON p.rfq_reference = r.rfq_reference
        WHERE p.presale_eng = ?
        AND p.status = 'Closed Won'
        AND strftime('%Y', p.registered_date) = ?
        ORDER BY p.registered_date DESC
    """
    c.execute(query, (engineer, year))
    deals = c.fetchall()
    conn.close()
    
    result = []
    total_value = 0
    for deal in deals:
        selling_price = deal['quotation_selling_price'] or 0
        cost_price = deal['quotation_cost'] or 0
        margin = ((selling_price - cost_price) / selling_price * 100) if selling_price > 0 else 0
        total_value += selling_price
        
        result.append({
            'project_id': deal['id'],
            'rfq_id': deal['rfq_id'],
            'quote_ref': deal['quote_ref'],
            'project_name': deal['project_name'],
            'rfq_reference': deal['rfq_reference'],
            'date': deal['registered_date'][:10] if deal['registered_date'] else None,
            'value': selling_price,
            'margin': round(margin, 1),
            'system': deal['system'],
            'sales_engineer': deal['sales_engineer_sales'] or deal['sales_eng']
        })
    
    return jsonify({
        'engineer': engineer,
        'year': year,
        'count': len(result),
        'total_value': total_value,
        'deals': result
    })

@app.route('/api/rfts_performance')
@login_required
@permission_required('view_rfts')
def get_rfts_performance():
    """API endpoint to get RFTS data for performance chart drill-down"""
    engineer = request.args.get('engineer')
    data_type = request.args.get('type')  # 'requested' or 'done'
    date_from = request.args.get('date_from')
    date_to = request.args.get('date_to')
    
    if not engineer or not data_type:
        return jsonify({'error': 'Missing parameters'}), 400
    
    from datetime import timedelta
    today = datetime.now()
    
    if date_from and date_to:
        start_date = date_from
        end_date = date_to
        try:
            from_dt = datetime.strptime(date_from, '%Y-%m-%d')
            to_dt = datetime.strptime(date_to, '%Y-%m-%d')
            days_diff = (to_dt - from_dt).days
            period_label = f"{from_dt.strftime('%b %d')} - {to_dt.strftime('%b %d, %Y')}"
        except:
            period_label = f"{date_from} to {date_to}"
    else:
        start_date = (today - timedelta(days=30)).strftime('%Y-%m-%d')
        end_date = today.strftime('%Y-%m-%d')
        period_label = 'Last 30 Days'
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    result = []
    
    if data_type == 'requested':
        # Get all RFTS requested by the engineer
        query = """
            SELECT id, rfts_reference, project_name, request_type, system,
                   requested_time, deadline, request_status, priority
            FROM technical_support_requests
            WHERE presale_engineer = ?
            AND date(requested_time) >= ? AND date(requested_time) <= ?
            ORDER BY requested_time DESC
        """
        c.execute(query, (engineer, start_date, end_date))
    elif data_type == 'not_done':
        # Get RFTS that are NOT marked as 'Done' for the engineer
        query = """
            SELECT id, rfts_reference, project_name, request_type, system,
                   requested_time, deadline, request_status, priority
            FROM technical_support_requests
            WHERE presale_engineer = ?
            AND (request_status IS NULL OR request_status != 'Done')
            AND date(requested_time) >= ? AND date(requested_time) <= ?
            ORDER BY requested_time DESC
        """
        c.execute(query, (engineer, start_date, end_date))
    else:
        # Get only RFTS marked as 'Done' for the engineer
        query = """
            SELECT id, rfts_reference, project_name, request_type, system,
                   requested_time, deadline, request_status, priority
            FROM technical_support_requests
            WHERE presale_engineer = ?
            AND request_status = 'Done'
            AND date(requested_time) >= ? AND date(requested_time) <= ?
            ORDER BY requested_time DESC
        """
        c.execute(query, (engineer, start_date, end_date))
    
    rfts_items = c.fetchall()
    conn.close()
    
    for item in rfts_items:
        result.append({
            'id': item['id'],
            'reference': item['rfts_reference'],
            'project': item['project_name'],
            'request_type': item['request_type'],
            'system': item['system'],
            'date': item['requested_time'][:10] if item['requested_time'] else None,
            'deadline': item['deadline'],
            'status': item['request_status'],
            'priority': item['priority']
        })
    
    return jsonify({
        'engineer': engineer,
        'type': data_type,
        'period': period_label,
        'count': len(result),
        'items': result
    })


@app.route('/api/sales_engineer_quotations')
@login_required
def get_sales_engineer_quotations():
    """API endpoint to get quotations for a sales engineer - for chart drill-down"""
    engineer = request.args.get('engineer')
    data_type = request.args.get('type', 'all')  # 'quoted', 'won', or 'all'
    year = request.args.get('year', type=int)
    
    if not engineer:
        return jsonify({'error': 'Missing engineer parameter'}), 400
    
    if not year:
        year = datetime.now().year
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    result = []
    
    # Build query based on type
    if data_type == 'won':
        query = """
            SELECT p.id, p.rfq_reference, p.quote_ref, p.project_name, p.system,
                   p.registered_date, p.quotation_selling_price, p.presale_eng, p.status, p.quarter
            FROM projects p
            WHERE p.sales_eng = ?
            AND strftime('%Y', p.registered_date) = ?
            AND p.status IN ('Closed Won', 'WON')
            ORDER BY p.registered_date DESC
        """
    else:  # 'quoted' or 'all'
        query = """
            SELECT p.id, p.rfq_reference, p.quote_ref, p.project_name, p.system,
                   p.registered_date, p.quotation_selling_price, p.presale_eng, p.status, p.quarter
            FROM projects p
            WHERE p.sales_eng = ?
            AND strftime('%Y', p.registered_date) = ?
            ORDER BY p.registered_date DESC
        """
    
    c.execute(query, (engineer, str(year)))
    quotations = c.fetchall()
    conn.close()
    
    for q in quotations:
        result.append({
            'id': q['id'],
            'rfq_reference': q['rfq_reference'],
            'quote_ref': q['quote_ref'],
            'project_name': q['project_name'],
            'system': q['system'],
            'date': q['registered_date'][:10] if q['registered_date'] else None,
            'value': float(q['selling_price']) if q['selling_price'] else 0,
            'presale_eng': q['presale_eng'],
            'status': q['status'],
            'quarter': q['quarter']
        })
    
    return jsonify({
        'engineer': engineer,
        'type': data_type,
        'year': year,
        'count': len(result),
        'items': result
    })


