@app.route('/sales_performance')
@login_required
@permission_required('view_sales_performance')
def sales_performance():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Get filter values from URL
    current_year = datetime.now().year
    selected_year = request.args.get('year', default=current_year, type=int)
    sales_filter = request.args.get('sales_engineer')
    
    # --- ACCESS CONTROL: Check if user is a Sales Engineer ---
    user_role = None
    user_sales_eng_name = None
    is_sales_engineer = False
    
    if 'user_id' in session:
        c.execute("SELECT role FROM users WHERE id = ?", (session['user_id'],))
        user_role_result = c.fetchone()
        if user_role_result:
            user_role = user_role_result[0]
            if user_role == 'Sales Engineer':
                is_sales_engineer = True
                # Get the engineer's username (case-insensitive match)
                c.execute("SELECT username FROM engineers WHERE LOWER(username) = LOWER(?)", (session['username'],))
                eng_result = c.fetchone()
                if eng_result:
                    user_sales_eng_name = eng_result[0]

    # Fetch SALES engineers for the filter dropdown (only for managers)
    if is_sales_engineer:
        sales_engineers = []  # Hide dropdown for Sales Engineers
    else:
        c.execute("SELECT username FROM engineers WHERE role IN ('Sales Engineer', 'Technical Team Leader')")
        sales_engineers = [row[0] for row in c.fetchall()]

    # --- Calculation 1: Win Rate & Value Analysis (Grouped by SALES Engineer) ---
    value_query = """
        SELECT
            sales_eng,
            SUM(quotation_selling_price) AS total_quoted,
            SUM(CASE WHEN status = 'Closed Won' THEN quotation_selling_price ELSE 0 END) AS total_won
        FROM projects
        WHERE strftime('%Y', registered_date) = ? AND sales_eng IS NOT NULL
    """
    value_params = [str(selected_year)]
    
    # Sales Engineers only see their own data
    if is_sales_engineer and user_sales_eng_name:
        value_query += " AND sales_eng = ?"
        value_params.append(user_sales_eng_name)
    elif sales_filter:
        value_query += " AND sales_eng = ?"
        value_params.append(sales_filter)
    value_query += " GROUP BY sales_eng ORDER BY total_won DESC"
    c.execute(value_query, value_params)
    value_results = c.fetchall()

    # --- Calculation 2: Sales Leaderboard (Grouped by SALES Engineer) ---
    leaderboard_query = """
        SELECT 
            p.sales_eng, 
            COUNT(p.id) AS total_quotes, 
            SUM(CASE WHEN p.status = 'Closed Won' THEN 1 ELSE 0 END) AS won_deals,
            SUM(CASE WHEN p.status = 'Closed Won' THEN p.quotation_selling_price ELSE 0 END) AS won_value,
            AVG(CASE WHEN p.status = 'Closed Won' THEN p.margin ELSE NULL END) AS avg_margin
        FROM projects p 
        WHERE strftime('%Y', p.registered_date) = ? AND p.sales_eng IS NOT NULL
    """
    leaderboard_params = [str(selected_year)]
    
    # Sales Engineers only see their own data
    if is_sales_engineer and user_sales_eng_name:
        leaderboard_query += " AND p.sales_eng = ?"
        leaderboard_params.append(user_sales_eng_name)
    elif sales_filter:
        leaderboard_query += " AND p.sales_eng = ?"
        leaderboard_params.append(sales_filter)
    leaderboard_query += " GROUP BY p.sales_eng ORDER BY won_value DESC"
    c.execute(leaderboard_query, leaderboard_params)
    leaderboard_data = c.fetchall()
    
    # --- Calculation 3: Total Quoted Value and Total Lost Value ---
    totals_query = """
        SELECT 
            SUM(quotation_selling_price) AS total_quoted_value,
            SUM(CASE WHEN status IN ('Closed Lost', 'LOST') THEN quotation_selling_price ELSE 0 END) AS total_lost_value
        FROM projects
        WHERE strftime('%Y', registered_date) = ? AND sales_eng IS NOT NULL
    """
    totals_params = [str(selected_year)]
    
    if is_sales_engineer and user_sales_eng_name:
        totals_query += " AND sales_eng = ?"
        totals_params.append(user_sales_eng_name)
    elif sales_filter:
        totals_query += " AND sales_eng = ?"
        totals_params.append(sales_filter)
    
    c.execute(totals_query, totals_params)
    totals_result = c.fetchone()
    total_quoted_value = totals_result[0] or 0 if totals_result else 0
    total_lost_value = totals_result[1] or 0 if totals_result else 0
    
    conn.close()

    # Prepare data for the charts
    value_labels = [row[0] for row in value_results]
    total_quoted_data = [row[1] for row in value_results]
    total_won_data = [row[2] for row in value_results]
    year_range = range(current_year - 5, current_year + 5)

    return render_template('sales_performance.html',
                           selected_year=selected_year, year_range=year_range,
                           sales_engineers=sales_engineers, sales_filter=sales_filter,
                           leaderboard_data=leaderboard_data,
                           value_labels=value_labels,
                           total_quoted_data=total_quoted_data,
                           total_won_data=total_won_data,
                           total_quoted_value=total_quoted_value,
                           total_lost_value=total_lost_value,
                           is_sales_engineer=is_sales_engineer)
