@app.route('/rfq_profile/<int:rfq_id>')
@login_required
def rfq_profile(rfq_id):
    """
    RFQ Profile page showing complete RFQ details, process timeline,
    related quotations, and comments
    """
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    # Get RFQ details
    c.execute("SELECT * FROM rfq_requests WHERE id = ?", (rfq_id,))
    rfq = c.fetchone()
    
    if not rfq:
        conn.close()
        flash('RFQ not found', 'danger')
        return redirect(url_for('rfq_summary'))
    
    # Get related project
    c.execute("SELECT id, project_name FROM register_project WHERE project_name = ?", (rfq['project_name'],))
    project = c.fetchone()
    
    # Get related quotations for this RFQ (from projects table linked by rfq_reference)
    c.execute("""
        SELECT quote_ref, registered_by as created_by, registered_date as created_date, quotation_selling_price as total_value
        FROM projects 
        WHERE rfq_reference = ?
        ORDER BY registered_date DESC
    """, (rfq['rfq_reference'],))
    quotations = c.fetchall()
    
    # Get RFQ comments
    c.execute("""
        SELECT id, username, comment, created_at 
        FROM rfq_comments 
        WHERE rfq_id = ?
        ORDER BY created_at DESC
    """, (rfq_id,))
    comments = c.fetchall()
    
    # Calculate age in days (from RFQ creation to now)
    age_days = 0
    requested_date = None
    if rfq['requested_time']:
        try:
            requested_date = datetime.strptime(rfq['requested_time'].split(' ')[0], '%Y-%m-%d')
            age_days = (datetime.now() - requested_date).days
        except:
            age_days = 0
    
    # Calculate turnaround time (days from RFQ creation to first quotation submission)
    turnaround_days = None
    quote_submitted_date = None
    if quotations and len(quotations) > 0 and requested_date:
        try:
            # Get the earliest quotation date (first submitted)
            first_quote = quotations[-1] if len(quotations) > 1 else quotations[0]
            quote_date_str = first_quote['created_date']
            if quote_date_str:
                quote_submitted_date = datetime.strptime(quote_date_str.split(' ')[0], '%Y-%m-%d')
                turnaround_days = (quote_submitted_date - requested_date).days
        except Exception as e:
            turnaround_days = None
    
    # Check if overdue and calculate days overdue
    is_overdue = False
    days_overdue = 0
    deadline_date = None
    if rfq['deadline']:
        try:
            deadline_date = datetime.strptime(rfq['deadline'], '%Y-%m-%d')
            if datetime.now() > deadline_date:
                is_overdue = True
                days_overdue = (datetime.now() - deadline_date).days
            # Check if quote was submitted after deadline
            if quote_submitted_date and quote_submitted_date > deadline_date:
                days_overdue = (quote_submitted_date - deadline_date).days
        except:
            is_overdue = False
            days_overdue = 0
    
    # Get RFQ follow-ups
    c.execute("""
        SELECT * FROM rfq_follow_ups
        WHERE rfq_id = ?
        ORDER BY follow_up_date DESC, created_at DESC
    """, (rfq_id,))
    follow_ups = c.fetchall()
    
    # Get RFQ activity log
    c.execute("""
        SELECT * FROM rfq_activity_log
        WHERE rfq_id = ?
        ORDER BY created_at DESC
        LIMIT 20
    """, (rfq_id,))
    activities = c.fetchall()
    
    # Get vendors and distributors for follow-up form
    c.execute("SELECT id, name FROM vendors ORDER BY name")
    vendors = c.fetchall()
    
    c.execute("SELECT id, name FROM distributors ORDER BY name")
    distributors = c.fetchall()
    
    # Get users for assignment dropdown
    c.execute("SELECT username FROM users ORDER BY username")
    users = [row['username'] for row in c.fetchall()]
    
    # Get current date for overdue checking
    current_date = datetime.now().strftime('%Y-%m-%d')
    
    # Count pending follow-ups
    pending_follow_ups = len([f for f in follow_ups if f['status'] == 'Pending'])
    
    conn.close()
    
    return render_template('rfq_profile.html',
                         rfq=rfq,
                         project=project,
                         quotations=quotations,
                         comments=comments,
                         age_days=age_days,
                         is_overdue=is_overdue,
                         days_overdue=days_overdue,
                         turnaround_days=turnaround_days,
                         quote_submitted_date=quote_submitted_date.strftime('%Y-%m-%d') if quote_submitted_date else None,
                         follow_ups=follow_ups,
                         activities=activities,
                         vendors=vendors,
                         distributors=distributors,
                         users=users,
                         current_date=current_date,
                         pending_follow_ups=pending_follow_ups)

