# Export RFTS Engineer Report to Excel
@app.route('/export_rfts_engineer_report_excel')
@login_required
@permission_required('view_rfts')
def export_rfts_engineer_report_excel():
    """Export RFTS Engineer Report to Excel"""
    import pandas as pd
    from io import BytesIO
    from datetime import datetime, date
    
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    report_type = request.args.get('type', 'sales')
    selected_engineer = request.args.get('engineer', '')
    selected_year = request.args.get('year', '')
    selected_quarter = request.args.get('quarter', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    
    if not selected_engineer:
        flash('Please select an engineer first', 'warning')
        return redirect(url_for('rfts_engineer_reports', type=report_type))
    
    # Build date filter conditions
    date_conditions = ""
    params_base = [selected_engineer]
    
    if selected_year:
        date_conditions += " AND strftime('%Y', requested_time) = ?"
        params_base.append(selected_year)
    
    if selected_month:
        date_conditions += " AND strftime('%m', requested_time) = ?"
        params_base.append(selected_month)
        
        if selected_week:
            week_num = int(selected_week)
            start_day = (week_num - 1) * 7 + 1
            end_day = week_num * 7
            date_conditions += " AND CAST(strftime('%d', requested_time) AS INTEGER) BETWEEN ? AND ?"
            params_base.extend([start_day, end_day])
    elif selected_quarter:
        quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
        if selected_quarter in quarter_map:
            start_month, end_month = quarter_map[selected_quarter]
            date_conditions += " AND strftime('%m', requested_time) BETWEEN ? AND ?"
            params_base.extend([start_month, end_month])
    
    # Get RFTS for this engineer
    if report_type == 'sales':
        query = f"""
            SELECT id, rfts_reference, request_type, project_name, priority,
                   presale_engineer, sales_engineer, request_status,
                   request_result, deadline, note, requested_time, system
            FROM technical_support_requests 
            WHERE sales_engineer = ?
            {date_conditions}
            ORDER BY requested_time DESC
        """
    else:
        query = f"""
            SELECT id, rfts_reference, request_type, project_name, priority,
                   presale_engineer, sales_engineer, request_status,
                   request_result, deadline, note, requested_time, system
            FROM technical_support_requests 
            WHERE presale_engineer = ?
            {date_conditions}
            ORDER BY requested_time DESC
        """
    
    c.execute(query, params_base)
    rfts_data = c.fetchall()
    conn.close()
    
    # Create summary stats
    summary = {'queue': 0, 'studying': 0, 'done': 0, 'pending': 0, 'in_progress': 0}
    today = date.today()
    
    for rfts in rfts_data:
        status = (rfts[7] or '').lower()
        if 'queue' in status:
            summary['queue'] += 1
        elif 'study' in status:
            summary['studying'] += 1
        elif 'done' in status:
            summary['done'] += 1
        elif 'pending' in status:
            summary['pending'] += 1
        elif 'progress' in status:
            summary['in_progress'] += 1
        else:
            summary['queue'] += 1
    
    # Prepare data for Excel
    excel_data = []
    for rfts in rfts_data:
        days_remaining = None
        deadline_str = rfts[9]
        if deadline_str:
            try:
                deadline_date = datetime.strptime(deadline_str, '%Y-%m-%d').date()
                days_remaining = (deadline_date - today).days
            except:
                pass
        
        time_left = ''
        status = (rfts[7] or '').lower()
        if days_remaining is not None and status not in ['done']:
            if days_remaining < 0:
                time_left = f'{abs(days_remaining)} days overdue'
            elif days_remaining == 0:
                time_left = 'Due today'
            else:
                time_left = f'{days_remaining} days left'
        
        excel_data.append({
            'Reference': rfts[1],
            'Type': rfts[2],
            'Project Name': rfts[3],
            'Priority': rfts[4],
            'Presale Engineer': rfts[5],
            'Sales Engineer': rfts[6],
            'Status': rfts[7],
            'Result': rfts[8] or '',
            'Deadline': rfts[9] or '',
            'Time Left': time_left,
            'Note': rfts[10] or '',
            'Requested Time': rfts[11][:10] if rfts[11] else ''
        })
    
    # Create Excel file with multiple sheets
    output = BytesIO()
    with pd.ExcelWriter(output, engine='xlsxwriter') as writer:
        # Summary sheet
        summary_df = pd.DataFrame([{
            'Engineer': selected_engineer,
            'Report Type': 'Sales Engineer' if report_type == 'sales' else 'Presale Engineer',
            'Total RFTS': len(rfts_data),
            'Queue': summary['queue'],
            'Studying': summary['studying'],
            'In Progress': summary['in_progress'],
            'Done': summary['done'],
            'Pending': summary['pending'],
            'Period': f"{selected_year or 'All'} {selected_quarter or ''} {selected_month or ''}"
        }])
        summary_df.to_excel(writer, sheet_name='Summary', index=False)
        
        # RFTS Details sheet
        df = pd.DataFrame(excel_data)
        df.to_excel(writer, sheet_name='RFTS Details', index=False)
        
        # Format the worksheets
        workbook = writer.book
        header_format = workbook.add_format({
            'bold': True,
            'bg_color': '#667eea',
            'font_color': 'white',
            'border': 1
        })
        
        for sheet_name in ['Summary', 'RFTS Details']:
            worksheet = writer.sheets[sheet_name]
            if sheet_name == 'Summary':
                for col, col_name in enumerate(summary_df.columns):
                    worksheet.write(0, col, col_name, header_format)
                    worksheet.set_column(col, col, 15)
            else:
                for col, col_name in enumerate(df.columns):
                    worksheet.write(0, col, col_name, header_format)
                    worksheet.set_column(col, col, 18)
    
    output.seek(0)
    
    filename = f"{selected_engineer}_rfts_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
    
    return send_file(
        output,
        mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        as_attachment=True,
        download_name=filename
    )


###################################
# Export RFTS Engineer Report to PowerPoint
@app.route('/export_rfts_engineer_report_pptx')
@login_required
@permission_required('view_rfts')
def export_rfts_engineer_report_pptx():
    """Export RFTS Engineer Report to PowerPoint with modern attractive styling"""
    from pptx import Presentation
    from pptx.util import Inches, Pt
    from pptx.dml.color import RGBColor
    from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
    from pptx.enum.shapes import MSO_SHAPE
    from io import BytesIO
    from datetime import datetime, date
    
    FONT_NAME = 'Calibri'
    
    # Modern color palette
    PRIMARY_BLUE = RGBColor(102, 126, 234)
    SECONDARY_PURPLE = RGBColor(118, 75, 162)
    GREEN = RGBColor(40, 167, 69)
    YELLOW = RGBColor(255, 193, 7)
    RED = RGBColor(220, 53, 69)
    ORANGE = RGBColor(253, 126, 20)
    TEAL = RGBColor(0, 150, 136)
    GRAY = RGBColor(108, 117, 125)
    WHITE = RGBColor(255, 255, 255)
    DARK_TEXT = RGBColor(51, 51, 51)
    LIGHT_BG = RGBColor(248, 249, 250)
    
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    report_type = request.args.get('type', 'sales')
    selected_engineer = request.args.get('engineer', '')
    selected_year = request.args.get('year', '')
    selected_quarter = request.args.get('quarter', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    
    if not selected_engineer:
        flash('Please select an engineer first', 'warning')
        return redirect(url_for('rfts_engineer_reports', type=report_type))
    
    # Build date filter conditions
    date_conditions = ""
    params_base = [selected_engineer]
    
    if selected_year:
        date_conditions += " AND strftime('%Y', requested_time) = ?"
        params_base.append(selected_year)
    
    if selected_month:
        date_conditions += " AND strftime('%m', requested_time) = ?"
        params_base.append(selected_month)
        if selected_week:
            week_num = int(selected_week)
            start_day = (week_num - 1) * 7 + 1
            end_day = week_num * 7
            date_conditions += " AND CAST(strftime('%d', requested_time) AS INTEGER) BETWEEN ? AND ?"
            params_base.extend([start_day, end_day])
    elif selected_quarter:
        quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
        if selected_quarter in quarter_map:
            start_month, end_month = quarter_map[selected_quarter]
            date_conditions += " AND strftime('%m', requested_time) BETWEEN ? AND ?"
            params_base.extend([start_month, end_month])
    
    # Get RFTS for this engineer
    if report_type == 'sales':
        query = f"""
            SELECT id, rfts_reference, request_type, project_name, priority,
                   presale_engineer, sales_engineer, request_status,
                   request_result, deadline, note, requested_time, system
            FROM technical_support_requests 
            WHERE sales_engineer = ?
            {date_conditions}
            ORDER BY requested_time DESC
        """
    else:
        query = f"""
            SELECT id, rfts_reference, request_type, project_name, priority,
                   presale_engineer, sales_engineer, request_status,
                   request_result, deadline, note, requested_time, system
            FROM technical_support_requests 
            WHERE presale_engineer = ?
            {date_conditions}
            ORDER BY requested_time DESC
        """
    
    c.execute(query, params_base)
    rfts_data = c.fetchall()
    
    # Calculate summary
    summary = {'queue': 0, 'studying': 0, 'in_progress': 0, 'done': 0, 'pending': 0}
    rfts_details = []
    today = date.today()
    
    for rfts in rfts_data:
        status = (rfts[7] or '').lower()
        if 'queue' in status:
            status_category = 'queue'
            summary['queue'] += 1
        elif 'study' in status:
            status_category = 'studying'
            summary['studying'] += 1
        elif 'progress' in status:
            status_category = 'in_progress'
            summary['in_progress'] += 1
        elif 'done' in status:
            status_category = 'done'
            summary['done'] += 1
        elif 'pending' in status:
            status_category = 'pending'
            summary['pending'] += 1
        else:
            status_category = 'queue'
            summary['queue'] += 1
        
        rfts_details.append({
            'id': rfts[0],
            'rfts_reference': rfts[1],
            'request_type': rfts[2],
            'project_name': rfts[3] or 'Unknown Project',
            'priority': rfts[4],
            'presale_engineer': rfts[5],
            'sales_engineer': rfts[6],
            'request_status': rfts[7],
            'request_result': rfts[8],
            'deadline': rfts[9],
            'requested_time': rfts[11][:10] if rfts[11] else '-',
            'status_category': status_category,
            'note': rfts[10] or '',
            'system': rfts[12] or ''
        })
    
    total_rfts = len(rfts_data)
    
    # Create PowerPoint
    prs = Presentation()
    prs.slide_width = Inches(13.333)
    prs.slide_height = Inches(7.5)
    slide_layout = prs.slide_layouts[6]  # Blank
    
    # ===== SLIDE 1: GRADIENT TITLE SLIDE =====
    slide = prs.slides.add_slide(slide_layout)
    
    # Full slide gradient background
    bg_shape = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, prs.slide_width, prs.slide_height)
    bg_shape.fill.gradient()
    bg_shape.fill.gradient_angle = 135
    bg_shape.fill.gradient_stops[0].color.rgb = PRIMARY_BLUE
    bg_shape.fill.gradient_stops[1].color.rgb = SECONDARY_PURPLE
    bg_shape.line.fill.background()
    
    # Title
    title_box = slide.shapes.add_textbox(Inches(0.5), Inches(2.2), Inches(12.333), Inches(1))
    tf = title_box.text_frame
    p = tf.paragraphs[0]
    p.text = "RFTS Engineer Report"
    p.font.size = Pt(54)
    p.font.bold = True
    p.font.color.rgb = WHITE
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # Engineer name
    eng_box = slide.shapes.add_textbox(Inches(0.5), Inches(3.4), Inches(12.333), Inches(0.8))
    tf = eng_box.text_frame
    p = tf.paragraphs[0]
    report_type_title = "Sales Engineer" if report_type == 'sales' else "Presales Engineer"
    p.text = f"{report_type_title}: {selected_engineer}"
    p.font.size = Pt(32)
    p.font.color.rgb = WHITE
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # Period info
    period_parts = []
    if selected_year:
        period_parts.append(f"Year: {selected_year}")
    if selected_quarter:
        period_parts.append(f"Quarter: {selected_quarter}")
    if selected_month:
        month_names = {
            '01': 'January', '02': 'February', '03': 'March', '04': 'April',
            '05': 'May', '06': 'June', '07': 'July', '08': 'August',
            '09': 'September', '10': 'October', '11': 'November', '12': 'December'
        }
        period_parts.append(f"Month: {month_names.get(selected_month, selected_month)}")
    if selected_week:
        period_parts.append(f"Week: {selected_week}")
    
    period_text = " | ".join(period_parts) if period_parts else "All Time"
    
    period_box = slide.shapes.add_textbox(Inches(0.5), Inches(4.3), Inches(12.333), Inches(0.6))
    tf = period_box.text_frame
    p = tf.paragraphs[0]
    p.text = period_text
    p.font.size = Pt(20)
    p.font.color.rgb = RGBColor(230, 230, 250)
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # Date generated
    date_box = slide.shapes.add_textbox(Inches(0.5), Inches(6.5), Inches(12.333), Inches(0.5))
    tf = date_box.text_frame
    p = tf.paragraphs[0]
    p.text = f"Generated: {datetime.now().strftime('%B %d, %Y')}"
    p.font.size = Pt(14)
    p.font.color.rgb = RGBColor(200, 200, 220)
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # ===== SLIDE 2: DASHBOARD WITH STAT CARDS =====
    slide = prs.slides.add_slide(slide_layout)
    
    # Header gradient bar
    header_bar = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, prs.slide_width, Inches(1.2))
    header_bar.fill.gradient()
    header_bar.fill.gradient_angle = 90
    header_bar.fill.gradient_stops[0].color.rgb = PRIMARY_BLUE
    header_bar.fill.gradient_stops[1].color.rgb = SECONDARY_PURPLE
    header_bar.line.fill.background()
    
    # Dashboard title
    title_box = slide.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(8), Inches(0.7))
    tf = title_box.text_frame
    p = tf.paragraphs[0]
    p.text = "Performance Dashboard"
    p.font.size = Pt(32)
    p.font.bold = True
    p.font.color.rgb = WHITE
    p.font.name = FONT_NAME
    
    # Summary stats cards - 6 cards in a row
    stats = [
        ('TOTAL RFTS', total_rfts, PRIMARY_BLUE),
        ('QUEUE', summary['queue'], ORANGE),
        ('STUDYING', summary['studying'], TEAL),
        ('IN PROGRESS', summary['in_progress'], GRAY),
        ('DONE', summary['done'], GREEN),
        ('PENDING', summary['pending'], RED)
    ]
    
    card_width = Inches(1.9)
    card_height = Inches(1.4)
    start_x = Inches(0.5)
    start_y = Inches(1.8)
    gap = Inches(0.16)
    
    for i, (label, value, color) in enumerate(stats):
        x = start_x + i * (card_width + gap)
        
        # Card background with shadow effect
        shadow = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x + Inches(0.05), start_y + Inches(0.05), card_width, card_height)
        shadow.fill.solid()
        shadow.fill.fore_color.rgb = RGBColor(200, 200, 200)
        shadow.line.fill.background()
        
        # Main card
        card = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, start_y, card_width, card_height)
        card.fill.solid()
        card.fill.fore_color.rgb = WHITE
        card.line.color.rgb = RGBColor(230, 230, 230)
        
        # Colored top accent
        accent = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, x, start_y, card_width, Inches(0.12))
        accent.fill.solid()
        accent.fill.fore_color.rgb = color
        accent.line.fill.background()
        
        # Label
        label_box = slide.shapes.add_textbox(x, start_y + Inches(0.2), card_width, Inches(0.35))
        tf = label_box.text_frame
        p = tf.paragraphs[0]
        p.text = label
        p.font.size = Pt(9)
        p.font.bold = True
        p.font.color.rgb = RGBColor(100, 100, 100)
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
        
        # Value
        value_box = slide.shapes.add_textbox(x, start_y + Inches(0.55), card_width, Inches(0.7))
        tf = value_box.text_frame
        p = tf.paragraphs[0]
        p.text = str(value)
        p.font.size = Pt(36)
        p.font.bold = True
        p.font.color.rgb = color
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
    
    # ===== RELATED ENGINEERS SECTION ON DASHBOARD =====
    conn2 = sqlite3.connect('ProjectStatus.db')
    c2 = conn2.cursor()
    
    if report_type == 'sales':
        related_query = f"""
            SELECT presale_engineer, COUNT(*) as total_rfts,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%queue%' THEN 1 ELSE 0 END) as queue,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%study%' THEN 1 ELSE 0 END) as studying,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%progress%' THEN 1 ELSE 0 END) as in_progress,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%done%' THEN 1 ELSE 0 END) as done,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%pending%' THEN 1 ELSE 0 END) as pending
            FROM technical_support_requests
            WHERE sales_engineer = ? 
            AND presale_engineer IS NOT NULL 
            AND presale_engineer != ''
            {date_conditions}
            GROUP BY presale_engineer
            ORDER BY total_rfts DESC
        """
        related_type_title = "Presale Engineers Performance"
    else:
        related_query = f"""
            SELECT sales_engineer, COUNT(*) as total_rfts,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%queue%' THEN 1 ELSE 0 END) as queue,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%study%' THEN 1 ELSE 0 END) as studying,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%progress%' THEN 1 ELSE 0 END) as in_progress,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%done%' THEN 1 ELSE 0 END) as done,
                   SUM(CASE WHEN LOWER(request_status) LIKE '%pending%' THEN 1 ELSE 0 END) as pending
            FROM technical_support_requests
            WHERE presale_engineer = ? 
            AND sales_engineer IS NOT NULL 
            AND sales_engineer != ''
            {date_conditions}
            GROUP BY sales_engineer
            ORDER BY total_rfts DESC
        """
        related_type_title = "Sales Engineers Performance"
    
    c2.execute(related_query, params_base)
    related_engineers = c2.fetchall()
    conn2.close()
    
    # Add related engineers section header
    section_bar = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, Inches(0.5), Inches(3.5), Inches(12.333), Inches(0.55))
    section_bar.fill.gradient()
    section_bar.fill.gradient_angle = 90
    section_bar.fill.gradient_stops[0].color.rgb = GREEN
    section_bar.fill.gradient_stops[1].color.rgb = RGBColor(60, 200, 100)
    section_bar.line.fill.background()
    
    section_title = slide.shapes.add_textbox(Inches(0.7), Inches(3.55), Inches(6), Inches(0.5))
    tf = section_title.text_frame
    p = tf.paragraphs[0]
    p.text = f"{related_type_title}"
    p.font.size = Pt(18)
    p.font.bold = True
    p.font.color.rgb = WHITE
    p.font.name = FONT_NAME
    
    # Engineer count badge
    eng_count = len(related_engineers)
    count_badge = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, Inches(11), Inches(3.55), Inches(1.7), Inches(0.45))
    count_badge.fill.solid()
    count_badge.fill.fore_color.rgb = WHITE
    count_badge.line.color.rgb = WHITE
    
    count_text = slide.shapes.add_textbox(Inches(11), Inches(3.58), Inches(1.7), Inches(0.4))
    tf = count_text.text_frame
    p = tf.paragraphs[0]
    p.text = f"{eng_count} Engineers"
    p.font.size = Pt(12)
    p.font.bold = True
    p.font.color.rgb = GREEN
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # Display engineer cards (up to 6 on dashboard)
    card_width = Inches(4)
    card_height = Inches(1.3)
    cards_per_row = 3
    start_y = Inches(4.2)
    
    for idx, eng in enumerate(related_engineers[:6]):
        row = idx // cards_per_row
        col = idx % cards_per_row
        x = Inches(0.5) + col * (card_width + Inches(0.167))
        y = start_y + row * (card_height + Inches(0.15))
        
        eng_name = eng[0]
        total = eng[1]
        queue = eng[2]
        studying = eng[3]
        in_progress = eng[4]
        done = eng[5]
        pending = eng[6]
        
        # Shadow
        shadow = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x + Inches(0.03), y + Inches(0.03), card_width, card_height)
        shadow.fill.solid()
        shadow.fill.fore_color.rgb = RGBColor(220, 220, 220)
        shadow.line.fill.background()
        
        # Card
        card = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x, y, card_width, card_height)
        card.fill.solid()
        card.fill.fore_color.rgb = WHITE
        card.line.color.rgb = RGBColor(230, 230, 230)
        
        # Header bar with engineer name
        header = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, x, y, card_width, Inches(0.35))
        header.fill.gradient()
        header.fill.gradient_angle = 90
        header.fill.gradient_stops[0].color.rgb = RGBColor(59, 89, 152)
        header.fill.gradient_stops[1].color.rgb = RGBColor(100, 130, 200)
        header.line.fill.background()
        
        # Name
        name_box = slide.shapes.add_textbox(x + Inches(0.1), y + Inches(0.05), Inches(2.5), Inches(0.3))
        tf = name_box.text_frame
        p = tf.paragraphs[0]
        p.text = eng_name
        p.font.size = Pt(12)
        p.font.bold = True
        p.font.color.rgb = WHITE
        p.font.name = FONT_NAME
        
        # RFTS count badge
        badge = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x + Inches(3.1), y + Inches(0.05), Inches(0.8), Inches(0.25))
        badge.fill.solid()
        badge.fill.fore_color.rgb = GREEN
        badge.line.fill.background()
        
        badge_text = slide.shapes.add_textbox(x + Inches(3.1), y + Inches(0.05), Inches(0.8), Inches(0.25))
        tf = badge_text.text_frame
        p = tf.paragraphs[0]
        p.text = f"{total} RFTS"
        p.font.size = Pt(9)
        p.font.bold = True
        p.font.color.rgb = WHITE
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
        
        # Stats row - 5 items
        stat_items = [
            (queue, 'Queue', ORANGE),
            (studying, 'Study', TEAL),
            (in_progress, 'Progress', GRAY),
            (done, 'Done', GREEN),
            (pending, 'Pending', RED)
        ]
        
        stat_width = card_width / 5
        for si, (val, lbl, clr) in enumerate(stat_items):
            sx = x + si * stat_width
            
            # Value
            val_box = slide.shapes.add_textbox(sx, y + Inches(0.45), stat_width, Inches(0.45))
            tf = val_box.text_frame
            p = tf.paragraphs[0]
            p.text = str(val)
            p.font.size = Pt(18)
            p.font.bold = True
            p.font.color.rgb = clr
            p.font.name = FONT_NAME
            p.alignment = PP_ALIGN.CENTER
            
            # Label
            lbl_box = slide.shapes.add_textbox(sx, y + Inches(0.9), stat_width, Inches(0.3))
            tf = lbl_box.text_frame
            p = tf.paragraphs[0]
            p.text = lbl
            p.font.size = Pt(8)
            p.font.color.rgb = RGBColor(120, 120, 120)
            p.font.name = FONT_NAME
            p.alignment = PP_ALIGN.CENTER
    
    # ===== SLIDE 3+: RFTS DETAILS TABLES =====
    status_groups = {
        'queue': {'title': 'Queue RFTS', 'color': ORANGE, 'rfts': []},
        'studying': {'title': 'Studying RFTS', 'color': TEAL, 'rfts': []},
        'in_progress': {'title': 'In Progress RFTS', 'color': GRAY, 'rfts': []},
        'done': {'title': 'Done RFTS', 'color': GREEN, 'rfts': []},
        'pending': {'title': 'Pending RFTS', 'color': RED, 'rfts': []}
    }
    
    for rfts in rfts_details:
        cat = rfts['status_category']
        if cat in status_groups:
            status_groups[cat]['rfts'].append(rfts)
    
    # Create slides for each status category that has RFTS
    for status_key, group in status_groups.items():
        if not group['rfts']:
            continue
        
        items_per_slide = 8
        for page_num in range(0, len(group['rfts']), items_per_slide):
            page_rfts = group['rfts'][page_num:page_num + items_per_slide]
            
            slide = prs.slides.add_slide(slide_layout)
            
            # Header bar
            header_bar = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, prs.slide_width, Inches(0.9))
            header_bar.fill.solid()
            header_bar.fill.fore_color.rgb = group['color']
            header_bar.line.fill.background()
            
            # Title
            title_box = slide.shapes.add_textbox(Inches(0.5), Inches(0.2), Inches(10), Inches(0.6))
            tf = title_box.text_frame
            p = tf.paragraphs[0]
            page_indicator = f" (Page {page_num//items_per_slide + 1})" if len(group['rfts']) > items_per_slide else ""
            p.text = f"{group['title']} - {len(group['rfts'])} Total{page_indicator}"
            p.font.size = Pt(28)
            p.font.bold = True
            p.font.color.rgb = WHITE
            p.font.name = FONT_NAME
            
            # Table
            rows = len(page_rfts) + 1
            cols = 8
            table = slide.shapes.add_table(rows, cols, Inches(0.2), Inches(1.2), Inches(12.933), Inches(0.6 * rows)).table
            
            # Column widths
            table.columns[0].width = Inches(0.35)   # #
            table.columns[1].width = Inches(1.4)    # RFTS Reference
            table.columns[2].width = Inches(2.6)    # Project Name
            table.columns[3].width = Inches(1.3)    # Request Type
            table.columns[4].width = Inches(1.0)    # System
            table.columns[5].width = Inches(1.4)    # Engineer
            table.columns[6].width = Inches(1.0)    # Deadline
            table.columns[7].width = Inches(1.0)    # Request Date
            
            # Headers
            headers = ['#', 'RFTS Reference', 'Project Name', 'Request Type', 'System',
                      'Presale Eng' if report_type == 'sales' else 'Sales Eng', 
                      'Deadline', 'Request Date']
            for col, header in enumerate(headers):
                cell = table.cell(0, col)
                cell.text = header
                cell.fill.solid()
                cell.fill.fore_color.rgb = group['color']
                para = cell.text_frame.paragraphs[0]
                para.font.color.rgb = WHITE
                para.font.bold = True
                para.font.size = Pt(10)
                para.font.name = FONT_NAME
                para.alignment = PP_ALIGN.CENTER
                cell.vertical_anchor = MSO_ANCHOR.MIDDLE
            
            # Data rows
            for i, rfts in enumerate(page_rfts, 1):
                row_idx = i
                row_color = LIGHT_BG if i % 2 == 0 else WHITE
                
                # Row number
                cell = table.cell(row_idx, 0)
                cell.text = str(page_num + i)
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # RFTS Reference
                cell = table.cell(row_idx, 1)
                cell.text = rfts['rfts_reference'] or ''
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Project Name
                cell = table.cell(row_idx, 2)
                proj = rfts['project_name'] or ''
                cell.text = proj[:30] + '...' if len(proj) > 30 else proj
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Request Type
                cell = table.cell(row_idx, 3)
                cell.text = rfts['request_type'] or ''
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # System
                cell = table.cell(row_idx, 4)
                cell.text = rfts.get('system', '') or ''
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Engineer
                cell = table.cell(row_idx, 5)
                eng = rfts['presale_engineer'] if report_type == 'sales' else rfts['sales_engineer']
                cell.text = eng or ''
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Deadline
                cell = table.cell(row_idx, 6)
                cell.text = rfts['deadline'] or '-'
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Request Date
                cell = table.cell(row_idx, 7)
                cell.text = rfts['requested_time'] or '-'
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Style all cells
                for col in range(cols):
                    para = table.cell(row_idx, col).text_frame.paragraphs[0]
                    para.font.size = Pt(9)
                    para.font.name = FONT_NAME
                    para.font.color.rgb = DARK_TEXT
                    para.alignment = PP_ALIGN.CENTER
                    table.cell(row_idx, col).vertical_anchor = MSO_ANCHOR.MIDDLE
    
    # ===== FOLLOW-UP SLIDE: RFTS Not Completed =====
    not_completed_rfts = []
    for rfts in rfts_details:
        if rfts['status_category'] != 'done':
            days_overdue = None
            if rfts['deadline'] and rfts['deadline'] != '-':
                try:
                    deadline_date = datetime.strptime(rfts['deadline'], '%Y-%m-%d').date()
                    days_overdue = (today - deadline_date).days
                except:
                    pass
            rfts['days_overdue'] = days_overdue
            not_completed_rfts.append(rfts)
    
    not_completed_rfts.sort(key=lambda x: x['deadline'] if x['deadline'] != '-' else '9999-99-99')
    
    if not_completed_rfts:
        items_per_slide = 8
        for page_num in range(0, len(not_completed_rfts), items_per_slide):
            page_rfts = not_completed_rfts[page_num:page_num + items_per_slide]
            
            slide = prs.slides.add_slide(slide_layout)
            
            # Header with warning color
            header_bar = slide.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, prs.slide_width, Inches(0.9))
            header_bar.fill.gradient()
            header_bar.fill.gradient_angle = 90
            header_bar.fill.gradient_stops[0].color.rgb = RGBColor(255, 100, 100)
            header_bar.fill.gradient_stops[1].color.rgb = RGBColor(255, 150, 80)
            header_bar.line.fill.background()
            
            # Title
            title_box = slide.shapes.add_textbox(Inches(0.5), Inches(0.2), Inches(12), Inches(0.6))
            tf = title_box.text_frame
            p = tf.paragraphs[0]
            page_indicator = f" (Page {page_num//items_per_slide + 1})" if len(not_completed_rfts) > items_per_slide else ""
            p.text = f'Follow Up "RFTS Not Completed" - {len(not_completed_rfts)} RFTS{page_indicator}'
            p.font.size = Pt(26)
            p.font.bold = True
            p.font.color.rgb = WHITE
            p.font.name = FONT_NAME
            
            # Table
            rows = len(page_rfts) + 1
            cols = 7
            table = slide.shapes.add_table(rows, cols, Inches(0.2), Inches(1.2), Inches(12.933), Inches(0.6 * rows)).table
            
            # Column widths
            table.columns[0].width = Inches(0.4)    # #
            table.columns[1].width = Inches(1.5)    # RFTS Reference
            table.columns[2].width = Inches(3.0)    # Project Name
            table.columns[3].width = Inches(1.6)    # Engineer
            table.columns[4].width = Inches(1.2)    # Status
            table.columns[5].width = Inches(1.1)    # Deadline
            table.columns[6].width = Inches(0.9)    # Overdue
            
            # Headers
            headers = ['#', 'RFTS Reference', 'Project Name',
                      'Presale Eng' if report_type == 'sales' else 'Sales Eng',
                      'Status', 'Deadline', 'Overdue']
            for col, header in enumerate(headers):
                cell = table.cell(0, col)
                cell.text = header
                cell.fill.solid()
                cell.fill.fore_color.rgb = RGBColor(200, 50, 50)
                para = cell.text_frame.paragraphs[0]
                para.font.color.rgb = WHITE
                para.font.bold = True
                para.font.size = Pt(10)
                para.font.name = FONT_NAME
                para.alignment = PP_ALIGN.CENTER
                cell.vertical_anchor = MSO_ANCHOR.MIDDLE
            
            # Data rows
            for i, rfts in enumerate(page_rfts, 1):
                row_idx = i
                row_color = LIGHT_BG if i % 2 == 0 else WHITE
                
                # Row number
                cell = table.cell(row_idx, 0)
                cell.text = str(page_num + i)
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # RFTS Reference
                cell = table.cell(row_idx, 1)
                cell.text = rfts['rfts_reference'] or ''
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Project Name
                cell = table.cell(row_idx, 2)
                proj = rfts['project_name'] or ''
                cell.text = proj[:32] + '...' if len(proj) > 32 else proj
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Engineer
                cell = table.cell(row_idx, 3)
                eng = rfts['presale_engineer'] if report_type == 'sales' else rfts['sales_engineer']
                cell.text = eng or ''
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Status
                cell = table.cell(row_idx, 4)
                cell.text = rfts['request_status'] or ''
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Deadline
                cell = table.cell(row_idx, 5)
                cell.text = rfts['deadline'] or '-'
                cell.fill.solid()
                cell.fill.fore_color.rgb = row_color
                
                # Overdue
                cell = table.cell(row_idx, 6)
                if rfts.get('days_overdue') is not None:
                    days = rfts['days_overdue']
                    if days > 0:
                        cell.text = f"+{days}d"
                        cell.fill.solid()
                        cell.fill.fore_color.rgb = RGBColor(255, 220, 220)
                    else:
                        cell.text = f"{days}d"
                        cell.fill.solid()
                        cell.fill.fore_color.rgb = row_color
                else:
                    cell.text = '-'
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = row_color
                
                # Style all cells
                for col in range(cols):
                    para = table.cell(row_idx, col).text_frame.paragraphs[0]
                    para.font.size = Pt(9)
                    para.font.name = FONT_NAME
                    para.font.color.rgb = DARK_TEXT
                    para.alignment = PP_ALIGN.CENTER
                    table.cell(row_idx, col).vertical_anchor = MSO_ANCHOR.MIDDLE
    
    conn.close()
    
    # Save to BytesIO
    output = BytesIO()
    prs.save(output)
    output.seek(0)
    
    filename = f"{selected_engineer}_rfts_report_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pptx"
    
    return send_file(
        output,
        mimetype='application/vnd.openxmlformats-officedocument.presentationml.presentation',
        as_attachment=True,
        download_name=filename
    )





@app.route('/engineer_performance_center')
@login_required
def engineer_performance_center():
    """Engineer Performance Center - Combined report for Projects, RFQs, and RFTS"""
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    report_type = request.args.get('type', 'sales')
    selected_engineer = request.args.get('engineer', '')
    selected_year = request.args.get('year', '')
    selected_quarter = request.args.get('quarter', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    
    # Get available years
    c.execute("SELECT DISTINCT strftime('%Y', registered_date) as year FROM projects WHERE registered_date IS NOT NULL ORDER BY year DESC")
    years = [row[0] for row in c.fetchall() if row[0]]
    
    # Get list of engineers
    if report_type == 'sales':
        c.execute("SELECT DISTINCT sales_eng FROM projects WHERE sales_eng IS NOT NULL AND sales_eng != '' ORDER BY sales_eng")
    else:
        c.execute("SELECT DISTINCT presale_eng FROM projects WHERE presale_eng IS NOT NULL AND presale_eng != '' ORDER BY presale_eng")
    engineers = [row[0] for row in c.fetchall()]
    
    projects = []
    rfqs = []
    rfts_list = []
    project_stats = {'total': 0, 'won': 0, 'ongoing': 0, 'lost': 0}
    quotation_stats = {'total': 0, 'won': 0, 'ongoing': 0, 'lost': 0, 'won_value': 0, 'ongoing_value': 0, 'lost_value': 0}
    rfq_stats = {'total': 0, 'queue': 0, 'studying': 0, 'pricing': 0, 'quoted': 0, 'cancelled': 0}
    rfts_stats = {'total': 0, 'queue': 0, 'studying': 0, 'in_progress': 0, 'done': 0, 'pending': 0}
    period_text = ''
    
    if selected_engineer:
        # Build date filter conditions
        date_conditions = ""
        params_base = [selected_engineer]
        
        if selected_year:
            date_conditions += " AND strftime('%Y', registered_date) = ?"
            params_base.append(selected_year)
            period_text = selected_year
        
        if selected_month:
            date_conditions += " AND strftime('%m', registered_date) = ?"
            params_base.append(selected_month)
            month_names = ['', 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
            period_text = f"{month_names[int(selected_month)]} {selected_year}" if selected_year else month_names[int(selected_month)]
            
            if selected_week:
                week_num = int(selected_week)
                start_day = (week_num - 1) * 7 + 1
                end_day = week_num * 7
                date_conditions += " AND CAST(strftime('%d', registered_date) AS INTEGER) BETWEEN ? AND ?"
                params_base.extend([start_day, end_day])
                period_text += f" Week {selected_week}"
        elif selected_quarter:
            quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
            if selected_quarter in quarter_map:
                start_month, end_month = quarter_map[selected_quarter]
                date_conditions += " AND strftime('%m', registered_date) BETWEEN ? AND ?"
                params_base.extend([start_month, end_month])
                period_text = f"{selected_quarter} {selected_year}" if selected_year else selected_quarter
        
        # === PROJECTS DATA ===
        if report_type == 'sales':
            query = f"""
                SELECT project_name, MAX(registered_date) as latest_date
                FROM projects 
                WHERE sales_eng = ? AND project_name IS NOT NULL AND project_name != ''
                {date_conditions}
                GROUP BY project_name
                ORDER BY latest_date DESC
            """
        else:
            query = f"""
                SELECT project_name, MAX(registered_date) as latest_date
                FROM projects 
                WHERE presale_eng = ? AND project_name IS NOT NULL AND project_name != ''
                {date_conditions}
                GROUP BY project_name
                ORDER BY latest_date DESC
            """
        c.execute(query, params_base)
        project_names = [row[0] for row in c.fetchall()]
        
        for project_name in project_names:
            if report_type == 'sales':
                query = f"""
                    SELECT p.id, p.quote_ref, p.status, p.quotation_selling_price, p.registered_date
                    FROM projects p
                    WHERE p.project_name = ? AND p.sales_eng = ?
                    {date_conditions.replace('registered_date', 'p.registered_date') if date_conditions else ''}
                    ORDER BY p.registered_date DESC
                """
            else:
                query = f"""
                    SELECT p.id, p.quote_ref, p.status, p.quotation_selling_price, p.registered_date
                    FROM projects p
                    WHERE p.project_name = ? AND p.presale_eng = ?
                    {date_conditions.replace('registered_date', 'p.registered_date') if date_conditions else ''}
                    ORDER BY p.registered_date DESC
                """
            c.execute(query, [project_name] + params_base)
            quotations_data = c.fetchall()
            
            if quotations_data:
                quotations = []
                project_status = 'Ongoing'
                for q in quotations_data:
                    status = q[2] or 'Ongoing'
                    if status == 'Won':
                        project_status = 'Won'
                    elif status == 'Lost' and project_status != 'Won':
                        project_status = 'Lost'
                    
                    quotations.append({
                        'reference': q[1] or '',
                        'selling_price': q[3] or 0,
                        'status': status,
                        'date': q[4][:10] if q[4] else '-'
                    })
                
                projects.append({
                    'name': project_name,
                    'status': project_status,
                    'quotations': quotations
                })
                
                project_stats['total'] += 1
                if project_status == 'Won':
                    project_stats['won'] += 1
                elif project_status == 'Lost':
                    project_stats['lost'] += 1
                else:
                    project_stats['ongoing'] += 1
        
        # === RFQ DATA ===
        rfq_date_conditions = date_conditions.replace('registered_date', 'r.requested_time')
        if report_type == 'sales':
            rfq_query = f"""
                SELECT r.id, r.rfq_reference, r.project_name, r.rfq_status, r.deadline,
                       COALESCE(eu.name, co.name, cn.name, 'N/A') as client_name,
                       r.sales_engineer_presale, r.sales_engineer_sales
                FROM rfq_requests r
                LEFT JOIN register_project rp ON r.project_name = rp.project_name
                LEFT JOIN end_users eu ON rp.end_user_id = eu.id
                LEFT JOIN contractors co ON rp.contractor_id = co.id
                LEFT JOIN consultants cn ON rp.consultant_id = cn.id
                WHERE r.sales_engineer_sales = ?
                {rfq_date_conditions}
                ORDER BY r.requested_time DESC
            """
        else:
            rfq_query = f"""
                SELECT r.id, r.rfq_reference, r.project_name, r.rfq_status, r.deadline,
                       COALESCE(eu.name, co.name, cn.name, 'N/A') as client_name,
                       r.sales_engineer_presale, r.sales_engineer_sales
                FROM rfq_requests r
                LEFT JOIN register_project rp ON r.project_name = rp.project_name
                LEFT JOIN end_users eu ON rp.end_user_id = eu.id
                LEFT JOIN contractors co ON rp.contractor_id = co.id
                LEFT JOIN consultants cn ON rp.consultant_id = cn.id
                WHERE r.sales_engineer_presale = ?
                {rfq_date_conditions}
                ORDER BY r.requested_time DESC
            """
        c.execute(rfq_query, params_base)
        rfq_rows = c.fetchall()
        
        for row in rfq_rows:
            status = row[3] or 'Queue'
            rfqs.append({
                'id': row[0],
                'rfq_reference': row[1],
                'project_name': row[2] or '',
                'status': status,
                'rfq_status': status,
                'due_date': row[4] or '',
                'client_name': row[5] or 'N/A',
                'presale_engineer': row[6] or '',
                'sales_engineer': row[7] or ''
            })
            
            rfq_stats['total'] += 1
            status_lower = status.lower()
            if 'queue' in status_lower:
                rfq_stats['queue'] += 1
            elif 'study' in status_lower:
                rfq_stats['studying'] += 1
            elif 'pric' in status_lower:
                rfq_stats['pricing'] += 1
            elif 'quot' in status_lower:
                rfq_stats['quoted'] += 1
            elif 'cancel' in status_lower:
                rfq_stats['cancelled'] += 1
        
        # === RFTS DATA ===
        rfts_date_conditions = date_conditions.replace('registered_date', 'requested_time')
        if report_type == 'sales':
            rfts_query = f"""
                SELECT id, rfts_reference, project_name, request_type, request_status,
                       deadline, system, presale_engineer, sales_engineer
                FROM technical_support_requests
                WHERE sales_engineer = ?
                {rfts_date_conditions}
                ORDER BY requested_time DESC
            """
        else:
            rfts_query = f"""
                SELECT id, rfts_reference, project_name, request_type, request_status,
                       deadline, system, presale_engineer, sales_engineer
                FROM technical_support_requests
                WHERE presale_engineer = ?
                {rfts_date_conditions}
                ORDER BY requested_time DESC
            """
        c.execute(rfts_query, params_base)
        rfts_rows = c.fetchall()
        
        for row in rfts_rows:
            status = row[4] or 'Queue'
            rfts_list.append({
                'id': row[0],
                'rfts_reference': row[1],
                'project_name': row[2] or '',
                'request_type': row[3] or '',
                'request_status': status,
                'status': status,
                'deadline': row[5] or '',
                'system': row[6] or '',
                'presale_engineer': row[7] or '',
                'sales_engineer': row[8] or ''
            })
            
            rfts_stats['total'] += 1
            status_lower = status.lower()
            if 'queue' in status_lower:
                rfts_stats['queue'] += 1
            elif 'study' in status_lower:
                rfts_stats['studying'] += 1
            elif 'progress' in status_lower:
                rfts_stats['in_progress'] += 1
            elif 'done' in status_lower:
                rfts_stats['done'] += 1
            elif 'pending' in status_lower:
                rfts_stats['pending'] += 1
        
        # === QUOTATIONS DETAIL DATA ===
        if report_type == 'sales':
            quotations_query = f"""
                SELECT quote_ref, project_name, sales_eng, presale_eng, registered_date, 
                       quotation_cost, quotation_selling_price, margin, quotation_note, feedback
                FROM projects 
                WHERE sales_eng = ? AND quote_ref IS NOT NULL AND quote_ref != ''
                {date_conditions}
                ORDER BY registered_date DESC
            """
        else:
            quotations_query = f"""
                SELECT quote_ref, project_name, sales_eng, presale_eng, registered_date, 
                       quotation_cost, quotation_selling_price, margin, quotation_note, feedback
                FROM projects 
                WHERE presale_eng = ? AND quote_ref IS NOT NULL AND quote_ref != ''
                {date_conditions}
                ORDER BY registered_date DESC
            """
        c.execute(quotations_query, params_base)
        quotations_data = c.fetchall()
        quotations_list = []
        for idx, q in enumerate(quotations_data, 1):
            quotations_list.append({
                'num': idx,
                'quote_ref': q[0] or '-',
                'project_name': q[1] or '-',
                'engineer': q[2] or '-',
                'presale_engineer': q[3] or '-',
                'date': q[4][:10] if q[4] else '-',
                'cost': q[5] or 0,
                'selling': q[6] or 0,
                'margin': f"{q[7]:.1f}%" if q[7] is not None else '-',
                'note': q[8] or '-',
                'feedback': q[9] or '-'
            })
            
            # Update quotation stats
            quotation_stats['total'] += 1
            selling = q[6] or 0
            # Get status for this quotation
            c.execute("SELECT status FROM projects WHERE quote_ref = ?", (q[0],))
            status_row = c.fetchone()
            if status_row:
                q_status = status_row[0] or ''
                if q_status in ['Won', 'Done', 'Closed Won']:
                    quotation_stats['won'] += 1
                    quotation_stats['won_value'] += selling
                elif q_status in ['Lost', 'Cancelled', 'Closed Lost']:
                    quotation_stats['lost'] += 1
                    quotation_stats['lost_value'] += selling
                else:
                    quotation_stats['ongoing'] += 1
                    quotation_stats['ongoing_value'] += selling
    else:
        quotations_list = []
    
    # === RELATED ENGINEERS PERFORMANCE ===
    # Calculate performance stats for related engineers including RFQ, RFTS, and Quotations
    related_engineer_stats = {}
    
    if selected_engineer and selected_engineer.strip():
        # Initialize stats from RFQs
        for rfq in rfqs:
            # For sales report, show presale engineers; for presale report, show sales engineers
            if report_type == 'sales':
                eng_name = rfq.get('presale_engineer', '')
            else:
                eng_name = rfq.get('sales_engineer', '')
            
            if eng_name and eng_name.strip():
                if eng_name not in related_engineer_stats:
                    related_engineer_stats[eng_name] = {
                        'rfq_total': 0, 'rfq_queue': 0, 'rfq_studying': 0, 'rfq_pricing': 0, 'rfq_quoted': 0, 'rfq_cancelled': 0,
                        'rfts_total': 0, 'rfts_queue': 0, 'rfts_studying': 0, 'rfts_in_progress': 0, 'rfts_done': 0, 'rfts_pending': 0,
                        'quote_total': 0, 'quote_won': 0, 'quote_lost': 0, 'quote_ongoing': 0,
                        'quote_won_value': 0, 'quote_lost_value': 0, 'quote_ongoing_value': 0
                    }
                related_engineer_stats[eng_name]['rfq_total'] += 1
                rfq_status = rfq.get('rfq_status', '') or rfq.get('status', '')
                if 'Queue' in rfq_status:
                    related_engineer_stats[eng_name]['rfq_queue'] += 1
                elif 'Studying' in rfq_status:
                    related_engineer_stats[eng_name]['rfq_studying'] += 1
                elif 'Pricing' in rfq_status:
                    related_engineer_stats[eng_name]['rfq_pricing'] += 1
                elif 'Quoted' in rfq_status:
                    related_engineer_stats[eng_name]['rfq_quoted'] += 1
                elif 'Cancelled' in rfq_status:
                    related_engineer_stats[eng_name]['rfq_cancelled'] += 1
        
        # Add RFTS stats
        for rfts in rfts_list:
            # For sales report, show presale engineers; for presale report, show sales engineers
            if report_type == 'sales':
                eng_name = rfts.get('presale_engineer', '')
            else:
                eng_name = rfts.get('sales_engineer', '')
            
            if eng_name and eng_name.strip():
                if eng_name not in related_engineer_stats:
                    related_engineer_stats[eng_name] = {
                        'rfq_total': 0, 'rfq_queue': 0, 'rfq_studying': 0, 'rfq_pricing': 0, 'rfq_quoted': 0, 'rfq_cancelled': 0,
                        'rfts_total': 0, 'rfts_queue': 0, 'rfts_studying': 0, 'rfts_in_progress': 0, 'rfts_done': 0, 'rfts_pending': 0,
                        'quote_total': 0, 'quote_won': 0, 'quote_lost': 0, 'quote_ongoing': 0,
                        'quote_won_value': 0, 'quote_lost_value': 0, 'quote_ongoing_value': 0
                    }
                related_engineer_stats[eng_name]['rfts_total'] += 1
                rfts_status = rfts.get('status', '')
                if 'Queue' in rfts_status:
                    related_engineer_stats[eng_name]['rfts_queue'] += 1
                elif 'Studying' in rfts_status:
                    related_engineer_stats[eng_name]['rfts_studying'] += 1
                elif 'Progress' in rfts_status:
                    related_engineer_stats[eng_name]['rfts_in_progress'] += 1
                elif 'Done' in rfts_status:
                    related_engineer_stats[eng_name]['rfts_done'] += 1
                elif 'Pending' in rfts_status:
                    related_engineer_stats[eng_name]['rfts_pending'] += 1
        
        # Add Quotation stats
        for q in quotations_list:
            quote_ref = q.get('quote_ref', '')
            if quote_ref and quote_ref != '-':
                c.execute("SELECT status, quotation_selling_price FROM projects WHERE quote_ref = ?", (quote_ref,))
                result = c.fetchone()
                if result:
                    status = result[0] or ''
                    selling = result[1] or 0
                    
                    # For sales report, show presale engineers; for presale report, show sales engineers
                    if report_type == 'sales':
                        eng_name = q.get('presale_engineer', '')
                    else:
                        eng_name = q.get('engineer', '')
                    
                    if eng_name and eng_name.strip():
                        if eng_name not in related_engineer_stats:
                            related_engineer_stats[eng_name] = {
                                'rfq_total': 0, 'rfq_queue': 0, 'rfq_studying': 0, 'rfq_pricing': 0, 'rfq_quoted': 0, 'rfq_cancelled': 0,
                                'rfts_total': 0, 'rfts_queue': 0, 'rfts_studying': 0, 'rfts_in_progress': 0, 'rfts_done': 0, 'rfts_pending': 0,
                                'quote_total': 0, 'quote_won': 0, 'quote_lost': 0, 'quote_ongoing': 0,
                                'quote_won_value': 0, 'quote_lost_value': 0, 'quote_ongoing_value': 0
                            }
                        related_engineer_stats[eng_name]['quote_total'] += 1
                        
                        if status in ['Won', 'Done', 'Closed Won']:
                            related_engineer_stats[eng_name]['quote_won'] += 1
                            related_engineer_stats[eng_name]['quote_won_value'] += selling
                        elif status in ['Lost', 'Cancelled', 'Closed Lost']:
                            related_engineer_stats[eng_name]['quote_lost'] += 1
                            related_engineer_stats[eng_name]['quote_lost_value'] += selling
                        else:
                            related_engineer_stats[eng_name]['quote_ongoing'] += 1
                            related_engineer_stats[eng_name]['quote_ongoing_value'] += selling
    
    # Sort by combined total descending
    sorted_related_engineers = sorted(related_engineer_stats.items(), 
        key=lambda x: x[1]['rfq_total'] + x[1]['rfts_total'] + x[1]['quote_total'], reverse=True) if related_engineer_stats else []
    
    conn.close()
    
    return render_template('engineer_performance_center.html',
                          report_type=report_type,
                          engineers=engineers,
                          selected_engineer=selected_engineer,
                          years=years,
                          selected_year=selected_year,
                          selected_quarter=selected_quarter,
                          selected_month=selected_month,
                          selected_week=selected_week,
                          period_text=period_text,
                          projects=projects,
                          rfqs=rfqs,
                          rfts_list=rfts_list,
                          quotations_list=quotations_list,
                          project_stats=project_stats,
                          quotation_stats=quotation_stats,
                          rfq_stats=rfq_stats,
                          rfts_stats=rfts_stats,
                          related_engineers=sorted_related_engineers)




@app.route('/export_engineer_performance_pptx')
@login_required
def export_engineer_performance_pptx():
    """Export combined Engineer Performance Report as PowerPoint"""
    from pptx import Presentation
    from pptx.util import Inches, Pt
    from pptx.dml.color import RGBColor
    from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
    from pptx.enum.shapes import MSO_SHAPE
    from pptx.oxml.ns import qn
    from pptx.oxml import parse_xml
    from io import BytesIO
    
    selected_engineer = request.args.get('engineer', '')
    report_type = request.args.get('type', 'sales')
    selected_year = request.args.get('year', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    selected_quarter = request.args.get('quarter', '')
    
    if not selected_engineer:
        return "No engineer selected", 400
    
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    # Build date conditions
    date_conditions = ""
    params_base = [selected_engineer]
    period_text = "All Time"
    
    if selected_year:
        date_conditions += " AND strftime('%Y', registered_date) = ?"
        params_base.append(selected_year)
        period_text = selected_year
    
    if selected_month:
        date_conditions += " AND strftime('%m', registered_date) = ?"
        params_base.append(selected_month)
        month_names = ['', 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
        period_text = f"{month_names[int(selected_month)]} {selected_year}" if selected_year else month_names[int(selected_month)]
        
        if selected_week:
            week_num = int(selected_week)
            start_day = (week_num - 1) * 7 + 1
            end_day = week_num * 7
            date_conditions += " AND CAST(strftime('%d', registered_date) AS INTEGER) BETWEEN ? AND ?"
            params_base.extend([start_day, end_day])
            period_text += f" Week {selected_week}"
    elif selected_quarter:
        quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
        if selected_quarter in quarter_map:
            start_month, end_month = quarter_map[selected_quarter]
            date_conditions += " AND strftime('%m', registered_date) BETWEEN ? AND ?"
            params_base.extend([start_month, end_month])
            period_text = f"{selected_quarter} {selected_year}" if selected_year else selected_quarter
    
    # Collect all data
    # === PROJECTS ===
    projects = []
    project_stats = {'total': 0, 'won': 0, 'ongoing': 0, 'lost': 0, 'total_value': 0}
    quotation_stats = {'total': 0, 'won': 0, 'ongoing': 0, 'lost': 0, 'won_value': 0, 'ongoing_value': 0, 'lost_value': 0}
    
    if report_type == 'sales':
        query = f"""
            SELECT project_name FROM projects 
            WHERE sales_eng = ? AND project_name IS NOT NULL AND project_name != ''
            {date_conditions}
            GROUP BY project_name
        """
    else:
        query = f"""
            SELECT project_name FROM projects 
            WHERE presale_eng = ? AND project_name IS NOT NULL AND project_name != ''
            {date_conditions}
            GROUP BY project_name
        """
    c.execute(query, params_base)
    project_names = [row[0] for row in c.fetchall()]
    
    for project_name in project_names:
        if report_type == 'sales':
            query = f"""
                SELECT quote_ref, status, quotation_selling_price, registered_date
                FROM projects WHERE project_name = ? AND sales_eng = ?
                {date_conditions.replace('registered_date', 'registered_date') if date_conditions else ''}
            """
        else:
            query = f"""
                SELECT quote_ref, status, quotation_selling_price, registered_date
                FROM projects WHERE project_name = ? AND presale_eng = ?
                {date_conditions.replace('registered_date', 'registered_date') if date_conditions else ''}
            """
        c.execute(query, [project_name] + params_base)
        quotations = c.fetchall()
        
        project_status = 'Ongoing'
        total_selling = 0
        for q in quotations:
            status = q[1] or 'Ongoing'
            total_selling += q[2] or 0
            if status == 'Won':
                project_status = 'Won'
                project_stats['total_value'] += q[2] or 0
            elif status == 'Lost' and project_status != 'Won':
                project_status = 'Lost'
        
        projects.append({
            'name': project_name,
            'status': project_status,
            'selling_price': total_selling,
            'quotations': len(quotations)
        })
        
        project_stats['total'] += 1
        if project_status == 'Won':
            project_stats['won'] += 1
        elif project_status == 'Lost':
            project_stats['lost'] += 1
        else:
            project_stats['ongoing'] += 1
    
    # === RFQs ===
    rfqs = []
    rfq_stats = {'total': 0, 'queue': 0, 'studying': 0, 'pricing': 0, 'quoted': 0, 'cancelled': 0}
    
    rfq_date_conditions = date_conditions.replace('registered_date', 'r.requested_time')
    if report_type == 'sales':
        rfq_query = f"""
            SELECT r.rfq_reference, r.project_name, r.rfq_status, r.deadline, 
                   r.sales_engineer_sales, r.sales_engineer_presale, r.requested_time,
                   (SELECT p.registered_date FROM projects p WHERE p.rfq_reference = r.rfq_reference LIMIT 1) as submitted_time,
                   r.system
            FROM rfq_requests r WHERE r.sales_engineer_sales = ?
            {rfq_date_conditions}
        """
    else:
        rfq_query = f"""
            SELECT r.rfq_reference, r.project_name, r.rfq_status, r.deadline,
                   r.sales_engineer_sales, r.sales_engineer_presale, r.requested_time,
                   (SELECT p.registered_date FROM projects p WHERE p.rfq_reference = r.rfq_reference LIMIT 1) as submitted_time,
                   r.system
            FROM rfq_requests r WHERE r.sales_engineer_presale = ?
            {rfq_date_conditions}
        """
    c.execute(rfq_query, params_base)
    for row in c.fetchall():
        status = row[2] or 'Queue'
        rfqs.append({
            'reference': row[0],
            'project': row[1] or '',
            'status': status,
            'due_date': row[3] or '',
            'sales_engineer': row[4] or '',
            'presale_engineer': row[5] or '',
            'request_date': row[6][:10] if row[6] else '',
            'submitted_date': row[7][:10] if row[7] else '',
            'system': row[8] or ''
        })
        rfq_stats['total'] += 1
        status_lower = status.lower()
        if 'queue' in status_lower:
            rfq_stats['queue'] += 1
        elif 'study' in status_lower:
            rfq_stats['studying'] += 1
        elif 'pric' in status_lower:
            rfq_stats['pricing'] += 1
        elif 'quot' in status_lower:
            rfq_stats['quoted'] += 1
        elif 'cancel' in status_lower:
            rfq_stats['cancelled'] += 1
    
    # === RFTS ===
    rfts_list = []
    rfts_stats = {'total': 0, 'queue': 0, 'studying': 0, 'in_progress': 0, 'done': 0, 'pending': 0}
    
    rfts_date_conditions = date_conditions.replace('registered_date', 'requested_time')
    if report_type == 'sales':
        rfts_query = f"""
            SELECT rfts_reference, project_name, request_type, request_status, deadline, system, sales_engineer, presale_engineer, requested_time
            FROM technical_support_requests WHERE sales_engineer = ?
            {rfts_date_conditions}
        """
    else:
        rfts_query = f"""
            SELECT rfts_reference, project_name, request_type, request_status, deadline, system, sales_engineer, presale_engineer, requested_time
            FROM technical_support_requests WHERE presale_engineer = ?
            {rfts_date_conditions}
        """
    c.execute(rfts_query, params_base)
    for row in c.fetchall():
        status = row[3] or 'Queue'
        rfts_list.append({
            'reference': row[0],
            'project': row[1] or '',
            'type': row[2] or '',
            'status': status,
            'sales_engineer': row[6] or '',
            'presale_engineer': row[7] or '',
            'deadline': row[4] or '',
            'system': row[5] or '',
            'request_date': row[8][:10] if row[8] else ''
        })
        rfts_stats['total'] += 1
        status_lower = status.lower()
        if 'queue' in status_lower:
            rfts_stats['queue'] += 1
        elif 'study' in status_lower:
            rfts_stats['studying'] += 1
        elif 'progress' in status_lower:
            rfts_stats['in_progress'] += 1
        elif 'done' in status_lower:
            rfts_stats['done'] += 1
        elif 'pending' in status_lower:
            rfts_stats['pending'] += 1
    
    # === QUOTATIONS DETAIL DATA ===
    quotations_list = []
    if report_type == 'sales':
        quotations_query = f"""
            SELECT quote_ref, project_name, sales_eng, presale_eng, registered_date, 
                   quotation_cost, quotation_selling_price, margin, quotation_note, feedback, status
            FROM projects 
            WHERE sales_eng = ? AND quote_ref IS NOT NULL AND quote_ref != ''
            {date_conditions}
            ORDER BY registered_date DESC
        """
    else:
        quotations_query = f"""
            SELECT quote_ref, project_name, sales_eng, presale_eng, registered_date, 
                   quotation_cost, quotation_selling_price, margin, quotation_note, feedback, status
            FROM projects 
            WHERE presale_eng = ? AND quote_ref IS NOT NULL AND quote_ref != ''
            {date_conditions}
            ORDER BY registered_date DESC
        """
    c.execute(quotations_query, params_base)
    quotations_data = c.fetchall()
    for idx, q in enumerate(quotations_data, 1):
        quotations_list.append({
            'num': idx,
            'quote_ref': q[0] or '-',
            'project_name': q[1] or '-',
            'engineer': q[2] or '-',
            'presale_engineer': q[3] or '-',
            'date': q[4][:10] if q[4] else '-',
            'cost': q[5] or 0,
            'selling': q[6] or 0,
            'margin': f"{q[7]:.1f}%" if q[7] is not None else '-',
            'note': q[8] or '-',
            'feedback': q[9] or '-',
            'status': q[10] or '-'
        })
        
        # Update quotation stats
        quotation_stats['total'] += 1
        selling = q[6] or 0
        # Get status for this quotation
        c.execute("SELECT status FROM projects WHERE quote_ref = ?", (q[0],))
        status_row = c.fetchone()
        if status_row:
            q_status = status_row[0] or ''
            if q_status in ['Won', 'Done', 'Closed Won']:
                quotation_stats['won'] += 1
                quotation_stats['won_value'] += selling
            elif q_status in ['Lost', 'Cancelled', 'Closed Lost']:
                quotation_stats['lost'] += 1
                quotation_stats['lost_value'] += selling
            else:
                quotation_stats['ongoing'] += 1
                quotation_stats['ongoing_value'] += selling
    
    conn.close()
    
    # === RELATED ENGINEERS PERFORMANCE ===
    related_engineer_stats = {}
    
    # Initialize stats from RFQs
    for rfq in rfqs:
        if report_type == 'sales':
            eng_name = rfq.get('presale_engineer', '')
        else:
            eng_name = rfq.get('sales_engineer', '')
        
        if eng_name and eng_name.strip() and eng_name != '-':
            if eng_name not in related_engineer_stats:
                related_engineer_stats[eng_name] = {
                    'rfq_total': 0, 'rfq_queue': 0, 'rfq_studying': 0, 'rfq_pricing': 0, 'rfq_quoted': 0, 'rfq_cancelled': 0,
                    'rfts_total': 0, 'rfts_queue': 0, 'rfts_studying': 0, 'rfts_in_progress': 0, 'rfts_done': 0, 'rfts_pending': 0,
                    'quote_total': 0, 'quote_won': 0, 'quote_lost': 0, 'quote_ongoing': 0,
                    'quote_won_value': 0, 'quote_lost_value': 0, 'quote_ongoing_value': 0
                }
            related_engineer_stats[eng_name]['rfq_total'] += 1
            rfq_status = rfq.get('status', '')
            if 'queue' in rfq_status.lower():
                related_engineer_stats[eng_name]['rfq_queue'] += 1
            elif 'study' in rfq_status.lower():
                related_engineer_stats[eng_name]['rfq_studying'] += 1
            elif 'pric' in rfq_status.lower():
                related_engineer_stats[eng_name]['rfq_pricing'] += 1
            elif 'quot' in rfq_status.lower():
                related_engineer_stats[eng_name]['rfq_quoted'] += 1
            elif 'cancel' in rfq_status.lower():
                related_engineer_stats[eng_name]['rfq_cancelled'] += 1

    # Add RFTS stats
    for rfts in rfts_list:
        if report_type == 'sales':
            eng_name = rfts.get('presale_engineer', '')
        else:
            eng_name = rfts.get('sales_engineer', '')
        
        if eng_name and eng_name.strip() and eng_name != '-':
            if eng_name not in related_engineer_stats:
                related_engineer_stats[eng_name] = {
                    'rfq_total': 0, 'rfq_queue': 0, 'rfq_studying': 0, 'rfq_pricing': 0, 'rfq_quoted': 0, 'rfq_cancelled': 0,
                    'rfts_total': 0, 'rfts_queue': 0, 'rfts_studying': 0, 'rfts_in_progress': 0, 'rfts_done': 0, 'rfts_pending': 0,
                    'quote_total': 0, 'quote_won': 0, 'quote_lost': 0, 'quote_ongoing': 0,
                    'quote_won_value': 0, 'quote_lost_value': 0, 'quote_ongoing_value': 0
                }
            related_engineer_stats[eng_name]['rfts_total'] += 1
            rfts_status = rfts.get('status', '')
            if rfts_status == 'Queue':
                related_engineer_stats[eng_name]['rfts_queue'] += 1
            elif rfts_status == 'Studying':
                related_engineer_stats[eng_name]['rfts_studying'] += 1
            elif rfts_status == 'In Progress':
                related_engineer_stats[eng_name]['rfts_in_progress'] += 1
            elif rfts_status == 'Done':
                related_engineer_stats[eng_name]['rfts_done'] += 1
            elif rfts_status == 'Pending':
                related_engineer_stats[eng_name]['rfts_pending'] += 1

    # Add Quotation stats
    for q in quotations_list:
        if report_type == 'sales':
            eng_name = q.get('presale_engineer', '')
        else:
            eng_name = q.get('engineer', '')
        
        if eng_name and eng_name.strip() and eng_name != '-':
            if eng_name not in related_engineer_stats:
                related_engineer_stats[eng_name] = {
                    'rfq_total': 0, 'rfq_queue': 0, 'rfq_studying': 0, 'rfq_pricing': 0, 'rfq_quoted': 0, 'rfq_cancelled': 0,
                    'rfts_total': 0, 'rfts_queue': 0, 'rfts_studying': 0, 'rfts_in_progress': 0, 'rfts_done': 0, 'rfts_pending': 0,
                    'quote_total': 0, 'quote_won': 0, 'quote_lost': 0, 'quote_ongoing': 0,
                    'quote_won_value': 0, 'quote_lost_value': 0, 'quote_ongoing_value': 0
                }
            related_engineer_stats[eng_name]['quote_total'] += 1
    
    # Create PowerPoint
    prs = Presentation()
    prs.slide_width = Inches(13.333)
    prs.slide_height = Inches(7.5)
    
    FONT_NAME = 'Calibri'
    PRIMARY_BLUE = RGBColor(102, 126, 234)
    SECONDARY_PURPLE = RGBColor(118, 75, 162)
    GREEN = RGBColor(40, 167, 69)
    YELLOW = RGBColor(255, 193, 7)
    RED = RGBColor(220, 53, 69)
    ORANGE = RGBColor(253, 126, 20)
    TEAL = RGBColor(0, 150, 136)
    GRAY = RGBColor(108, 117, 125)
    WHITE = RGBColor(255, 255, 255)
    DARK_TEXT = RGBColor(33, 37, 41)
    LIGHT_BG = RGBColor(248, 249, 250)
    
    def add_gradient_background(slide, color1, color2):
        background = slide.shapes.add_shape(1, Inches(0), Inches(0), Inches(13.333), Inches(7.5))
        background.fill.gradient()
        background.fill.gradient_angle = 135
        background.fill.gradient_stops[0].color.rgb = color1
        background.fill.gradient_stops[1].color.rgb = color2
        background.line.fill.background()
        spTree = slide.shapes._spTree
        sp = background._element
        spTree.remove(sp)
        spTree.insert(2, sp)

    def add_section_separator(prs, title, subtitle, icon_text, color1, color2):
        """Add a section separator slide with gradient background"""
        slide = prs.slides.add_slide(prs.slide_layouts[6])
        add_gradient_background(slide, color1, color2)
        
        # Icon circle
        icon_shape = slide.shapes.add_shape(9, Inches(5.666), Inches(2.0), Inches(2), Inches(2))  # Oval
        icon_shape.fill.solid()
        icon_shape.fill.fore_color.rgb = RGBColor(255, 255, 255)
        icon_shape.fill.fore_color.brightness = 0.1
        icon_shape.line.fill.background()
        
        # Icon text
        icon_box = slide.shapes.add_textbox(Inches(5.666), Inches(2.4), Inches(2), Inches(1.2))
        tf = icon_box.text_frame
        p = tf.paragraphs[0]
        p.text = icon_text
        p.font.size = Pt(48)
        p.font.bold = True
        p.font.color.rgb = color1
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
        
        # Title
        title_box = slide.shapes.add_textbox(Inches(0.5), Inches(4.3), Inches(12.333), Inches(1))
        tf = title_box.text_frame
        p = tf.paragraphs[0]
        p.text = title
        p.font.size = Pt(44)
        p.font.bold = True
        p.font.color.rgb = WHITE
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
        
        # Subtitle
        sub_box = slide.shapes.add_textbox(Inches(0.5), Inches(5.3), Inches(12.333), Inches(0.8))
        tf = sub_box.text_frame
        p = tf.paragraphs[0]
        p.text = subtitle
        p.font.size = Pt(20)
        p.font.color.rgb = RGBColor(220, 220, 255)
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
        
        return slide


    # ========== SLIDE 1: Title Slide ==========
    slide_layout = prs.slide_layouts[6]
    slide = prs.slides.add_slide(slide_layout)
    add_gradient_background(slide, PRIMARY_BLUE, SECONDARY_PURPLE)
    
    # Title
    title_box = slide.shapes.add_textbox(Inches(0.5), Inches(2), Inches(12.333), Inches(1.5))
    tf = title_box.text_frame
    p = tf.paragraphs[0]
    p.text = "Engineer Performance Report"
    p.font.size = Pt(48)
    p.font.bold = True
    p.font.color.rgb = WHITE
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # Engineer name
    name_box = slide.shapes.add_textbox(Inches(0.5), Inches(3.5), Inches(12.333), Inches(1))
    tf = name_box.text_frame
    p = tf.paragraphs[0]
    role = "Sales Engineer" if report_type == 'sales' else "Presale Engineer"
    p.text = f"{selected_engineer} - {role}"
    p.font.size = Pt(32)
    p.font.color.rgb = WHITE
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # Period
    period_box = slide.shapes.add_textbox(Inches(0.5), Inches(4.5), Inches(12.333), Inches(0.8))
    tf = period_box.text_frame
    p = tf.paragraphs[0]
    p.text = f"Period: {period_text}"
    p.font.size = Pt(20)
    p.font.color.rgb = RGBColor(200, 200, 255)
    p.font.name = FONT_NAME
    p.alignment = PP_ALIGN.CENTER
    
    # ========== SLIDE 2: INDEX SLIDE ==========
    # Define colors for index slide
    IDX_PURPLE = RGBColor(124, 58, 237)
    IDX_BLUE = RGBColor(37, 99, 235)
    IDX_SEC_PURPLE = RGBColor(139, 92, 246)
    IDX_GREEN = RGBColor(34, 197, 94)
    IDX_WHITE = RGBColor(255, 255, 255)
    IDX_DARK = RGBColor(31, 41, 55)
    
    slide = prs.slides.add_slide(slide_layout)
    slide.background.fill.solid()
    slide.background.fill.fore_color.rgb = RGBColor(245, 247, 250)
    
    # Header
    header = slide.shapes.add_shape(1, Inches(0), Inches(0), Inches(13.333), Inches(0.9))
    header.fill.gradient()
    header.fill.gradient_angle = 90
    header.fill.gradient_stops[0].color.rgb = IDX_BLUE
    header.fill.gradient_stops[1].color.rgb = IDX_SEC_PURPLE
    header.line.fill.background()
    
    title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(10), Inches(0.5))
    tf = title_box.text_frame
    p = tf.paragraphs[0]
    p.text = "Report Contents"
    p.font.size = Pt(28)
    p.font.bold = True
    p.font.color.rgb = IDX_WHITE
    p.font.name = FONT_NAME
    
    # Index items with icons
    index_items = [
        ("1", "Performance Overview", "Key metrics and statistics dashboard", IDX_PURPLE),
        ("2", "Engineers Performance", "Related engineers comparison", RGBColor(59, 130, 246)),
        ("3", "Projects & Quotations", "Project breakdown and quotation details", IDX_GREEN),
        ("4", "RFQ Status", "Request for Quotation tracking by status", RGBColor(243, 156, 18)),
        ("5", "Follow-Up Items", "Pending RFQs requiring attention", RGBColor(220, 53, 69)),
        ("6", "RFTS Status", "Request for Technical Support tracking", RGBColor(13, 110, 253))
    ]
    
    y_pos = 1.2
    for num, title, desc, color in index_items:
        # Number circle
        circle = slide.shapes.add_shape(9, Inches(0.5), Inches(y_pos), Inches(0.6), Inches(0.6))
        circle.fill.solid()
        circle.fill.fore_color.rgb = color
        circle.line.fill.background()
        
        # Number text
        num_box = slide.shapes.add_textbox(Inches(0.5), Inches(y_pos + 0.1), Inches(0.6), Inches(0.4))
