            quote_badge = slide.shapes.add_shape(MSO_SHAPE.ROUNDED_RECTANGLE, x + card_width - Inches(0.65), quote_y + Inches(0.02), Inches(0.5), Inches(0.22))
            quote_badge.fill.gradient()
