                p.font.size = Pt(12)
                p.font.bold = True
                p.font.color.rgb = text_color
                p.font.name = FONT_NAME
                p.alignment = PP_ALIGN.CENTER
                
                # Label
                label_box = slide.shapes.add_textbox(box_x, box_y + Inches(0.16), col_width - Inches(0.05), Inches(0.1))
                tf = label_box.text_frame
