@app.route('/view_po_status', methods=['GET', 'POST'])
@permission_required('view_po_status')
def view_po_status():
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row  # Enable named field access
    c = conn.cursor()

    # Fetch distinct presale engineers and Technical Team Leaders using JOIN on username
    c.execute('''
        SELECT DISTINCT e.username
        FROM purchase_orders po
        LEFT JOIN engineers e ON CAST(po.presale_engineer AS TEXT) = e.username
        WHERE e.username IS NOT NULL
        ORDER BY e.username
    ''')
    presale_engineers = c.fetchall()

    # Fetch distinct project managers using JOIN on username
    c.execute('''
        SELECT DISTINCT e.username
        FROM purchase_orders po
        LEFT JOIN engineers e ON CAST(po.project_manager AS TEXT) = e.username
        WHERE e.username IS NOT NULL
        ORDER BY e.username
    ''')
    project_managers = c.fetchall()

    # Fetch distinct distributors using JOIN on names
    c.execute('''
        SELECT DISTINCT d.name
        FROM purchase_orders po
        LEFT JOIN distributors d ON CAST(po.distributor AS TEXT) = d.name
        WHERE d.name IS NOT NULL
        ORDER BY d.name
    ''')
    distributors = c.fetchall()
    
    # Fetch distinct vendors using JOIN on names
    c.execute('''
        SELECT DISTINCT v.name
        FROM purchase_orders po
        LEFT JOIN vendors v ON CAST(po.vendor AS TEXT) = v.name
        WHERE v.name IS NOT NULL
        ORDER BY v.name
    ''')
    vendors = c.fetchall()
    
    # Fetch distinct project names
    c.execute('''
        SELECT DISTINCT rp.project_name, rp.project_name
        FROM purchase_orders po
        JOIN register_project rp ON po.project_name = rp.project_name
    ''')
    projects = c.fetchall()
    
    # Fetch ALL vendors and distributors for inline editing dropdowns
    c.execute('SELECT id, name FROM vendors ORDER BY name')
    all_vendors = c.fetchall()
    
    c.execute('SELECT id, name FROM distributors ORDER BY name')
    all_distributors = c.fetchall()

    # Initialize filters
    presale_engineer_filter = request.form.get('presale_engineer', '')
    project_manager_filter = request.form.get('project_manager', '')
    distributor_filter = request.form.get('distributor', '')
    vendor_filter = request.form.get('vendor', '')
    po_delivery_status_filter = request.form.get('po_delivery_status', '')
    po_approval_status_filter = request.form.get('po_approval_status', '')
    project_name_filter = request.form.get('project_name', '')

    # Calculate statistics with filters applied - JOIN on names/usernames not IDs
    stats_query = '''
    SELECT 
        COUNT(*) as total_pos,
        SUM(CASE WHEN po.po_approval_status = 'Approved' THEN 1 ELSE 0 END) as approved_count,
        SUM(CASE WHEN po.po_approval_status = 'Pending' THEN 1 ELSE 0 END) as pending_count,
        SUM(CASE WHEN po.po_approval_status = 'Rejected' THEN 1 ELSE 0 END) as rejected_count,
        SUM(CASE WHEN po.po_delivery_status LIKE '%Delivered%' THEN 1 ELSE 0 END) as delivered_count,
        SUM(CASE WHEN po.po_delivery_status = 'Order Placed' THEN 1 ELSE 0 END) as in_progress_count,
        COALESCE(SUM(po.total_amount), 0) as total_amount,
        COALESCE(AVG(po.total_amount), 0) as avg_amount
    FROM purchase_orders po
    LEFT JOIN register_project rp ON CAST(po.project_name AS TEXT) = CAST(rp.project_name AS TEXT)
    LEFT JOIN distributors d ON CAST(po.distributor AS TEXT) = d.name
    LEFT JOIN vendors v ON CAST(po.vendor AS TEXT) = v.name
    LEFT JOIN engineers eng ON CAST(po.presale_engineer AS TEXT) = eng.username
    LEFT JOIN engineers pmeng ON CAST(po.project_manager AS TEXT) = pmeng.username
    WHERE 1=1
    '''
    stats_params = []
    
    if presale_engineer_filter:
        stats_query += " AND eng.username = ?"
        stats_params.append(presale_engineer_filter)
    
    if project_manager_filter:
        stats_query += " AND pmeng.username = ?"
        stats_params.append(project_manager_filter)
    
    if distributor_filter:
        stats_query += " AND d.name = ?"
        stats_params.append(distributor_filter)
    
    if vendor_filter:
        stats_query += " AND v.name = ?"
        stats_params.append(vendor_filter)
    
    if po_delivery_status_filter:
        stats_query += " AND po.po_delivery_status = ?"
        stats_params.append(po_delivery_status_filter)
    
    if po_approval_status_filter:
        stats_query += " AND po.po_approval_status = ?"
        stats_params.append(po_approval_status_filter)
        
    if project_name_filter:
        stats_query += " AND rp.project_name = ?"
        stats_params.append(project_name_filter)
    
    c.execute(stats_query, stats_params)
    stats = c.fetchone()

    # Build the main query with vendor information - use subqueries to avoid duplicates from multiple vendors/distributors with same name
    query = '''
    SELECT 
        po.id AS po_id,
        po.po_request_number, 
        po.project_name,
        (SELECT MIN(d2.id) FROM distributors d2 WHERE d2.name = po.distributor) AS distributor_id,
        COALESCE(po.distributor, '') AS distributor_name,
        (SELECT MIN(v2.id) FROM vendors v2 WHERE v2.name = po.vendor) AS vendor_id,
        COALESCE(po.vendor, '') AS vendor_name,
        po.po_approval_status, 
        po.po_delivery_status, 
        COALESCE(eng.username, po.presale_engineer) AS presale_engineer_name,
        COALESCE(pmeng.username, po.project_manager) AS project_manager_name,
        po.po_number,
        po.po_notes_vendor,
        po.po_notes_client,
        po.total_amount,
        po.system,
        po.project_name,
        po.presale_engineer AS presale_engineer_id,
        po.project_manager AS project_manager_id,
        po.distributor AS distributor_raw_id
    FROM purchase_orders po
    LEFT JOIN engineers eng ON CAST(po.presale_engineer AS TEXT) = eng.username
    LEFT JOIN engineers pmeng ON CAST(po.project_manager AS TEXT) = pmeng.username
    WHERE 1=1
    '''
    params = []

    if presale_engineer_filter:
        query += " AND eng.username = ?"
        params.append(presale_engineer_filter)

    if project_manager_filter:
        query += " AND pmeng.username = ?"
        params.append(project_manager_filter)

    if distributor_filter:
        query += " AND po.distributor = ?"
        params.append(distributor_filter)
    
    if vendor_filter:
        query += " AND po.vendor = ?"
        params.append(vendor_filter)

    if po_delivery_status_filter:
        query += " AND po.po_delivery_status = ?"
        params.append(po_delivery_status_filter)

    if po_approval_status_filter:
        query += " AND po.po_approval_status = ?"
        params.append(po_approval_status_filter)
        
    if project_name_filter:
        query += " AND po.project_name = ?"
        params.append(project_name_filter)
    
    query += " ORDER BY po.id DESC"

    c.execute(query, params)
    purchase_orders = c.fetchall()
    conn.close()

    return render_template('view_po_status.html',
                           purchase_orders=purchase_orders,
                           presale_engineers=presale_engineers,
                           project_managers=project_managers,
                           distributors=distributors,
                           vendors=vendors,
                           projects=projects,
                           all_vendors=all_vendors,
                           all_distributors=all_distributors,
                           stats=stats,
                           project_name_filter=project_name_filter,
                           presale_engineer_filter=presale_engineer_filter,
                           project_manager_filter=project_manager_filter,
                           distributor_filter=distributor_filter,
                           vendor_filter=vendor_filter,
                           po_delivery_status_filter=po_delivery_status_filter,
                           po_approval_status_filter=po_approval_status_filter)

@app.route('/po_reports', methods=['GET', 'POST'])
@permission_required('view_po_reports')
def po_reports():
    """PO Reports page - View and export purchase order reports grouped by project"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    # Get all projects that have purchase orders
    c.execute('''
        SELECT DISTINCT rp.id, rp.project_name,
            COALESCE(eu.name, con.name, cons.name, 'N/A') as client_name
        FROM register_project rp
        INNER JOIN purchase_orders po ON po.project_name = rp.project_name
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors con ON rp.contractor_id = con.id
        LEFT JOIN consultants cons ON rp.consultant_id = cons.id
        ORDER BY rp.project_name
    ''')
    projects = c.fetchall()
    
    # Get filter values
    project_filter = request.args.get('project', '') or request.form.get('project', '')
    vendor_filter = request.args.get('vendor', '') or request.form.get('vendor', '')
    distributor_filter = request.args.get('distributor', '') or request.form.get('distributor', '')
    year_filter = request.args.get('year', '') or request.form.get('year', '')
    quarter_filter = request.args.get('quarter', '') or request.form.get('quarter', '')
    delivery_status_filter = request.args.get('delivery_status', '') or request.form.get('delivery_status', '')
    
    # Get distinct vendors
    c.execute('''
        SELECT DISTINCT v.name
        FROM purchase_orders po
        LEFT JOIN vendors v ON po.vendor = v.name
        WHERE v.name IS NOT NULL
        ORDER BY v.name
    ''')
    vendors = c.fetchall()
    
    # Get distinct distributors
    c.execute('''
        SELECT DISTINCT d.name
        FROM purchase_orders po
        LEFT JOIN distributors d ON po.distributor = d.name
        WHERE d.name IS NOT NULL
        ORDER BY d.name
    ''')
    distributors = c.fetchall()
    
    # Get distinct years from PO creation dates
    c.execute('''
        SELECT DISTINCT strftime('%Y', created_at) as year
        FROM purchase_orders
        WHERE created_at IS NOT NULL
        ORDER BY year DESC
    ''')
    years = [row['year'] for row in c.fetchall() if row['year']]
    
    # Build main query for project-grouped data
    query = '''
        SELECT 
            rp.id as project_id,
            rp.project_name,
            COALESCE(eu.name, con.name, cons.name, 'N/A') as client_name,
            po.id as po_id,
            po.po_request_number,
            po.po_number,
            po.vendor,
            po.distributor,
            po.total_amount,
            po.po_approval_status,
            po.po_delivery_status,
            po.presale_engineer,
            po.project_manager,
            po.system,
            po.created_at,
            (SELECT COUNT(*) FROM po_items WHERE po_number = po.po_number) as item_count,
            (SELECT SUM(quantity) FROM po_items WHERE po_number = po.po_number) as total_qty,
            (SELECT SUM(COALESCE(quantity_delivered, 0)) FROM po_items WHERE po_number = po.po_number) as delivered_qty
        FROM purchase_orders po
        JOIN register_project rp ON po.project_name = rp.project_name
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors con ON rp.contractor_id = con.id
        LEFT JOIN consultants cons ON rp.consultant_id = cons.id
        WHERE 1=1
    '''
    params = []
    
    if project_filter:
        query += " AND rp.project_name = ?"
        params.append(project_filter)
    
    if vendor_filter:
        query += " AND po.vendor = ?"
        params.append(vendor_filter)
    
    if distributor_filter:
        query += " AND po.distributor = ?"
        params.append(distributor_filter)
    
    if year_filter:
        query += " AND strftime('%Y', po.created_at) = ?"
        params.append(year_filter)
    
    if quarter_filter:
        if quarter_filter == 'Q1':
            query += " AND strftime('%m', po.created_at) IN ('01', '02', '03')"
        elif quarter_filter == 'Q2':
            query += " AND strftime('%m', po.created_at) IN ('04', '05', '06')"
        elif quarter_filter == 'Q3':
            query += " AND strftime('%m', po.created_at) IN ('07', '08', '09')"
        elif quarter_filter == 'Q4':
            query += " AND strftime('%m', po.created_at) IN ('10', '11', '12')"
    
    if delivery_status_filter:
        query += " AND po.po_delivery_status = ?"
        params.append(delivery_status_filter)
    
    query += " ORDER BY rp.project_name, po.id DESC"
    
    c.execute(query, params)
    all_pos = c.fetchall()
    
    # Group POs by project
    projects_data = {}
    for po in all_pos:
        project_name = po['project_name']
        if project_name not in projects_data:
            projects_data[project_name] = {
                'project_id': po['project_id'],
                'project_name': project_name,
                'client_name': po['client_name'],
                'pos': [],
                'total_amount': 0,
                'total_pos': 0,
                'approved_count': 0,
                'pending_count': 0,
                'rejected_count': 0,
                'delivered_count': 0,
                'partial_count': 0,
                'not_delivered_count': 0
            }
        
        projects_data[project_name]['pos'].append(po)
        projects_data[project_name]['total_pos'] += 1
        projects_data[project_name]['total_amount'] += float(po['total_amount'] or 0)
        
        # Count by approval status
        if po['po_approval_status'] == 'Approved':
            projects_data[project_name]['approved_count'] += 1
        elif po['po_approval_status'] == 'Pending':
            projects_data[project_name]['pending_count'] += 1
        elif po['po_approval_status'] == 'Rejected':
            projects_data[project_name]['rejected_count'] += 1
        
        # Count by delivery status
        delivery_status = po['po_delivery_status'] or ''
        if 'Delivered' in delivery_status and 'Not' not in delivery_status:
            projects_data[project_name]['delivered_count'] += 1
        elif 'Partial' in delivery_status:
            projects_data[project_name]['partial_count'] += 1
        else:
            projects_data[project_name]['not_delivered_count'] += 1
    
    # Calculate overall statistics
    total_projects = len(projects_data)
    total_pos = sum(p['total_pos'] for p in projects_data.values())
    total_amount = sum(p['total_amount'] for p in projects_data.values())
    total_approved = sum(p['approved_count'] for p in projects_data.values())
    total_delivered = sum(p['delivered_count'] for p in projects_data.values())
    
    conn.close()
    
    return render_template('po_reports.html',
                           projects=projects,
                           projects_data=projects_data,
                           vendors=vendors,
                           distributors=distributors,
                           years=years,
                           project_filter=project_filter,
                           vendor_filter=vendor_filter,
                           distributor_filter=distributor_filter,
                           year_filter=year_filter,
                           quarter_filter=quarter_filter,
                           delivery_status_filter=delivery_status_filter,
                           total_projects=total_projects,
                           total_pos=total_pos,
                           total_amount=total_amount,
                           total_approved=total_approved,
                           total_delivered=total_delivered)

@app.route('/export_po_report_excel', methods=['POST'])
@permission_required('view_po_reports')
def export_po_report_excel():
    """Export PO Reports to Excel file"""
    import pandas as pd
    from io import BytesIO
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    # Get filter values
    project_filter = request.form.get('project', '')
    vendor_filter = request.form.get('vendor', '')
    distributor_filter = request.form.get('distributor', '')
    year_filter = request.form.get('year', '')
    quarter_filter = request.form.get('quarter', '')
    delivery_status_filter = request.form.get('delivery_status', '')
    
    # Build query
    query = '''
        SELECT 
            rp.project_name as "Project Name",
            COALESCE(eu.name, con.name, cons.name, 'N/A') as "Client",
            po.po_request_number as "PO Request #",
            po.po_number as "PO Number",
            po.vendor as "Vendor",
            po.distributor as "Distributor",
            po.system as "System",
            po.total_amount as "Total Amount (SAR)",
            po.po_approval_status as "Approval Status",
            po.po_delivery_status as "Delivery Status",
            po.presale_engineer as "Presale Engineer",
            po.project_manager as "Account Manager",
            po.created_at as "Created Date"
        FROM purchase_orders po
        JOIN register_project rp ON po.project_name = rp.project_name
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors con ON rp.contractor_id = con.id
        LEFT JOIN consultants cons ON rp.consultant_id = cons.id
        WHERE 1=1
    '''
    params = []
    
    if project_filter:
        query += " AND rp.project_name = ?"
        params.append(project_filter)
    if vendor_filter:
        query += " AND po.vendor = ?"
        params.append(vendor_filter)
    if distributor_filter:
        query += " AND po.distributor = ?"
        params.append(distributor_filter)
    if year_filter:
        query += " AND strftime('%Y', po.created_at) = ?"
        params.append(year_filter)
    if quarter_filter:
        if quarter_filter == 'Q1':
            query += " AND strftime('%m', po.created_at) IN ('01', '02', '03')"
        elif quarter_filter == 'Q2':
            query += " AND strftime('%m', po.created_at) IN ('04', '05', '06')"
        elif quarter_filter == 'Q3':
            query += " AND strftime('%m', po.created_at) IN ('07', '08', '09')"
        elif quarter_filter == 'Q4':
            query += " AND strftime('%m', po.created_at) IN ('10', '11', '12')"
    if delivery_status_filter:
        query += " AND po.po_delivery_status = ?"
        params.append(delivery_status_filter)
    
    query += " ORDER BY rp.project_name, po.id DESC"
    
    c.execute(query, params)
    rows = c.fetchall()
    
    # Get PO items for each PO
    items_query = '''
        SELECT 
            po.project_name as "Project Name",
            po.po_number as "PO Number",
            pi.part_number as "Part Number",
            pi.description as "Description",
            pi.quantity as "Quantity",
            pi.unit_price as "Unit Price",
            pi.total_price as "Total Price",
            COALESCE(pi.quantity_delivered, 0) as "Delivered Qty",
            (pi.quantity - COALESCE(pi.quantity_delivered, 0)) as "Remaining Qty",
            pi.delivery_status as "Item Status"
        FROM po_items pi
        JOIN purchase_orders po ON pi.po_number = po.po_number
        JOIN register_project rp ON po.project_name = rp.project_name
        WHERE 1=1
    '''
    if project_filter:
        items_query += " AND rp.project_name = ?"
    
    items_params = [project_filter] if project_filter else []
    items_query += " ORDER BY po.project_name, po.po_number, pi.id"
    
    c.execute(items_query, items_params)
    items_rows = c.fetchall()
    
    conn.close()
    
    # Create Excel file
    output = BytesIO()
    with pd.ExcelWriter(output, engine='xlsxwriter') as writer:
        # Summary sheet
        df_summary = pd.DataFrame([dict(row) for row in rows])
        if not df_summary.empty:
            df_summary.to_excel(writer, sheet_name='PO Summary', index=False)
            workbook = writer.book
            worksheet = writer.sheets['PO Summary']
            
            header_format = workbook.add_format({
                'bold': True, 'bg_color': '#667eea', 'font_color': 'white',
                'border': 1, 'align': 'center', 'valign': 'vcenter'
            })
            money_format = workbook.add_format({'num_format': '#,##0.00', 'border': 1})
            
            for col_num, value in enumerate(df_summary.columns.values):
                worksheet.write(0, col_num, value, header_format)
                worksheet.set_column(col_num, col_num, 18)
        
        # Items sheet
        df_items = pd.DataFrame([dict(row) for row in items_rows])
        if not df_items.empty:
            df_items.to_excel(writer, sheet_name='PO Items', index=False)
            worksheet_items = writer.sheets['PO Items']
            
            for col_num, value in enumerate(df_items.columns.values):
                worksheet_items.write(0, col_num, value, header_format)
                worksheet_items.set_column(col_num, col_num, 16)
    
    output.seek(0)
    
    filename = f"PO_Report_{project_filter or 'All_Projects'}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
    
    return send_file(
        output,
        mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        as_attachment=True,
        download_name=filename
    )

@app.route('/export_po_report_pptx', methods=['POST'])
@permission_required('view_po_reports')
def export_po_report_pptx():
    """Export PO Reports to PowerPoint presentation"""
    from pptx import Presentation
    from pptx.util import Inches, Pt
    from pptx.dml.color import RGBColor
    from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
    from io import BytesIO
    
    FONT_NAME = 'Arial'
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    # Get filter values
    project_filter = request.form.get('project', '')
    vendor_filter = request.form.get('vendor', '')
    distributor_filter = request.form.get('distributor', '')
    year_filter = request.form.get('year', '')
    quarter_filter = request.form.get('quarter', '')
    delivery_status_filter = request.form.get('delivery_status', '')
    
    # Build query for POs
    query = '''
        SELECT 
            rp.project_name,
            COALESCE(eu.name, con.name, cons.name, 'N/A') as client_name,
            po.id as po_id,
            po.po_request_number,
            po.po_number,
            po.vendor,
            po.distributor,
            po.total_amount,
            po.po_approval_status,
            po.po_delivery_status,
            po.presale_engineer,
            po.project_manager,
            po.system,
            po.created_at
        FROM purchase_orders po
        JOIN register_project rp ON po.project_name = rp.project_name
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors con ON rp.contractor_id = con.id
        LEFT JOIN consultants cons ON rp.consultant_id = cons.id
        WHERE 1=1
    '''
    params = []
    
    if project_filter:
        query += " AND rp.project_name = ?"
        params.append(project_filter)
    if vendor_filter:
        query += " AND po.vendor = ?"
        params.append(vendor_filter)
    if distributor_filter:
        query += " AND po.distributor = ?"
        params.append(distributor_filter)
    if year_filter:
        query += " AND strftime('%Y', po.created_at) = ?"
        params.append(year_filter)
    if quarter_filter:
        if quarter_filter == 'Q1':
            query += " AND strftime('%m', po.created_at) IN ('01', '02', '03')"
        elif quarter_filter == 'Q2':
            query += " AND strftime('%m', po.created_at) IN ('04', '05', '06')"
        elif quarter_filter == 'Q3':
            query += " AND strftime('%m', po.created_at) IN ('07', '08', '09')"
        elif quarter_filter == 'Q4':
            query += " AND strftime('%m', po.created_at) IN ('10', '11', '12')"
    if delivery_status_filter:
        query += " AND po.po_delivery_status = ?"
        params.append(delivery_status_filter)
    
    query += " ORDER BY rp.project_name, po.id DESC"
    
    c.execute(query, params)
    all_pos = c.fetchall()
    
    # Group by project
    projects_data = {}
    for po in all_pos:
        project_name = po['project_name']
        if project_name not in projects_data:
            projects_data[project_name] = {
                'client_name': po['client_name'],
                'pos': [],
                'total_amount': 0
            }
        projects_data[project_name]['pos'].append(po)
        projects_data[project_name]['total_amount'] += float(po['total_amount'] or 0)
    
    # Helper function to get delivery status
    def get_item_delivery_status(item):
        try:
            qty = int(item['quantity'] or 0)
            delivered = int(item['quantity_delivered'] or 0)
            if delivered >= qty:
                return 'Delivered'
            elif delivered > 0:
                return 'Partial'
            else:
                return 'Not Delivered'
        except:
            return item.get('delivery_status') or 'Not Delivered'
    
    # Create presentation
    prs = Presentation()
    prs.slide_width = Inches(13.333)
    prs.slide_height = Inches(7.5)
    slide_layout = prs.slide_layouts[6]
    
    FONT_NAME = "Calibri"
    
    # Title slide
    slide = prs.slides.add_slide(slide_layout)
    title_shape = slide.shapes.add_shape(1, Inches(0), Inches(0), Inches(13.333), Inches(3))
    title_shape.fill.solid()
    title_shape.fill.fore_color.rgb = RGBColor(102, 126, 234)
    title_shape.line.fill.background()
    
    title_box = slide.shapes.add_textbox(Inches(0.5), Inches(1.5), Inches(12.333), Inches(1.5))
    tf = title_box.text_frame
    p = tf.paragraphs[0]
    p.text = "Purchase Order Report"
    p.font.size = Pt(44)
    p.font.bold = True
    p.font.name = FONT_NAME
    p.font.color.rgb = RGBColor(255, 255, 255)
    p.alignment = PP_ALIGN.CENTER
    
    p2 = tf.add_paragraph()
    filter_text = project_filter if project_filter else "All Projects"
    p2.text = f"{filter_text} - {datetime.now().strftime('%B %d, %Y')}"
    p2.font.size = Pt(24)
    p2.font.name = FONT_NAME
    p2.font.color.rgb = RGBColor(255, 255, 255)
    p2.alignment = PP_ALIGN.CENTER
    
    # Summary stats box
    stats_box = slide.shapes.add_textbox(Inches(2), Inches(4), Inches(9.333), Inches(2.5))
    tf = stats_box.text_frame
    p = tf.paragraphs[0]
    total_projects = len(projects_data)
    total_pos_count = sum(len(pd['pos']) for pd in projects_data.values())
    total_amount = sum(pd['total_amount'] for pd in projects_data.values())
    p.text = f"Projects: {total_projects}  |  Purchase Orders: {total_pos_count}  |  Total Value: {total_amount:,.2f} SAR"
    p.font.size = Pt(20)
    p.font.name = FONT_NAME
    p.font.color.rgb = RGBColor(60, 60, 60)
    p.alignment = PP_ALIGN.CENTER
    
    # Get base URL for download links
    import os
    base_url = os.environ.get('REPLIT_DEV_DOMAIN', '')
    if base_url:
        base_url = f"https://{base_url}"
    
    # Iterate through each project and each PO to create detailed slides
    for project_name, proj_data in projects_data.items():
        # Project summary slide
        slide = prs.slides.add_slide(slide_layout)
        
        header = slide.shapes.add_shape(1, Inches(0), Inches(0), Inches(13.333), Inches(1.3))
        header.fill.solid()
        header.fill.fore_color.rgb = RGBColor(102, 126, 234)
        header.line.fill.background()
        
        title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.5))
        tf = title_box.text_frame
        p = tf.paragraphs[0]
        p.text = f"Project: {project_name[:55]}"
        p.font.size = Pt(24)
        p.font.bold = True
        p.font.name = FONT_NAME
        p.font.color.rgb = RGBColor(255, 255, 255)
        
        p2 = tf.add_paragraph()
        p2.text = f"Client: {proj_data['client_name'] or 'N/A'}  |  POs: {len(proj_data['pos'])}  |  Total: {proj_data['total_amount']:,.2f} SAR"
        p2.font.size = Pt(14)
        p2.font.name = FONT_NAME
        p2.font.color.rgb = RGBColor(220, 220, 255)
        
        # PO summary table
        pos_to_show = proj_data['pos'][:8]
        rows = len(pos_to_show) + 1
        cols = 6
        table = slide.shapes.add_table(rows, cols, Inches(0.2), Inches(1.5), Inches(12.9), Inches(0.5) * rows).table
        
        table.columns[0].width = Inches(2.0)
        table.columns[1].width = Inches(2.5)
        table.columns[2].width = Inches(2.5)
        table.columns[3].width = Inches(2.0)
        table.columns[4].width = Inches(1.8)
        table.columns[5].width = Inches(2.1)
        
        headers_list = ['PO Reference', 'Vendor', 'Distributor', 'System', 'Approval', 'Delivery']
        for col, hdr in enumerate(headers_list):
            cell = table.cell(0, col)
            cell.text = hdr
            cell.fill.solid()
            cell.fill.fore_color.rgb = RGBColor(59, 89, 152)
            cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
            cell.text_frame.paragraphs[0].font.bold = True
            cell.text_frame.paragraphs[0].font.size = Pt(10)
            cell.text_frame.paragraphs[0].font.name = FONT_NAME
            cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
            cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        for i, po in enumerate(pos_to_show, 1):
            table.cell(i, 0).text = str(po['po_number'] or po['po_request_number'] or '')[:20]
            table.cell(i, 1).text = str(po['vendor'] or '')[:25]
            table.cell(i, 2).text = str(po['distributor'] or '')[:25]
            table.cell(i, 3).text = f"{float(po['total_amount'] or 0):,.2f}"
            
            approval_cell = table.cell(i, 4)
            approval_status = po['po_approval_status'] or ''
            approval_cell.text = approval_status
            approval_cell.fill.solid()
            if approval_status == 'Approved':
                approval_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                approval_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
            elif approval_status == 'Pending':
                approval_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
            else:
                approval_cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                approval_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
            
            delivery_cell = table.cell(i, 5)
            delivery_status = po['po_delivery_status'] or 'Pending'
            delivery_cell.text = delivery_status[:15]
            delivery_cell.fill.solid()
            if 'Delivered' in delivery_status and 'Not' not in delivery_status:
                delivery_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                delivery_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
            elif 'Partial' in delivery_status:
                delivery_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
            else:
                delivery_cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                delivery_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
            
            for col in range(4):
                cell = table.cell(i, col)
                if i % 2 == 0:
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(230, 240, 255)
                else:
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(245, 248, 255)
            
            for col in range(cols):
                cell = table.cell(i, col)
                for para in cell.text_frame.paragraphs:
                    para.font.size = Pt(9)
                    para.font.name = FONT_NAME
                    para.alignment = PP_ALIGN.CENTER
                cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        # Create detailed slides for each PO in the project
        for po in proj_data['pos']:
            po_number = po['po_number'] or po['po_request_number'] or ''
            po_request_number = po['po_request_number'] or ''
            
            # Get PO items
            c.execute('''
                SELECT id, part_number, description, quantity, unit_price, total_price,
                       COALESCE(quantity_delivered, 0) as quantity_delivered, delivery_status
                FROM po_items WHERE po_number = ?
            ''', (po_number,))
            po_items = c.fetchall()
            
            # Get delivery notes
            c.execute('''
                SELECT id, order_date, expected_delivery, status, notes
                FROM purchase_order_monitoring WHERE po_number = ?
                ORDER BY expected_delivery DESC
            ''', (po_number,))
            delivery_notes = c.fetchall()
            
            # Get the latest expected delivery/follow-up info for this PO
            latest_expected_delivery = ''
            latest_follow_up_notes = ''
            if delivery_notes:
                for dn in delivery_notes:
                    if dn['expected_delivery']:
                        latest_expected_delivery = str(dn['expected_delivery'])[:10]
                        break
                for dn in delivery_notes:
                    if dn['notes']:
                        latest_follow_up_notes = str(dn['notes'])[:30]
                        break
            
            # Get VAT invoices
            c.execute('''
                SELECT id, invoice_name, file_name, uploaded_by_username, uploaded_at
                FROM vat_invoices WHERE po_request_number = ?
            ''', (po_request_number,))
            vat_invoices = c.fetchall()
            
            # PO Detail slide - Items
            if po_items:
                items_per_slide = 6
                for slide_start in range(0, len(po_items), items_per_slide):
                    slide_items = list(po_items)[slide_start:slide_start + items_per_slide]
                    
                    slide = prs.slides.add_slide(slide_layout)
                    
                    header = slide.shapes.add_shape(1, Inches(0), Inches(0), Inches(13.333), Inches(1.1))
                    header.fill.solid()
                    header.fill.fore_color.rgb = RGBColor(59, 89, 152)
                    header.line.fill.background()
                    
                    title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.15), Inches(12.733), Inches(0.4))
                    tf = title_box.text_frame
                    p = tf.paragraphs[0]
                    p.text = f"PO: {po_number} - Items ({slide_start + 1}-{min(slide_start + items_per_slide, len(po_items))} of {len(po_items)})"
                    p.font.size = Pt(22)
                    p.font.bold = True
                    p.font.name = FONT_NAME
                    p.font.color.rgb = RGBColor(255, 255, 255)
                    
                    p2 = tf.add_paragraph()
                    p2.text = f"Project: {project_name[:50]}  |  Vendor: {po['vendor'] or 'N/A'}  |  Total: {float(po['total_amount'] or 0):,.2f} SAR"
                    p2.font.size = Pt(12)
                    p2.font.name = FONT_NAME
                    p2.font.color.rgb = RGBColor(200, 210, 255)
                    
                    # Items table with delivery info
                    rows = len(slide_items) + 1
                    item_cols = 10
                    row_height = Inches(0.65)
                    item_table = slide.shapes.add_table(rows, item_cols, Inches(0.15), Inches(1.2), Inches(13.0), row_height * rows).table
                    
                    item_table.columns[0].width = Inches(0.35)
                    item_table.columns[1].width = Inches(1.1)
                    item_table.columns[2].width = Inches(2.5)
                    item_table.columns[3].width = Inches(0.6)
                    item_table.columns[4].width = Inches(1.1)
                    item_table.columns[5].width = Inches(1.1)
                    item_table.columns[6].width = Inches(0.9)
                    item_table.columns[7].width = Inches(0.9)
                    item_table.columns[8].width = Inches(1.4)
                    item_table.columns[9].width = Inches(3.0)
                    
                    item_headers = ['#', 'Part Number', 'Description', 'Qty', 'Unit Price', 'Total', 'Delivered', 'Remaining', 'Status', 'Follow Up / Expected']
                    for col, hdr in enumerate(item_headers):
                        cell = item_table.cell(0, col)
                        cell.text = hdr
                        cell.fill.solid()
                        cell.fill.fore_color.rgb = RGBColor(59, 89, 152)
                        cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                        cell.text_frame.paragraphs[0].font.bold = True
                        cell.text_frame.paragraphs[0].font.size = Pt(9)
                        cell.text_frame.paragraphs[0].font.name = FONT_NAME
                        cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                        cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                    
                    for i, item in enumerate(slide_items, 1):
                        row_idx = i
                        total_qty = int(item['quantity'] or 0)
                        try:
                            delivered_qty = int(item['quantity_delivered'] or 0)
                        except:
                            delivered_qty = 0
                        remaining_qty = max(0, total_qty - delivered_qty)
                        
                        item_table.cell(row_idx, 0).text = str(slide_start + i)
                        item_table.cell(row_idx, 1).text = str(item['part_number'] or '')[:12]
                        item_table.cell(row_idx, 2).text = str(item['description'] or '')[:35]
                        item_table.cell(row_idx, 3).text = str(total_qty)
                        item_table.cell(row_idx, 4).text = f"{float(item['unit_price'] or 0):,.2f}"
                        item_table.cell(row_idx, 5).text = f"{float(item['total_price'] or 0):,.2f}"
                        
                        # Delivered column
                        del_cell = item_table.cell(row_idx, 6)
                        del_cell.text = str(delivered_qty)
                        del_cell.fill.solid()
                        if delivered_qty >= total_qty:
                            del_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                            del_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                        elif delivered_qty > 0:
                            del_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                        else:
                            del_cell.fill.fore_color.rgb = RGBColor(245, 248, 255)
                        
                        # Remaining column
                        rem_cell = item_table.cell(row_idx, 7)
                        rem_cell.text = str(remaining_qty)
                        rem_cell.fill.solid()
                        if remaining_qty == 0:
                            rem_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                            rem_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                        elif remaining_qty < total_qty:
                            rem_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                        else:
                            rem_cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                            rem_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                        
                        # Status column
                        status = get_item_delivery_status(item)
                        status_cell = item_table.cell(row_idx, 8)
                        status_cell.text = status
                        status_cell.fill.solid()
                        if status == 'Delivered':
                            status_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                            status_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                        elif status == 'Partial':
                            status_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                        else:
                            status_cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                            status_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                        
                        # Follow Up / Expected Delivery column
                        followup_cell = item_table.cell(row_idx, 9)
                        followup_text = ''
                        if latest_expected_delivery:
                            followup_text = f"Exp: {latest_expected_delivery}"
                            if latest_follow_up_notes:
                                followup_text += f" | {latest_follow_up_notes}"
                        elif latest_follow_up_notes:
                            followup_text = latest_follow_up_notes
                        else:
                            followup_text = '-'
                        followup_cell.text = followup_text[:35]
                        followup_cell.fill.solid()
                        followup_cell.fill.fore_color.rgb = RGBColor(23, 162, 184)
                        followup_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                        followup_cell.text_frame.paragraphs[0].font.size = Pt(8)
                        followup_cell.text_frame.paragraphs[0].font.name = FONT_NAME
                        followup_cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                        followup_cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                        
                        for col in range(6):
                            cell = item_table.cell(row_idx, col)
                            if i % 2 == 0:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(230, 240, 255)
                            else:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(245, 248, 255)
                        
                        for col in range(item_cols):
                            cell = item_table.cell(row_idx, col)
                            for para in cell.text_frame.paragraphs:
                                para.font.size = Pt(8)
                                para.font.name = FONT_NAME
                                para.alignment = PP_ALIGN.CENTER
                            cell.vertical_anchor = MSO_ANCHOR.MIDDLE
            
            # Delivery Notes slide
            if delivery_notes:
                slide = prs.slides.add_slide(slide_layout)
                
                title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.6))
                tf = title_box.text_frame
                p = tf.paragraphs[0]
                p.text = f"PO: {po_number} - Delivery Notes ({len(delivery_notes)})"
                p.font.size = Pt(26)
                p.font.bold = True
                p.font.name = FONT_NAME
                p.font.color.rgb = RGBColor(23, 162, 184)
                
                dn_per_slide = 8
                dns_to_show = list(delivery_notes)[:dn_per_slide]
                dn_rows = len(dns_to_show) + 1
                dn_cols = 6
                dn_table = slide.shapes.add_table(dn_rows, dn_cols, Inches(0.3), Inches(1.0), Inches(12.7), Inches(0.55) * dn_rows).table
                
                dn_table.columns[0].width = Inches(0.8)
                dn_table.columns[1].width = Inches(2.0)
                dn_table.columns[2].width = Inches(2.0)
                dn_table.columns[3].width = Inches(1.6)
                dn_table.columns[4].width = Inches(3.5)
                dn_table.columns[5].width = Inches(2.8)
                
                dn_headers = ['ID', 'Order Date', 'Expected Delivery', 'Status', 'Notes', 'Download']
                for col, hdr in enumerate(dn_headers):
                    cell = dn_table.cell(0, col)
                    cell.text = hdr
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(23, 162, 184)
                    cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                    cell.text_frame.paragraphs[0].font.bold = True
                    cell.text_frame.paragraphs[0].font.size = Pt(10)
                    cell.text_frame.paragraphs[0].font.name = FONT_NAME
                    cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                    cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                
                for i, dn in enumerate(dns_to_show, 1):
                    dn_id = dn['id'] or ''
                    dn_table.cell(i, 0).text = str(dn_id)
                    dn_table.cell(i, 1).text = str(dn['order_date'] or '')[:10]
                    dn_table.cell(i, 2).text = str(dn['expected_delivery'] or '')[:10]
                    
                    status_val = dn['status'] or ''
                    status_cell = dn_table.cell(i, 3)
                    status_cell.text = status_val
                    status_cell.fill.solid()
                    if status_val.lower() == 'delivered':
                        status_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                        status_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                    elif status_val.lower() == 'pending':
                        status_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                    else:
                        status_cell.fill.fore_color.rgb = RGBColor(108, 117, 125)
                        status_cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                    
                    dn_table.cell(i, 4).text = str(dn['notes'] or '')[:40]
                    
                    download_cell = dn_table.cell(i, 5)
                    download_cell.text = "Download"
                    download_cell.fill.solid()
                    download_cell.fill.fore_color.rgb = RGBColor(0, 123, 255)
                    for para in download_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                        para.font.bold = True
                        para.font.size = Pt(9)
                        para.font.name = FONT_NAME
                        para.alignment = PP_ALIGN.CENTER
                        if base_url and dn_id:
                            run = para.runs[0] if para.runs else para.add_run()
                            run.hyperlink.address = f"{base_url}/download_delivery_note/{dn_id}"
                    download_cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                    
                    for col in range(5):
                        cell = dn_table.cell(i, col)
                        if col != 3:
                            if i % 2 == 0:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(230, 245, 255)
                            else:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(245, 252, 255)
                        for para in cell.text_frame.paragraphs:
                            para.font.size = Pt(10)
                            para.font.name = FONT_NAME
                            para.alignment = PP_ALIGN.CENTER
                        cell.vertical_anchor = MSO_ANCHOR.MIDDLE
            
            # VAT Invoices slide
            if vat_invoices:
                slide = prs.slides.add_slide(slide_layout)
                
                title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.6))
                tf = title_box.text_frame
                p = tf.paragraphs[0]
                p.text = f"PO: {po_number} - VAT Invoices ({len(vat_invoices)})"
                p.font.size = Pt(26)
                p.font.bold = True
                p.font.name = FONT_NAME
                p.font.color.rgb = RGBColor(111, 66, 193)
                
                vat_per_slide = 8
                vats_to_show = list(vat_invoices)[:vat_per_slide]
                vat_rows = len(vats_to_show) + 1
                vat_cols = 5
                vat_table = slide.shapes.add_table(vat_rows, vat_cols, Inches(0.3), Inches(1.0), Inches(12.7), Inches(0.55) * vat_rows).table
                
                vat_table.columns[0].width = Inches(3.0)
                vat_table.columns[1].width = Inches(3.0)
