                vat_table.columns[4].width = Inches(2.7)
                
                vat_headers = ['Invoice Name', 'File Name', 'Uploaded By', 'Upload Date', 'Download']
                for col, hdr in enumerate(vat_headers):
                    cell = vat_table.cell(0, col)
