@app.route('/po_profile/<po_request_number>', methods=['GET'])
@login_required
def po_profile(po_request_number):
    """Comprehensive PO Profile page with delivery tracking"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    cursor.execute("""
        SELECT 
            po.*,
            COALESCE(rp.project_name, po.project_name) as project_name_actual,
            COALESCE(po.distributor, 'N/A') as distributor_name,
            COALESCE(po.vendor, 'N/A') as vendor_name,
            e.name as presale_engineer_name,
            pm.name as project_manager_name
        FROM purchase_orders po
        LEFT JOIN register_project rp ON po.project_name = rp.project_name
        LEFT JOIN engineers e ON po.presale_engineer = e.username
        LEFT JOIN engineers pm ON po.project_manager = pm.username
        WHERE po.po_request_number = ?
    """, (po_request_number,))
    po = cursor.fetchone()
    
    if not po:
        flash('Purchase Order not found!', 'danger')
        conn.close()
        return redirect(url_for('view_po_status'))
    
    po_number = po['po_number']
    
    cursor.execute("""
        SELECT * FROM po_items 
        WHERE po_number = ? 
        ORDER BY item_number ASC
    """, (po_number,))
    po_items = cursor.fetchall()
    
    cursor.execute("""
        SELECT * FROM purchase_order_monitoring 
        WHERE (po_number = ? OR po_number = ?) AND deleted_at IS NULL
        ORDER BY order_date DESC
    """, (po_number, po_request_number))
    delivery_notes = cursor.fetchall()
    
    cursor.execute("""
        SELECT * FROM vat_invoices 
        WHERE po_request_number = ?
        ORDER BY uploaded_at DESC
    """, (po_request_number,))
    vat_invoices = cursor.fetchall()
    
    # Fetch follow-ups for this PO
    cursor.execute("""
        SELECT * FROM po_follow_ups 
        WHERE po_id = ?
        ORDER BY 
            CASE WHEN status = 'Pending' THEN 0 ELSE 1 END,
            follow_up_date ASC
    """, (po['id'],))
    follow_ups = cursor.fetchall()
    
    # Fetch activity log for this PO
    cursor.execute("""
        SELECT * FROM po_activity_log 
        WHERE po_id = ?
        ORDER BY created_at DESC
    """, (po['id'],))
    activities = cursor.fetchall()
    
    # Get current date for overdue detection
    current_date = datetime.now().strftime('%Y-%m-%d')
    
    # Get users for assignment dropdown
    cursor.execute("SELECT username FROM users ORDER BY username")
    users = [row['username'] for row in cursor.fetchall()]
    
    delivered_count = sum(1 for item in po_items if item['delivery_status'] == 'Delivered')
    partial_count = sum(1 for item in po_items if item['delivery_status'] == 'Partial')
    not_delivered_count = sum(1 for item in po_items if item['delivery_status'] == 'Not Delivered')
    
    conn.close()
    
    return render_template('po_profile.html',
                           po=po,
                           po_number=po_number,
                           po_request_number=po_request_number,
                           po_items=po_items,
                           delivery_notes=delivery_notes,
                           vat_invoices=vat_invoices,
                           follow_ups=follow_ups,
                           activities=activities,
                           current_date=current_date,
                           users=users,
                           delivered_count=delivered_count,
                           partial_count=partial_count,
                           not_delivered_count=not_delivered_count)



@app.route('/api/po_ai_email/<po_number>', methods=['POST'])
def po_ai_email(po_number):
    """Generate AI follow-up email to distributor about delivery status"""
    import os as _os
    try:
        import openai as _openai
    except ImportError:
        return jsonify({'ok': False, 'error': 'OpenAI library not available'}), 500

    # Manual auth check — returns JSON instead of redirecting to HTML login page
    if 'user_id' not in session:
        return jsonify({'ok': False, 'error': 'Session expired. Please refresh the page and log in again.'}), 401

    try:
        data = request.get_json(silent=True) or {}
        tone = data.get('tone', 'Professional')

        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()

        po = cursor.execute(
            "SELECT * FROM purchase_orders WHERE po_number=?", (po_number,)
        ).fetchone()

        if not po:
            conn.close()
            return jsonify({'ok': False, 'error': 'PO not found'}), 404

        items = cursor.execute(
            "SELECT * FROM po_items WHERE po_number=? ORDER BY id", (po_number,)
        ).fetchall()
        conn.close()

        total_qty     = sum((r['quantity'] or 0) for r in items)
        delivered_qty = sum((r['quantity_delivered'] or 0) for r in items)
        remaining_qty = total_qty - delivered_qty
        grand_total   = sum((r['total_price'] or 0) for r in items)
        delivered_val = sum((r['quantity_delivered'] or 0) * (r['unit_price'] or 0) for r in items)
        delivered_pct = round(delivered_qty / total_qty * 100, 1) if total_qty > 0 else 0

        not_delivered = [r for r in items if r['delivery_status'] != 'Delivered']
        pending_lines = []
        for r in not_delivered[:15]:
            pn   = r['part_number'] or 'N/A'
            desc = (r['description'] or '')[:60]
            rem  = (r['quantity'] or 0) - (r['quantity_delivered'] or 0)
            pending_lines.append("  - " + str(pn) + " | " + str(desc) + " (Remaining: " + str(rem) + " units)")
        pending_text = chr(10).join(pending_lines) if pending_lines else '  All items fully delivered.'

        sender_name  = session.get('username', 'Procurement Team')
        dist_contact = po['distributor_engineer'] or 'Sir/Madam'
        dist_company = po['distributor'] or 'your company'
        dist_email   = po['distributor_email'] or ''
        system_name  = po['system'] or 'N/A'
        vendor_name  = po['vendor'] or 'N/A'
        vat_pct      = po['vat_percentage'] or 15
        total_with_vat = grand_total * (1 + vat_pct / 100)

        NL = chr(10)
        prompt = (
            "You are " + sender_name + ", a procurement professional at EJTech. "
            "Write a " + tone + " follow-up email to the distributor about PO delivery status." + NL + NL
            + "PURCHASE ORDER DETAILS:" + NL
            + "- PO Number: " + po_number + NL
            + "- System / Category: " + system_name + NL
            + "- Vendor / Brand: " + vendor_name + NL
            + "- Grand Total: SAR " + "{:,.2f}".format(grand_total)
              + " (incl. VAT: SAR " + "{:,.2f}".format(total_with_vat) + ")" + NL
            + "- Total Units Ordered: " + "{:,}".format(total_qty) + NL
            + "- Delivered: " + "{:,}".format(delivered_qty)
              + " units (" + str(delivered_pct) + "%)" + NL
            + "- Remaining: " + "{:,}".format(remaining_qty) + " units" + NL
            + "- Delivered Value: SAR " + "{:,.2f}".format(delivered_val) + NL + NL
            + "PENDING / PARTIALLY DELIVERED ITEMS:" + NL + pending_text + NL + NL
            + "DISTRIBUTOR CONTACT: " + dist_contact + " at " + dist_company + NL + NL
            + "INSTRUCTIONS:" + NL
            + "- Write a complete, ready-to-send professional email (Subject + Body)." + NL
            + "- Start with: Subject: ..." + NL
            + "- Then a blank line, then the email body." + NL
            + "- Greet the contact by name." + NL
            + "- Reference the PO number clearly." + NL
            + "- Summarize delivery progress concisely." + NL
            + "- List 2-3 specific pending items if applicable." + NL
            + "- Request a firm delivery schedule / ETA for outstanding items." + NL
            + "- Keep it under 250 words." + NL
            + "- End with a professional sign-off from " + sender_name + ", EJTech Procurement Team." + NL
            + "- Tone: " + tone + "."
        )

        _ai_key  = _os.environ.get('AI_INTEGRATIONS_OPENAI_API_KEY') or _os.environ.get('OPENAI_API_KEY')
        _ai_base = _os.environ.get('AI_INTEGRATIONS_OPENAI_BASE_URL')
        if not _ai_key:
            return jsonify({'ok': False, 'error': 'OpenAI API key not configured. Set OPENAI_API_KEY environment variable.'}), 500

        client = _openai.OpenAI(api_key=_ai_key, **({'base_url': _ai_base} if _ai_base else {}))
        resp = client.chat.completions.create(
            model='gpt-4o-mini',
            messages=[{'role': 'user', 'content': prompt}],
            max_tokens=500,
            temperature=0.7,
        )
        email_text = resp.choices[0].message.content.strip()

        return jsonify({
            'ok': True,
            'email': email_text,
            'distributor_email': dist_email,
            'distributor_name':  dist_contact,
        })

    except Exception as _e:
        import traceback
        traceback.print_exc()
        _msg = str(_e)
        # Friendly messages for common OpenAI errors
        if '429' in _msg or 'insufficient_quota' in _msg or 'exceeded your current quota' in _msg:
            _friendly = ('OpenAI quota exceeded. The API key has run out of credits. '
                         'Please top up your OpenAI account or update the OPENAI_API_KEY '
                         'in your environment variables with an active key.')
        elif '401' in _msg or 'Unauthorized' in _msg or 'invalid_api_key' in _msg:
            _friendly = 'Invalid or missing OpenAI API key. Please check the OPENAI_API_KEY environment variable.'
        elif '503' in _msg or '502' in _msg or 'ServiceUnavailable' in _msg:
            _friendly = 'OpenAI service is temporarily unavailable. Please try again in a few moments.'
        elif 'connect' in _msg.lower() or 'timeout' in _msg.lower():
            _friendly = 'Could not connect to OpenAI. Please check your internet connection and try again.'
        else:
            _friendly = _msg
        return jsonify({'ok': False, 'error': _friendly}), 500


@app.route('/add_po_item/<po_number>', methods=['POST'])
@login_required
def add_po_item(po_number):
    """Add new item to PO with comprehensive validation"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    # Resolve po_request_number for redirect
    _req_row = cursor.execute("SELECT po_request_number FROM purchase_orders WHERE po_number=?", (po_number,)).fetchone()
    po_request_number = _req_row['po_request_number'] if _req_row else po_number
    conn.row_factory = None
    
    try:
        part_number = request.form.get('part_number', '').strip()
        
        description = request.form.get('description', '').strip()
        if not description:
            flash('Description is required!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_request_number=po_request_number))
        
        quantity_str = request.form.get('quantity', '').strip()
        if not quantity_str:
            flash('Quantity is required!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_request_number=po_request_number))
        
        try:
            quantity = float(quantity_str)
            if quantity <= 0:
                flash('Quantity must be greater than zero!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_request_number=po_request_number))
        except (ValueError, TypeError):
            flash('Invalid quantity value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_request_number=po_request_number))
        
        unit_price_str = request.form.get('unit_price', '0').strip()
        try:
            unit_price = float(unit_price_str) if unit_price_str else 0
            if unit_price < 0:
                flash('Unit price cannot be negative!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_request_number=po_request_number))
        except (ValueError, TypeError):
            flash('Invalid unit price value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_request_number=po_request_number))
        
        total_price_str = request.form.get('total_price', '0').strip()
        try:
            total_price = float(total_price_str) if total_price_str else 0
            if total_price < 0:
                flash('Total price cannot be negative!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_request_number=po_request_number))
        except (ValueError, TypeError):
            flash('Invalid total price value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_request_number=po_request_number))
        
        if total_price == 0 and unit_price > 0:
            total_price = quantity * unit_price
        
        notes = request.form.get('notes', '').strip()
        
        cursor.execute("""
            SELECT COALESCE(MAX(item_number), 0) + 1 
            FROM po_items 
            WHERE po_number = ?
        """, (po_number,))
        next_item_number = cursor.fetchone()[0]
        
        cursor.execute("""
            INSERT INTO po_items (
                po_number, item_number, part_number, description, 
                quantity, unit_price, total_price, notes
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """, (po_number, next_item_number, part_number, description, 
              quantity, unit_price, total_price, notes))
        
        conn.commit()
        flash('Item added successfully!', 'success')
        
    except KeyError as e:
        flash(f'Missing required field: {str(e)}', 'danger')
    except Exception as e:
        flash(f'Error adding item: {str(e)}', 'danger')
    finally:
        conn.close()
    
    return redirect(url_for('po_profile', po_request_number=po_request_number))


