@app.route('/update_po_vat/<po_number>', methods=['POST'])
@login_required
def update_po_vat(po_number):
    """Update VAT percentage for PO"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    vat_percentage = float(request.form['vat_percentage'])
    
    cursor.execute("SELECT total_amount FROM purchase_orders WHERE po_number = ?", (po_number,))
    result = cursor.fetchone()
    
    if not result:
        flash('Purchase Order not found!', 'danger')
        conn.close()
        return redirect(url_for('view_po_status'))
    
    total_amount = result['total_amount']
    vat_amount = total_amount * (vat_percentage / 100)
    total_with_vat = total_amount + vat_amount
    
    cursor.execute("""
        UPDATE purchase_orders SET
            vat_percentage = ?,
            vat_amount = ?,
            total_with_vat = ?
        WHERE po_number = ?
    """, (vat_percentage, vat_amount, total_with_vat, po_number))
    
    conn.commit()
    conn.close()
    
    flash('VAT updated successfully!', 'success')
    return redirect(url_for('po_profile', po_request_number=po_request_number))


@app.route('/import_po_items_excel/<po_request_number>', methods=['POST'])
@login_required
def import_po_items_excel(po_request_number):
    """Import PO items from Excel file"""
    if 'excel_file' not in request.files:
        flash('No file uploaded!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    file = request.files['excel_file']
    
    if file.filename == '':
        flash('No file selected!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    if not file.filename.endswith('.xlsx'):
        flash('Invalid file format! Please upload an Excel file (.xlsx only)', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    try:
        import openpyxl
        from io import BytesIO
        
        file_content = BytesIO(file.read())
        workbook = openpyxl.load_workbook(file_content)
        sheet = workbook.active
        
        conn = sqlite3.connect('ProjectStatus.db')
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT po_number, distributor, system
            FROM purchase_orders WHERE po_request_number = ?
        """, (po_request_number,))
        result = cursor.fetchone()
        po_number = result[0] if result and result[0] else po_request_number
        distributor_name = result[1] if result else None
        po_system = result[2] if result else None
        
        # Get distributor_id from distributors table if distributor name exists
        distributor_id = None
        if distributor_name:
            cursor.execute("SELECT id FROM distributors WHERE name = ?", (distributor_name,))
            dist_result = cursor.fetchone()
            distributor_id = dist_result[0] if dist_result else None
        
        cursor.execute("""
            SELECT COALESCE(MAX(item_number), 0) 
            FROM po_items 
            WHERE po_number = ?
        """, (po_number,))
        next_item_number = cursor.fetchone()[0] + 1
        
        # Get or create a default supplier quotation for PO imports
        cursor.execute("""
            SELECT id FROM supplier_quotations 
            WHERE filename = 'PO Import' AND system = 'PO Import'
            LIMIT 1
        """)
        sq_result = cursor.fetchone()
        
        if sq_result:
            supplier_quotation_id = sq_result[0]
        else:
            cursor.execute("""
                INSERT INTO supplier_quotations 
                (quote_ref, system, filename, quotation_file, uploaded_by, uploaded_at)
                VALUES ('PO-IMPORT', 'PO Import', 'PO Import', X'00', ?, CURRENT_TIMESTAMP)
            """, (session.get('username'),))
            supplier_quotation_id = cursor.lastrowid
        
        items_added = 0
        items_updated = 0
        errors = []
        price_changes = []  # Track price changes during import

        # ── Pre-merge duplicate part numbers: sum quantities ────────────────
        # Key: (lower part_number or lower description) → merged row dict
        merged_rows = {}   # ordered dict of merged items
        raw_parse_errors = []
        for row_idx, row in enumerate(sheet.iter_rows(min_row=2, values_only=True), start=2):
            if not row or all(cell is None or str(cell).strip() == '' for cell in row):
                continue
            part_number = str(row[0]).strip() if row[0] else ''
            description = str(row[1]).strip() if row[1] else ''
            if not description:
                raw_parse_errors.append(f"Row {row_idx}: Description is required")
                continue
            try:
                quantity = float(row[2]) if row[2] else 0
                if quantity <= 0:
                    raw_parse_errors.append(f"Row {row_idx}: Quantity must be greater than zero")
                    continue
            except (ValueError, TypeError):
                raw_parse_errors.append(f"Row {row_idx}: Invalid quantity value")
                continue
            try:
                unit_price = float(row[3]) if row[3] else 0
                if unit_price < 0:
                    raw_parse_errors.append(f"Row {row_idx}: Unit price cannot be negative")
                    continue
            except (ValueError, TypeError):
                raw_parse_errors.append(f"Row {row_idx}: Invalid unit price value")
                continue
            quantity_delivered = 0
            quantity_delivered_provided = False
            try:
                if len(row) > 5 and row[5] is not None and str(row[5]).strip() != '':
                    quantity_delivered = float(row[5])
                    if quantity_delivered < 0:
                        quantity_delivered = 0
                    else:
                        quantity_delivered_provided = True
            except (ValueError, TypeError, IndexError):
                pass
            # Merge key: prefer part_number, fall back to lower description
            merge_key = part_number.lower() if part_number else description.lower()
            if merge_key in merged_rows:
                # Sum quantities; keep first-seen part_number, description, unit_price
                merged_rows[merge_key]['quantity'] += quantity
                merged_rows[merge_key]['quantity_delivered'] += quantity_delivered
                if quantity_delivered_provided:
                    merged_rows[merge_key]['quantity_delivered_provided'] = True
            else:
                merged_rows[merge_key] = {
                    'part_number': part_number,
                    'description': description,
                    'quantity': quantity,
                    'unit_price': unit_price,
                    'quantity_delivered': quantity_delivered,
                    'quantity_delivered_provided': quantity_delivered_provided,
                }
        errors.extend(raw_parse_errors)
        # ── Now process the merged rows ──────────────────────────────────────
        for merge_key, merged in merged_rows.items():
            try:
                part_number  = merged['part_number']
                description  = merged['description']
                quantity     = merged['quantity']
                unit_price   = merged['unit_price']
                quantity_delivered          = merged['quantity_delivered']
                quantity_delivered_provided = merged['quantity_delivered_provided']
                # Always calculate total as Qty * Unit Price (ignore Excel column)
                total_price = quantity * unit_price

                existing_item = None
                
                if part_number:
                    cursor.execute("""
                        SELECT id, quantity_delivered, delivery_status FROM po_items 
                        WHERE po_number = ? AND LOWER(TRIM(part_number)) = LOWER(TRIM(?))
                    """, (po_number, part_number))
                    existing_item = cursor.fetchone()
                
                if not existing_item:
                    cursor.execute("""
                        SELECT id, quantity_delivered, delivery_status FROM po_items 
                        WHERE po_number = ? AND LOWER(TRIM(description)) = LOWER(TRIM(?))
                    """, (po_number, description))
                    existing_item = cursor.fetchone()
                
                if existing_item:
                    existing_qty_delivered = existing_item[1] or 0
                    existing_delivery_status = existing_item[2] or 'Not Delivered'
                    
                    if quantity_delivered_provided:
                        if quantity_delivered >= quantity:
                            final_delivery_status = 'Delivered'
                        elif quantity_delivered > 0:
                            final_delivery_status = 'Partial'
                        else:
                            final_delivery_status = 'Not Delivered'
                        final_qty_delivered = quantity_delivered
                    else:
                        final_delivery_status = existing_delivery_status
                        final_qty_delivered = existing_qty_delivered
                    
                    cursor.execute("""
                        UPDATE po_items SET
                            part_number = ?,
                            description = ?,
                            quantity = ?,
                            unit_price = ?,
                            total_price = ?,
                            quantity_delivered = ?,
                            delivery_status = ?,
                            updated_at = CURRENT_TIMESTAMP
                        WHERE id = ?
                    """, (part_number, description, quantity, unit_price, total_price, 
                          final_qty_delivered, final_delivery_status, existing_item[0]))
                    items_updated += 1
                    
                    # Check if product exists in quotation_products, if not add it
                    cursor.execute("""
                        SELECT id, unit_price FROM quotation_products 
                        WHERE po_number = ? AND (
                            LOWER(TRIM(part_number)) = LOWER(TRIM(?)) OR
                            LOWER(TRIM(description)) = LOWER(TRIM(?))
                        )
                    """, (po_number, part_number, description))
                    existing_qp = cursor.fetchone()
                    
                    if existing_qp:
                        # Check for price change and log it
                        old_price = existing_qp[1] or 0
                        if old_price != unit_price and part_number:
                            price_change = unit_price - old_price
                            price_change_percent = (price_change / old_price * 100) if old_price > 0 else 0
                            cursor.execute("""
                                INSERT INTO product_price_history 
                                (part_number, old_price, new_price, price_change, price_change_percent, 
                                 currency, supplier_name, po_number, source, changed_by)
                                VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'PO Import Update', ?)
                            """, (part_number, old_price, unit_price, price_change, price_change_percent,
                                  distributor_name, po_number, session.get('username')))
                            # Track this price change for alert
                            price_changes.append({
                                'part_number': part_number,
                                'description': description[:50],
                                'old_price': old_price,
                                'new_price': unit_price,
                                'change': price_change,
                                'change_percent': price_change_percent
                            })
                            # Update the price in quotation_products
                            cursor.execute("""
                                UPDATE quotation_products SET unit_price = ? WHERE id = ?
                            """, (unit_price, existing_qp[0]))
                    else:
                        # Check if same part_number exists with different price (from another source)
                        if part_number:
                            cursor.execute("""
                                SELECT unit_price FROM quotation_products 
                                WHERE LOWER(TRIM(part_number)) = LOWER(TRIM(?))
                                ORDER BY added_at DESC LIMIT 1
                            """, (part_number,))
                            prev_price_row = cursor.fetchone()
                            if prev_price_row and prev_price_row[0] != unit_price:
                                old_price = prev_price_row[0]
                                price_change = unit_price - old_price
                                price_change_percent = (price_change / old_price * 100) if old_price > 0 else 0
                                cursor.execute("""
                                    INSERT INTO product_price_history 
                                    (part_number, old_price, new_price, price_change, price_change_percent, 
                                     currency, supplier_name, po_number, source, changed_by)
                                    VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'PO Import New', ?)
                                """, (part_number, old_price, unit_price, price_change, price_change_percent,
                                      distributor_name, po_number, session.get('username')))
                                # Track this price change for alert
                                price_changes.append({
                                    'part_number': part_number,
                                    'description': description[:50],
                                    'old_price': old_price,
                                    'new_price': unit_price,
                                    'change': price_change,
                                    'change_percent': price_change_percent
                                })
                        
                        # Add to quotation_products table
                        cursor.execute("""
                            INSERT INTO quotation_products (
                                supplier_quotation_id, part_number, description, 
                                unit_price, quantity, currency, system,
                                supplier_name, supplier_type, added_by,
                                po_number, distributor_id
                            ) VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'Distributor', ?, ?, ?)
                        """, (supplier_quotation_id, part_number, description,
                              unit_price, int(quantity), po_system,
                              distributor_name, session.get('username'),
                              po_number, distributor_id))
                else:
                    if quantity_delivered_provided:
                        if quantity_delivered >= quantity:
                            new_delivery_status = 'Delivered'
                        elif quantity_delivered > 0:
                            new_delivery_status = 'Partial'
                        else:
                            new_delivery_status = 'Not Delivered'
                    else:
                        new_delivery_status = 'Not Delivered'
                        quantity_delivered = 0
                    
                    cursor.execute("""
                        INSERT INTO po_items (
                            po_number, item_number, part_number, description, 
                            quantity, unit_price, total_price, 
                            quantity_delivered, delivery_status
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """, (po_number, next_item_number, part_number, description, 
                          quantity, unit_price, total_price, quantity_delivered, new_delivery_status))
                    next_item_number += 1
                    items_added += 1
                    
                    # Check if same part_number exists with different price (for price history)
                    if part_number:
                        cursor.execute("""
                            SELECT unit_price FROM quotation_products 
                            WHERE LOWER(TRIM(part_number)) = LOWER(TRIM(?))
                            ORDER BY added_at DESC LIMIT 1
                        """, (part_number,))
                        prev_price_row = cursor.fetchone()
                        if prev_price_row and prev_price_row[0] != unit_price:
                            old_price = prev_price_row[0]
                            price_change = unit_price - old_price
                            price_change_percent = (price_change / old_price * 100) if old_price > 0 else 0
                            cursor.execute("""
                                INSERT INTO product_price_history 
                                (part_number, old_price, new_price, price_change, price_change_percent, 
                                 currency, supplier_name, po_number, source, changed_by)
                                VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'PO Import', ?)
                            """, (part_number, old_price, unit_price, price_change, price_change_percent,
                                  distributor_name, po_number, session.get('username')))
                            # Track this price change for alert
                            price_changes.append({
                                'part_number': part_number,
                                'description': description[:50],
                                'old_price': old_price,
                                'new_price': unit_price,
                                'change': price_change,
                                'change_percent': price_change_percent
                            })
                    
                    # Also add to quotation_products table
                    cursor.execute("""
                        INSERT INTO quotation_products (
                            supplier_quotation_id, part_number, description, 
                            unit_price, quantity, currency, system,
                            supplier_name, supplier_type, added_by,
                            po_number, distributor_id
                        ) VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'Distributor', ?, ?, ?)
                    """, (supplier_quotation_id, part_number, description,
                          unit_price, int(quantity), po_system,
                          distributor_name, session.get('username'),
                          po_number, distributor_id))
                
            except Exception as e:
                errors.append(f"Row {row_idx}: {str(e)}")
        
        conn.commit()
        conn.close()
        
        success_msg = []
        if items_added > 0:
            success_msg.append(f"{items_added} item(s) added")
        if items_updated > 0:
            success_msg.append(f"{items_updated} item(s) updated")
        
        if success_msg:
            flash(f"Excel import successful! {', '.join(success_msg)}", 'success')
        
        if errors:
            flash(f"Some rows had errors: {'; '.join(errors[:5])}", 'warning')
        
        # Store price changes in session for alert display
        if price_changes:
            session['price_changes'] = price_changes
            session['price_changes_po'] = po_number
            flash(f"PRICE_ALERT:{len(price_changes)} price change(s) detected during import!", 'price_alert')
        
    except Exception as e:
        flash(f'Error importing Excel file: {str(e)}', 'danger')
    
    return redirect(url_for('po_profile', po_request_number=po_request_number))


@app.route('/export_po_items_excel/<po_number>')
@login_required
def export_po_items_excel(po_number):
    """Export PO items to Excel file"""
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment
        from io import BytesIO
        
        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT part_number, description, quantity, unit_price, 
                   total_price, quantity_delivered
            FROM po_items
            WHERE po_number = ?
            ORDER BY item_number
        """, (po_number,))
        items = cursor.fetchall()
        conn.close()
        
        workbook = openpyxl.Workbook()
        sheet = workbook.active
        sheet.title = "PO Items"
        
        headers = ['Part Number', 'Description', 'Qty', 'Unit Price', 'Total', 'Delivered']
        
        header_fill = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
        header_font = Font(bold=True, color='FFFFFF')
        header_alignment = Alignment(horizontal='center', vertical='center')
        
        for col_idx, header in enumerate(headers, start=1):
            cell = sheet.cell(row=1, column=col_idx, value=header)
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = header_alignment
        
        for row_idx, item in enumerate(items, start=2):
            sheet.cell(row=row_idx, column=1, value=item['part_number'] or '')
            sheet.cell(row=row_idx, column=2, value=item['description'] or '')
            sheet.cell(row=row_idx, column=3, value=item['quantity'] or 0)
            sheet.cell(row=row_idx, column=4, value=item['unit_price'] or 0)
            sheet.cell(row=row_idx, column=5, value=item['total_price'] or 0)
            sheet.cell(row=row_idx, column=6, value=item['quantity_delivered'] or 0)
        
        sheet.column_dimensions['A'].width = 20
        sheet.column_dimensions['B'].width = 50
        sheet.column_dimensions['C'].width = 12
        sheet.column_dimensions['D'].width = 15
        sheet.column_dimensions['E'].width = 15
        sheet.column_dimensions['F'].width = 15
        
        output = BytesIO()
        workbook.save(output)
        output.seek(0)
        
        return send_file(
            output,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=f'PO_{po_number}_Items.xlsx'
        )
        
    except Exception as e:
        flash(f'Error exporting to Excel: {str(e)}', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))


###################################
# Export Complete PO Profile Report to Excel
@app.route('/export_po_profile_excel/<po_request_number>')
@login_required
def export_po_profile_excel(po_request_number):
    """Export comprehensive PO Profile Report to Excel"""
    try:
        import pandas as pd
        from io import BytesIO
        from datetime import datetime
        
        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        
        # Get PO details with joins
        cursor.execute("""
            SELECT 
                po.*,
                COALESCE(rp.project_name, po.project_name) as project_name_actual,
                COALESCE(po.distributor, 'N/A') as distributor_name,
                COALESCE(po.vendor, 'N/A') as vendor_name,
                e.name as presale_engineer_name,
                pm.name as project_manager_name
            FROM purchase_orders po
            LEFT JOIN register_project rp ON po.project_name = rp.project_name
            LEFT JOIN engineers e ON po.presale_engineer = e.username
            LEFT JOIN engineers pm ON po.project_manager = pm.username
            WHERE po.po_request_number = ?
        """, (po_request_number,))
        po = cursor.fetchone()
        
        if not po:
            flash('Purchase Order not found!', 'danger')
            conn.close()
            return redirect(url_for('view_po_status'))
        
        po_number = po['po_number']
        
        # Get PO items
        cursor.execute("""
            SELECT * FROM po_items 
            WHERE po_number = ? 
            ORDER BY item_number ASC
        """, (po_number,))
        po_items = cursor.fetchall()
        
        # Get delivery notes
        cursor.execute("""
            SELECT * FROM purchase_order_monitoring 
            WHERE (po_number = ? OR po_number = ?) AND deleted_at IS NULL
            ORDER BY order_date DESC
        """, (po_number, po_request_number))
        delivery_notes = cursor.fetchall()
        
        # Get VAT invoices
        cursor.execute("""
            SELECT * FROM vat_invoices 
            WHERE po_request_number = ?
            ORDER BY uploaded_at DESC
        """, (po_request_number,))
        vat_invoices = cursor.fetchall()
        
        # Get PO ID for follow-ups and activity log
        po_id = po['id']
        
        # Get follow-ups
        cursor.execute("""
            SELECT * FROM po_follow_ups 
            WHERE po_id = ? 
            ORDER BY follow_up_date DESC, follow_up_time DESC
        """, (po_id,))
        follow_ups = cursor.fetchall()
        
        # Get activity log
        cursor.execute("""
            SELECT * FROM po_activity_log 
            WHERE po_id = ? 
            ORDER BY created_at DESC
        """, (po_id,))
        activity_logs = cursor.fetchall()
        
        conn.close()
        
        # Calculate delivery stats (safely handle missing columns)
        def get_delivery_status(item):
            try:
                return item['delivery_status'] if 'delivery_status' in item.keys() else 'Not Delivered'
            except:
                return 'Not Delivered'
        
        delivered_count = sum(1 for item in po_items if get_delivery_status(item) == 'Delivered')
        partial_count = sum(1 for item in po_items if get_delivery_status(item) == 'Partial')
        not_delivered_count = sum(1 for item in po_items if get_delivery_status(item) == 'Not Delivered')
        total_items = len(po_items)
        
        # Calculate financial summary
        total_value = sum(float(item['total_price'] or 0) for item in po_items)
        vat_amount = total_value * 0.15
        grand_total = total_value + vat_amount
        
        # Create Excel file with multiple sheets
        output = BytesIO()
        with pd.ExcelWriter(output, engine='xlsxwriter') as writer:
            workbook = writer.book
            
            # Formats
            header_format = workbook.add_format({
                'bold': True, 'bg_color': '#667eea', 'font_color': 'white',
                'border': 1, 'align': 'center', 'valign': 'vcenter'
            })
            title_format = workbook.add_format({
                'bold': True, 'font_size': 16, 'font_color': '#667eea'
            })
            label_format = workbook.add_format({
                'bold': True, 'bg_color': '#f0f4ff', 'border': 1
            })
            value_format = workbook.add_format({'border': 1})
            money_format = workbook.add_format({'border': 1, 'num_format': '#,##0.00'})
            
            # Sheet 1: PO Summary
            summary_sheet = workbook.add_worksheet('PO Summary')
            summary_sheet.set_column('A:A', 25)
            summary_sheet.set_column('B:B', 40)
            summary_sheet.set_column('C:C', 25)
            summary_sheet.set_column('D:D', 40)
            
            summary_sheet.write('A1', f'Purchase Order Report - {po_request_number}', title_format)
            summary_sheet.write('A2', f'Generated: {datetime.now().strftime("%Y-%m-%d %H:%M")}')
            
            row = 4
            summary_sheet.write(row, 0, 'PO Details', header_format)
            summary_sheet.merge_range(row, 0, row, 3, 'Purchase Order Details', header_format)
            
            row += 1
            details = [
                ('PO Reference', po['po_number'] or 'N/A', 'PO Request Number', po_request_number),
                ('System', po['system'] or 'N/A', 'Status', po['po_approval_status'] or 'N/A'),
                ('Distributor', po['distributor_name'] or 'N/A', 'Vendor', po['vendor_name'] or 'N/A'),
                ('Presale Engineer', po['presale_engineer_name'] or 'N/A', 'Project Manager', po['project_manager_name'] or 'N/A'),
                ('Project', po['project_name_actual'] or 'N/A', 'Created Date', str(po['created_at'])[:10] if po['created_at'] else 'N/A'),
                ('Delivery Status', po['po_delivery_status'] or 'N/A', 'Vendor Notes', (po['po_notes_vendor'] or 'N/A')[:50])
            ]
            
            for label1, val1, label2, val2 in details:
                summary_sheet.write(row, 0, label1, label_format)
                summary_sheet.write(row, 1, val1, value_format)
                summary_sheet.write(row, 2, label2, label_format)
                summary_sheet.write(row, 3, val2, value_format)
                row += 1
            
            row += 2
            summary_sheet.merge_range(row, 0, row, 1, 'Delivery Summary', header_format)
            summary_sheet.merge_range(row, 2, row, 3, 'Financial Summary', header_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Total Items', label_format)
            summary_sheet.write(row, 1, total_items, value_format)
            summary_sheet.write(row, 2, 'Subtotal', label_format)
            summary_sheet.write(row, 3, total_value, money_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Delivered', label_format)
            summary_sheet.write(row, 1, delivered_count, value_format)
            summary_sheet.write(row, 2, 'VAT (15%)', label_format)
            summary_sheet.write(row, 3, vat_amount, money_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Partial', label_format)
            summary_sheet.write(row, 1, partial_count, value_format)
            summary_sheet.write(row, 2, 'Grand Total', label_format)
            summary_sheet.write(row, 3, grand_total, money_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Not Delivered', label_format)
            summary_sheet.write(row, 1, not_delivered_count, value_format)
            
            # Sheet 2: PO Items
            if po_items:
                items_data = []
                for item in po_items:
                    # Safely access columns that might not exist
                    try:
                        qty_delivered = item['quantity_delivered'] if 'quantity_delivered' in item.keys() else 0
                    except:
                        qty_delivered = 0
                    try:
                        del_status = item['delivery_status'] if 'delivery_status' in item.keys() else 'Not Delivered'
                    except:
                        del_status = 'Not Delivered'
                    
                    items_data.append({
                        'Item #': item['item_number'] or '',
                        'Part Number': item['part_number'] or '',
                        'Description': item['description'] or '',
                        'Quantity': item['quantity'] or 0,
                        'Unit Price': float(item['unit_price'] or 0),
                        'Total Price': float(item['total_price'] or 0),
                        'Qty Delivered': qty_delivered or 0,
                        'Delivery Status': del_status or 'Not Delivered'
                    })
                items_df = pd.DataFrame(items_data)
                items_df.to_excel(writer, sheet_name='PO Items', index=False, startrow=1)
                
                items_sheet = writer.sheets['PO Items']
                items_sheet.write('A1', 'PO Items List', title_format)
                for col, header in enumerate(items_df.columns):
                    items_sheet.write(1, col, header, header_format)
                    items_sheet.set_column(col, col, 18 if col == 2 else 14)
            
            # Sheet 3: Delivery Notes
            if delivery_notes:
                dn_data = []
                for dn in delivery_notes:
                    dn_data.append({
                        'ID': dn['id'] or '',
                        'Order Date': str(dn['order_date'])[:10] if dn['order_date'] else '',
                        'Expected Delivery': str(dn['expected_delivery'])[:10] if dn['expected_delivery'] else '',
                        'Status': dn['status'] or '',
                        'Notes': dn['notes'] or ''
                    })
                dn_df = pd.DataFrame(dn_data)
                dn_df.to_excel(writer, sheet_name='Delivery Notes', index=False, startrow=1)
                
                dn_sheet = writer.sheets['Delivery Notes']
                dn_sheet.write('A1', 'Delivery Notes', title_format)
                for col, header in enumerate(dn_df.columns):
                    dn_sheet.write(1, col, header, header_format)
                    dn_sheet.set_column(col, col, 20)
            
            # Sheet 4: VAT Invoices
            if vat_invoices:
                vat_data = []
                for inv in vat_invoices:
                    vat_data.append({
                        'Invoice Name': inv['invoice_name'] or '',
                        'File Name': inv['file_name'] or '',
                        'Uploaded By': inv['uploaded_by_username'] or '',
                        'Upload Date': str(inv['uploaded_at'])[:10] if inv['uploaded_at'] else ''
                    })
                vat_df = pd.DataFrame(vat_data)
                vat_df.to_excel(writer, sheet_name='VAT Invoices', index=False, startrow=1)
                
                vat_sheet = writer.sheets['VAT Invoices']
                vat_sheet.write('A1', 'VAT Invoices', title_format)
                for col, header in enumerate(vat_df.columns):
                    vat_sheet.write(1, col, header, header_format)
                    vat_sheet.set_column(col, col, 18)
        
        output.seek(0)
        
        filename = f'PO_Report_{po_request_number}_{datetime.now().strftime("%Y%m%d")}.xlsx'
        
        return send_file(
            output,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=filename
        )
        
    except Exception as e:
        flash(f'Error exporting PO Report: {str(e)}', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))


###################################
# Export Complete PO Profile Report to PowerPoint
@app.route('/export_po_profile_pptx/<po_request_number>')
@login_required
def export_po_profile_pptx(po_request_number):
    """Export comprehensive PO Profile Report to PowerPoint"""
    try:
        from pptx import Presentation
        from pptx.util import Inches, Pt
        from pptx.dml.color import RGBColor
        from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
        from io import BytesIO
        from datetime import datetime
        
        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        
        # Get PO details with joins
        cursor.execute("""
            SELECT 
                po.*,
                COALESCE(rp.project_name, po.project_name) as project_name_actual,
                COALESCE(po.distributor, 'N/A') as distributor_name,
                COALESCE(po.vendor, 'N/A') as vendor_name,
                e.name as presale_engineer_name,
                pm.name as project_manager_name
            FROM purchase_orders po
            LEFT JOIN register_project rp ON po.project_name = rp.project_name
            LEFT JOIN engineers e ON po.presale_engineer = e.username
            LEFT JOIN engineers pm ON po.project_manager = pm.username
            WHERE po.po_request_number = ?
        """, (po_request_number,))
        po = cursor.fetchone()
        
        if not po:
            flash('Purchase Order not found!', 'danger')
            conn.close()
            return redirect(url_for('view_po_status'))
        
        po_number = po['po_number']
        
        # Get PO items
        cursor.execute("""
            SELECT * FROM po_items 
            WHERE po_number = ? 
            ORDER BY item_number ASC
        """, (po_number,))
        po_items = cursor.fetchall()
        
        # Get delivery notes
        cursor.execute("""
            SELECT * FROM purchase_order_monitoring 
            WHERE (po_number = ? OR po_number = ?) AND deleted_at IS NULL
            ORDER BY order_date DESC
        """, (po_number, po_request_number))
        delivery_notes = cursor.fetchall()
        
        # Get VAT invoices
        cursor.execute("""
            SELECT * FROM vat_invoices 
            WHERE po_request_number = ?
            ORDER BY uploaded_at DESC
        """, (po_request_number,))
        vat_invoices = cursor.fetchall()
        
        # Get PO ID for follow-ups and activity log
        po_id = po['id']
        
        # Get follow-ups
        cursor.execute("""
            SELECT * FROM po_follow_ups 
            WHERE po_id = ? 
            ORDER BY follow_up_date DESC, follow_up_time DESC
        """, (po_id,))
        follow_ups = cursor.fetchall()
        
        # Get activity log
        cursor.execute("""
            SELECT * FROM po_activity_log 
            WHERE po_id = ? 
            ORDER BY created_at DESC
        """, (po_id,))
        activity_logs = cursor.fetchall()
        
        conn.close()
        
        # Calculate stats (safely handle missing columns)
        def get_delivery_status(item):
            try:
                return item['delivery_status'] if 'delivery_status' in item.keys() else 'Not Delivered'
            except:
                return 'Not Delivered'
        
        delivered_count = sum(1 for item in po_items if get_delivery_status(item) == 'Delivered')
        partial_count = sum(1 for item in po_items if get_delivery_status(item) == 'Partial')
        not_delivered_count = sum(1 for item in po_items if get_delivery_status(item) == 'Not Delivered')
        total_items = len(po_items)
        
        # Calculate financial summary
        total_value = sum(float(item['total_price'] or 0) for item in po_items)
        vat_amount = total_value * 0.15
        grand_total = total_value + vat_amount
        
        # Create presentation
        prs = Presentation()
        prs.slide_width = Inches(13.333)
        prs.slide_height = Inches(7.5)
        
        slide_layout = prs.slide_layouts[6]  # Blank layout
        
        # Default font name for compatibility
        FONT_NAME = 'Arial'
        
        # Slide 1: Title Slide
        slide = prs.slides.add_slide(slide_layout)
        
        # Title
        title_box = slide.shapes.add_textbox(Inches(0.5), Inches(2.0), Inches(12.333), Inches(1.5))
        tf = title_box.text_frame
        p = tf.paragraphs[0]
        p.text = "Purchase Order Report"
        p.font.size = Pt(44)
        p.font.bold = True
        p.font.name = FONT_NAME
        p.font.color.rgb = RGBColor(102, 126, 234)
        p.alignment = PP_ALIGN.CENTER
        
        # PO Number subtitle
        subtitle_box = slide.shapes.add_textbox(Inches(0.5), Inches(3.5), Inches(12.333), Inches(1))
        tf = subtitle_box.text_frame
        p = tf.paragraphs[0]
        p.text = f"PO Number: {po_number}"
        p.font.size = Pt(28)
        p.font.name = FONT_NAME
        p.font.color.rgb = RGBColor(100, 100, 100)
        p.alignment = PP_ALIGN.CENTER
        
        # Status badge
        status = po['po_approval_status'] or 'Pending'
        status_color = RGBColor(40, 167, 69) if status == 'Approved' else RGBColor(255, 193, 7) if status == 'Pending' else RGBColor(220, 53, 69)
        
        status_box = slide.shapes.add_textbox(Inches(0.5), Inches(4.5), Inches(12.333), Inches(0.6))
        tf = status_box.text_frame
        p = tf.paragraphs[0]
        p.text = f"Status: {status}"
        p.font.size = Pt(20)
        p.font.name = FONT_NAME
        p.font.color.rgb = status_color
        p.alignment = PP_ALIGN.CENTER
        
        # Date
        date_box = slide.shapes.add_textbox(Inches(0.5), Inches(5.2), Inches(12.333), Inches(0.5))
        tf = date_box.text_frame
        p = tf.paragraphs[0]
        p.text = f"Generated: {datetime.now().strftime('%Y-%m-%d')}"
        p.font.size = Pt(14)
        p.font.name = FONT_NAME
        p.font.color.rgb = RGBColor(150, 150, 150)
        p.alignment = PP_ALIGN.CENTER
        
        # Slide 2: PO Details
        slide = prs.slides.add_slide(slide_layout)
        
        title_box = slide.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(12.333), Inches(0.8))
        tf = title_box.text_frame
        p = tf.paragraphs[0]
        p.text = "Purchase Order Details"
        p.font.size = Pt(32)
        p.font.bold = True
        p.font.name = FONT_NAME
        p.font.color.rgb = RGBColor(102, 126, 234)
        
        # Details table
        details_data = [
            ['PO Reference', po['po_number'] or 'N/A', 'PO Request #', po_request_number],
            ['System', po['system'] or 'N/A', 'Project', (po['project_name_actual'] or 'N/A')[:30]],
            ['Distributor', (po['distributor_name'] or 'N/A')[:25], 'Vendor', (po['vendor_name'] or 'N/A')[:25]],
            ['Presale Eng.', (po['presale_engineer_name'] or 'N/A')[:20], 'Project Mgr', (po['project_manager_name'] or 'N/A')[:20]],
            ['Created', str(po['created_at'])[:10] if po['created_at'] else 'N/A', 'Delivery Status', po['po_delivery_status'] or 'N/A']
        ]
        
        table = slide.shapes.add_table(len(details_data), 4, Inches(0.5), Inches(1.3), Inches(12.3), Inches(0.6 * len(details_data))).table
        
        table.columns[0].width = Inches(2.0)
        table.columns[1].width = Inches(4.0)
        table.columns[2].width = Inches(2.0)
        table.columns[3].width = Inches(4.3)
        
        for row_idx, row_data in enumerate(details_data):
            for col_idx, cell_data in enumerate(row_data):
                cell = table.cell(row_idx, col_idx)
                cell.text = str(cell_data)
                
                if col_idx in [0, 2]:
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(102, 126, 234)
                    for para in cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                        para.font.bold = True
                        para.font.size = Pt(11)
                else:
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(245, 248, 255)
                    for para in cell.text_frame.paragraphs:
                        para.font.size = Pt(11)
                
                cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        # Slide 3: Summary Dashboard
        slide = prs.slides.add_slide(slide_layout)
        
        title_box = slide.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(12.333), Inches(0.8))
        tf = title_box.text_frame
        p = tf.paragraphs[0]
        p.text = "Summary Dashboard"
        p.font.size = Pt(32)
        p.font.bold = True
        p.font.name = FONT_NAME
        p.font.color.rgb = RGBColor(102, 126, 234)
        
        # Delivery Summary Cards
        delivery_cards = [
            ('Total Items', total_items, RGBColor(102, 126, 234)),
            ('Delivered', delivered_count, RGBColor(40, 167, 69)),
            ('Partial', partial_count, RGBColor(255, 193, 7)),
            ('Not Delivered', not_delivered_count, RGBColor(220, 53, 69))
        ]
        
        card_width = Inches(2.8)
        card_height = Inches(1.5)
        start_x = Inches(0.5)
        start_y = Inches(1.5)
        gap = Inches(0.3)
        
        for i, (label, value, color) in enumerate(delivery_cards):
            x = start_x + (i * (card_width + gap))
            shape = slide.shapes.add_shape(1, x, start_y, card_width, card_height)
            shape.fill.solid()
            shape.fill.fore_color.rgb = color
            shape.line.fill.background()
            
            tf = shape.text_frame
            tf.word_wrap = True
            p = tf.paragraphs[0]
            p.text = str(value)
            p.font.size = Pt(42)
            p.font.bold = True
            p.font.color.rgb = RGBColor(255, 255, 255)
            p.alignment = PP_ALIGN.CENTER
            
            p2 = tf.add_paragraph()
            p2.text = label
            p2.font.size = Pt(14)
            p2.font.color.rgb = RGBColor(255, 255, 255)
            p2.alignment = PP_ALIGN.CENTER
        
        # Financial Summary Cards
        fin_cards = [
            ('Subtotal', f'{total_value:,.2f} SAR', RGBColor(59, 89, 152)),
            ('VAT (15%)', f'{vat_amount:,.2f} SAR', RGBColor(111, 66, 193)),
            ('Grand Total', f'{grand_total:,.2f} SAR', RGBColor(23, 162, 184))
        ]
        
        card_width = Inches(3.8)
        start_x = Inches(0.7)
        start_y = Inches(3.5)
        gap = Inches(0.3)
        
        for i, (label, value, color) in enumerate(fin_cards):
            x = start_x + (i * (card_width + gap))
            shape = slide.shapes.add_shape(1, x, start_y, card_width, card_height)
            shape.fill.solid()
            shape.fill.fore_color.rgb = color
            shape.line.fill.background()
            
            tf = shape.text_frame
            tf.word_wrap = True
            p = tf.paragraphs[0]
            p.text = value
            p.font.size = Pt(28)
            p.font.bold = True
            p.font.color.rgb = RGBColor(255, 255, 255)
            p.alignment = PP_ALIGN.CENTER
            
            p2 = tf.add_paragraph()
            p2.text = label
            p2.font.size = Pt(14)
            p2.font.color.rgb = RGBColor(255, 255, 255)
            p2.alignment = PP_ALIGN.CENTER
        
        # Slide 4+: PO Items (6 per slide)
        items_per_slide = 6
        for slide_start in range(0, len(po_items), items_per_slide):
            slide_items = list(po_items)[slide_start:slide_start + items_per_slide]
            
            slide = prs.slides.add_slide(slide_layout)
            
            title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.6))
            tf = title_box.text_frame
            p = tf.paragraphs[0]
            p.text = f"PO Items ({slide_start + 1}-{min(slide_start + items_per_slide, len(po_items))} of {len(po_items)})"
            p.font.size = Pt(28)
            p.font.bold = True
            p.font.name = FONT_NAME
            p.font.color.rgb = RGBColor(102, 126, 234)
            
            # Items table with Delivered Qty and Not Delivered columns
            rows = len(slide_items) + 1
            cols = 9
            row_height = Inches(0.7)
            table = slide.shapes.add_table(rows, cols, Inches(0.2), Inches(1.0), Inches(12.9), row_height * rows).table
            
            table.columns[0].width = Inches(0.4)
            table.columns[1].width = Inches(1.3)
            table.columns[2].width = Inches(3.2)
            table.columns[3].width = Inches(0.8)
            table.columns[4].width = Inches(1.3)
            table.columns[5].width = Inches(1.4)
            table.columns[6].width = Inches(1.0)
            table.columns[7].width = Inches(1.0)
            table.columns[8].width = Inches(1.7)
            
            headers = ['#', 'Part Number', 'Description', 'Qty', 'Unit Price', 'Total', 'Delivered', 'Remaining', 'Status']
            for col, header in enumerate(headers):
                cell = table.cell(0, col)
                cell.text = header
                cell.fill.solid()
                cell.fill.fore_color.rgb = RGBColor(59, 89, 152)
                cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                cell.text_frame.paragraphs[0].font.bold = True
                cell.text_frame.paragraphs[0].font.size = Pt(9)
                cell.text_frame.paragraphs[0].font.name = FONT_NAME
                cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                cell.vertical_anchor = MSO_ANCHOR.MIDDLE
            
            for i, item in enumerate(slide_items, 1):
                row_idx = i
                
                # Get quantity values
                total_qty = int(item['quantity'] or 0)
                try:
                    delivered_qty = int(item['quantity_delivered'] or 0)
                except:
                    delivered_qty = 0
                remaining_qty = total_qty - delivered_qty
                if remaining_qty < 0:
                    remaining_qty = 0
                
                table.cell(row_idx, 0).text = str(slide_start + i)
                table.cell(row_idx, 1).text = str(item['part_number'] or '')[:12]
                table.cell(row_idx, 2).text = str(item['description'] or '')[:35]
                table.cell(row_idx, 3).text = str(total_qty)
                table.cell(row_idx, 4).text = f"{float(item['unit_price'] or 0):,.2f}"
                table.cell(row_idx, 5).text = f"{float(item['total_price'] or 0):,.2f}"
                
                # Delivered Qty column
                delivered_cell = table.cell(row_idx, 6)
                delivered_cell.text = str(delivered_qty)
                delivered_cell.fill.solid()
                if delivered_qty >= total_qty:
                    delivered_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                    for para in delivered_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                elif delivered_qty > 0:
                    delivered_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                else:
                    delivered_cell.fill.fore_color.rgb = RGBColor(245, 248, 255)
                
                # Remaining (Not Delivered) column
                remaining_cell = table.cell(row_idx, 7)
                remaining_cell.text = str(remaining_qty)
                remaining_cell.fill.solid()
                if remaining_qty == 0:
                    remaining_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                    for para in remaining_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                elif remaining_qty < total_qty:
                    remaining_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                else:
                    remaining_cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                    for para in remaining_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                
                # Delivery Status column
                delivery_status = get_delivery_status(item)
                status_cell = table.cell(row_idx, 8)
                status_cell.text = delivery_status
                
                if delivery_status == 'Delivered':
                    status_cell.fill.solid()
                    status_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                    for para in status_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                elif delivery_status == 'Partial':
                    status_cell.fill.solid()
                    status_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                else:
                    status_cell.fill.solid()
                    status_cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                    for para in status_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                
                for col in range(6):  # Only style first 6 columns (not delivery-related)
                    cell = table.cell(row_idx, col)
                    if i % 2 == 0:
                        cell.fill.solid()
                        cell.fill.fore_color.rgb = RGBColor(230, 240, 255)
                    else:
                        cell.fill.solid()
                        cell.fill.fore_color.rgb = RGBColor(245, 248, 255)
                
                for col in range(cols):
                    cell = table.cell(row_idx, col)
                    for para in cell.text_frame.paragraphs:
                        para.font.size = Pt(9)
                        para.font.name = FONT_NAME
                        para.alignment = PP_ALIGN.CENTER
                    cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        # Get base URL for download links
        import os
        base_url = os.environ.get('REPLIT_DEV_DOMAIN', '')
        if base_url:
            base_url = f"https://{base_url}"
        
        # Slide: Delivery Notes (if any)
        if delivery_notes:
            dn_per_slide = 8
            for slide_start in range(0, len(delivery_notes), dn_per_slide):
                slide_dns = list(delivery_notes)[slide_start:slide_start + dn_per_slide]
                
                slide = prs.slides.add_slide(slide_layout)
                
                title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.6))
                tf = title_box.text_frame
                p = tf.paragraphs[0]
                p.text = f"Delivery Notes ({slide_start + 1}-{min(slide_start + dn_per_slide, len(delivery_notes))} of {len(delivery_notes)})"
                p.font.size = Pt(28)
                p.font.bold = True
                p.font.name = FONT_NAME
                p.font.color.rgb = RGBColor(102, 126, 234)
                
                # Delivery Notes table
                dn_rows = len(slide_dns) + 1
                dn_cols = 6
                dn_row_height = Inches(0.6)
                dn_table = slide.shapes.add_table(dn_rows, dn_cols, Inches(0.3), Inches(1.0), Inches(12.7), dn_row_height * dn_rows).table
                
                dn_table.columns[0].width = Inches(0.8)
                dn_table.columns[1].width = Inches(2.0)
                dn_table.columns[2].width = Inches(2.0)
                dn_table.columns[3].width = Inches(1.6)
                dn_table.columns[4].width = Inches(3.5)
                dn_table.columns[5].width = Inches(2.8)
                
                dn_headers = ['ID', 'Order Date', 'Expected Delivery', 'Status', 'Notes', 'Download']
                for col, header in enumerate(dn_headers):
                    cell = dn_table.cell(0, col)
                    cell.text = header
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(23, 162, 184)
                    cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                    cell.text_frame.paragraphs[0].font.bold = True
                    cell.text_frame.paragraphs[0].font.size = Pt(11)
                    cell.text_frame.paragraphs[0].font.name = FONT_NAME
                    cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                    cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                
                for i, dn in enumerate(slide_dns, 1):
                    row_idx = i
                    dn_id = dn['id'] or ''
                    dn_table.cell(row_idx, 0).text = str(dn_id)
                    dn_table.cell(row_idx, 1).text = str(dn['order_date'] or '')[:10] if dn['order_date'] else ''
                    dn_table.cell(row_idx, 2).text = str(dn['expected_delivery'] or '')[:10] if dn['expected_delivery'] else ''
                    
                    status_val = dn['status'] or ''
                    status_cell = dn_table.cell(row_idx, 3)
                    status_cell.text = status_val
                    if status_val.lower() == 'delivered':
                        status_cell.fill.solid()
                        status_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                        for para in status_cell.text_frame.paragraphs:
                            para.font.color.rgb = RGBColor(255, 255, 255)
                    elif status_val.lower() == 'pending':
                        status_cell.fill.solid()
                        status_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                    else:
                        status_cell.fill.solid()
                        status_cell.fill.fore_color.rgb = RGBColor(108, 117, 125)
                        for para in status_cell.text_frame.paragraphs:
                            para.font.color.rgb = RGBColor(255, 255, 255)
                    
                    dn_table.cell(row_idx, 4).text = str(dn['notes'] or '')[:40]
                    
                    # Add download link
                    download_cell = dn_table.cell(row_idx, 5)
                    download_cell.text = "Download File"
                    download_cell.fill.solid()
                    download_cell.fill.fore_color.rgb = RGBColor(0, 123, 255)
                    for para in download_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                        para.font.bold = True
                        para.font.size = Pt(9)
                        para.font.name = FONT_NAME
                        para.alignment = PP_ALIGN.CENTER
                        # Add hyperlink
                        if base_url and dn_id:
                            run = para.runs[0] if para.runs else para.add_run()
                            run.hyperlink.address = f"{base_url}/download_delivery_note/{dn_id}"
                    download_cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                    
                    for col in range(dn_cols - 1):  # Skip last column (download)
                        cell = dn_table.cell(row_idx, col)
                        if col != 3:
                            if i % 2 == 0:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(230, 245, 255)
                            else:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(245, 252, 255)
                        for para in cell.text_frame.paragraphs:
                            para.font.size = Pt(10)
                            para.font.name = FONT_NAME
                            para.alignment = PP_ALIGN.CENTER
                        cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        # Slide: VAT Invoices (if any)
        if vat_invoices:
            vat_per_slide = 8
            for slide_start in range(0, len(vat_invoices), vat_per_slide):
                slide_vats = list(vat_invoices)[slide_start:slide_start + vat_per_slide]
                
                slide = prs.slides.add_slide(slide_layout)
                
                title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.6))
                tf = title_box.text_frame
                p = tf.paragraphs[0]
                p.text = f"VAT Invoices ({slide_start + 1}-{min(slide_start + vat_per_slide, len(vat_invoices))} of {len(vat_invoices)})"
                p.font.size = Pt(28)
                p.font.bold = True
                p.font.name = FONT_NAME
                p.font.color.rgb = RGBColor(111, 66, 193)
                
                # VAT Invoices table
                vat_rows = len(slide_vats) + 1
                vat_cols = 5
                vat_row_height = Inches(0.6)
                vat_table = slide.shapes.add_table(vat_rows, vat_cols, Inches(0.3), Inches(1.0), Inches(12.7), vat_row_height * vat_rows).table
                
                vat_table.columns[0].width = Inches(3.0)
                vat_table.columns[1].width = Inches(3.0)
                vat_table.columns[2].width = Inches(2.0)
                vat_table.columns[3].width = Inches(2.0)
                vat_table.columns[4].width = Inches(2.7)
                
                vat_headers = ['Invoice Name', 'File Name', 'Uploaded By', 'Upload Date', 'Download']
                for col, header in enumerate(vat_headers):
                    cell = vat_table.cell(0, col)
                    cell.text = header
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(111, 66, 193)
                    cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                    cell.text_frame.paragraphs[0].font.bold = True
                    cell.text_frame.paragraphs[0].font.size = Pt(11)
                    cell.text_frame.paragraphs[0].font.name = FONT_NAME
                    cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                    cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                
                for i, inv in enumerate(slide_vats, 1):
                    row_idx = i
                    inv_id = inv['id'] or ''
                    vat_table.cell(row_idx, 0).text = str(inv['invoice_name'] or '')[:25]
                    vat_table.cell(row_idx, 1).text = str(inv['file_name'] or '')[:25]
                    vat_table.cell(row_idx, 2).text = str(inv['uploaded_by_username'] or '')
                    vat_table.cell(row_idx, 3).text = str(inv['uploaded_at'] or '')[:10] if inv['uploaded_at'] else ''
                    
                    # Add download link
                    download_cell = vat_table.cell(row_idx, 4)
                    download_cell.text = "Download Invoice"
                    download_cell.fill.solid()
                    download_cell.fill.fore_color.rgb = RGBColor(111, 66, 193)
                    for para in download_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                        para.font.bold = True
                        para.font.size = Pt(9)
                        para.font.name = FONT_NAME
                        para.alignment = PP_ALIGN.CENTER
                        # Add hyperlink
                        if base_url and inv_id:
                            run = para.runs[0] if para.runs else para.add_run()
                            run.hyperlink.address = f"{base_url}/download_vat_invoice_file/{inv_id}"
                    download_cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                    
                    for col in range(vat_cols - 1):  # Skip last column (download)
                        cell = vat_table.cell(row_idx, col)
                        if i % 2 == 0:
                            cell.fill.solid()
                            cell.fill.fore_color.rgb = RGBColor(240, 230, 255)
                        else:
                            cell.fill.solid()
                            cell.fill.fore_color.rgb = RGBColor(250, 245, 255)
                        for para in cell.text_frame.paragraphs:
                            para.font.size = Pt(10)
                            para.font.name = FONT_NAME
                            para.alignment = PP_ALIGN.CENTER
                        cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        # Slide: Follow-ups (if any)
        if follow_ups:
            fu_per_slide = 6
            for slide_start in range(0, len(follow_ups), fu_per_slide):
                slide_fus = list(follow_ups)[slide_start:slide_start + fu_per_slide]
                
                slide = prs.slides.add_slide(slide_layout)
                
                title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.6))
                tf = title_box.text_frame
                p = tf.paragraphs[0]
                p.text = f"Follow-ups ({slide_start + 1}-{min(slide_start + fu_per_slide, len(follow_ups))} of {len(follow_ups)})"
                p.font.size = Pt(28)
                p.font.bold = True
                p.font.name = FONT_NAME
                p.font.color.rgb = RGBColor(40, 167, 69)
                
                # Follow-ups table
                fu_rows = len(slide_fus) + 1
                fu_cols = 7
                fu_row_height = Inches(0.8)
                fu_table = slide.shapes.add_table(fu_rows, fu_cols, Inches(0.2), Inches(1.0), Inches(12.9), fu_row_height * fu_rows).table
                
                fu_table.columns[0].width = Inches(1.5)
                fu_table.columns[1].width = Inches(1.5)
                fu_table.columns[2].width = Inches(1.5)
                fu_table.columns[3].width = Inches(1.0)
                fu_table.columns[4].width = Inches(3.0)
                fu_table.columns[5].width = Inches(1.2)
                fu_table.columns[6].width = Inches(2.2)
                
                fu_headers = ['Date', 'Type', 'Contact', 'Priority', 'Subject', 'Status', 'Created By']
                for col, header in enumerate(fu_headers):
                    cell = fu_table.cell(0, col)
                    cell.text = header
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                    cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                    cell.text_frame.paragraphs[0].font.bold = True
                    cell.text_frame.paragraphs[0].font.size = Pt(10)
                    cell.text_frame.paragraphs[0].font.name = FONT_NAME
                    cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                    cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                
                for i, fu in enumerate(slide_fus, 1):
                    row_idx = i
                    fu_date = str(fu['follow_up_date'] or '')[:10] if fu['follow_up_date'] else ''
                    fu_time = str(fu['follow_up_time'] or '')[:5] if fu['follow_up_time'] else ''
                    fu_table.cell(row_idx, 0).text = f"{fu_date} {fu_time}".strip()
                    fu_table.cell(row_idx, 1).text = str(fu['follow_up_type'] or '')[:15]
                    fu_table.cell(row_idx, 2).text = str(fu['contact_type'] or '')[:15]
                    
                    priority_val = str(fu['priority'] or 'Normal')
                    priority_cell = fu_table.cell(row_idx, 3)
                    priority_cell.text = priority_val
                    if priority_val.lower() == 'high':
                        priority_cell.fill.solid()
                        priority_cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                        for para in priority_cell.text_frame.paragraphs:
                            para.font.color.rgb = RGBColor(255, 255, 255)
                    elif priority_val.lower() == 'normal':
                        priority_cell.fill.solid()
                        priority_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                    else:
                        priority_cell.fill.solid()
                        priority_cell.fill.fore_color.rgb = RGBColor(108, 117, 125)
                    
                    fu_table.cell(row_idx, 4).text = str(fu['subject'] or '')[:40]
                    
                    status_val = str(fu['status'] or 'Pending')
                    status_cell = fu_table.cell(row_idx, 5)
                    status_cell.text = status_val
                    if status_val.lower() == 'completed':
                        status_cell.fill.solid()
                        status_cell.fill.fore_color.rgb = RGBColor(40, 167, 69)
                        for para in status_cell.text_frame.paragraphs:
                            para.font.color.rgb = RGBColor(255, 255, 255)
                    else:
                        status_cell.fill.solid()
                        status_cell.fill.fore_color.rgb = RGBColor(255, 193, 7)
                    
                    fu_table.cell(row_idx, 6).text = str(fu['created_by'] or '')[:20]
                    
                    for col in range(fu_cols):
                        cell = fu_table.cell(row_idx, col)
                        if col not in [3, 5]:  # Skip priority and status (already styled)
                            if i % 2 == 0:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(220, 255, 220)
                            else:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(240, 255, 240)
                        for para in cell.text_frame.paragraphs:
                            para.font.size = Pt(9)
                            para.font.name = FONT_NAME
                            para.alignment = PP_ALIGN.CENTER
                        cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        # Slide: Activity Log (if any)
        if activity_logs:
            al_per_slide = 8
            for slide_start in range(0, len(activity_logs), al_per_slide):
                slide_als = list(activity_logs)[slide_start:slide_start + al_per_slide]
                
                slide = prs.slides.add_slide(slide_layout)
                
                title_box = slide.shapes.add_textbox(Inches(0.3), Inches(0.2), Inches(12.733), Inches(0.6))
                tf = title_box.text_frame
                p = tf.paragraphs[0]
                p.text = f"Activity Log ({slide_start + 1}-{min(slide_start + al_per_slide, len(activity_logs))} of {len(activity_logs)})"
                p.font.size = Pt(28)
                p.font.bold = True
                p.font.name = FONT_NAME
                p.font.color.rgb = RGBColor(220, 53, 69)
                
                # Activity Log table
                al_rows = len(slide_als) + 1
                al_cols = 5
                al_row_height = Inches(0.7)
                al_table = slide.shapes.add_table(al_rows, al_cols, Inches(0.2), Inches(1.0), Inches(12.9), al_row_height * al_rows).table
                
                al_table.columns[0].width = Inches(2.0)
                al_table.columns[1].width = Inches(1.8)
                al_table.columns[2].width = Inches(1.5)
                al_table.columns[3].width = Inches(5.3)
                al_table.columns[4].width = Inches(2.3)
                
                al_headers = ['Date & Time', 'Activity Type', 'Contact Type', 'Description', 'Logged By']
                for col, header in enumerate(al_headers):
                    cell = al_table.cell(0, col)
                    cell.text = header
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(220, 53, 69)
                    cell.text_frame.paragraphs[0].font.color.rgb = RGBColor(255, 255, 255)
                    cell.text_frame.paragraphs[0].font.bold = True
                    cell.text_frame.paragraphs[0].font.size = Pt(10)
                    cell.text_frame.paragraphs[0].font.name = FONT_NAME
                    cell.text_frame.paragraphs[0].alignment = PP_ALIGN.CENTER
                    cell.vertical_anchor = MSO_ANCHOR.MIDDLE
                
                for i, al in enumerate(slide_als, 1):
                    row_idx = i
                    al_datetime = str(al['created_at'] or '')[:16] if al['created_at'] else ''
                    al_table.cell(row_idx, 0).text = al_datetime
                    
                    activity_type = str(al['activity_type'] or '')
                    type_cell = al_table.cell(row_idx, 1)
                    type_cell.text = activity_type[:20]
                    type_cell.fill.solid()
                    type_cell.fill.fore_color.rgb = RGBColor(111, 66, 193)
                    for para in type_cell.text_frame.paragraphs:
                        para.font.color.rgb = RGBColor(255, 255, 255)
                    
                    al_table.cell(row_idx, 2).text = str(al['contact_type'] or '')[:15]
                    al_table.cell(row_idx, 3).text = str(al['activity_description'] or '')[:60]
                    al_table.cell(row_idx, 4).text = str(al['created_by'] or '')[:20]
                    
                    for col in range(al_cols):
                        cell = al_table.cell(row_idx, col)
                        if col != 1:  # Skip activity type (already styled)
                            if i % 2 == 0:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(255, 220, 220)
                            else:
                                cell.fill.solid()
                                cell.fill.fore_color.rgb = RGBColor(255, 240, 240)
                        for para in cell.text_frame.paragraphs:
                            para.font.size = Pt(9)
                            para.font.name = FONT_NAME
                            para.alignment = PP_ALIGN.CENTER
                        cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        # Save to BytesIO
        output = BytesIO()
        prs.save(output)
        output.seek(0)
        
        filename = f'PO_Report_{po_request_number}_{datetime.now().strftime("%Y%m%d")}.pptx'
        
        return send_file(
            output,
            mimetype='application/vnd.openxmlformats-officedocument.presentationml.presentation',
            as_attachment=True,
            download_name=filename
        )
        
    except Exception as e:
        flash(f'Error exporting PO Report: {str(e)}', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))


@app.route('/upload_vat_invoice/<po_request_number>', methods=['POST'])
@login_required
def upload_vat_invoice(po_request_number):
    """Upload VAT Invoice PDF for purchase order"""
    if 'vat_invoice' not in request.files:
        flash('No file uploaded!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    file = request.files['vat_invoice']
    
    if file.filename == '':
        flash('No file selected!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    if not file.filename.endswith('.pdf'):
        flash('Invalid file format! Please upload a PDF file', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    invoice_name = request.form.get('invoice_name', '').strip()
    if not invoice_name:
        invoice_name = f"VAT Invoice - {file.filename}"
    
    try:
        pdf_data = file.read()
        file_size = len(pdf_data)
        
        conn = sqlite3.connect('ProjectStatus.db')
        cursor = conn.cursor()
        
        cursor.execute("""
            INSERT INTO vat_invoices 
            (po_request_number, invoice_name, file_name, file_blob, file_size, uploaded_by_user_id, uploaded_by_username)
            VALUES (?, ?, ?, ?, ?, ?, ?)
        """, (po_request_number, invoice_name, file.filename, pdf_data, file_size, 
              session.get('user_id'), session.get('username')))
        
        conn.commit()
        conn.close()
        
        flash('VAT Invoice uploaded successfully!', 'success')
    except Exception as e:
        flash(f'Error uploading VAT Invoice: {str(e)}', 'danger')
    
    return redirect(url_for('po_profile', po_request_number=po_request_number))


@app.route('/download_vat_invoice/<po_request_number>')
@login_required
def download_vat_invoice(po_request_number):
    """Download VAT Invoice PDF"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    cursor.execute("SELECT vat_invoice_pdf, po_number FROM purchase_orders WHERE po_request_number = ?", (po_request_number,))
    result = cursor.fetchone()
    conn.close()
    
    if result and result['vat_invoice_pdf']:
        from io import BytesIO
        output = BytesIO(result['vat_invoice_pdf'])
        po_num = result['po_number'] or po_request_number
        return send_file(
            output,
            mimetype='application/pdf',
            as_attachment=True,
            download_name=f'VAT_Invoice_{po_num}.pdf'
        )
    else:
        flash('VAT Invoice not found!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))


@app.route('/add_po_delivery_note/<po_request_number>', methods=['POST'])
@login_required
def add_po_delivery_note(po_request_number):
    """Add delivery note with optional PDF"""
    status = request.form.get('status', '').strip()
    expected_delivery = request.form.get('expected_delivery', '').strip()
    notes = request.form.get('notes', '').strip()
    
    if not status:
        flash('Delivery status is required!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    delivery_note_pdf = None
    if 'delivery_note_pdf' in request.files:
        file = request.files['delivery_note_pdf']
        if file and file.filename and file.filename.endswith('.pdf'):
            delivery_note_pdf = file.read()
    
    try:
        from datetime import datetime
        conn = sqlite3.connect('ProjectStatus.db')
        cursor = conn.cursor()
        
        cursor.execute("SELECT po_number FROM purchase_orders WHERE po_request_number = ?", (po_request_number,))
        result = cursor.fetchone()
        po_number = result[0] if result and result[0] else po_request_number
        
        cursor.execute("""
            INSERT INTO purchase_order_monitoring 
            (po_number, status, expected_delivery, notes, delivery_note, registration_date, order_date)
            VALUES (?, ?, ?, ?, ?, ?, ?)
        """, (po_number, status, expected_delivery or None, notes, delivery_note_pdf,
              datetime.now().strftime('%Y-%m-%d %H:%M:%S'), datetime.now().strftime('%Y-%m-%d')))
        
        conn.commit()
        conn.close()
        
        flash('Delivery note added successfully!', 'success')
    except Exception as e:
        flash(f'Error adding delivery note: {str(e)}', 'danger')
    
    return redirect(url_for('po_profile', po_request_number=po_request_number))


