@app.route('/implementation/<int:id>/export_materials')
@login_required
@permission_required('manage_implementation')
def implementation_export_materials(id):
    import io
    import xlsxwriter
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    c.execute("""
        SELECT ip.*, rp.project_name, COALESCE(eu.name, con.name, cons.name, 'N/A') as client_name
        FROM implementation_projects ip
        JOIN register_project rp ON ip.register_project_id = rp.id
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors con ON rp.contractor_id = con.id
        LEFT JOIN consultants cons ON rp.consultant_id = cons.id
        WHERE ip.id = ?
    """, (id,))
    project = c.fetchone()
    if not project:
        flash('Project not found.', 'danger')
        conn.close()
        return redirect(url_for('implementation_dashboard'))
    
    c.execute("""
        SELECT po.po_number, po.po_request_number, po.vendor, po.distributor, po.system as po_system
        FROM purchase_orders po
        WHERE po.project_name = ?
    """, (project['project_name'],))
    pos = c.fetchall()
    po_numbers = [p['po_number'] for p in pos if p['po_number']]
    po_info = {p['po_number']: dict(p) for p in pos if p['po_number']}
    
    material_items = []
    if po_numbers:
        placeholders = ','.join('?' * len(po_numbers))
        c.execute(f"""
            SELECT * FROM po_items WHERE po_number IN ({placeholders})
            ORDER BY po_number, item_number
        """, po_numbers)
        material_items = [dict(row) for row in c.fetchall()]
    
    conn.close()
    
    output = io.BytesIO()
    workbook = xlsxwriter.Workbook(output, {'in_memory': True})
    
    title_format = workbook.add_format({
        'bold': True, 'font_size': 16, 'font_color': '#FFFFFF',
        'bg_color': '#00b894', 'border': 0, 'align': 'left', 'valign': 'vcenter'
    })
    subtitle_format = workbook.add_format({
        'bold': True, 'font_size': 11, 'font_color': '#2c3e50',
        'bottom': 1, 'bottom_color': '#00b894'
    })
    header_format = workbook.add_format({
        'bold': True, 'font_size': 10, 'font_color': '#FFFFFF',
        'bg_color': '#00b894', 'border': 1, 'border_color': '#CCCCCC',
        'align': 'center', 'valign': 'vcenter', 'text_wrap': True
    })
    cell_format = workbook.add_format({
        'font_size': 10, 'border': 1, 'border_color': '#E0E0E0',
        'valign': 'vcenter', 'text_wrap': True
    })
    number_format = workbook.add_format({
        'font_size': 10, 'border': 1, 'border_color': '#E0E0E0',
        'valign': 'vcenter', 'num_format': '#,##0.00', 'align': 'right'
    })
    qty_format = workbook.add_format({
        'font_size': 10, 'border': 1, 'border_color': '#E0E0E0',
        'valign': 'vcenter', 'num_format': '#,##0', 'align': 'center'
    })
    delivered_format = workbook.add_format({
        'bold': True, 'font_size': 10, 'font_color': '#FFFFFF',
        'bg_color': '#28a745', 'border': 1, 'border_color': '#E0E0E0',
        'align': 'center', 'valign': 'vcenter'
    })
    not_delivered_format = workbook.add_format({
        'bold': True, 'font_size': 10, 'font_color': '#FFFFFF',
        'bg_color': '#dc3545', 'border': 1, 'border_color': '#E0E0E0',
        'align': 'center', 'valign': 'vcenter'
    })
    partial_format = workbook.add_format({
        'bold': True, 'font_size': 10, 'font_color': '#FFFFFF',
        'bg_color': '#17a2b8', 'border': 1, 'border_color': '#E0E0E0',
        'align': 'center', 'valign': 'vcenter'
    })
    total_label_format = workbook.add_format({
        'bold': True, 'font_size': 11, 'font_color': '#FFFFFF',
        'bg_color': '#2c3e50', 'border': 1, 'align': 'right', 'valign': 'vcenter'
    })
    total_value_format = workbook.add_format({
        'bold': True, 'font_size': 11, 'font_color': '#FFFFFF',
        'bg_color': '#2c3e50', 'border': 1, 'num_format': '#,##0.00',
        'align': 'right', 'valign': 'vcenter'
    })
    summary_label_format = workbook.add_format({
        'bold': True, 'font_size': 10, 'border': 1, 'bg_color': '#f8f9fa',
        'align': 'right', 'valign': 'vcenter'
    })
    summary_value_format = workbook.add_format({
        'bold': True, 'font_size': 10, 'border': 1, 'bg_color': '#f8f9fa',
        'align': 'center', 'valign': 'vcenter'
    })
    
    sheet = workbook.add_worksheet('Material Status')
    
    sheet.set_landscape()
    sheet.set_paper(9)
    sheet.set_margins(0.4, 0.4, 0.6, 0.4)
    sheet.set_header('&C&"Arial,Bold"&12Material Status Report')
    sheet.set_footer('&L&D &T&R&P of &N')
    
    sheet.merge_range('A1:I1', f'  Material Status - {project["project_name"]}', title_format)
    sheet.set_row(0, 35)
    
    sheet.write('A3', f'Client: {project["client_name"]}', subtitle_format)
    sheet.merge_range('A3:D3', f'Client: {project["client_name"]}', subtitle_format)
    sheet.merge_range('F3:I3', f'Generated: {__import__("datetime").datetime.now().strftime("%Y-%m-%d %H:%M")}', subtitle_format)
    
    delivered_count = sum(1 for i in material_items if i.get('delivery_status') == 'Delivered')
    partial_count = sum(1 for i in material_items if i.get('delivery_status') == 'Partially Delivered')
    not_delivered_count = sum(1 for i in material_items if i.get('delivery_status') not in ('Delivered', 'Partially Delivered'))
    total_value = sum(float(i.get('total_price') or 0) for i in material_items)
    
    sheet.write('A5', 'Total Items:', summary_label_format)
    sheet.write('B5', len(material_items), summary_value_format)
    sheet.write('C5', 'Delivered:', summary_label_format)
    sheet.write('D5', delivered_count, summary_value_format)
    sheet.write('E5', 'Partial:', summary_label_format)
    sheet.write('F5', partial_count, summary_value_format)
    sheet.write('G5', 'Not Delivered:', summary_label_format)
    sheet.write('H5', not_delivered_count, summary_value_format)
    
    row = 7
    headers = ['#', 'PO Number', 'Part Number', 'Description', 'Qty', 'Unit Price (SAR)', 'Total (SAR)', 'Qty Delivered', 'Delivery Status']
    col_widths = [5, 16, 20, 40, 8, 15, 15, 13, 15]
    for col, (header, width) in enumerate(zip(headers, col_widths)):
        sheet.write(row, col, header, header_format)
        sheet.set_column(col, col, width)
    
    row = 8
    for idx, item in enumerate(material_items, 1):
        sheet.write(row, 0, idx, qty_format)
        sheet.write(row, 1, item.get('po_number', ''), cell_format)
        sheet.write(row, 2, item.get('part_number', '') or '', cell_format)
        sheet.write(row, 3, item.get('description', '') or '', cell_format)
        sheet.write(row, 4, float(item.get('quantity') or 0), qty_format)
        sheet.write(row, 5, float(item.get('unit_price') or 0), number_format)
        sheet.write(row, 6, float(item.get('total_price') or 0), number_format)
        sheet.write(row, 7, float(item.get('quantity_delivered') or 0), qty_format)
        
        status = item.get('delivery_status', 'Not Delivered') or 'Not Delivered'
        if status == 'Delivered':
            fmt = delivered_format
        elif status == 'Partially Delivered':
            fmt = partial_format
        else:
            fmt = not_delivered_format
        sheet.write(row, 8, status, fmt)
        row += 1
    
    sheet.merge_range(row, 0, row, 5, 'TOTAL', total_label_format)
    sheet.write(row, 6, total_value, total_value_format)
    sheet.write(row, 7, '', total_label_format)
    sheet.write(row, 8, '', total_label_format)
    
    sheet.autofilter(7, 0, row - 1, 8)
    
    workbook.close()
    output.seek(0)
    
    safe_name = project['project_name'].replace(' ', '_')[:30]
    filename = f'Material_Status_{safe_name}.xlsx'
    
    return send_file(output, mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                     as_attachment=True, download_name=filename)




# ─────────────────────────────────────────────────────────────────────────────
# QUOTATION PRICE CHECKER
# ─────────────────────────────────────────────────────────────────────────────

@app.route('/quotation_price_checker', methods=['GET', 'POST'])
@login_required
@permission_required('view_products')
def quotation_price_checker():
    import io, json
    import pandas as pd

    results = None
    stats = None
    results_json = None
    column_info = None
    header_row = 1
    pn_column = ''
    price_column = ''

    PN_CANDIDATES   = ['item code', 'part number', 'part no', 'p/n', 'pn', 'item no',
                       'part#', 'part #', 'model', 'sku', 'material code', 'product code']
    PRICE_CANDIDATES = ['unit cost', 'unit price', 'price', 'cost', 'rate',
                        'net price', 'net', 'sale price', 'list price']
    QTY_CANDIDATES  = ['qty', 'quantity', 'qnty', 'no of units', 'units']
    DESC_CANDIDATES = ['item description', 'description', 'desc', 'item name', 'name', 'product name']
    UOM_CANDIDATES  = ['uom', 'unit', 'u/m', 'unit of measure']
    TOTAL_CANDIDATES= ['total', 'total amount', 'total cost', 'amount', 'line total']
    SN_CANDIDATES   = ['s.#', 's#', 'sn', 'no.', 'sr no', 'sr.no', '#', 'seq']

    if request.method == 'POST':
        file = request.files.get('excel_file')
        header_row = int(request.form.get('header_row', 1))
        pn_column   = request.form.get('pn_column', '').strip()
        price_column = request.form.get('price_column', '').strip()

        if not file or file.filename == '':
            flash('Please select an Excel file.', 'danger')
            return render_template('quotation_price_checker.html',
                                   results=None, stats=None, results_json=None,
                                   column_info=None, header_row=header_row,
                                   pn_column=pn_column, price_column=price_column)

        orig_filename = file.filename
        filename_lower = orig_filename.lower()
        file_data = file.read()

        try:
            if filename_lower.endswith('.csv'):
                df = pd.read_csv(io.BytesIO(file_data), header=header_row - 1, dtype=str)
            else:
                df = pd.read_excel(io.BytesIO(file_data), header=header_row - 1, dtype=str)
        except Exception as e:
            flash(f'Error reading file: {str(e)}', 'danger')
            return render_template('quotation_price_checker.html',
                                   results=None, stats=None, results_json=None,
                                   column_info=None, header_row=header_row,
                                   pn_column=pn_column, price_column=price_column)

        df.columns = [str(c).strip() for c in df.columns]
        cols_lower = {c.lower().strip(): c for c in df.columns}

        def detect_col(candidates, override='', exclude_col=None):
            if override:
                up = override.upper()
                for c in df.columns:
                    if c.upper() == up:
                        return c
                if len(override) == 1:
                    idx = ord(override.upper()) - ord('A')
                    if 0 <= idx < len(df.columns):
                        return df.columns[idx]
            for cand in candidates:
                if cand in cols_lower:
                    col = cols_lower[cand]
                    if col != exclude_col:
                        return col
            return None

        detected_pn    = detect_col(PN_CANDIDATES, pn_column)
        detected_price = detect_col(PRICE_CANDIDATES, price_column, exclude_col=detected_pn)
        detected_qty   = detect_col(QTY_CANDIDATES)
        detected_desc  = detect_col(DESC_CANDIDATES)
        detected_uom   = detect_col(UOM_CANDIDATES)
        detected_total = detect_col(TOTAL_CANDIDATES)
        detected_sn    = detect_col(SN_CANDIDATES)

        if not detected_pn and len(df.columns) > 0:
            detected_pn = df.columns[0]

        column_info = {
            'pn_col':    detected_pn or 'Not detected',
            'price_col': detected_price or 'Not detected',
            'qty_col':   detected_qty or '—',
            'desc_col':  detected_desc or '—',
            'uom_col':   detected_uom or '—',
            'total_col': detected_total or '—',
            'sn_col':    detected_sn or '—',
            'header_row': header_row,
            'filename':  orig_filename,
            'all_cols':  list(df.columns)
        }

        def to_float(val):
            if val is None:
                return None
            s = str(val).replace(',', '').replace('SAR', '').replace('$', '').strip()
            try:
                return float(s)
            except Exception:
                return None

        # Build rows list from Excel
        excel_rows = []
        for _, row in df.iterrows():
            pn_raw = str(row.get(detected_pn, '') or '').strip() if detected_pn else ''
            if not pn_raw or pn_raw.lower() in ('nan', 'none', ''):
                continue
            excel_rows.append({
                'sn':          str(row.get(detected_sn, '') or '').strip() if detected_sn else '',
                'part_number': pn_raw,
                'description': str(row.get(detected_desc, '') or '').strip() if detected_desc else '',
                'uom':         str(row.get(detected_uom, '') or '').strip() if detected_uom else '',
                'qty':         to_float(row.get(detected_qty)) if detected_qty else None,
                'unit_cost':   to_float(row.get(detected_price)) if detected_price else None,
                'total':       to_float(row.get(detected_total)) if detected_total else None,
            })

        # Query DB for all part numbers at once
        part_numbers = list({r['part_number'] for r in excel_rows})
        db_map = {}
        if part_numbers:
            conn = sqlite3.connect('ProjectStatus.db')
            conn.row_factory = sqlite3.Row
            c = conn.cursor()
            placeholders = ','.join(['?' for _ in part_numbers])
            c.execute(f"""
                SELECT
                    TRIM(part_number) as pn,
                    description,
                    unit_price,
                    supplier_name,
                    supplier_type,
                    COALESCE(quote_ref, '') as quote_ref,
                    COALESCE(po_number, '') as po_number,
                    system,
                    COALESCE(d.name, qp.supplier_name, '') as distributor_name,
                    COUNT(*) OVER (PARTITION BY TRIM(LOWER(part_number))) as cnt
                FROM quotation_products qp
                LEFT JOIN distributors d ON qp.distributor_id = d.id
                WHERE TRIM(LOWER(part_number)) IN ({placeholders})
                ORDER BY qp.added_at DESC
            """, [p.lower() for p in part_numbers])
            seen = set()
            for row in c.fetchall():
                key = row['pn'].strip().lower()
                if key not in seen:
                    db_map[key] = dict(row)
                    seen.add(key)
            conn.close()

        results = []
        for er in excel_rows:
            key = er['part_number'].strip().lower()
            db = db_map.get(key)

            new_price = er['unit_cost']
            old_price = float(db['unit_price']) if db and db['unit_price'] is not None else None
            diff = round(new_price - old_price, 4) if (new_price is not None and old_price is not None) else None
            diff_pct = round((diff / old_price) * 100, 2) if (diff is not None and old_price and old_price != 0) else None

            if db:
                if diff_pct is not None:
                    status = 'same' if abs(diff_pct) < 0.5 else ('cheaper' if diff < 0 else 'higher')
                else:
                    status = 'no_price'
            else:
                status = 'not_found'

            results.append({
                'sn':           er['sn'],
                'part_number':  er['part_number'],
                'description':  er['description'] or (db['description'] if db else ''),
                'uom':          er['uom'],
                'qty':          er['qty'],
                'unit_cost':    new_price,
                'total':        er['total'],
                'old_price':    old_price,
                'source':       db['quote_ref'] if db else '',
                'po_number':    db['po_number'] if db else '',
                'distributor':  db['distributor_name'] if db else '',
                'db_supplier':  db['supplier_name'] if db else '',
                'diff':         diff,
                'diff_pct':     diff_pct,
                'status':       status,
            })

        matched   = sum(1 for r in results if r['status'] != 'not_found')
        not_found = sum(1 for r in results if r['status'] == 'not_found')
        cheaper   = sum(1 for r in results if r['status'] == 'cheaper')
        same      = sum(1 for r in results if r['status'] == 'same')
        higher    = sum(1 for r in results if r['status'] == 'higher')
        diffs     = [r['diff_pct'] for r in results if r['diff_pct'] is not None]
        avg_diff  = round(sum(diffs) / len(diffs), 2) if diffs else 0

        stats = {
            'total_excel': len(results),
            'matched': matched, 'not_found': not_found,
            'cheaper': cheaper, 'same': same, 'higher': higher,
            'avg_diff_pct': avg_diff,
        }
        results_json = json.dumps(results)

    return render_template('quotation_price_checker.html',
                           results=results, stats=stats,
                           results_json=results_json,
                           column_info=column_info,
                           header_row=header_row,
                           pn_column=pn_column,
                           price_column=price_column)



@app.route('/quotation_price_checker/from_cost_sheet', methods=['POST'])
@login_required
@permission_required('view_products')
def price_checker_from_cost_sheet():
    """Run price check using cost sheet items posted as JSON — no Excel upload needed."""
    import json as _json
    raw = request.form.get('items_json', '[]')
    try:
        cs_items = _json.loads(raw)
    except Exception:
        cs_items = []

    PN_CANDIDATES    = ['item code', 'part number', 'part no', 'p/n', 'pn', 'item no',
                        'part#', 'part #', 'model', 'sku', 'material code', 'product code']
    PRICE_CANDIDATES = ['unit cost', 'unit price', 'price', 'cost', 'rate',
                        'net price', 'net', 'sale price', 'list price']

    def to_float(val):
        if val is None:
            return None
        try:
            return float(str(val).replace(',', '').strip())
        except Exception:
            return None

    excel_rows = []
    sn = 0
    for item in cs_items:
        if item.get('type') != 'item':
            continue
        pn = str(item.get('item_code') or '').strip()
        if not pn or pn.lower() in ('nan', 'none', ''):
            continue
        sn += 1
        qty_val  = to_float(item.get('qty'))
        cost_val = to_float(item.get('unit_cost'))
        total_val = round(qty_val * cost_val, 2) if (qty_val is not None and cost_val is not None) else None
        excel_rows.append({
            'sn':          str(sn),
            'part_number': pn,
            'description': str(item.get('desc') or '').strip(),
            'uom':         str(item.get('uom') or '').strip(),
            'qty':         qty_val,
            'unit_cost':   cost_val,
            'total':       total_val,
            'sheet_name':  str(item.get('sheet_name') or '').strip(),
        })

    db_map = {}
    if excel_rows:
        part_numbers = list({r['part_number'] for r in excel_rows})
        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        c = conn.cursor()
        placeholders = ','.join(['?' for _ in part_numbers])
        c.execute(f"""
            SELECT
                TRIM(part_number) as pn,
                description,
                unit_price,
                supplier_name,
                supplier_type,
                COALESCE(quote_ref, '') as quote_ref,
                COALESCE(po_number, '') as po_number,
                system,
                COALESCE(d.name, qp.supplier_name, '') as distributor_name
            FROM quotation_products qp
            LEFT JOIN distributors d ON qp.distributor_id = d.id
            WHERE TRIM(LOWER(part_number)) IN ({placeholders})
            ORDER BY qp.added_at DESC
        """, [p.lower() for p in part_numbers])
        seen = set()
        for row in c.fetchall():
            key = row['pn'].strip().lower()
            if key not in seen:
                db_map[key] = dict(row)
                seen.add(key)
        conn.close()

    results = []
    for er in excel_rows:
        key = er['part_number'].strip().lower()
        db  = db_map.get(key)
        new_price = er['unit_cost']
        old_price = float(db['unit_price']) if db and db['unit_price'] is not None else None
        diff = round(new_price - old_price, 4) if (new_price is not None and old_price is not None) else None
        diff_pct = round((diff / old_price) * 100, 2) if (diff is not None and old_price and old_price != 0) else None
        if db:
            if diff_pct is not None:
                status = 'same' if abs(diff_pct) < 0.5 else ('cheaper' if diff < 0 else 'higher')
            else:
                status = 'no_price'
        else:
            status = 'not_found'
        results.append({
            'sn':          er['sn'],
            'part_number': er['part_number'],
            'description': er['description'] or (db['description'] if db else ''),
            'uom':         er['uom'],
            'qty':         er['qty'],
            'unit_cost':   new_price,
            'total':       er['total'],
            'old_price':   old_price,
            'source':      db['quote_ref']        if db else '',
            'po_number':   db['po_number']        if db else '',
            'distributor': db['distributor_name'] if db else '',
            'db_supplier': db['supplier_name']    if db else '',
            'diff':        diff,
            'diff_pct':    diff_pct,
            'status':      status,
            'sheet_name':  er.get('sheet_name', ''),
        })

    matched   = sum(1 for r in results if r['status'] != 'not_found')
    not_found = sum(1 for r in results if r['status'] == 'not_found')
    cheaper   = sum(1 for r in results if r['status'] == 'cheaper')
    same      = sum(1 for r in results if r['status'] == 'same')
    higher    = sum(1 for r in results if r['status'] == 'higher')
    diffs     = [r['diff_pct'] for r in results if r['diff_pct'] is not None]
    avg_diff  = round(sum(diffs) / len(diffs), 2) if diffs else 0

    stats = {
        'total_excel': len(results),
        'matched':  matched,  'not_found': not_found,
        'cheaper':  cheaper,  'same':      same,
        'higher':   higher,   'avg_diff_pct': avg_diff,
    }

    column_info = {
        'pn_col': 'Item Code', 'price_col': 'Unit Cost',
        'qty_col': 'Qty', 'desc_col': 'Item Description',
        'uom_col': 'UOM', 'total_col': 'Total',
        'sn_col': 'S.#', 'header_row': 1,
        'filename': 'Cost Sheet (auto)', 'all_cols': []
    }

    return render_template('quotation_price_checker.html',
                           results=results, stats=stats,
                           results_json=_json.dumps(results),
                           column_info=column_info,
                           header_row=1, pn_column='', price_column='')

@app.route('/quotation_price_checker/export', methods=['POST'])
@login_required
@permission_required('view_products')
def quotation_price_checker_export():
    import io, json
    import xlsxwriter

    results_json = request.form.get('results_json', '[]')
    try:
        results = json.loads(results_json)
    except Exception:
        flash('Error exporting results.', 'danger')
        return redirect(url_for('quotation_price_checker'))

    output = io.BytesIO()
    wb = xlsxwriter.Workbook(output, {'in_memory': True})
    ws = wb.add_worksheet('Price Comparison')
    ws.set_landscape()
    ws.set_paper(9)  # A4

    # ── Formats ──────────────────────────────────────────────────────────────
    def fmt(**kw):
        base = {'border': 1, 'valign': 'vcenter', 'text_wrap': True, 'font_size': 10}
        base.update(kw)
        return wb.add_format(base)

    hdr_fmt   = fmt(bold=True, bg_color='#4B2D8F', font_color='white', align='center', font_size=11, border_color='#ffffff')
    num_fmt   = '#,##0.00'
    plain     = fmt()
    plain_num = fmt(num_format=num_fmt)
    grn_bg    = fmt(bg_color='#E8F5E9')
    grn_num   = fmt(bg_color='#E8F5E9', num_format=num_fmt)
    red_bg    = fmt(bg_color='#FFEBEE')
    red_num   = fmt(bg_color='#FFEBEE', num_format=num_fmt)
    ylw_bg    = fmt(bg_color='#FFFDE7')
    ylw_num   = fmt(bg_color='#FFFDE7', num_format=num_fmt)
    grey_bg   = fmt(bg_color='#F5F5F5', font_color='#888888')
    grey_num  = fmt(bg_color='#F5F5F5', font_color='#888888', num_format=num_fmt)
    diff_grn  = fmt(bg_color='#E8F5E9', font_color='#1B5E20', bold=True, num_format='+#,##0.00;-#,##0.00;0.00')
    diff_red  = fmt(bg_color='#FFEBEE', font_color='#B71C1C', bold=True, num_format='+#,##0.00;-#,##0.00;0.00')
    pct_grn   = fmt(bg_color='#E8F5E9', font_color='#1B5E20', bold=True, num_format='+0.0%;-0.0%;0.0%')
    pct_red   = fmt(bg_color='#FFEBEE', font_color='#B71C1C', bold=True, num_format='+0.0%;-0.0%;0.0%')
    pct_ylw   = fmt(bg_color='#FFFDE7', font_color='#856404', bold=True, num_format='0.0%')
    title_fmt = wb.add_format({'bold': True, 'font_size': 14, 'font_color': '#4B2D8F', 'border': 0})
    sub_fmt   = wb.add_format({'italic': True, 'font_color': '#888', 'font_size': 9, 'border': 0})
    stat_lbl  = wb.add_format({'bold': True, 'font_size': 9, 'bg_color': '#EDE7F6', 'border': 1, 'align': 'center'})
    stat_val  = wb.add_format({'font_size': 10, 'bold': True, 'bg_color': '#D1C4E9', 'border': 1, 'align': 'center'})

    # ── Title ─────────────────────────────────────────────────────────────────
    ws.merge_range('A1:L1', 'Quotation Price Comparison Report', title_fmt)
    generated_by = session.get('username', 'Unknown')
    ws.merge_range('A2:L2', f'Generated: {datetime.now().strftime("%Y-%m-%d %H:%M")}    |    Generated by: {generated_by}', sub_fmt)
    ws.set_row(0, 22)
    ws.set_row(1, 16)

    # ── Stats row ─────────────────────────────────────────────────────────────
    matched   = sum(1 for r in results if r.get('status') != 'not_found')
    not_found = sum(1 for r in results if r.get('status') == 'not_found')
    cheaper   = sum(1 for r in results if r.get('status') == 'cheaper')
    higher    = sum(1 for r in results if r.get('status') == 'higher')
    same      = sum(1 for r in results if r.get('status') == 'same')

    ws.write(3, 0, 'Total Items', stat_lbl)
    ws.write(3, 1, len(results), stat_val)
    ws.write(3, 2, 'Matched in DB', stat_lbl)
    ws.write(3, 3, matched, stat_val)
    ws.write(3, 4, 'Not Found', stat_lbl)
    ws.write(3, 5, not_found, wb.add_format({'font_size':10,'bold':True,'bg_color':'#FFCCBC','border':1,'align':'center'}))
    ws.write(3, 6, 'Excel Cheaper', stat_lbl)
    ws.write(3, 7, cheaper, wb.add_format({'font_size':10,'bold':True,'bg_color':'#C8E6C9','border':1,'align':'center'}))
    ws.write(3, 8, 'Same Price', stat_lbl)
    ws.write(3, 9, same, wb.add_format({'font_size':10,'bold':True,'bg_color':'#FFF9C4','border':1,'align':'center'}))
    ws.write(3, 10, 'Excel Higher', stat_lbl)
    ws.write(3, 11, higher, wb.add_format({'font_size':10,'bold':True,'bg_color':'#FFCDD2','border':1,'align':'center'}))
    ws.set_row(3, 18)

    # ── Column Headers ────────────────────────────────────────────────────────
    headers = ['S.#', 'Item Code', 'Item Description', 'UOM', 'Qty',
               'Unit Cost\n(New)', 'Total', 'OLD Price\n(DB)', 'Difference\n(SAR)',
               'Diff %', 'Source\n(Quote Ref)', 'PO Number', 'Distributor', 'Status']
    col_widths = [5, 16, 48, 6, 7, 13, 13, 13, 13, 9, 16, 13, 20, 12]
    for i, (h, w) in enumerate(zip(headers, col_widths)):
        ws.write(4, i, h, hdr_fmt)
        ws.set_column(i, i, w)
    ws.set_row(4, 30)

    # ── Data Rows ─────────────────────────────────────────────────────────────
    status_labels = {
        'cheaper': 'Cheaper ↓', 'higher': 'Higher ↑',
        'same': 'Same =', 'not_found': 'Not Found',
        'no_price': 'No Price', 'no_db_price': 'No DB Price'
    }

    for idx, r in enumerate(results):
        row = idx + 5
        status = r.get('status', 'not_found')

        if status == 'cheaper':
            tb, tn = grn_bg, grn_num
            td, tp = diff_grn, pct_grn
        elif status == 'higher':
            tb, tn = red_bg, red_num
            td, tp = diff_red, pct_red
        elif status == 'same':
            tb, tn = ylw_bg, ylw_num
            td, tp = ylw_bg, pct_ylw
        else:
            tb, tn = grey_bg, grey_num
            td, tp = grey_bg, grey_bg

        ws.write(row, 0,  r.get('sn') or (idx + 1), tb)
        ws.write(row, 1,  r.get('part_number', ''), tb)
        ws.write(row, 2,  r.get('description', ''), tb)
        ws.write(row, 3,  r.get('uom', ''), tb)

        qty = r.get('qty')
        ws.write(row, 4, qty if qty is not None else '', tn if qty is not None else tb)

        uc = r.get('unit_cost')
        ws.write(row, 5, uc if uc is not None else '', tn if uc is not None else tb)

        tot = r.get('total')
        ws.write(row, 6, tot if tot is not None else '', tn if tot is not None else tb)

        op = r.get('old_price')
        ws.write(row, 7, op if op is not None else 'Not found', tn if op is not None else tb)

        diff = r.get('diff')
        ws.write(row, 8, diff if diff is not None else '', td if diff is not None else tb)

        dp = r.get('diff_pct')
        ws.write(row, 9, (dp / 100) if dp is not None else '', tp if dp is not None else tb)

        ws.write(row, 10, r.get('source', ''), tb)
        ws.write(row, 11, r.get('po_number', ''), tb)
        ws.write(row, 12, r.get('distributor', ''), tb)
        ws.write(row, 13, status_labels.get(status, status), tb)
        ws.set_row(row, 36)

    # ── Legend ────────────────────────────────────────────────────────────────
    leg_row = len(results) + 6
    ws.write(leg_row, 0, 'Legend:', wb.add_format({'bold': True, 'border': 0}))
    ws.write(leg_row, 1, 'Cheaper ↓', grn_bg)
    ws.write(leg_row, 2, 'Same =', ylw_bg)
    ws.write(leg_row, 3, 'Higher ↑', red_bg)
    ws.write(leg_row, 4, 'Not Found', grey_bg)

    wb.close()
    output.seek(0)
    filename = f"price_comparison_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx"
    return send_file(output,
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                     as_attachment=True, download_name=filename)

if __name__ == '__main__':
    init_db()
    seed_permissions()
    seed_default_role_permissions()
    seed_default_roles()
    host = os.getenv('HOST', '0.0.0.0')
    port = int(os.getenv('PORT', 5000))
    debug = os.getenv('FLASK_DEBUG', '0') == '1'
